class DotNetLibraryIntegrationTest : TestCaseWithTmpdir() {
    @Test
    fun testParsesClrSerializedTypeNames() {
        val assemblyQualified = (
                DotNetClrSerializedTypeNameParser.parse(
                    "Forwarded.ExternalKind, ForwardDestination, Version=1.0.0.0, " +
                            "Culture=neutral, PublicKeyToken=null"
                ) as DotNetClrSerializedTypeNameParsing.Parsed
                ).type
        assertEquals("Forwarded", assemblyQualified.namedType.namespaceName)
        assertEquals(
            "ExternalKind",
            assemblyQualified.namedType.topLevelType.metadataName,
        )
        assertEquals(
            "ForwardDestination, Version=1.0.0.0, Culture=neutral, PublicKeyToken=null",
            assemblyQualified.assemblyDisplayName,
        )

        val escapedNested = (
                DotNetClrSerializedTypeNameParser.parse(
                    "Ozzy.Out\\+Back.Kangaroo+Wallaby\\+Leaf"
                ) as DotNetClrSerializedTypeNameParsing.Parsed
                ).type
        assertEquals("Ozzy.Out+Back", escapedNested.namedType.namespaceName)
        assertEquals("Kangaroo", escapedNested.namedType.topLevelType.metadataName)
        assertEquals(
            listOf("Wallaby+Leaf"),
            escapedNested.namedType.nestedTypes.map { part -> part.metadataName },
        )

        val constructed = (
                DotNetClrSerializedTypeNameParser.parse(
                    "System.Collections.Generic.Dictionary`2" +
                            "[[System.String, System.Private.CoreLib]," +
                            "[Forwarded.Outer+Inner, ForwardDestination]][,][]*&"
                ) as DotNetClrSerializedTypeNameParsing.Parsed
                ).type
        assertEquals(2, constructed.namedType.totalGenericArity)
        assertEquals(2, constructed.genericArguments.size)
        assertEquals(
            "System.Private.CoreLib",
            constructed.genericArguments[0].assemblyDisplayName,
        )
        assertEquals(
            listOf("Inner"),
            constructed.genericArguments[1].namedType.nestedTypes
                .map { part -> part.metadataName },
        )
        assertEquals(
            listOf(
                DotNetClrSerializedTypeModifier.MdArray(2),
                DotNetClrSerializedTypeModifier.SzArray,
                DotNetClrSerializedTypeModifier.Pointer,
                DotNetClrSerializedTypeModifier.ByReference,
            ),
            constructed.modifiers,
        )

        val starDimensions = (
                DotNetClrSerializedTypeNameParser.parse(
                    "System.Int32[*,*]"
                ) as DotNetClrSerializedTypeNameParsing.Parsed
                ).type
        val commaDimensions = (
                DotNetClrSerializedTypeNameParser.parse(
                    "System.Int32[,]"
                ) as DotNetClrSerializedTypeNameParsing.Parsed
                ).type
        assertEquals(starDimensions, commaDimensions)

        val openGeneric = (
                DotNetClrSerializedTypeNameParser.parse(
                    "System.Collections.Generic.List`1, System.Private.CoreLib"
                ) as DotNetClrSerializedTypeNameParsing.Parsed
                ).type
        assertEquals(1, openGeneric.namedType.totalGenericArity)
        assertTrue(openGeneric.genericArguments.isEmpty())
        val digitLeadingArgument = (
                DotNetClrSerializedTypeNameParser.parse(
                    "Example.Box`1[123Type]"
                ) as DotNetClrSerializedTypeNameParsing.Parsed
                ).type
        assertEquals(
            "123Type",
            digitLeadingArgument.genericArguments.single()
                .namedType.topLevelType.metadataName,
        )
        val quotedAssemblyArgument = (
                DotNetClrSerializedTypeNameParser.parse(
                    "Example.Box`1[[System.String, \"Odd]Assembly\"]]"
                ) as DotNetClrSerializedTypeNameParsing.Parsed
                ).type
        assertEquals(
            "\"Odd]Assembly\"",
            quotedAssemblyArgument.genericArguments.single().assemblyDisplayName,
        )
        val openGenericArray = (
                DotNetClrSerializedTypeNameParser.parse(
                    "Example.Pair`2[,]"
                ) as DotNetClrSerializedTypeNameParsing.Parsed
                ).type
        assertTrue(openGenericArray.genericArguments.isEmpty())
        assertEquals(
            listOf(DotNetClrSerializedTypeModifier.MdArray(2)),
            openGenericArray.modifiers,
        )

        val invalidEscape =
            DotNetClrSerializedTypeNameParser.parse("Broken\\qName") as
                    DotNetClrSerializedTypeNameParsing.Invalid
        assertEquals(
            DotNetClrSerializedTypeNameFailure.INVALID_ESCAPE,
            invalidEscape.failure,
        )
        val wrongArity =
            DotNetClrSerializedTypeNameParser.parse(
                "Example.Pair`2[System.String]"
            ) as DotNetClrSerializedTypeNameParsing.Invalid
        assertEquals(
            DotNetClrSerializedTypeNameFailure.GENERIC_ARGUMENT_COUNT_MISMATCH,
            wrongArity.failure,
        )
        val emptyArgument =
            DotNetClrSerializedTypeNameParser.parse(
                "Example.Pair`2[System.String,]"
            ) as DotNetClrSerializedTypeNameParsing.Invalid
        assertEquals(
            DotNetClrSerializedTypeNameFailure.EMPTY_GENERIC_ARGUMENT,
            emptyArgument.failure,
        )
        val invalidByReference =
            DotNetClrSerializedTypeNameParser.parse("System.Int32&&") as
                    DotNetClrSerializedTypeNameParsing.Invalid
        assertEquals(
            DotNetClrSerializedTypeNameFailure.INVALID_BY_REFERENCE_SHAPE,
            invalidByReference.failure,
        )
        val reflectionEmitBound =
            DotNetClrSerializedTypeNameParser.parse("System.Int32[0..5]") as
                    DotNetClrSerializedTypeNameParsing.Unsupported
        assertEquals(
            DotNetClrSerializedTypeNameUnsupported.REFLECTION_EMIT_ARRAY_BOUND,
            reflectionEmitBound.unsupported,
        )
        val excessiveNestingName = buildString {
            repeat(65) { append("Example.Box`1[") }
            append("System.Int32")
            repeat(65) { append(']') }
        }
        val excessiveNesting =
            DotNetClrSerializedTypeNameParser.parse(excessiveNestingName) as
                    DotNetClrSerializedTypeNameParsing.Invalid
        assertEquals(
            DotNetClrSerializedTypeNameFailure.NESTING_LIMIT_EXCEEDED,
            excessiveNesting.failure,
        )

        val assemblyName = (
                DotNetClrSerializedAssemblyNameParser.parse(
                    "\"Odd\\,Name\", Version=1.2.65535.4, Culture=\"\", " +
                            "PublicKey=00ff, ProcessorArchitecture=MSIL, " +
                            "Retargetable=Yes, ContentType=WindowsRuntime, " +
                            "Future=\"x\\,y\""
                ) as DotNetClrSerializedAssemblyNameParsing.Parsed
                ).assemblyName
        assertEquals("Odd,Name", assemblyName.name)
        assertEquals(
            DotNetClrSerializedAssemblyVersion(listOf(1, 2, 65535, 4)),
            assemblyName.version,
        )
        assertEquals("", assemblyName.cultureName)
        assertEquals(listOf(0, 255), assemblyName.publicKeyOrToken)
        assertTrue(assemblyName.hasPublicKey)
        assertEquals(
            DotNetClrSerializedProcessorArchitecture.MSIL,
            assemblyName.processorArchitecture,
        )
        assertTrue(assemblyName.isRetargetable)
        assertEquals(
            DotNetClrSerializedAssemblyContentType.WINDOWS_RUNTIME,
            assemblyName.contentType,
        )
        assertEquals(
            listOf(DotNetClrSerializedAssemblyProperty("Future", "x,y")),
            assemblyName.unknownProperties,
        )

        val explicitNullToken = (
                DotNetClrSerializedAssemblyNameParser.parse(
                    "Portable, Culture=neutral, PublicKeyToken=null"
                ) as DotNetClrSerializedAssemblyNameParsing.Parsed
                ).assemblyName
        assertEquals("", explicitNullToken.cultureName)
        assertEquals(emptyList<Int>(), explicitNullToken.publicKeyOrToken)
        assertFalse(explicitNullToken.hasPublicKey)

        val duplicateKey =
            DotNetClrSerializedAssemblyNameParser.parse(
                "Broken, PublicKeyToken=null, PublicKey=00"
            ) as DotNetClrSerializedAssemblyNameParsing.Invalid
        assertEquals(
            DotNetClrSerializedAssemblyNameFailure.DUPLICATE_PROPERTY,
            duplicateKey.failure,
        )
        val malformedToken =
            DotNetClrSerializedAssemblyNameParser.parse(
                "Broken, PublicKeyToken=0011"
            ) as DotNetClrSerializedAssemblyNameParsing.Invalid
        assertEquals(
            DotNetClrSerializedAssemblyNameFailure.INVALID_PUBLIC_KEY_OR_TOKEN,
            malformedToken.failure,
        )
        val malformedVersion =
            DotNetClrSerializedAssemblyNameParser.parse(
                "Broken, Version=1"
            ) as DotNetClrSerializedAssemblyNameParsing.Invalid
        assertEquals(
            DotNetClrSerializedAssemblyNameFailure.INVALID_VERSION,
            malformedVersion.failure,
        )
        val missingValue =
            DotNetClrSerializedAssemblyNameParser.parse(
                "Broken, Culture="
            ) as DotNetClrSerializedAssemblyNameParsing.Invalid
        assertEquals(
            DotNetClrSerializedAssemblyNameFailure.UNEXPECTED_TOKEN,
            missingValue.failure,
        )
        val unclosedQuote =
            DotNetClrSerializedAssemblyNameParser.parse(
                "Broken, Culture=\"neutral"
            ) as DotNetClrSerializedAssemblyNameParsing.Invalid
        assertEquals(
            DotNetClrSerializedAssemblyNameFailure.UNCLOSED_QUOTE,
            unclosedQuote.failure,
        )
    }

    @Test
    fun testReadsPhysicalClrMetadataAndSignatures() {
        val frameworkIlasm = DotNetIlAssembler.findFrameworkIlasm()
        requireOrAssumeToolchain(
            frameworkIlasm != null,
            ".NET Framework ilasm is not available",
        )
        requireOrAssumeToolchain(
            DotNetIlAssembler.findModernIlasm() != null,
            "Modern ilasm is not available",
        )
        val modernCSharp = DotNetIlAssembler.findModernCSharpCompiler()
        requireOrAssumeToolchain(
            modernCSharp != null,
            "Modern Roslyn and the net10 reference pack are not available",
        )
        val ilFile = File(tmpdir, "clr-metadata/ImporterFixture.il").apply {
            parentFile.mkdirs()
            writeText(
                """
                .assembly extern mscorlib
                {
                }
                .assembly 'ImporterFixture'
                {
                  .ver 2:3:4:5
                }
                .module 'ImporterFixture.dll'

                .namespace Fixture
                {
                  .class public auto ansi beforefieldinit 'Base'
                         extends [mscorlib]System.Object
                  {
                    .custom instance void [mscorlib]System.ObsoleteAttribute::.ctor() = (
                      01 00 00 00
                    )
                    .custom instance void [mscorlib]System.ObsoleteAttribute::.ctor() = (
                      01 00 00 00
                    )
                  }

                  .class public auto ansi beforefieldinit 'Outer'
                         extends Fixture.Base
                  {
                    .class nested assembly auto ansi beforefieldinit 'Nested'
                           extends [mscorlib]System.Object
                    {
                    }
                  }

                  .class interface public abstract auto ansi 'IMarker'
                  {
                  }

                  .class interface public abstract auto ansi 'IBox`1'<T>
                  {
                  }

                  .class interface public abstract auto ansi 'IVariant`2'<+ 'TOut', - 'TIn'>
                  {
                  }

                  .class interface public abstract auto ansi 'IDiamondTop'
                  {
                  }

                  .class interface public abstract auto ansi 'IDiamondLeft'
                         implements Fixture.IDiamondTop
                  {
                  }

                  .class interface public abstract auto ansi 'IDiamondRight'
                         implements Fixture.IDiamondTop
                  {
                  }

                  .class public auto ansi beforefieldinit 'Diamond'
                         extends Fixture.Base
                         implements Fixture.IDiamondLeft, Fixture.IDiamondRight
                  {
                  }

                  .class public auto ansi beforefieldinit 'IntArrayBox'
                         extends Fixture.Base
                         implements class 'Fixture.IBox`1'<int32[]>
                  {
                  }

                  .class public auto ansi beforefieldinit 'GenericBase`1'<T>
                         extends Fixture.Base
                  {
                  }

                  .class public auto ansi beforefieldinit 'GenericBox`1'<T>
                         extends class 'Fixture.GenericBase`1'<!0[]>
                         implements class 'Fixture.IBox`1'<!0[]>
                  {
                  }

                  .class public auto ansi sealed 'TinyKind'
                         extends [mscorlib]System.Enum
                  {
                    .field public specialname rtspecialname int16 'value__'
                    .field public static literal valuetype Fixture.TinyKind 'Zero' = int16(0)
                  }

                  .class public auto ansi beforefieldinit 'ConstantHost'
                         extends [mscorlib]System.Object
                  {
                    .field public static literal bool 'BooleanValue' = bool(true)
                    .field public static literal char 'CharValue' = char(8364)
                    .field public static literal int8 'Int8Value' = int8(-7)
                    .field public static literal unsigned int8 'UInt8Value' = unsigned int8(250)
                    .field public static literal int16 'Int16Value' = int16(-1234)
                    .field public static literal unsigned int16 'UInt16Value' = unsigned int16(60000)
                    .field public static literal int32 'Int32Value' = int32(-1234567)
                    .field public static literal unsigned int32 'UInt32Value' = unsigned int32(4000000000)
                    .field public static literal int64 'Int64Value' = int64(-1234567890123)
                    .field public static literal unsigned int64 'UInt64Value' =
                        unsigned int64(18000000000000000000)
                    .field public static literal float32 'Float32Value' = float32(0x7fc01234)
                    .field public static literal float64 'Float64Value' =
                        float64(0x8000000000000000)
                    .field public static literal object 'NullValue' = nullref
                    .field public static int32 'PropertySeed' = int32(73)

                    .method public hidebysig static void 'Defaults'(
                        [opt] int32 'number',
                        [opt] string 'text',
                        [opt] object 'missing'
                    ) cil managed
                    {
                      .param [1] = int32(42)
                      .param [2] = "default"
                      .param [3] = nullref
                      .maxstack 0
                      ret
                    }
                  }

                  .class public auto ansi beforefieldinit 'GenericOwner`1'<T>
                         extends [mscorlib]System.Object
                  {
                    .field public !0 'Value'
                    .field private static initonly native int 'NativeValue'

                    .method public hidebysig static !0 'Echo'(!0 'value') cil managed
                    {
                      .maxstack 1
                      ldarg.0
                      ret
                    }
                  }

                  .class public auto ansi beforefieldinit 'MemberRefHost'
                         extends [mscorlib]System.Object
                  {
                    .method public hidebysig static object 'MakeObject'() cil managed
                    {
                      .maxstack 1
                      newobj instance void [mscorlib]System.Object::.ctor()
                      ret
                    }

                    .method public hidebysig static string 'ReadEmpty'() cil managed
                    {
                      .maxstack 1
                      ldsfld string [mscorlib]System.String::Empty
                      ret
                    }

                    .method public hidebysig static int32 'ReadGeneric'(
                        int32 'value'
                    ) cil managed
                    {
                      .maxstack 1
                      ldarg.0
                      call !0 class Fixture.'GenericOwner`1'<int32>::'Echo'(!0)
                      ret
                    }
                  }

                  .class public auto ansi beforefieldinit 'SignatureHost`1'<(
                      class Fixture.Base,
                      class Fixture.IMarker
                  ) 'T'>
                         extends [mscorlib]System.Object
                  {
                    .method public hidebysig instance !!0 'Transform'<(
                        !0,
                        class Fixture.IMarker
                    ) 'M'>(
                        !0[] 'input',
                        int32& 'value',
                        int32[-8192...-8188,-268435456...-268435453] 'matrix',
                        !!0 'argument'
                    ) cil managed
                    {
                      .maxstack 1
                      ldarg.s 'argument'
                      ret
                    }
                  }

                  .class public auto ansi beforefieldinit 'PropertyHost'
                         extends [mscorlib]System.Object
                  {
                    .method public hidebysig specialname instance int32 'ReadAt'(
                        int32 'index'
                    ) cil managed
                    {
                      .maxstack 1
                      ldarg.1
                      ret
                    }

                    .method public hidebysig specialname instance void 'WriteAt'(
                        int32 'index',
                        int32 'value'
                    ) cil managed
                    {
                      .maxstack 0
                      ret
                    }

                    .property instance int32 'CLR Item'(int32)
                    {
                      .get instance int32 'Fixture.PropertyHost'::'ReadAt'(int32)
                      .set instance void 'Fixture.PropertyHost'::'WriteAt'(int32, int32)
                    }

                    .method public hidebysig specialname static string 'FetchName'() cil managed
                    {
                      .maxstack 1
                      ldstr "name"
                      ret
                    }

                    .property string 'Odd Name'()
                    {
                      .get string 'Fixture.PropertyHost'::'FetchName'()
                    }
                  }
                }
                """.trimIndent()
            )
        }
        for (target in listOf(DotNetTarget.NET48, DotNetTarget.NET10_0)) {
            val assembly = File(tmpdir, "clr-metadata/${target.description}/ImporterFixture.dll")
            assertTrue(
                DotNetIlAssembler.assembleLibrary(
                    ilFile,
                    assembly,
                    target,
                    MessageCollector.NONE,
                )
            )

            val metadata = DotNetClrMetadataReader.read(assembly)
            assertEquals("ImporterFixture", metadata.identity.name)
            assertEquals("2.3.4.5", metadata.identity.version)
            assertEquals("neutral", metadata.identity.culture)
            assertFalse(metadata.identity.hasPublicKey)
            assertTrue(metadata.identity.publicKey.isEmpty())
            assertTrue(metadata.identity.publicKeyToken.isEmpty())

            val coreLibrary = metadata.assemblyReferences.single { it.name == "mscorlib" }
            assertEquals("neutral", coreLibrary.culture)
            val systemObject = metadata.typeReferences.single {
                it.namespaceName == "System" && it.metadataName == "Object"
            }
            assertEquals(coreLibrary.handle, systemObject.resolutionScope)

            val fixtureTypes = metadata.typeDefinitions
                .filter { it.namespaceName == "Fixture" || it.declaringType != null }
                .associateBy { it.metadataName }
            val base = fixtureTypes.getValue("Base")
            val outer = fixtureTypes.getValue("Outer")
            val nested = fixtureTypes.getValue("Nested")
            val marker = fixtureTypes.getValue("IMarker")
            val box = fixtureTypes.getValue("IBox`1")
            val variant = fixtureTypes.getValue("IVariant`2")
            val diamondTop = fixtureTypes.getValue("IDiamondTop")
            val diamond = fixtureTypes.getValue("Diamond")
            val intArrayBox = fixtureTypes.getValue("IntArrayBox")
            val genericBase = fixtureTypes.getValue("GenericBase`1")
            val genericBox = fixtureTypes.getValue("GenericBox`1")
            val tinyKind = fixtureTypes.getValue("TinyKind")
            val constantHost = fixtureTypes.getValue("ConstantHost")
            val genericOwner = fixtureTypes.getValue("GenericOwner`1")
            val signatureHost = fixtureTypes.getValue("SignatureHost`1")
            val propertyHost = fixtureTypes.getValue("PropertyHost")
            assertEquals(DotNetClrTypeVisibility.PUBLIC, base.visibility)
            assertEquals(systemObject.handle, base.baseType)
            assertEquals(base.handle, outer.baseType)
            assertEquals(outer.handle, nested.declaringType)
            assertEquals(DotNetClrTypeVisibility.NESTED_ASSEMBLY, nested.visibility)
            assertTrue(marker.isInterface)
            assertTrue(marker.isAbstract)
            assertFalse(marker.isSealed)
            val baseAttributes = metadata.customAttributes.filter { attribute ->
                attribute.parent == base.handle
            }
            assertEquals(2, baseAttributes.size)
            assertEquals(1, baseAttributes.map(DotNetClrCustomAttribute::constructor).toSet().size)
            assertTrue(
                baseAttributes.all { attribute ->
                    attribute.rawValue?.toUnsignedIntList() == listOf(1, 0, 0, 0)
                }
            )
            val obsoleteConstructor = metadata.memberReferences.single { reference ->
                reference.handle == baseAttributes.first().constructor
            }
            assertEquals(".ctor", obsoleteConstructor.name)
            val obsoleteType = metadata.typeReferences.single { reference ->
                reference.handle == obsoleteConstructor.parent
            }
            assertEquals("System", obsoleteType.namespaceName)
            assertEquals("ObsoleteAttribute", obsoleteType.metadataName)
            val intArrayBoxInterfaceSpecification =
                metadata.typeSpecifications.single { specification ->
                    val signature = specification.signature
                    signature is DotNetClrTypeSignature.GenericInstance &&
                            signature.genericType.type == box.handle &&
                            signature.arguments.singleOrNull() is DotNetClrTypeSignature.SzArray &&
                            (signature.arguments.single() as
                                    DotNetClrTypeSignature.SzArray).elementType is
                                    DotNetClrTypeSignature.Primitive
                }
            assertEquals(
                DotNetClrTypeSignature.GenericInstance(
                    genericType = DotNetClrTypeSignature.Named(
                        type = box.handle,
                        isValueType = false,
                    ),
                    arguments = listOf(
                        DotNetClrTypeSignature.SzArray(
                            DotNetClrTypeSignature.Primitive(DotNetClrPrimitiveType.INT32)
                        )
                    ),
                ),
                intArrayBoxInterfaceSpecification.signature,
            )
            val constantsByParent =
                metadata.constantDefinitions.associateBy(DotNetClrConstantDefinition::parent)
            assertEquals(18, metadata.constantDefinitions.size)
            assertEquals(metadata.constantDefinitions.size, constantsByParent.size)
            fun fieldConstant(name: String): DotNetClrConstantDefinition {
                val field = metadata.fieldDefinitions.single { definition ->
                    definition.declaringType == constantHost.handle && definition.name == name
                }
                assertTrue(field.hasDefault)
                return constantsByParent.getValue(field.handle)
            }
            assertEquals(
                DotNetClrConstantValue.BooleanValue(true),
                fieldConstant("BooleanValue").value,
            )
            assertEquals(
                DotNetClrConstantValue.CharValue('\u20ac'),
                fieldConstant("CharValue").value,
            )
            assertEquals(
                DotNetClrConstantValue.IntegralValue(
                    DotNetClrPrimitiveType.INT8,
                    (-7).toByte().toUByte().toULong(),
                ),
                fieldConstant("Int8Value").value,
            )
            assertEquals(
                DotNetClrConstantValue.IntegralValue(DotNetClrPrimitiveType.UINT8, 250uL),
                fieldConstant("UInt8Value").value,
            )
            assertEquals(
                DotNetClrConstantValue.IntegralValue(
                    DotNetClrPrimitiveType.INT16,
                    (-1234).toShort().toUShort().toULong(),
                ),
                fieldConstant("Int16Value").value,
            )
            assertEquals(
                DotNetClrConstantValue.IntegralValue(DotNetClrPrimitiveType.UINT16, 60_000uL),
                fieldConstant("UInt16Value").value,
            )
            assertEquals(
                DotNetClrConstantValue.IntegralValue(
                    DotNetClrPrimitiveType.INT32,
                    (-1_234_567).toUInt().toULong(),
                ),
                fieldConstant("Int32Value").value,
            )
            assertEquals(
                DotNetClrConstantValue.IntegralValue(
                    DotNetClrPrimitiveType.UINT32,
                    4_000_000_000uL,
                ),
                fieldConstant("UInt32Value").value,
            )
            assertEquals(
                DotNetClrConstantValue.IntegralValue(
                    DotNetClrPrimitiveType.INT64,
                    (-1_234_567_890_123L).toULong(),
                ),
                fieldConstant("Int64Value").value,
            )
            assertEquals(
                DotNetClrConstantValue.IntegralValue(
                    DotNetClrPrimitiveType.UINT64,
                    18_000_000_000_000_000_000uL,
                ),
                fieldConstant("UInt64Value").value,
            )
            assertEquals(
                DotNetClrConstantValue.Float32Value(0x7fc01234),
                fieldConstant("Float32Value").value,
            )
            assertEquals(
                DotNetClrConstantValue.Float64Value(Long.MIN_VALUE),
                fieldConstant("Float64Value").value,
            )
            assertSame(
                DotNetClrConstantValue.NullReference,
                fieldConstant("NullValue").value,
            )
            val propertySeed = metadata.fieldDefinitions.single { definition ->
                definition.declaringType == constantHost.handle &&
                        definition.name == "PropertySeed"
            }
            assertTrue(propertySeed.hasDefault)
            assertEquals(
                DotNetClrConstantValue.IntegralValue(DotNetClrPrimitiveType.INT32, 73uL),
                constantsByParent.getValue(propertySeed.handle).value,
            )
            val defaultsMethod = metadata.methodDefinitions.single { definition ->
                definition.declaringType == constantHost.handle &&
                        definition.name == "Defaults"
            }
            val defaultParameters = metadata.parameterDefinitions
                .filter { definition -> definition.declaringMethod == defaultsMethod.handle }
                .associateBy { definition -> checkNotNull(definition.name) }
            assertEquals(setOf("number", "text", "missing"), defaultParameters.keys)
            assertTrue(defaultParameters.values.all(DotNetClrParameterDefinition::isOptional))
            assertTrue(defaultParameters.values.all(DotNetClrParameterDefinition::hasDefault))
            assertEquals(
                DotNetClrConstantValue.IntegralValue(DotNetClrPrimitiveType.INT32, 42uL),
                constantsByParent.getValue(defaultParameters.getValue("number").handle).value,
            )
            assertEquals(
                DotNetClrConstantValue.StringValue("default"),
                constantsByParent.getValue(defaultParameters.getValue("text").handle).value,
            )
            assertSame(
                DotNetClrConstantValue.NullReference,
                constantsByParent.getValue(defaultParameters.getValue("missing").handle).value,
            )
            val enumZero = metadata.fieldDefinitions.single { definition ->
                definition.declaringType == tinyKind.handle && definition.name == "Zero"
            }
            assertEquals(
                DotNetClrConstantValue.IntegralValue(DotNetClrPrimitiveType.INT16, 0uL),
                constantsByParent.getValue(enumZero.handle).value,
            )
            val metadataTables = locateClrMetadataTables(assembly.readBytes())
            fun constantValueIndex(
                image: ByteArray,
                constant: DotNetClrConstantDefinition,
            ): Int = readLittleEndianIndex(
                image,
                metadataTables.rowOffset(11, constant.handle.row) +
                        2 + metadataTables.hasConstantIndexSize,
                metadataTables.blobIndexSize,
            )

            fun writeConstantValueIndex(
                image: ByteArray,
                constant: DotNetClrConstantDefinition,
                valueIndex: Int,
            ) {
                writeLittleEndian(
                    image,
                    metadataTables.rowOffset(11, constant.handle.row) +
                            2 + metadataTables.hasConstantIndexSize,
                    metadataTables.blobIndexSize,
                    valueIndex,
                )
            }

            fun mutatedMetadata(
                name: String,
                mutate: (ByteArray) -> Unit,
            ): DotNetClrAssemblyMetadata {
                val mutatedAssembly = File(
                    assembly.parentFile,
                    "${assembly.nameWithoutExtension}-$name.dll",
                )
                val mutatedImage = assembly.readBytes()
                mutate(mutatedImage)
                mutatedAssembly.writeBytes(mutatedImage)
                return DotNetClrMetadataReader.read(mutatedAssembly)
            }

            fun assertMalformedConstant(
                name: String,
                expectedMessage: String,
                mutate: (ByteArray) -> Unit,
            ) {
                val failure = assertThrows(DotNetBadImageFormatException::class.java) {
                    mutatedMetadata(name, mutate)
                }
                assertTrue(expectedMessage in checkNotNull(failure.message)) {
                    failure.message
                }
            }

            val booleanConstant = fieldConstant("BooleanValue")
            val int8Constant = fieldConstant("Int8Value")
            val int32Constant = fieldConstant("Int32Value")
            val stringConstant = constantsByParent.getValue(
                defaultParameters.getValue("text").handle
            )
            val nullConstant = fieldConstant("NullValue")
            val numberConstant = constantsByParent.getValue(
                defaultParameters.getValue("number").handle
            )
            assertMalformedConstant("constant-invalid-type", "invalid element type") { image ->
                image[metadataTables.rowOffset(11, booleanConstant.handle.row)] = 0x1c
            }
            assertMalformedConstant(
                "constant-nonzero-padding",
                "non-zero reserved padding",
            ) { image ->
                image[metadataTables.rowOffset(11, booleanConstant.handle.row) + 1] = 1
            }
            assertMalformedConstant("constant-invalid-parent", "invalid tag") { image ->
                writeLittleEndian(
                    image,
                    metadataTables.rowOffset(11, booleanConstant.handle.row) + 2,
                    metadataTables.hasConstantIndexSize,
                    (1 shl 2) or 3,
                )
            }
            assertMalformedConstant("constant-duplicate-parent", "duplicates parent token") { image ->
                val booleanParent = readLittleEndianIndex(
                    image,
                    metadataTables.rowOffset(11, booleanConstant.handle.row) + 2,
                    metadataTables.hasConstantIndexSize,
                )
                writeLittleEndian(
                    image,
                    metadataTables.rowOffset(11, int8Constant.handle.row) + 2,
                    metadataTables.hasConstantIndexSize,
                    booleanParent,
                )
            }
            val ordinaryField = metadata.fieldDefinitions.single { definition ->
                definition.declaringType == genericOwner.handle && definition.name == "Value"
            }
            assertFalse(ordinaryField.hasDefault)
            assertMalformedConstant(
                "constant-field-flag-without-row",
                "HasDefault without a Constant row",
            ) { image ->
                val attributesOffset = metadataTables.rowOffset(4, ordinaryField.handle.row)
                val attributes = readLittleEndianIndex(image, attributesOffset, 2)
                writeLittleEndian(image, attributesOffset, 2, attributes or 0x8000)
            }
            assertMalformedConstant(
                "constant-param-row-without-flag",
                "HasDefault flag does not agree",
            ) { image ->
                val parameter = defaultParameters.getValue("number")
                val attributesOffset = metadataTables.rowOffset(8, parameter.handle.row)
                val attributes = readLittleEndianIndex(image, attributesOffset, 2)
                writeLittleEndian(image, attributesOffset, 2, attributes and 0x1000.inv())
            }
            val echoMethod = metadata.methodDefinitions.single { definition ->
                definition.declaringType == genericOwner.handle && definition.name == "Echo"
            }
            val echoParameter = metadata.parameterDefinitions.single { definition ->
                definition.declaringMethod == echoMethod.handle && definition.name == "value"
            }
            assertFalse(echoParameter.hasDefault)
            assertMalformedConstant(
                "constant-param-flag-without-row",
                "HasDefault flag does not agree",
            ) { image ->
                val attributesOffset = metadataTables.rowOffset(8, echoParameter.handle.row)
                val attributes = readLittleEndianIndex(image, attributesOffset, 2)
                writeLittleEndian(image, attributesOffset, 2, attributes or 0x1000)
            }
            assertMalformedConstant("constant-truncated-scalar", "truncated value") { image ->
                writeConstantValueIndex(
                    image,
                    numberConstant,
                    constantValueIndex(image, booleanConstant),
                )
            }
            assertMalformedConstant("constant-nonzero-nullref", "non-zero nullref") { image ->
                writeConstantValueIndex(
                    image,
                    nullConstant,
                    constantValueIndex(image, numberConstant),
                )
            }

            val nonCanonicalBoolean = mutatedMetadata("constant-noncanonical-boolean") { image ->
                writeConstantValueIndex(
                    image,
                    booleanConstant,
                    constantValueIndex(image, int8Constant),
                )
            }.constantDefinitions.single { constant -> constant.handle == booleanConstant.handle }
            assertEquals(DotNetClrConstantValue.BooleanValue(true), nonCanonicalBoolean.value)
            assertEquals(listOf(249), nonCanonicalBoolean.rawValue.toUnsignedIntList())

            val trailingScalar = mutatedMetadata("constant-trailing-scalar") { image ->
                writeConstantValueIndex(
                    image,
                    int8Constant,
                    constantValueIndex(image, int32Constant),
                )
            }.constantDefinitions.single { constant -> constant.handle == int8Constant.handle }
            assertEquals(
                DotNetClrConstantValue.IntegralValue(
                    DotNetClrPrimitiveType.INT8,
                    (-1_234_567).toByte().toUByte().toULong(),
                ),
                trailingScalar.value,
            )
            assertEquals(4, trailingScalar.rawValue.size)

            val oddUtf16 = mutatedMetadata("constant-odd-utf16") { image ->
                writeConstantValueIndex(
                    image,
                    stringConstant,
                    constantValueIndex(image, int8Constant),
                )
            }.constantDefinitions.single { constant -> constant.handle == stringConstant.handle }
            assertEquals(DotNetClrConstantValue.StringValue(""), oddUtf16.value)
            assertEquals(listOf(249), oddUtf16.rawValue.toUnsignedIntList())

            val charConstant = fieldConstant("CharValue")
            val unpairedUtf16 = mutatedMetadata("constant-unpaired-utf16") { image ->
                val charValueIndex = constantValueIndex(image, charConstant)
                val charValueOffset =
                    metadataTables.blobContentOffset(image, charValueIndex)
                image[charValueOffset] = 0
                image[charValueOffset + 1] = 0xd8.toByte()
                writeConstantValueIndex(image, stringConstant, charValueIndex)
            }.constantDefinitions.single { constant -> constant.handle == stringConstant.handle }
            assertEquals(
                DotNetClrConstantValue.StringValue("\ud800"),
                unpairedUtf16.value,
            )
            assertEquals(listOf(0, 216), unpairedUtf16.rawValue.toUnsignedIntList())

            val oddNameProperty = metadata.propertyDefinitions.single { property ->
                property.declaringType == propertyHost.handle && property.name == "Odd Name"
            }
            assertFalse(oddNameProperty.hasDefault)
            val fieldRowWithoutFlag =
                mutatedMetadata("constant-field-row-without-flag") { image ->
                    val fieldAttributesOffset =
                        metadataTables.rowOffset(4, propertySeed.handle.row)
                    val fieldAttributes =
                        readLittleEndianIndex(image, fieldAttributesOffset, 2)
                    writeLittleEndian(
                        image,
                        fieldAttributesOffset,
                        2,
                        fieldAttributes and 0x8000.inv(),
                    )
                }
            val unflaggedPropertySeed =
                fieldRowWithoutFlag.fieldDefinitions.single { field ->
                    field.handle == propertySeed.handle
                }
            assertFalse(unflaggedPropertySeed.hasDefault)
            assertEquals(
                DotNetClrConstantValue.IntegralValue(DotNetClrPrimitiveType.INT32, 73uL),
                fieldRowWithoutFlag.constantDefinitions.single { constant ->
                    constant.parent == unflaggedPropertySeed.handle
                }.value,
            )

            val propertyFlagWithoutRow =
                mutatedMetadata("constant-property-flag-without-row") { image ->
                    val propertyAttributesOffset =
                        metadataTables.rowOffset(23, oddNameProperty.handle.row)
                    val propertyAttributes =
                        readLittleEndianIndex(image, propertyAttributesOffset, 2)
                    writeLittleEndian(
                        image,
                        propertyAttributesOffset,
                        2,
                        propertyAttributes or 0x1000,
                    )
                }
            val flaggedOddName =
                propertyFlagWithoutRow.propertyDefinitions.single { property ->
                    property.handle == oddNameProperty.handle
                }
            assertTrue(flaggedOddName.hasDefault)
            assertTrue(
                propertyFlagWithoutRow.constantDefinitions.none { constant ->
                    constant.parent == flaggedOddName.handle
                }
            )

            val propertyConstantMetadata =
                mutatedMetadata("constant-property-parent") { image ->
                    val parentOffset =
                        metadataTables.rowOffset(11, constantsByParent.getValue(propertySeed.handle).handle.row) + 2
                    writeLittleEndian(
                        image,
                        parentOffset,
                        metadataTables.hasConstantIndexSize,
                        (oddNameProperty.handle.row shl 2) or 2,
                    )
                    val fieldAttributesOffset =
                        metadataTables.rowOffset(4, propertySeed.handle.row)
                    val fieldAttributes =
                        readLittleEndianIndex(image, fieldAttributesOffset, 2)
                    writeLittleEndian(
                        image,
                        fieldAttributesOffset,
                        2,
                        fieldAttributes and 0x8000.inv(),
                    )
                    val propertyAttributesOffset =
                        metadataTables.rowOffset(23, oddNameProperty.handle.row)
                    val propertyAttributes =
                        readLittleEndianIndex(image, propertyAttributesOffset, 2)
                    writeLittleEndian(
                        image,
                        propertyAttributesOffset,
                        2,
                        propertyAttributes or 0x1000,
                    )
                }
            val mutatedProperty = propertyConstantMetadata.propertyDefinitions.single { property ->
