            )
            val malformedMemberReferenceImage = assembly.readBytes()
            val memberReferenceSignatureIndexOffset =
                metadataTables.rowOffset(10, emptyFieldReference.handle.row) +
                        metadataTables.memberRefParentIndexSize +
                        metadataTables.stringIndexSize
            val memberReferenceSignatureIndex = readLittleEndianIndex(
                malformedMemberReferenceImage,
                memberReferenceSignatureIndexOffset,
                metadataTables.blobIndexSize,
            )
            val fieldSignatureOffset = metadataTables.blobContentOffset(
                malformedMemberReferenceImage,
                memberReferenceSignatureIndex,
            )
            malformedMemberReferenceImage[fieldSignatureOffset] = 0x07
            malformedMemberReferenceAssembly.writeBytes(malformedMemberReferenceImage)
            val malformedMemberReference = assertThrows(DotNetBadImageFormatException::class.java) {
                DotNetClrMetadataReader.read(malformedMemberReferenceAssembly)
            }
            assertTrue(
                "unsupported signature calling convention 0x7" in
                        checkNotNull(malformedMemberReference.message)
            ) {
                malformedMemberReference.message
            }

            val malformedFieldAssembly = File(
                assembly.parentFile,
                "ImporterFixture-malformed-field-signature.dll",
            )
            val malformedFieldImage = assembly.readBytes()
            val rawNativeFieldSignature = ByteArray(nativeValueField.rawSignature.size) { index ->
                nativeValueField.rawSignature[index].toByte()
            }
            val nativeFieldSignatureOffset =
                malformedFieldImage.uniqueSequenceOffset(rawNativeFieldSignature)
            malformedFieldImage[nativeFieldSignatureOffset] = 0x07
            malformedFieldAssembly.writeBytes(malformedFieldImage)
            val malformedField = assertThrows(DotNetBadImageFormatException::class.java) {
                DotNetClrMetadataReader.read(malformedFieldAssembly)
            }
            assertTrue(
                "invalid field signature header" in checkNotNull(malformedField.message)
            ) {
                malformedField.message
            }
        }

        val modernGenericsSource = File(tmpdir, "clr-metadata/ModernGenerics.cs").apply {
            writeText(
                """
                namespace ModernGenerics
                {
                    public interface IVariance<out TOut, in TIn>
                    {
                    }

                    public class ConstraintBase
                    {
                    }

                    public interface IConstraint
                    {
                    }

                    public static class GenericHost
                    {
                        public static T AcceptReference<T>(T value)
                            where T : class, new()
                            => value;

                        public static T AcceptValue<T>(T value)
                            where T : struct
                            => value;

                        public static T AcceptByRefLike<T>(T value)
                            where T : allows ref struct
                            => value;

                        public static TResult Convert<TSource, TResult>(TSource value)
                            where TSource : ConstraintBase, IConstraint, new()
                            where TResult : TSource, IConstraint
                            => default;
                    }
                }
                """.trimIndent()
            )
        }
        val modernGenericsAssembly = File(tmpdir, "clr-metadata/ModernGenerics.dll")
        val modernGenericsCompile = runModernCSharpCompiler(
            checkNotNull(modernCSharp),
            modernGenericsSource,
            modernGenericsAssembly,
        )
        assertEquals(0, modernGenericsCompile.exitCode, modernGenericsCompile.output)
        val modernGenericsMetadata = DotNetClrMetadataReader.read(modernGenericsAssembly)
        val modernGenericTypes = modernGenericsMetadata.typeDefinitions
            .filter { type -> type.namespaceName == "ModernGenerics" }
            .associateBy(DotNetClrTypeDefinition::metadataName)
        val varianceType = modernGenericTypes.getValue("IVariance`2")
        assertEquals(
            listOf(
                DotNetClrGenericParameterVariance.COVARIANT,
                DotNetClrGenericParameterVariance.CONTRAVARIANT,
            ),
            modernGenericsMetadata.genericParameterDefinitions
                .filter { parameter -> parameter.owner == varianceType.handle }
                .sortedBy(DotNetClrGenericParameterDefinition::number)
                .map(DotNetClrGenericParameterDefinition::variance),
        )
        val modernMethods = modernGenericsMetadata.methodDefinitions.associateBy(DotNetClrMethodDefinition::name)
        val referenceParameter = modernGenericsMetadata.genericParameterDefinitions.single { parameter ->
            parameter.owner == modernMethods.getValue("AcceptReference").handle
        }
        assertTrue(referenceParameter.hasReferenceTypeConstraint)
        assertTrue(referenceParameter.hasDefaultConstructorConstraint)
        assertFalse(referenceParameter.hasNotNullableValueTypeConstraint)
        assertFalse(referenceParameter.allowsByRefLike)
        val valueParameter = modernGenericsMetadata.genericParameterDefinitions.single { parameter ->
            parameter.owner == modernMethods.getValue("AcceptValue").handle
        }
        assertFalse(valueParameter.hasReferenceTypeConstraint)
        assertTrue(valueParameter.hasNotNullableValueTypeConstraint)
        assertTrue(valueParameter.hasDefaultConstructorConstraint)
        assertFalse(valueParameter.allowsByRefLike)
        val byRefLikeParameter = modernGenericsMetadata.genericParameterDefinitions.single { parameter ->
            parameter.owner == modernMethods.getValue("AcceptByRefLike").handle
        }
        assertTrue(byRefLikeParameter.allowsByRefLike)
        assertFalse(byRefLikeParameter.hasReferenceTypeConstraint)
        assertFalse(byRefLikeParameter.hasNotNullableValueTypeConstraint)
        assertFalse(byRefLikeParameter.hasDefaultConstructorConstraint)
        val convertParameters = modernGenericsMetadata.genericParameterDefinitions
            .filter { parameter -> parameter.owner == modernMethods.getValue("Convert").handle }
            .sortedBy(DotNetClrGenericParameterDefinition::number)
        assertEquals(listOf("TSource", "TResult"), convertParameters.map(DotNetClrGenericParameterDefinition::name))
        assertEquals(
            listOf(2, 2),
            convertParameters.map { parameter ->
                modernGenericsMetadata.genericParameterConstraints.count { constraint ->
                    constraint.owner == parameter.handle
                }
            },
        )

        val refFieldProducerSource = File(tmpdir, "clr-metadata/RefFieldProducer.cs").apply {
            writeText(
                """
                namespace ModernFields
                {
                    public ref struct RefFieldOwner
                    {
                        public ref int Value;

                        public RefFieldOwner(ref int value)
                        {
                            Value = ref value;
                        }
                    }
                }
                """.trimIndent()
            )
        }
        val refFieldProducerAssembly = File(tmpdir, "clr-metadata/RefFieldProducer.dll")
        val refFieldProducerCompile = runModernCSharpCompiler(
            checkNotNull(modernCSharp),
            refFieldProducerSource,
            refFieldProducerAssembly,
        )
        assertEquals(0, refFieldProducerCompile.exitCode, refFieldProducerCompile.output)
        val refFieldProducerMetadata = DotNetClrMetadataReader.read(refFieldProducerAssembly)
        val refFieldOwnerDefinition = refFieldProducerMetadata.typeDefinitions.single { definition ->
            definition.namespaceName == "ModernFields" && definition.metadataName == "RefFieldOwner"
        }
        val refFieldDefinition = refFieldProducerMetadata.fieldDefinitions.single { field ->
            field.declaringType == refFieldOwnerDefinition.handle && field.name == "Value"
        }
        assertEquals(
            DotNetClrFieldSignature(
                DotNetClrTypeSignature.ByReference(
                    DotNetClrTypeSignature.Primitive(DotNetClrPrimitiveType.INT32)
                )
            ),
            refFieldDefinition.signature,
        )
        val refFieldConsumerSource = File(tmpdir, "clr-metadata/RefFieldConsumer.cs").apply {
            writeText(
                """
                namespace ModernFields
                {
                    public static class RefFieldConsumer
                    {
                        public static ref int Read(ref RefFieldOwner owner)
                            => ref owner.Value;
                    }
                }
                """.trimIndent()
            )
        }
        val refFieldConsumerAssembly = File(tmpdir, "clr-metadata/RefFieldConsumer.dll")
        val refFieldConsumerCompile = runModernCSharpCompiler(
            checkNotNull(modernCSharp),
            refFieldConsumerSource,
            refFieldConsumerAssembly,
            refFieldProducerAssembly,
        )
        assertEquals(0, refFieldConsumerCompile.exitCode, refFieldConsumerCompile.output)
        val refFieldConsumerMetadata = DotNetClrMetadataReader.read(refFieldConsumerAssembly)
        val refFieldOwnerReference = refFieldConsumerMetadata.typeReferences.single { reference ->
            reference.namespaceName == "ModernFields" && reference.metadataName == "RefFieldOwner"
        }
        val refFieldReference = refFieldConsumerMetadata.memberReferences.single { reference ->
            reference.name == "Value" && reference.parent == refFieldOwnerReference.handle
        }
        assertEquals(
            DotNetClrMemberReferenceSignature.Field(
                DotNetClrFieldSignature(
                    DotNetClrTypeSignature.ByReference(
                        DotNetClrTypeSignature.Primitive(DotNetClrPrimitiveType.INT32)
                    )
                )
            ),
            refFieldReference.signature,
        )

        val profileCoreAssemblies = listOf(
            checkNotNull(frameworkIlasm).parentFile.resolve("mscorlib.dll") to "mscorlib",
            checkNotNull(modernCSharp).referenceDirectory.resolve("System.Runtime.dll") to "System.Runtime",
        )
        for (entry in profileCoreAssemblies) {
            val coreAssembly = entry.first
            assertTrue(coreAssembly.isFile) { "Missing profile core assembly '${coreAssembly.path}'" }
            val coreMetadata = DotNetClrMetadataReader.read(coreAssembly)
            assertEquals(entry.second, coreMetadata.identity.name)
            assertTrue(coreMetadata.identity.hasPublicKey)
            assertTrue(coreMetadata.identity.publicKey.isNotEmpty())
            assertEquals(8, coreMetadata.identity.publicKeyToken.size)
            assertTrue(coreMetadata.typeDefinitions.size > 100)
            assertTrue(coreMetadata.fieldDefinitions.size > 100)
            assertTrue(coreMetadata.methodDefinitions.size > 100)
            assertTrue(coreMetadata.memberReferences.isNotEmpty())
            assertTrue(coreMetadata.customAttributes.isNotEmpty())
            assertTrue(coreMetadata.propertyDefinitions.isNotEmpty())
            assertTrue(coreMetadata.methodSemantics.isNotEmpty())
            assertTrue(coreMetadata.genericParameterDefinitions.isNotEmpty())
            assertTrue(coreMetadata.genericParameterConstraints.isNotEmpty())
            if (entry.second == "System.Runtime") {
                assertTrue(
                    coreMetadata.typeSpecifications.any { specification ->
                        specification.signature is DotNetClrTypeSignature.Modified
                    }
                ) { "The net10 reference assembly no longer exercises a modified TypeSpec root" }
            }
        }
    }

