        val functionPointerType = DotNetClrResolvedTypeSignature.FunctionPointer(
            DotNetClrResolvedMethodSignature(
                callingConvention = DotNetClrSignatureCallingConvention.DEFAULT,
                hasThis = false,
                hasExplicitThis = false,
