                ).constraints

        fun resolvedConstructedConstraints(
            metadataName: String,
            argument: DotNetClrResolvedTypeSignature,
        ): DotNetClrResolvedConstructedTypeConstraints =
            resolvedConstructedConstraints(metadataName, listOf(argument))

