        assertSame(
            DotNetClrSpecialConstraintSatisfaction.Satisfied,
            specialSatisfaction(
                ordinaryAllowedArgument,
                DotNetClrSpecialConstraintKind.BY_REF_LIKE_ELIGIBILITY,
