        assertNamedArgumentFailure(
            DotNetClrCustomAttributeNamedArgumentValidationFailure.PROPERTY_SETTER_MISSING,
            integerNamedArgument.copy(
                kind = DotNetClrCustomAttributeNamedArgumentKind.PROPERTY,
                name = "ReadOnlyProperty",
            ),
        )
        assertNamedArgumentFailure(
            DotNetClrCustomAttributeNamedArgumentValidationFailure.PROPERTY_GETTER_MISSING,
            integerNamedArgument.copy(
                kind = DotNetClrCustomAttributeNamedArgumentKind.PROPERTY,
                name = "WriteOnlyProperty",
            ),
        )
        assertNamedArgumentFailure(
            DotNetClrCustomAttributeNamedArgumentValidationFailure
                .PROPERTY_ACCESSOR_NOT_PUBLIC,
            integerNamedArgument.copy(
                kind = DotNetClrCustomAttributeNamedArgumentKind.PROPERTY,
                name = "PrivateSetterProperty",
            ),
        )
        assertNamedArgumentFailure(
            DotNetClrCustomAttributeNamedArgumentValidationFailure.PROPERTY_IS_INDEXED,
            integerNamedArgument.copy(
                kind = DotNetClrCustomAttributeNamedArgumentKind.PROPERTY,
                name = "Item",
            ),
        )
        val duplicateNamedArgument = namedArgumentValidator.validate(
            decodedModernAttributeValues.first().copy(
                namedArguments = listOf(
                    integerNamedArgument,
                    integerNamedArgument.copy(
                        value = DotNetClrCustomAttributeValue.IntegralValue(
                            DotNetClrPrimitiveType.INT32,
                            100uL,
                        )
                    ),
                )
            )
        ) as DotNetClrCustomAttributeNamedArgumentValidation.Invalid
        assertEquals(
            DotNetClrCustomAttributeNamedArgumentValidationFailure.DUPLICATE_MEMBER,
            duplicateNamedArgument.failure,
        )
        assertEquals(1, duplicateNamedArgument.namedArgumentIndex)

        fun validateAgainstMetadata(
            selectedMetadata: DotNetClrAssemblyMetadata,
            namedArguments: List<DotNetClrCustomAttributeNamedArgument>,
            inheritanceLimit: Int = 256,
        ): DotNetClrCustomAttributeNamedArgumentValidation {
            val selectedResolver = DotNetClrTypeResolver(
                DotNetClrAssemblyReferenceBinder { sourceAssembly, reference ->
                    if (sourceAssembly === selectedMetadata &&
                        reference.name == systemRuntimeMetadata.identity.name
                    ) {
                        systemRuntimeMetadata
                    } else {
                        null
                    }
                }
            )
            val selectedAttributeType = DotNetClrResolvedTypeDefinition(
                selectedMetadata,
                selectedMetadata.typeDefinitions.single { definition ->
                    definition.handle ==
                            decodedModernAttributeValues.first()
                                .constructor.attributeType.type.definition.handle
                },
            )
            val selectedAttribute = decodedModernAttributeValues.first().copy(
                constructor = decodedModernAttributeValues.first().constructor.copy(
                    sourceAssembly = selectedMetadata,
                    attributeType = DotNetClrResolvedTypeView(
                        selectedAttributeType,
                        emptyList(),
                    ),
                ),
                namedArguments = namedArguments,
            )
            return DotNetClrCustomAttributeNamedArgumentValidator(
                selectedResolver,
                DotNetClrCustomAttributeCoreTypes(
                    systemAttribute,
                    systemEnum,
                    systemType,
                ),
                inheritanceLimit,
            ).validate(selectedAttribute)
        }

        val inheritedIntegerArgument =
            decodedModernAttributeValues.first().namedArguments.single { argument ->
                argument.name == "InheritedField"
            }
        val semanticProbeType =
            decodedModernAttributeValues.first().constructor.attributeType.type.definition
        val semanticProbeBaseSpecification =
            destinationMetadata.typeSpecifications.single { specification ->
                specification.handle == semanticProbeType.baseType
            }
        val semanticProbeBaseSignature =
            semanticProbeBaseSpecification.signature as DotNetClrTypeSignature.GenericInstance
        val invalidGenericArityMetadata = destinationMetadata.copy(
            typeSpecifications = destinationMetadata.typeSpecifications.map { specification ->
                if (specification.handle == semanticProbeBaseSpecification.handle) {
                    specification.copy(
                        signature = semanticProbeBaseSignature.copy(arguments = emptyList())
                    )
                } else {
                    specification
                }
            }
        )
        val invalidGenericArity = validateAgainstMetadata(
            invalidGenericArityMetadata,
            listOf(inheritedIntegerArgument),
        ) as DotNetClrCustomAttributeNamedArgumentValidation.Invalid
        assertEquals(
            DotNetClrCustomAttributeNamedArgumentValidationFailure
                .INVALID_RESOLVED_SIGNATURE,
            invalidGenericArity.failure,
        )
        assertEquals(
            1,
            invalidGenericArity.signatureResolution?.expectedGenericArity,
        )
        assertEquals(
            0,
            invalidGenericArity.signatureResolution?.actualGenericArity,
        )

        val invalidSubstitutionMetadata = destinationMetadata.copy(
            fieldDefinitions = destinationMetadata.fieldDefinitions.map { field ->
                if (field.handle == inheritedField.field.handle) {
                    field.copy(
                        signature = field.signature.copy(
                            fieldType = DotNetClrTypeSignature.GenericParameter(
                                DotNetClrGenericParameterKind.TYPE,
                                1,
                            )
                        )
                    )
                } else {
                    field
                }
            }
        )
        val invalidSubstitution = validateAgainstMetadata(
            invalidSubstitutionMetadata,
            listOf(inheritedIntegerArgument),
        ) as DotNetClrCustomAttributeNamedArgumentValidation.Invalid
        assertEquals(
            DotNetClrCustomAttributeNamedArgumentValidationFailure
                .GENERIC_SUBSTITUTION_FAILED,
            invalidSubstitution.failure,
        )
        assertEquals(1, invalidSubstitution.signatureSubstitution?.parameterIndex)
        assertEquals(1, invalidSubstitution.signatureSubstitution?.argumentCount)

        val cyclicMetadata = destinationMetadata.copy(
            typeDefinitions = destinationMetadata.typeDefinitions.map { definition ->
                if (definition.handle == semanticProbeType.handle) {
                    definition.copy(baseType = definition.handle)
                } else {
                    definition
                }
            }
        )
        val inheritanceCycle = validateAgainstMetadata(
            cyclicMetadata,
            listOf(integerNamedArgument.copy(name = "Missing")),
        ) as DotNetClrCustomAttributeNamedArgumentValidation.Invalid
        assertEquals(
            DotNetClrCustomAttributeNamedArgumentValidationFailure.INHERITANCE_CYCLE,
            inheritanceCycle.failure,
        )
        val inheritanceLimit = validateAgainstMetadata(
            destinationMetadata,
            listOf(integerNamedArgument.copy(name = "Missing")),
            inheritanceLimit = 1,
        ) as DotNetClrCustomAttributeNamedArgumentValidation.Invalid
        assertEquals(
            DotNetClrCustomAttributeNamedArgumentValidationFailure
                .INHERITANCE_LIMIT_EXCEEDED,
            inheritanceLimit.failure,
        )

        val noteArgument =
            decodedModernAttributeValues.first().namedArguments.single { argument ->
                argument.name == "Note"
            }
        val noteProperty = destinationMetadata.propertyDefinitions.single { property ->
            property.declaringType == semanticProbeType.handle &&
                    property.name == "Note"
        }
        val noteGetter = destinationMetadata.methodSemantics.single { semantics ->
            semantics.association == noteProperty.handle &&
                    semantics.kind == DotNetClrMethodSemanticsKind.GETTER
        }
        val duplicateAccessorMetadata = destinationMetadata.copy(
            methodSemantics = destinationMetadata.methodSemantics +
                    noteGetter.copy(
                        handle = DotNetClrMetadataHandle(
                            24,
                            destinationMetadata.methodSemantics.maxOf { semantics ->
                                semantics.handle.row
                            } + 1,
                        )
                    )
        )
        val duplicateAccessor = validateAgainstMetadata(
            duplicateAccessorMetadata,
            listOf(noteArgument),
        ) as DotNetClrCustomAttributeNamedArgumentValidation.Invalid
        assertEquals(
            DotNetClrCustomAttributeNamedArgumentValidationFailure
                .PROPERTY_ACCESSOR_AMBIGUOUS,
            duplicateAccessor.failure,
        )

        val resolvedNested = (
                serializedTypeResolver.resolve(
                    destinationMetadata,
                    "Forwarded.Outer+Inner, ForwardDestination",
                ) as DotNetClrSerializedTypeResolution.Resolved
                ).type as DotNetClrResolvedSerializedType.Named
        assertSame(destinationMetadata, resolvedNested.type.assembly)
        assertEquals("Inner", resolvedNested.type.definition.metadataName)

        val resolvedGeneric = (
                serializedTypeResolver.resolve(
                    destinationMetadata,
                    "Forwarded.Generic`1+Nested`1" +
                            "[[System.String, System.Runtime]," +
                            "[Forwarded.ExternalKind, ForwardDestination]]" +
                            "[]&, ForwardDestination",
                ) as DotNetClrSerializedTypeResolution.Resolved
                ).type as DotNetClrResolvedSerializedType.ByReference
        val resolvedGenericArray =
            resolvedGeneric.elementType as DotNetClrResolvedSerializedType.SzArray
        val resolvedGenericInstance =
            resolvedGenericArray.elementType as
                    DotNetClrResolvedSerializedType.GenericInstance
        assertEquals("Nested`1", resolvedGenericInstance.genericType.type.definition.metadataName)
        assertEquals(2, resolvedGenericInstance.arguments.size)
        assertEquals(
            "String",
            (
                    resolvedGenericInstance.arguments[0] as
                            DotNetClrResolvedSerializedType.Named
                    ).type.definition.metadataName,
        )
        assertEquals(
            forwardedEnum,
            (
                    resolvedGenericInstance.arguments[1] as
                            DotNetClrResolvedSerializedType.Named
                    ).type,
        )

        val unqualifiedGenericArgument = (
                serializedTypeResolver.resolve(
                    destinationMetadata,
                    "Forwarded.Generic`1[Forwarded.ExternalKind], ForwardDestination",
                ) as DotNetClrSerializedTypeResolution.Resolved
                ).type as DotNetClrResolvedSerializedType.GenericInstance
        assertEquals(
            forwardedEnum,
            (
                    unqualifiedGenericArgument.arguments.single() as
                            DotNetClrResolvedSerializedType.Named
                    ).type,
        )

        val invalidSerializedAssembly =
            serializedTypeResolver.resolve(
                destinationMetadata,
                "Forwarded.Outer, Broken, Version=1",
            ) as DotNetClrSerializedTypeResolution.InvalidAssemblyName
        assertEquals(
            DotNetClrSerializedAssemblyNameFailure.INVALID_VERSION,
            invalidSerializedAssembly.parsing.failure,
        )
        val unboundSerializedAssembly =
            serializedTypeResolver.resolve(
                destinationMetadata,
                "Forwarded.Outer, Missing",
            ) as DotNetClrSerializedTypeResolution.UnboundAssembly
        assertEquals("Missing", unboundSerializedAssembly.assemblyName?.name)
        val missingGenericArgumentAssembly =
            serializedTypeResolver.resolve(
                destinationMetadata,
                "Forwarded.Generic`1[[Forwarded.ExternalKind, Missing]], " +
                        "ForwardDestination",
            ) as DotNetClrSerializedTypeResolution.UnboundAssembly
        assertEquals(listOf(0), missingGenericArgumentAssembly.genericArgumentPath)

        val nextTypeReferenceRow =
            (facadeMetadata.typeReferences.maxOfOrNull { reference -> reference.handle.row } ?: 0) + 1
        val forwardedOuterReference = DotNetClrTypeReference(
            handle = DotNetClrMetadataHandle(1, nextTypeReferenceRow),
            namespaceName = "Forwarded",
            metadataName = "Outer",
            resolutionScope = null,
        )
        val nestedReference = DotNetClrTypeReference(
            handle = DotNetClrMetadataHandle(1, nextTypeReferenceRow + 1),
            namespaceName = "",
            metadataName = "Inner",
            resolutionScope = forwardedOuterReference.handle,
        )
        facadeConsumerMetadata = facadeMetadata.copy(
            typeReferences = facadeMetadata.typeReferences +
                    forwardedOuterReference +
                    nestedReference,
        )
        val nestedResolution = resolver.resolveTypeDefinition(
            checkNotNull(facadeConsumerMetadata),
            nestedReference.handle,
        )
        val nestedType = (nestedResolution as DotNetClrTypeResolution.Resolved).type
        assertSame(destinationMetadata, nestedType.assembly)
        assertEquals("Inner", nestedType.definition.metadataName)
        assertEquals(
            outerDefinition.handle,
            nestedType.definition.declaringType,
        )

        fun emptyAssembly(
            name: String,
            assemblyReferences: List<DotNetClrAssemblyReference> = emptyList(),
            typeDefinitions: List<DotNetClrTypeDefinition> = emptyList(),
            exportedTypes: List<DotNetClrExportedType> = emptyList(),
        ): DotNetClrAssemblyMetadata =
            DotNetClrAssemblyMetadata(
                identity = DotNetManagedAssemblyIdentity(
                    name = name,
                    version = "1.0.0.0",
                    culture = "neutral",
                    publicKey = emptyList(),
                    publicKeyToken = emptyList(),
                ),
                assemblyReferences = assemblyReferences,
                typeReferences = emptyList(),
                typeDefinitions = typeDefinitions,
                interfaceImplementations = emptyList(),
                exportedTypes = exportedTypes,
                typeSpecifications = emptyList(),
                fieldDefinitions = emptyList(),
                methodDefinitions = emptyList(),
                parameterDefinitions = emptyList(),
                constantDefinitions = emptyList(),
                fieldMarshalDefinitions = emptyList(),
                memberReferences = emptyList(),
                customAttributes = emptyList(),
                propertyDefinitions = emptyList(),
                methodSemantics = emptyList(),
                genericParameterDefinitions = emptyList(),
                genericParameterConstraints = emptyList(),
            )

        fun forwardingAssembly(name: String, targetName: String): DotNetClrAssemblyMetadata {
            val referenceHandle = DotNetClrMetadataHandle(35, 1)
            return emptyAssembly(
                name = name,
                assemblyReferences = listOf(
                    DotNetClrAssemblyReference(
                        handle = referenceHandle,
                        name = targetName,
                        version = "1.0.0.0",
                        culture = "neutral",
                        flags = 0,
                        publicKeyOrToken = emptyList(),
                        hashValue = emptyList(),
                    )
                ),
                exportedTypes = listOf(
                    DotNetClrExportedType(
                        handle = DotNetClrMetadataHandle(39, 1),
                        attributes = 0x0020_0001,
                        typeDefinitionId = 0,
                        namespaceName = "Cycle",
                        metadataName = "Loop",
                        implementation = referenceHandle,
                    )
                ),
            )
        }

        val cycleLeft = forwardingAssembly("CycleLeft", "CycleRight")
        val cycleRight = forwardingAssembly("CycleRight", "CycleLeft")
        val cycleResolver = DotNetClrTypeResolver(
            DotNetClrAssemblyReferenceBinder { sourceAssembly, reference ->
                when {
                    sourceAssembly === cycleLeft && reference.name == "CycleRight" -> cycleRight
                    sourceAssembly === cycleRight && reference.name == "CycleLeft" -> cycleLeft
                    else -> null
                }
            }
        )
        val cycle = cycleResolver.resolveTopLevelType(cycleLeft, "Cycle", "Loop")
            as DotNetClrTypeResolution.Unresolved
        assertEquals(DotNetClrTypeResolutionFailure.TYPE_RESOLUTION_CYCLE, cycle.failure)

        val ambiguousAssembly = emptyAssembly(
            name = "Ambiguous",
            typeDefinitions = listOf(
                DotNetClrTypeDefinition(
                    handle = DotNetClrMetadataHandle(2, 1),
                    namespaceName = "Broken",
                    metadataName = "Duplicate",
                    attributes = 1,
                    baseType = null,
                    declaringType = null,
                ),
                DotNetClrTypeDefinition(
                    handle = DotNetClrMetadataHandle(2, 2),
                    namespaceName = "Broken",
                    metadataName = "Duplicate",
                    attributes = 1,
                    baseType = null,
                    declaringType = null,
                ),
            ),
        )
        val ambiguous = DotNetClrTypeResolver(
            DotNetClrAssemblyReferenceBinder { _, _ -> null }
        ).resolveTopLevelType(ambiguousAssembly, "Broken", "Duplicate")
            as DotNetClrTypeResolution.Unresolved
        assertEquals(DotNetClrTypeResolutionFailure.AMBIGUOUS_TYPE, ambiguous.failure)

        val inheritanceCycleAssembly = emptyAssembly(
            name = "InheritanceCycle",
            typeDefinitions = listOf(
                DotNetClrTypeDefinition(
                    handle = DotNetClrMetadataHandle(2, 1),
                    namespaceName = "Broken",
                    metadataName = "Left",
                    attributes = 1,
                    baseType = DotNetClrMetadataHandle(2, 2),
                    declaringType = null,
                ),
                DotNetClrTypeDefinition(
                    handle = DotNetClrMetadataHandle(2, 2),
                    namespaceName = "Broken",
                    metadataName = "Right",
                    attributes = 1,
                    baseType = DotNetClrMetadataHandle(2, 1),
                    declaringType = null,
                ),
            ),
        )
        val inheritanceCycleResolver = DotNetClrTypeResolver(
            DotNetClrAssemblyReferenceBinder { _, _ -> null }
        )
        val inheritanceCycleType = (
                inheritanceCycleResolver.resolveTypeDefinition(
                    inheritanceCycleAssembly,
                    DotNetClrMetadataHandle(2, 1),
                ) as DotNetClrTypeResolution.Resolved
                ).type
        assertEquals(
            DotNetClrTypeHierarchyResolution.InheritanceCycle,
            inheritanceCycleResolver.isSameOrDerivedFrom(
                inheritanceCycleType,
                systemAttribute,
            ),
        )

        val unbound = DotNetClrTypeResolver(
            DotNetClrAssemblyReferenceBinder { _, _ -> null }
        ).resolveTopLevelType(facadeMetadata, "Forwarded", "ExternalKind")
            as DotNetClrTypeResolution.Unresolved
        assertEquals(DotNetClrTypeResolutionFailure.UNBOUND_ASSEMBLY_REFERENCE, unbound.failure)

        val multiModuleAssembly = emptyAssembly(
            name = "MultiModule",
            exportedTypes = listOf(
                DotNetClrExportedType(
                    handle = DotNetClrMetadataHandle(39, 1),
                    attributes = 1,
                    typeDefinitionId = 1,
                    namespaceName = "External",
                    metadataName = "FromAnotherModule",
                    implementation = DotNetClrMetadataHandle(38, 1),
                )
            ),
        )
        val unsupportedMultiModule = DotNetClrTypeResolver(
            DotNetClrAssemblyReferenceBinder { _, _ -> null }
        ).resolveTopLevelType(
            multiModuleAssembly,
            "External",
            "FromAnotherModule",
        ) as DotNetClrTypeResolution.Unresolved
        assertEquals(
            DotNetClrTypeResolutionFailure.UNSUPPORTED_MULTI_MODULE_REFERENCE,
            unsupportedMultiModule.failure,
        )
    }

    @Test
    fun testKotlinClassifierPhysicalOwnersRoundTrip() {
        val declarations = mapOf(
            "C:sample/Producer" to DotNetPhysicalDeclaration.Class(
                ownerPath = listOf("sample.Producer"),
            ),
            "C:sample/Consumer" to DotNetPhysicalDeclaration.Class(
                ownerPath = listOf("sample.Consumer"),
            ),
            "C:sample/Box" to DotNetPhysicalDeclaration.Class(
                ownerPath = listOf("sample.Box"),
                valueClassAbi = DotNetValueClassAbi(
                    primaryConstructorMethodName = "constructor-impl",
                    boxMethodName = "box-impl",
                    unboxMethodName = "unbox-impl",
                ),
            ),
            "C:sample/Counter" to DotNetPhysicalDeclaration.Class(
                ownerPath = listOf("sample.Counter"),
                staticInitialization = DotNetStaticInitialization(
                    ownerPath = listOf("sample.Counter", "<CompanionStatics>"),
                    methodName = "<EnsureInitialized>",
                ),
                objectInstance = DotNetObjectInstance(
                    ownerPath = listOf("sample.Counter", "<CompanionStatics>"),
                    fieldName = "INSTANCE",
                ),
            ),
            "F:sample/increment" to DotNetPhysicalDeclaration.Function(
                ownerPath = listOf("sample.LibraryKt"),
                methodName = "Increment",
                isInstance = false,
            ),
            "F:sample/abstractWithDefaults" to DotNetPhysicalDeclaration.Function(
                ownerPath = listOf("sample.Contract"),
                methodName = "abstractWithDefaults",
                isInstance = true,
                defaultArgumentDispatcher = DotNetDefaultArgumentDispatcher(
                    ownerPath = listOf("sample.Contract", "__KotlinDefaultImpls"),
                    methodName = "abstractWithDefaults\$default",
                ),
            ),
            "F:sample/defaultWithDefaults" to DotNetPhysicalDeclaration.Function(
                ownerPath = listOf("sample.Contract"),
                methodName = "defaultWithDefaults",
                isInstance = true,
                interfaceDefaultImplementation = DotNetInterfaceDefaultImplementation(
                    bodyPlacement = DotNetInterfaceDefaultBodyPlacement.HELPER_ONLY,
                    helperOwnerPath = listOf("sample.Contract", "__KotlinDefaultImpls"),
                    helperMethodName = "defaultWithDefaults",
                ),
                defaultArgumentDispatcher = DotNetDefaultArgumentDispatcher(
                    ownerPath = listOf("sample.Contract", "__KotlinDefaultImpls"),
                    methodName = "defaultWithDefaults\$default",
                ),
            ),
            "B:C:sample/Contract:F:sample/defaultWithDefaults:CANONICAL" to
                    DotNetPhysicalDeclaration.GenericInterfaceViewBridge(
                        ownerPath = listOf("sample.Contract"),
                        ownerLogicalKey = "C:sample/Contract",
                        inheritedLogicalMemberKey = "F:sample/defaultWithDefaults",
                        physicalView = DotNetInterfaceDefaultPromotionView.CANONICAL,
                        implementationMethodName = "<GenericInterfaceCanonicalBridge-defaultWithDefaults>",
                    ),
            "R:C:sample/Contract:F:sample/baseValue" to
                    DotNetPhysicalDeclaration.CovariantReturnBridge(
                        ownerPath = listOf("sample.Contract"),
                        ownerLogicalKey = "C:sample/Contract",
                        inheritedLogicalMemberKey = "F:sample/baseValue",
                        implementationMethodName = "<CovariantReturnBridge-baseValue>",
                    ),
            "W:C:sample/Consumer:F:sample/defaultWithDefaults:CANONICAL" to
                    DotNetPhysicalDeclaration.InterfaceDefaultClassForwarder(
                        ownerPath = listOf("sample.Consumer"),
                        ownerLogicalKey = "C:sample/Consumer",
                        inheritedLogicalMemberKey = "F:sample/defaultWithDefaults",
                        physicalView = DotNetInterfaceDefaultPromotionView.CANONICAL,
                        implementationMethodName = "<InterfaceDefaultForwarder-defaultWithDefaults>",
                    ),
        )
        val properties = Properties().apply {
            setProperty(DotNetLibraryAbiCodec.ABI_VERSION_PROPERTY, DotNetLibraryAbiCodec.ABI_VERSION)
            putAll(DotNetLibraryAbiCodec.encode(declarations))
        }

        assertEquals(
            DotNetLibraryAbiCodec.ABI_VERSION,
            properties.getProperty(DotNetLibraryAbiCodec.ABI_VERSION_PROPERTY),
        )
        assertEquals(declarations, DotNetLibraryAbiCodec.decode(properties))
        assertEquals(
            "be089ff358019a018b5e1ce2af85aedd",
            DotNetLibraryAbiCodec.logicalIdentityDigest("F:sample/foo|-123456789[0]"),
        )
        assertEquals(
            "faa734fbe159d9bc030a0dd498584bc5",
            DotNetLibraryAbiCodec.logicalIdentityDigest("C:kotlin.collections/List"),
        )
        val friendIdentities = setOf(
            DotNetFriendAssemblyIdentity("Unsigned.Consumer"),
            DotNetFriendAssemblyIdentity("Signed.Consumer", "00112233445566778899AABBCCDDEEFF"),
        )
        assertEquals(
            friendIdentities,
            DotNetLibraryAbiCodec.decodeFriendAssemblies(
                DotNetLibraryAbiCodec.encodeFriendAssemblies(friendIdentities)
            ),
        )
    }

    @Test
    fun testDllManifestExposesOnlyNonGenericInterfacesWithoutKlib() {
        requireOrAssumeToolchain(DotNetIlAssembler.findModernIlasm() != null, "Modern ilasm is not available")
        requireOrAssumeToolchain(
            DotNetIlAssembler.findFrameworkIlasm() != null,
            ".NET Framework ilasm is not available",
        )
        val csharpToolchain = DotNetIlAssembler.findModernCSharpCompiler()
        requireOrAssumeToolchain(
            csharpToolchain != null,
            "Modern Roslyn and the net10 reference pack are not available",
        )
        val modernCSharp = checkNotNull(csharpToolchain)
        val csharpAuthoringTooling = buildCSharpAuthoringTooling(modernCSharp)
        val readerDirectory = File(tmpdir, "csharp-implementation-manifest-reader").apply { mkdirs() }
        val bootstrapSource = readerDirectory.resolve("bootstrap.kt").apply { writeText("fun main() {}") }
        compileInProcess(
            K2DotNetCompiler(),
            bootstrapSource.path,
            K2DotNetCompilerArguments::dotNetTarget.cliArgument, "net10.0",
            K2DotNetCompilerArguments::moduleName.cliArgument, "ManifestReaderBootstrap",
            K2DotNetCompilerArguments::destination.cliArgument,
            readerDirectory.resolve("ManifestReaderBootstrap.dll").path,
        )
        val runtimeAssembly = readerDirectory.resolve("Kotlin.Runtime.dll")
        assertTrue(runtimeAssembly.isFile)

        val readerSource = readerDirectory.resolve("reader.cs").apply {
            writeText(
                """
                using System;
                using System.Collections.Immutable;
                using System.IO;
                using System.Linq;
                using System.Reflection;
                using System.Reflection.Metadata;
                using System.Reflection.PortableExecutable;
                using System.Text;

                public static class Program
                {
                    private static string Encode(string value)
                    {
                        return Convert.ToBase64String(Encoding.UTF8.GetBytes(value));
                    }

                    public static int Main(string[] args)
                    {
                        using (FileStream stream = File.OpenRead(args[0]))
                        using (PEReader pe = new PEReader(stream))
                        {
                            MetadataReader metadata = pe.GetMetadataReader();
                            foreach (ManifestResourceHandle resourceHandle
                                in metadata.ManifestResources)
                            {
                                ManifestResource resource =
                                    metadata.GetManifestResource(resourceHandle);
                                if (metadata.GetString(resource.Name) !=
                                    "${DotNetCSharpImplementationManifestCodec.MANAGED_RESOURCE_NAME}")
                                    continue;
                                if (!resource.Implementation.IsNil)
                                    throw new BadImageFormatException(
                                        "The C# implementation manifest is linked.");
                                DirectoryEntry directory =
                                    pe.PEHeaders.CorHeader.ResourcesDirectory;
                                PEMemoryBlock block =
                                    pe.GetSectionData(directory.RelativeVirtualAddress);
                                int offset = checked((int)resource.Offset);
                                BlobReader resourceReader =
                                    block.GetReader(offset, directory.Size - offset);
                                int resourceSize = resourceReader.ReadInt32();
                                Console.WriteLine(
                                    "R|" + ((int)resource.Attributes) + "|" +
                                    Convert.ToBase64String(
                                        resourceReader.ReadBytes(resourceSize)));
                            }
                            TypeProvider provider = new TypeProvider(metadata);
                            foreach (CustomAttributeHandle attributeHandle
                                in metadata.GetAssemblyDefinition().GetCustomAttributes())
                            {
                                CustomAttribute attribute =
                                    metadata.GetCustomAttribute(attributeHandle);
                                TypeIdentity owner = AttributeOwner(
                                    metadata,
                                    provider,
                                    attribute.Constructor);
                                Console.WriteLine(
                                    "C|" +
                                    Encode(owner.AssemblyName) + "|" +
                                    Encode(owner.Path) + "|" +
                                    Encode(Convert.ToBase64String(
                                        metadata.GetBlobBytes(attribute.Value))));
                            }
                            foreach (TypeDefinitionHandle typeHandle in metadata.TypeDefinitions)
                            {
                                TypeDefinition type = metadata.GetTypeDefinition(typeHandle);
                                TypeIdentity typeIdentity =
                                    provider.FromDefinition(typeHandle);
                                Console.WriteLine(
                                    "D|" +
                                    Encode(typeIdentity.Path) + "|" +
                                    Encode(((int)(
                                        type.Attributes &
                                        TypeAttributes.VisibilityMask)).ToString()));
                                foreach (CustomAttributeHandle attributeHandle
                                    in type.GetCustomAttributes())
                                {
                                    CustomAttribute attribute =
                                        metadata.GetCustomAttribute(attributeHandle);
                                    TypeIdentity attributeOwner = AttributeOwner(
                                        metadata,
                                        provider,
                                        attribute.Constructor);
                                    Console.WriteLine(
                                        "E|" +
                                        Encode(typeIdentity.Path) + "|" +
                                        Encode(attributeOwner.AssemblyName) + "|" +
                                        Encode(attributeOwner.Path) + "|" +
                                        Encode(Convert.ToBase64String(
                                            metadata.GetBlobBytes(attribute.Value))));
                                }
                                foreach (MethodImplementationHandle implementationHandle
                                    in type.GetMethodImplementations())
                                {
                                    MethodImplementation implementation =
                                        metadata.GetMethodImplementation(implementationHandle);
                                    MethodIdentity body = MethodIdentity.Read(
                                        metadata,
                                        provider,
                                        implementation.MethodBody);
                                    MethodIdentity declaration = MethodIdentity.Read(
                                        metadata,
                                        provider,
                                        implementation.MethodDeclaration);
                                    Console.WriteLine(
                                        "P|" +
                                        Encode(body.Owner.Path) + "|" +
                                        Encode(body.Name) + "|" +
                                        Encode(body.IsConcrete.ToString()) + "|" +
                                        Encode(declaration.Owner.AssemblyName) + "|" +
                                        Encode(declaration.Owner.Path) + "|" +
                                        Encode(declaration.Name) + "|" +
                                        Encode(declaration.GenericArity.ToString()) + "|" +
                                        Encode(declaration.ReturnType) + "|" +
                                        Encode(string.Join(
                                            "\u0001",
                                            declaration.ParameterTypes)));
                                }
                                TypeIdentity methodOwner = provider.FromDefinition(typeHandle);
                                foreach (MethodDefinitionHandle methodHandle in type.GetMethods())
                                {
                                    MethodDefinition method = metadata.GetMethodDefinition(methodHandle);
                                    foreach (GenericParameterHandle parameterHandle
                                        in method.GetGenericParameters())
                                    {
                                        GenericParameter parameter =
                                            metadata.GetGenericParameter(parameterHandle);
                                        StringBuilder constraints = new StringBuilder();
                                        foreach (GenericParameterConstraintHandle constraintHandle
                                            in parameter.GetConstraints())
                                        {
                                            GenericParameterConstraint constraint =
                                                metadata.GetGenericParameterConstraint(constraintHandle);
                                            TypeIdentity constraintType =
                                                provider.FromTypeHandle(constraint.Type);
                                            if (constraints.Length != 0)
                                                constraints.Append("\u0001");
                                            constraints.Append(constraintType.AssemblyName);
                                            constraints.Append("\0");
                                            constraints.Append(constraintType.Path);
                                        }
                                        Console.WriteLine(
                                            "G|" +
                                            Encode(methodOwner.Path) + "|" +
                                            Encode(metadata.GetString(method.Name)) + "|" +
                                            Encode(parameter.Index.ToString()) + "|" +
                                            Encode(((int)parameter.Attributes).ToString()) + "|" +
                                            Encode(constraints.ToString()));
                                    }
                                }
                            }
                        }
                        return 0;
                    }

                    private static TypeIdentity AttributeOwner(
                        MetadataReader metadata,
                        TypeProvider provider,
                        EntityHandle constructor)
                    {
                        if (constructor.Kind == HandleKind.MethodDefinition)
                        {
                            MethodDefinition method = metadata.GetMethodDefinition(
                                (MethodDefinitionHandle)constructor);
                            return provider.FromDefinition(method.GetDeclaringType());
                        }
                        if (constructor.Kind == HandleKind.MemberReference)
                        {
                            MemberReference member = metadata.GetMemberReference(
                                (MemberReferenceHandle)constructor);
                            return provider.FromMemberParent(member.Parent);
                        }
                        throw new BadImageFormatException(
                            "Unsupported custom attribute constructor " +
                            constructor.Kind);
                    }
                }

                internal sealed class MethodIdentity
                {
                    internal readonly TypeIdentity Owner;
                    internal readonly string Name;
                    internal readonly int GenericArity;
                    internal readonly string ReturnType;
                    internal readonly ImmutableArray<string> ParameterTypes;
                    internal readonly bool IsConcrete;

                    private MethodIdentity(
                        TypeIdentity owner,
                        string name,
                        int genericArity,
                        string returnType,
                        ImmutableArray<string> parameterTypes,
                        bool isConcrete)
                    {
                        Owner = owner;
                        Name = name;
                        GenericArity = genericArity;
                        ReturnType = returnType;
                        ParameterTypes = parameterTypes;
                        IsConcrete = isConcrete;
                    }

                    internal static MethodIdentity Read(
                        MetadataReader metadata,
                        TypeProvider provider,
                        EntityHandle handle)
                    {
                        if (handle.Kind == HandleKind.MethodDefinition)
                        {
                            MethodDefinition method = metadata.GetMethodDefinition(
                                (MethodDefinitionHandle)handle);
                            MethodSignature<TypeIdentity> signature =
                                method.DecodeSignature(provider, null);
                            return new MethodIdentity(
                                provider.FromDefinition(method.GetDeclaringType()),
                                metadata.GetString(method.Name),
                                signature.GenericParameterCount,
                                signature.ReturnType.Display,
                                signature.ParameterTypes
                                    .Select(type => type.Display)
                                    .ToImmutableArray(),
                                method.RelativeVirtualAddress != 0 &&
                                    (method.Attributes & MethodAttributes.Abstract) == 0);
                        }
                        if (handle.Kind == HandleKind.MemberReference)
                        {
                            MemberReference member = metadata.GetMemberReference(
                                (MemberReferenceHandle)handle);
                            MethodSignature<TypeIdentity> signature =
                                member.DecodeMethodSignature(provider, null);
                            return new MethodIdentity(
                                provider.FromMemberParent(member.Parent),
                                metadata.GetString(member.Name),
                                signature.GenericParameterCount,
                                signature.ReturnType.Display,
                                signature.ParameterTypes
                                    .Select(type => type.Display)
                                    .ToImmutableArray(),
                                false);
                        }
                        if (handle.Kind == HandleKind.MethodSpecification)
                        {
                            MethodSpecification specification = metadata.GetMethodSpecification(
                                (MethodSpecificationHandle)handle);
                            return Read(metadata, provider, specification.Method);
                        }
                        throw new BadImageFormatException(
                            "Unsupported MethodImpl method handle " + handle.Kind);
                    }
                }

                internal sealed class TypeIdentity
                {
                    internal readonly string AssemblyName;
                    internal readonly string Path;
                    internal readonly string Display;

                    internal TypeIdentity(string assemblyName, string path, string display)
                    {
                        AssemblyName = assemblyName;
                        Path = path;
                        Display = display;
                    }

                    internal TypeIdentity WithDisplay(string display)
                    {
                        return new TypeIdentity(AssemblyName, Path, display);
                    }
                }

                internal sealed class TypeProvider :
                    ISignatureTypeProvider<TypeIdentity, object>
                {
                    private readonly MetadataReader metadata;
                    private readonly string currentAssembly;

                    internal TypeProvider(MetadataReader metadata)
                    {
                        this.metadata = metadata;
                        currentAssembly = metadata.GetString(
                            metadata.GetAssemblyDefinition().Name);
                    }

                    internal TypeIdentity FromDefinition(TypeDefinitionHandle handle)
                    {
                        TypeDefinition type = metadata.GetTypeDefinition(handle);
                        string name = metadata.GetString(type.Name);
                        TypeDefinitionHandle declaring = type.GetDeclaringType();
                        string path;
                        if (!declaring.IsNil)
                        {
                            path = FromDefinition(declaring).Path + "\0" + name;
                        }
                        else
                        {
                            string namespaceName = metadata.GetString(type.Namespace);
                            path = namespaceName.Length == 0
                                ? name
                                : namespaceName + "." + name;
                        }
                        return new TypeIdentity(currentAssembly, path, path);
                    }

                    private TypeIdentity FromReference(TypeReferenceHandle handle)
                    {
                        TypeReference type = metadata.GetTypeReference(handle);
                        string name = metadata.GetString(type.Name);
                        EntityHandle scope = type.ResolutionScope;
                        if (scope.Kind == HandleKind.TypeReference)
                        {
                            TypeIdentity declaring = FromReference((TypeReferenceHandle)scope);
                            string path = declaring.Path + "\0" + name;
                            return new TypeIdentity(
                                declaring.AssemblyName,
                                path,
                                path);
                        }
                        string namespaceName = metadata.GetString(type.Namespace);
                        string topLevelPath = namespaceName.Length == 0
                            ? name
                            : namespaceName + "." + name;
                        return new TypeIdentity(
                            AssemblyName(scope),
                            topLevelPath,
                            topLevelPath);
                    }

                    private string AssemblyName(EntityHandle scope)
                    {
                        if (scope.Kind == HandleKind.AssemblyReference)
                        {
                            return metadata.GetString(
                                metadata.GetAssemblyReference(
                                    (AssemblyReferenceHandle)scope).Name);
                        }
                        if (scope.Kind == HandleKind.TypeReference)
                            return FromReference((TypeReferenceHandle)scope).AssemblyName;
                        return currentAssembly;
                    }

                    internal TypeIdentity FromMemberParent(EntityHandle handle)
                    {
                        if (handle.Kind == HandleKind.TypeDefinition)
                            return FromDefinition((TypeDefinitionHandle)handle);
                        if (handle.Kind == HandleKind.TypeReference)
                            return FromReference((TypeReferenceHandle)handle);
                        if (handle.Kind == HandleKind.TypeSpecification)
                        {
                            return metadata.GetTypeSpecification(
                                (TypeSpecificationHandle)handle).DecodeSignature(this, null);
                        }
                        throw new BadImageFormatException(
                            "Unsupported MemberRef parent " + handle.Kind);
                    }

                    internal TypeIdentity FromTypeHandle(EntityHandle handle)
                    {
                        if (handle.Kind == HandleKind.TypeDefinition)
                            return FromDefinition((TypeDefinitionHandle)handle);
                        if (handle.Kind == HandleKind.TypeReference)
                            return FromReference((TypeReferenceHandle)handle);
                        if (handle.Kind == HandleKind.TypeSpecification)
                        {
                            return metadata.GetTypeSpecification(
                                (TypeSpecificationHandle)handle).DecodeSignature(this, null);
                        }
                        throw new BadImageFormatException(
                            "Unsupported type handle " + handle.Kind);
                    }

                    public TypeIdentity GetArrayType(
                        TypeIdentity elementType,
                        ArrayShape shape)
                    {
                        return elementType.WithDisplay(elementType.Display + "[*]");
                    }

                    public TypeIdentity GetByReferenceType(TypeIdentity elementType)
                    {
                        return elementType.WithDisplay(elementType.Display + "&");
                    }

                    public TypeIdentity GetFunctionPointerType(
                        MethodSignature<TypeIdentity> signature)
                    {
                        return new TypeIdentity(
                            currentAssembly,
                            "",
                            "methodptr");
                    }

                    public TypeIdentity GetGenericInstantiation(
                        TypeIdentity genericType,
                        ImmutableArray<TypeIdentity> typeArguments)
                    {
                        StringBuilder display = new StringBuilder(genericType.Display);
                        display.Append("<");
                        for (int index = 0; index < typeArguments.Length; index++)
                        {
                            if (index != 0)
                                display.Append(",");
                            display.Append(typeArguments[index].Display);
                        }
                        display.Append(">");
                        return genericType.WithDisplay(display.ToString());
                    }

                    public TypeIdentity GetGenericMethodParameter(
                        object genericContext,
                        int index)
                    {
                        return new TypeIdentity(currentAssembly, "", "!!" + index);
                    }

                    public TypeIdentity GetGenericTypeParameter(
                        object genericContext,
                        int index)
                    {
                        return new TypeIdentity(currentAssembly, "", "!" + index);
                    }

                    public TypeIdentity GetModifiedType(
                        TypeIdentity modifier,
                        TypeIdentity unmodifiedType,
                        bool isRequired)
                    {
                        return unmodifiedType;
                    }

                    public TypeIdentity GetPinnedType(TypeIdentity elementType)
                    {
                        return elementType;
                    }

                    public TypeIdentity GetPointerType(TypeIdentity elementType)
                    {
                        return elementType.WithDisplay(elementType.Display + "*");
                    }

                    public TypeIdentity GetPrimitiveType(PrimitiveTypeCode typeCode)
                    {
                        string signature;
                        switch (typeCode)
                        {
                            case PrimitiveTypeCode.Boolean:
                                signature = "bool";
                                break;
                            case PrimitiveTypeCode.Byte:
                                signature = "uint8";
                                break;
                            case PrimitiveTypeCode.SByte:
                                signature = "int8";
                                break;
                            case PrimitiveTypeCode.Char:
                                signature = "char";
                                break;
                            case PrimitiveTypeCode.Int16:
                                signature = "int16";
                                break;
                            case PrimitiveTypeCode.UInt16:
                                signature = "uint16";
                                break;
                            case PrimitiveTypeCode.Int32:
                                signature = "int32";
                                break;
                            case PrimitiveTypeCode.UInt32:
                                signature = "uint32";
                                break;
                            case PrimitiveTypeCode.Int64:
                                signature = "int64";
                                break;
                            case PrimitiveTypeCode.UInt64:
                                signature = "uint64";
                                break;
                            case PrimitiveTypeCode.Single:
                                signature = "float32";
                                break;
                            case PrimitiveTypeCode.Double:
                                signature = "float64";
                                break;
                            case PrimitiveTypeCode.String:
                                signature = "string";
                                break;
                            case PrimitiveTypeCode.Object:
                                signature = "object";
                                break;
                            case PrimitiveTypeCode.IntPtr:
                                signature = "native int";
                                break;
                            case PrimitiveTypeCode.UIntPtr:
                                signature = "native uint";
                                break;
                            case PrimitiveTypeCode.TypedReference:
                                signature = "typedref";
                                break;
                            case PrimitiveTypeCode.Void:
                                signature = "void";
                                break;
                            default:
                                throw new BadImageFormatException(
                                    "Unsupported primitive type " + typeCode);
                        }
                        return new TypeIdentity(
                            currentAssembly,
                            "",
                            signature);
                    }

                    public TypeIdentity GetSZArrayType(TypeIdentity elementType)
                    {
                        return elementType.WithDisplay(elementType.Display + "[]");
                    }

                    public TypeIdentity GetTypeFromDefinition(
                        MetadataReader reader,
                        TypeDefinitionHandle handle,
                        byte rawTypeKind)
                    {
                        return SignatureType(
                            FromDefinition(handle),
                            rawTypeKind);
                    }

                    public TypeIdentity GetTypeFromReference(
                        MetadataReader reader,
                        TypeReferenceHandle handle,
                        byte rawTypeKind)
                    {
                        return SignatureType(
                            FromReference(handle),
                            rawTypeKind);
                    }

                    public TypeIdentity GetTypeFromSpecification(
                        MetadataReader reader,
                        object genericContext,
                        TypeSpecificationHandle handle,
                        byte rawTypeKind)
                    {
                        return reader.GetTypeSpecification(handle)
                            .DecodeSignature(this, genericContext);
                    }

                    private TypeIdentity SignatureType(
                        TypeIdentity type,
                        byte rawTypeKind)
                    {
                        string prefix;
                        if (rawTypeKind == 0x11)
                        {
                            prefix = "valuetype ";
                        }
                        else if (rawTypeKind == 0x12)
                        {
                            prefix = "class ";
                        }
                        else
                        {
                            throw new BadImageFormatException(
                                "Unsupported raw type kind " + rawTypeKind);
                        }
                        string assembly = type.AssemblyName == currentAssembly
                            ? ""
                            : "[" + type.AssemblyName + "]";
                        string path = string.Join(
                            "/",
                            type.Path.Split('\0').Select(Identifier));
                        return type.WithDisplay(prefix + assembly + path);
                    }

                    private static string Identifier(string value)
                    {
                        return "'" +
                            value.Replace("\\", "\\\\").Replace("'", "\\'") +
                            "'";
                    }
                }
                """.trimIndent()
            )
        }
        val readerAssembly = readerDirectory.resolve("ManifestReader.dll")
        val readerCompile = runModernCSharpCompiler(
            modernCSharp,
            readerSource,
            readerAssembly,
            target = "exe",
        )
        assertEquals(0, readerCompile.exitCode, readerCompile.output)
        readerDirectory.resolve("ManifestReader.runtimeconfig.json").writeText(net10RuntimeConfig())
        val runtimeManifest = readCSharpImplementationManifestFromDll(
            modernCSharp,
            readerAssembly,
            readerDirectory,
            runtimeAssembly,
        )
        assertEquals("Kotlin.Runtime", runtimeManifest.assemblyName)
        assertEquals("net10.0", runtimeManifest.targetProfile)
        assertEquals(
            DotNetLibraryAbiCodec.LOGICAL_IDENTITY_SCHEME,
            runtimeManifest.logicalIdentityScheme,
        )
        assertEquals(1, runtimeManifest.interfaces.size)
        assertTrue(runtimeManifest.interfaces.all { contract ->
            contract.logicalKey.startsWith("C:") &&
                    !contract.logicalKey.startsWith("runtime:") &&
                    contract.members.all { member ->
                        member.logicalKey.startsWith("F:") &&
                                !member.logicalKey.startsWith("runtime:")
                    }
        })
        val runtimeCharSequenceContract = runtimeManifest.interfaces.single { contract ->
            contract.canonicalOwnerPath.last() == "Kotlin.CharSequence"
        }
        assertTrue(runtimeCharSequenceContract.sourceAuthoringSupported)
        assertEquals(null, runtimeCharSequenceContract.declaredOwnerPath)
        assertEquals(null, runtimeCharSequenceContract.exactOwnerPath)
        assertTrue(runtimeCharSequenceContract.typeParameters.isEmpty())
        assertEquals(
            setOf("length", "get", "subSequence"),
            runtimeCharSequenceContract.members.map { member -> member.sourceName }.toSet(),
        )
        runtimeCharSequenceContract.members.forEach { member ->
            assertEquals(DotNetCSharpInterfaceView.CANONICAL, member.authoringView)
            assertEquals(1, member.slots.size)
            assertEquals(DotNetCSharpSlotRole.CANONICAL, member.slots.single().role)
            assertEquals(listOf("Kotlin.CharSequence"), member.slots.single().ownerPath)
        }
        runtimeCharSequenceContract.members.single { member -> member.sourceName == "length" }
            .slots.single().also { slot ->
                assertEquals("get_length", slot.methodName)
                assertEquals("length", slot.propertyName)
                assertEquals("int32", slot.returnType)
                assertTrue(slot.parameterTypes.isEmpty())
            }
        runtimeCharSequenceContract.members.single { member -> member.sourceName == "get" }
            .slots.single().also { slot ->
                assertEquals("get", slot.methodName)
                assertEquals(null, slot.propertyName)
                assertEquals("char", slot.returnType)
                assertEquals(listOf("int32"), slot.parameterTypes)
            }
        runtimeCharSequenceContract.members.single { member -> member.sourceName == "subSequence" }
            .slots.single().also { slot ->
                assertEquals("subSequence", slot.methodName)
                assertEquals(null, slot.propertyName)
                assertEquals("object", slot.returnType)
                assertEquals(listOf("int32", "int32"), slot.parameterTypes)
            }
        val runtimeContractsByProfile = DotNetTarget.entries.associateWith { target ->
            val assembly = if (target == DotNetTarget.NET10_0) {
                runtimeAssembly
            } else {
                val profileDirectory =
                    File(tmpdir, "runtime-manifest-${target.description}").apply { mkdirs() }
                checkNotNull(
                    DotNetIlAssembler.assembleRuntimeWithManifestForTests(
                        profileDirectory,
                        target,
                        runtimeManifest.copy(targetProfile = target.description),
                        MessageCollector.NONE,
                    )
                )
            }
            val profileReaderDirectory = checkNotNull(assembly.parentFile)
            val profileReader = if (profileReaderDirectory == readerDirectory) {
                readerAssembly
            } else {
                readerAssembly.copyTo(
                    profileReaderDirectory.resolve(readerAssembly.name),
                    overwrite = true,
                ).also {
                    readerDirectory.resolve("ManifestReader.runtimeconfig.json").copyTo(
                        profileReaderDirectory.resolve("ManifestReader.runtimeconfig.json"),
                        overwrite = true,
                    )
                }
            }
            readCSharpImplementationManifestFromDll(
                modernCSharp,
                profileReader,
                profileReaderDirectory,
                assembly,
            ).also { manifest ->
                assertEquals(target.description, manifest.targetProfile)
                assertEquals(
                    DotNetLibraryAbiCodec.LOGICAL_IDENTITY_SCHEME,
                    manifest.logicalIdentityScheme,
                )
            }
        }
        val modernRuntimeContracts = runtimeContractsByProfile
            .getValue(DotNetTarget.NET10_0)
            .interfaces
        for (portableTarget in listOf(DotNetTarget.NET48, DotNetTarget.NETSTANDARD_2_0)) {
            assertEquals(
                modernRuntimeContracts,
                runtimeContractsByProfile.getValue(portableTarget).interfaces,
            )
        }
    }

