    @Test
    fun testCompanionExtensionsUseReceiverFreeCrossModuleAbi() {
        requireOrAssumeToolchain(DotNetIlAssembler.findModernIlasm() != null, "Modern ilasm is not available")
        val csharpToolchain = DotNetIlAssembler.findModernCSharpCompiler()
        requireOrAssumeToolchain(csharpToolchain != null, "Modern Roslyn and the net10 reference pack are not available")
        val producerDirectory = File(tmpdir, "companion-extension-producer")
        val producerSource = File(tmpdir, "library.kt").apply {
            writeText(
                """
                package companionlib

                private var targetInitialized = false

                private fun initializeTarget(): Int {
                    targetInitialized = true
                    return 40
                }

                public class Target {
                    companion {
                        public val state: Int = initializeTarget()
                        public fun blockAnswer(delta: Int): Int = state + delta
                    }
                }

                public companion fun Target.answer(value: Int): Int = value + 1
                public companion fun Target.wasInitialized(): Boolean = targetInitialized
                public companion val Target.label: String
                    get() = "receiver-free"
                """.trimIndent()
            )
        }
        compileInProcess(
            K2DotNetCompiler(),
            producerSource.path,
            "-Xcompanion-blocks-and-extensions",
            K2DotNetCompilerArguments::dotNetProduceLibrary.cliArgument,
            K2DotNetCompilerArguments::dotNetTarget.cliArgument, "netstandard2.0",
            K2DotNetCompilerArguments::moduleName.cliArgument, "Companion.Extension.Library",
            K2DotNetCompilerArguments::destination.cliArgument, producerDirectory.path,
        )

        val producerIl = producerDirectory.resolve("Companion.Extension.Library.il").readText()
        assertTrue("static int32 'answer'(int32 'value')" in producerIl) { producerIl }
        assertTrue("static bool 'wasInitialized'()" in producerIl) { producerIl }
        assertTrue("static string 'get_label'()" in producerIl) { producerIl }
        assertTrue(".property string 'label'" !in producerIl) { producerIl }
        assertTrue("static int32 'state'" in producerIl) { producerIl }
        assertTrue("static int32 'blockAnswer'(int32 'delta')" in producerIl) { producerIl }

        val consumerDirectory = File(tmpdir, "companion-extension-consumer").apply { mkdirs() }
        val consumerSource = consumerDirectory.resolve("consumer.kt").apply {
            writeText(
                """
                package consumer

                import companionlib.Target
                import companionlib.answer
                import companionlib.label
                import companionlib.wasInitialized

                fun main() {
                    if (Target.answer(41) != 42) throw Error("answer")
                    if (Target.label != "receiver-free") throw Error("label")
                    if (Target.wasInitialized()) throw Error("extension initialized target")
                    if (Target.blockAnswer(2) != 42) throw Error("block")
                    if (!Target.wasInitialized()) throw Error("block did not initialize target")
                }
                """.trimIndent()
            )
        }
        val consumerAssembly = consumerDirectory.resolve("CompanionExtensionConsumer.dll")
        compileInProcess(
            K2DotNetCompiler(),
            consumerSource.path,
            "-Xcompanion-blocks-and-extensions",
            K2DotNetCompilerArguments::classpath.cliArgument,
            producerDirectory.resolve("Companion.Extension.Library.dll").path,
            K2DotNetCompilerArguments::dotNetTarget.cliArgument, "net10.0",
            K2DotNetCompilerArguments::moduleName.cliArgument, "CompanionExtensionConsumer",
            K2DotNetCompilerArguments::destination.cliArgument, consumerAssembly.path,
        )

        val consumerIl = consumerDirectory.resolve("CompanionExtensionConsumer.il").readText()
        assertTrue(
            "call int32 [Companion.Extension.Library]'companionlib.libraryKt'::'answer'(int32)" in consumerIl
        ) { consumerIl }
        assertTrue(
            "call string [Companion.Extension.Library]'companionlib.libraryKt'::'get_label'()" in consumerIl
        ) { consumerIl }
        assertTrue(
            "call int32 [Companion.Extension.Library]'companionlib.Target'::'blockAnswer'(int32)" in consumerIl
        ) { consumerIl }
        runDotNet(
            modernDotNetHostOrSkip(),
            consumerAssembly,
            consumerDirectory,
            "Companion-extension cross-module consumer failed",
        )

        val csharpDirectory = File(tmpdir, "companion-static-csharp-consumer").apply { mkdirs() }
        val csharpSource = csharpDirectory.resolve("Program.cs").apply {
            writeText(
                """
                public static class Program
                {
                    public static int Main()
                    {
                        if (companionlib.Target.blockAnswer(2) != 42)
                            return 1;
                        return companionlib.Target.state == 40 ? 0 : 2;
                    }
                }
                """.trimIndent()
            )
        }
        val csharpAssembly = csharpDirectory.resolve("CompanionStaticCSharpConsumer.dll")
        val producerAssembly = producerDirectory.resolve("Companion.Extension.Library.dll")
        val runtimeAssembly = consumerDirectory.resolve("Kotlin.Runtime.dll")
        val csharpCompile = runModernCSharpCompiler(
            checkNotNull(csharpToolchain),
            csharpSource,
            csharpAssembly,
            producerAssembly,
            runtimeAssembly,
            target = "exe",
        )
        assertEquals(0, csharpCompile.exitCode, csharpCompile.output)
        producerAssembly.copyTo(csharpDirectory.resolve(producerAssembly.name), overwrite = true)
        runtimeAssembly.copyTo(csharpDirectory.resolve(runtimeAssembly.name), overwrite = true)
        csharpDirectory.resolve("CompanionStaticCSharpConsumer.runtimeconfig.json").writeText(
            """
            {
              "runtimeOptions": {
                "tfm": "net10.0",
                "framework": {
                  "name": "Microsoft.NETCore.App",
                  "version": "10.0.0"
                },
                "rollForward": "LatestMinor"
              }
            }
            """.trimIndent()
        )
        runDotNet(
            checkNotNull(csharpToolchain).dotNetHost,
            csharpAssembly,
            csharpDirectory,
            "C# companion-static consumer failed",
        )
    }

    @Test
    fun testLateinitPropertiesAcrossKotlinAndCSharpBoundaries() {
        requireOrAssumeToolchain(DotNetIlAssembler.findModernIlasm() != null, "Modern ilasm is not available")
        val csharpToolchain = DotNetIlAssembler.findModernCSharpCompiler()
        requireOrAssumeToolchain(
            csharpToolchain != null,
            "Modern Roslyn and the net10 reference pack are not available",
        )
        val dotnetHost = modernDotNetHostOrSkip()
        val producerDirectory = File(tmpdir, "lateinit-producer")
        val producerSource = File(tmpdir, "LateinitBoundary.kt").apply {
            writeText(
                """
                package lateinit.boundary

                public class Holder {
                    public lateinit var value: String

                    public fun isInitialized(): Boolean = this::value.isInitialized
                }
                """.trimIndent()
            )
        }
        compileInProcess(
            K2DotNetCompiler(),
            producerSource.path,
            K2DotNetCompilerArguments::dotNetProduceLibrary.cliArgument,
            K2DotNetCompilerArguments::dotNetTarget.cliArgument, "netstandard2.0",
            K2DotNetCompilerArguments::moduleName.cliArgument, "Lateinit.Boundary",
            K2DotNetCompilerArguments::destination.cliArgument, producerDirectory.path,
        )

        val producerAssembly = producerDirectory.resolve("Lateinit.Boundary.dll")
        val producerIl = producerDirectory.resolve("Lateinit.Boundary.il").readText()
        val holderIl = producerIl
            .substringAfter(".class public auto ansi sealed beforefieldinit 'lateinit.boundary.Holder'")
            .substringBefore("\n.class ")
        assertTrue(".field private string 'value'" in holderIl) { holderIl }
        assertEquals(1, Regex("(?m)^\\s*\\.field ").findAll(holderIl).count()) {
            "A legal reference-valued lateinit property needs exactly one storage field:\n$holderIl"
        }
        assertTrue("instance string 'get_value'()" in holderIl) { holderIl }
        assertTrue("instance void 'set_value'(string" in holderIl) { holderIl }
        assertTrue("throwUninitializedPropertyAccessException" in holderIl) { holderIl }

        val kotlinDirectory = File(tmpdir, "lateinit-kotlin-consumer").apply { mkdirs() }
        val kotlinSource = kotlinDirectory.resolve("main.kt").apply {
            writeText(
                """
                import lateinit.boundary.Holder

                fun main() {
                    val holder = Holder()
                    if (holder.isInitialized()) throw Error("initial state")
                    val message = try {
                        holder.value
                        "no exception"
                    } catch (exception: UninitializedPropertyAccessException) {
                        exception.message
                    }
                    if (message != "lateinit property value has not been initialized") {
                        throw Error("failure contract: ${'$'}message")
                    }
                    holder.value = "OK"
                    if (!holder.isInitialized() || holder.value != "OK") throw Error("initialized state")
                }
                """.trimIndent()
            )
        }
        val kotlinAssembly = kotlinDirectory.resolve("LateinitKotlinConsumer.dll")
        compileInProcess(
            K2DotNetCompiler(),
            kotlinSource.path,
            K2DotNetCompilerArguments::classpath.cliArgument, producerAssembly.path,
            K2DotNetCompilerArguments::dotNetTarget.cliArgument, "net10.0",
            K2DotNetCompilerArguments::moduleName.cliArgument, "LateinitKotlinConsumer",
            K2DotNetCompilerArguments::destination.cliArgument, kotlinAssembly.path,
        )
        runDotNet(
            dotnetHost,
            kotlinAssembly,
            kotlinDirectory,
            "Kotlin lateinit consumer failed across a portable library boundary",
        )

        val csharpDirectory = File(tmpdir, "lateinit-csharp-consumer").apply { mkdirs() }
        val csharpSource = csharpDirectory.resolve("Program.cs").apply {
            writeText(
                """
                public static class Program
                {
                    public static int Main()
                    {
                        var holder = new lateinit.boundary.Holder();
                        if (holder.isInitialized()) return 1;
                        try
                        {
                            string ignored = holder.value;
                            return 2;
                        }
                        catch (Kotlin.UninitializedPropertyAccessException exception)
                        {
                            if (exception.Message != "lateinit property value has not been initialized")
                                return 3;
                        }
                        holder.value = "OK";
                        if (!holder.isInitialized() || holder.value != "OK") return 4;
                        holder.value = null;
                        if (holder.isInitialized()) return 5;
                        try
                        {
                            string ignored = holder.value;
                            return 6;
                        }
                        catch (Kotlin.UninitializedPropertyAccessException)
                        {
                        }
                        return 0;
                    }
                }
                """.trimIndent()
            )
        }
        val csharpAssembly = csharpDirectory.resolve("LateinitCSharpConsumer.dll")
        val runtimeAssembly = kotlinDirectory.resolve(DotNetRuntimeArtifact.ASSEMBLY_FILE_NAME)
        val stdlibAssembly = kotlinDirectory.resolve("Kotlin.Stdlib.dll")
        val csharpCompile = runModernCSharpCompiler(
            checkNotNull(csharpToolchain),
            csharpSource,
            csharpAssembly,
            producerAssembly,
            runtimeAssembly,
            stdlibAssembly,
            target = "exe",
        )
        assertEquals(0, csharpCompile.exitCode, csharpCompile.output)
        producerAssembly.copyTo(csharpDirectory.resolve(producerAssembly.name), overwrite = true)
        runtimeAssembly.copyTo(csharpDirectory.resolve(runtimeAssembly.name), overwrite = true)
        stdlibAssembly.copyTo(csharpDirectory.resolve(stdlibAssembly.name), overwrite = true)
        csharpDirectory.resolve("LateinitCSharpConsumer.runtimeconfig.json").writeText(net10RuntimeConfig())
        runDotNet(
            checkNotNull(csharpToolchain).dotNetHost,
            csharpAssembly,
            csharpDirectory,
            "C# lateinit property consumer failed",
        )
    }

    @Test
    fun testTopLevelDelegatedPropertyAcrossKotlinAndCSharpBoundaries() {
        requireOrAssumeToolchain(DotNetIlAssembler.findModernIlasm() != null, "Modern ilasm is not available")
        val csharpToolchain = DotNetIlAssembler.findModernCSharpCompiler()
        requireOrAssumeToolchain(
            csharpToolchain != null,
            "Modern Roslyn and the net10 reference pack are not available",
        )
        val dotnetHost = modernDotNetHostOrSkip()
        val producerDirectory = File(tmpdir, "delegated-property-producer")
        val producerSource = File(tmpdir, "DelegatedBoundary.kt").apply {
            writeText(
                """
                package delegated.boundary

                import kotlin.reflect.KProperty

                private var log: String = ""

                private class StateDelegate(private var value: String) {
                    operator fun getValue(receiver: Any?, property: KProperty<*>): String {
                        log += "get:${'$'}{property.name};"
                        return value
                    }

                    operator fun setValue(receiver: Any?, property: KProperty<*>, newValue: String) {
                        log += "set:${'$'}{property.name}=${'$'}newValue;"
                        value = newValue
                    }
                }

                private fun newDelegate(value: String): StateDelegate {
                    log += "create;"
                    return StateDelegate(value)
                }

                private operator fun StateDelegate.provideDelegate(
                    receiver: Any?,
                    property: KProperty<*>,
                ): StateDelegate {
                    log += "provide:${'$'}{property.name};"
                    return this
                }

                public var state: String by newDelegate("start")

                public fun trace(): String = log
                """.trimIndent()
            )
        }
        compileInProcess(
            K2DotNetCompiler(),
            producerSource.path,
            K2DotNetCompilerArguments::dotNetProduceLibrary.cliArgument,
            K2DotNetCompilerArguments::dotNetTarget.cliArgument, "netstandard2.0",
            K2DotNetCompilerArguments::moduleName.cliArgument, "Delegated.Boundary",
            K2DotNetCompilerArguments::destination.cliArgument, producerDirectory.path,
        )

        val producerAssembly = producerDirectory.resolve("Delegated.Boundary.dll")
        val producerIl = producerDirectory.resolve("Delegated.Boundary.il").readText()
        val facadeIl = producerIl
            .substringAfter(".class public abstract sealed auto ansi 'delegated.boundary.DelegatedBoundaryKt'")
            .substringBefore("\n.class ")
        assertTrue(".field private static class 'delegated.boundary.StateDelegate' 'state${'$'}delegate'" in facadeIl) {
            facadeIl
        }
        assertEquals(1, Regex("(?m)^\\s*\\.field .*'state\\${'$'}delegate'").findAll(facadeIl).count()) {
            "A top-level delegated property needs exactly one private delegate field:\n$facadeIl"
        }
        assertTrue("static void .cctor()" in facadeIl) { facadeIl }
        assertTrue("::'provideDelegate'(" in facadeIl) { facadeIl }
        assertTrue("::'getValue'(" in facadeIl) { facadeIl }
        assertTrue("::'setValue'(" in facadeIl) { facadeIl }

        val kotlinDirectory = File(tmpdir, "delegated-property-kotlin-consumer").apply { mkdirs() }
        val kotlinSource = kotlinDirectory.resolve("main.kt").apply {
            writeText(
                """
                import delegated.boundary.state
                import delegated.boundary.trace

                fun main() {
                    if (trace() != "create;provide:state;") throw Error("initialization: ${'$'}{trace()}")
                    if (state != "start") throw Error("initial read")
                    state = "Kotlin"
                    if (state != "Kotlin") throw Error("mutation")
                    if (trace() != "create;provide:state;get:state;set:state=Kotlin;get:state;") {
                        throw Error("trace: ${'$'}{trace()}")
                    }
                }
                """.trimIndent()
            )
        }
        val kotlinAssembly = kotlinDirectory.resolve("DelegatedPropertyKotlinConsumer.dll")
        compileInProcess(
            K2DotNetCompiler(),
            kotlinSource.path,
            K2DotNetCompilerArguments::classpath.cliArgument, producerAssembly.path,
            K2DotNetCompilerArguments::dotNetTarget.cliArgument, "net10.0",
            K2DotNetCompilerArguments::moduleName.cliArgument, "DelegatedPropertyKotlinConsumer",
            K2DotNetCompilerArguments::destination.cliArgument, kotlinAssembly.path,
        )
        runDotNet(
            dotnetHost,
            kotlinAssembly,
            kotlinDirectory,
            "Kotlin top-level delegated-property consumer failed across a portable library boundary",
        )

        val csharpDirectory = File(tmpdir, "delegated-property-csharp-consumer").apply { mkdirs() }
        val csharpSource = csharpDirectory.resolve("Program.cs").apply {
            writeText(
                """
                public static class Program
                {
                    public static int Main()
                    {
                        if (delegated.boundary.DelegatedBoundaryKt.trace() != "create;provide:state;") return 1;
                        if (delegated.boundary.DelegatedBoundaryKt.state != "start") return 2;
                        delegated.boundary.DelegatedBoundaryKt.state = "CSharp";
                        if (delegated.boundary.DelegatedBoundaryKt.state != "CSharp") return 3;
                        if (delegated.boundary.DelegatedBoundaryKt.trace() !=
                            "create;provide:state;get:state;set:state=CSharp;get:state;") return 4;
                        return 0;
                    }
                }
                """.trimIndent()
            )
        }
        val csharpAssembly = csharpDirectory.resolve("DelegatedPropertyCSharpConsumer.dll")
        val runtimeAssembly = kotlinDirectory.resolve(DotNetRuntimeArtifact.ASSEMBLY_FILE_NAME)
        val stdlibAssembly = kotlinDirectory.resolve("Kotlin.Stdlib.dll")
        val csharpCompile = runModernCSharpCompiler(
            checkNotNull(csharpToolchain),
            csharpSource,
            csharpAssembly,
            producerAssembly,
            runtimeAssembly,
            stdlibAssembly,
            target = "exe",
        )
        assertEquals(0, csharpCompile.exitCode, csharpCompile.output)
        producerAssembly.copyTo(csharpDirectory.resolve(producerAssembly.name), overwrite = true)
        runtimeAssembly.copyTo(csharpDirectory.resolve(runtimeAssembly.name), overwrite = true)
        stdlibAssembly.copyTo(csharpDirectory.resolve(stdlibAssembly.name), overwrite = true)
        csharpDirectory.resolve("DelegatedPropertyCSharpConsumer.runtimeconfig.json").writeText(net10RuntimeConfig())
        runDotNet(
            checkNotNull(csharpToolchain).dotNetHost,
            csharpAssembly,
            csharpDirectory,
            "C# top-level delegated-property consumer failed",
        )
    }

    @Test
    fun testKTypeGraphAcrossLibraryBoundary() {
        requireOrAssumeToolchain(DotNetIlAssembler.findModernIlasm() != null, "Modern ilasm is not available")
        val frameworkHost = DotNetIlAssembler.findFrameworkPowerShellHost()
        requireOrAssumeToolchain(frameworkHost != null, "Windows PowerShell CLR 4 host is not available")
        val csharpToolchain = DotNetIlAssembler.findModernCSharpCompiler()
        requireOrAssumeToolchain(
            csharpToolchain != null,
            "Modern Roslyn and the net10 reference pack are not available",
        )

        val producerDirectory = File(tmpdir, "ktype-producer")
        val producerSource = File(tmpdir, "KTypeBoundary.kt").apply {
            writeText(
                """
                package ktype.boundary

                import kotlin.reflect.KType
                import kotlin.reflect.typeOf

                public class LibraryBox<T>

                public fun concreteType(): KType = typeOf<LibraryBox<String?>>()

                public fun projectedType(): KType = typeOf<LibraryBox<out CharSequence>>()

                public fun <T> declarationType(): KType = typeOf<LibraryBox<T>>()

                public fun <T : Comparable<T>> recursiveDeclarationType(): KType = typeOf<LibraryBox<T>>()

                public fun <X, Y> nullableRelativeType(): KType where X : Y? = typeOf<LibraryBox<X>>()
                """.trimIndent()
            )
        }
        compileInProcess(
            K2DotNetCompiler(),
            producerSource.path,
            K2DotNetCompilerArguments::dotNetProduceLibrary.cliArgument,
            K2DotNetCompilerArguments::dotNetTarget.cliArgument, "netstandard2.0",
            K2DotNetCompilerArguments::moduleName.cliArgument, "KType.Library",
            K2DotNetCompilerArguments::destination.cliArgument, producerDirectory.path,
        )

        val producerAssembly = producerDirectory.resolve("KType.Library.dll")
        val producerIl = producerDirectory.resolve("KType.Library.il").readText()
        assertTrue("'ktype.boundary.LibraryBox`1'" !in producerIl) { producerIl }
        assertTrue("'ktype.boundary.LibraryBox'" in producerIl) { producerIl }
        assertTrue("dotNetCreateKType" in producerIl) { producerIl }
        assertTrue("::'typeOf'" !in producerIl) { "A typeOf intrinsic survived library lowering:\n$producerIl" }
        assertTrue("'nullableRelativeType'<'X', 'Y'>()" in producerIl) {
            "The unrepresentable nullable relative bound became a stronger CLR constraint:\n$producerIl"
        }

        var modernConsumerDirectory: File? = null
        for (target in listOf("net48", "net10.0")) {
            val targetSuffix = if (target == "net48") "Framework" else "Core"
            val consumerDirectory = File(tmpdir, "ktype-consumer-$targetSuffix").apply { mkdirs() }
            if (target == "net10.0") modernConsumerDirectory = consumerDirectory
            val consumerSource = consumerDirectory.resolve("consumer.kt").apply {
                writeText(
                    """
                    package consumer

                    import kotlin.reflect.KTypeParameter
                    import kotlin.reflect.typeOf
                    import ktype.boundary.*

                    fun main() {
                        val concrete = concreteType()
                        if (concrete != typeOf<LibraryBox<String?>>()) throw Error("concrete graph")
                        if (concrete == typeOf<LibraryBox<Int>>()) throw Error("erased arguments became equal")
                        if (concrete.classifier != LibraryBox::class) throw Error("classifier identity")
                        if (concrete.arguments.single().type?.isMarkedNullable != true) throw Error("argument nullability")

                        val projected = projectedType().arguments.single()
                        if (projected.toString() != "out kotlin.CharSequence") throw Error("projection: ${'$'}projected")

                        val declarationString = declarationType<String>()
                        val declarationInt = declarationType<Int>()
                        if (declarationString != declarationInt) throw Error("CLR instantiation changed declaration graph")
                        val declarationParameter = declarationString.arguments.single().type?.classifier as KTypeParameter
                        if (declarationParameter.name != "T" || declarationParameter.isReified) {
                            throw Error("declaration parameter flags")
                        }

                        val recursive = recursiveDeclarationType<String>()
                        val recursiveParameter = recursive.arguments.single().type?.classifier as KTypeParameter
                        val recursiveArgument = recursiveParameter.upperBounds.single().arguments.single().type?.classifier
                        if (recursiveArgument != recursiveParameter) throw Error("recursive parameter identity")

                        val nullableReference = nullableRelativeType<String?, String>()
                        val nullableValue = nullableRelativeType<Int?, Int>()
                        if (nullableReference != nullableValue) throw Error("nullable relative declaration identity")
                        val relativeParameter = nullableReference.arguments.single().type?.classifier as KTypeParameter
                        val relativeBound = relativeParameter.upperBounds.single()
                        if (!relativeBound.isMarkedNullable || (relativeBound.classifier as KTypeParameter).name != "Y") {
                            throw Error("nullable relative bound")
                        }
                        println("OK")
                    }
                    """.trimIndent()
                )
            }
            val assemblyName = "KType${targetSuffix}Consumer"
            val consumerAssembly = consumerDirectory.resolve(
                if (target == "net48") "$assemblyName.exe" else "$assemblyName.dll"
            )
            compileInProcess(
                K2DotNetCompiler(),
                consumerSource.path,
                K2DotNetCompilerArguments::classpath.cliArgument, producerAssembly.path,
                K2DotNetCompilerArguments::dotNetTarget.cliArgument, target,
                K2DotNetCompilerArguments::moduleName.cliArgument, assemblyName,
                K2DotNetCompilerArguments::destination.cliArgument, consumerAssembly.path,
            )
            val consumerIl = consumerDirectory.resolve("$assemblyName.il").readText()
            assertTrue("[KType.Library]'ktype.boundary.KTypeBoundaryKt'::'concreteType'()" in consumerIl) {
                consumerIl
            }
            if (target == "net48") {
                runAssemblerPairing(
                    frameworkExecutionCommand(checkNotNull(frameworkHost), consumerAssembly),
                    consumerDirectory,
                    "Framework KType consumer failed",
                )
            } else {
                runDotNet(
                    modernDotNetHostOrSkip(),
                    consumerAssembly,
                    consumerDirectory,
                    "CoreCLR KType consumer failed",
                )
            }
        }

        val csharpDirectory = checkNotNull(modernConsumerDirectory)
        val csharpSource = csharpDirectory.resolve("KTypeConsumer.cs").apply {
            writeText(
                """
                public static class KTypeConsumer
                {
                    public static int Main()
                    {
                        Kotlin.KType concrete = ktype.boundary.KTypeBoundaryKt.concreteType();
                        if (concrete.classifier == null || concrete.isMarkedNullable) return 1;
                        Kotlin.Collections.List annotations =
                            ((Kotlin.KAnnotatedElement)concrete).annotations;
                        if (annotations.Size != 0) return 3;
                        Kotlin.KType declared =
                            ktype.boundary.KTypeBoundaryKt.declarationType<string>();
                        Kotlin.Reflection.KTypeProjection projection =
                            (Kotlin.Reflection.KTypeProjection)declared.arguments.Get(0);
                        Kotlin.Reflection.KTypeParameter parameter =
                            projection.type.classifier as Kotlin.Reflection.KTypeParameter;
                        if (parameter == null || parameter.name != "T" || parameter.isReified) return 2;
                        return 0;
                    }
                }
                """.trimIndent()
            )
        }
        val csharpAssembly = csharpDirectory.resolve("KTypeCSharpConsumer.dll")
        val csharpCompile = runModernCSharpCompiler(
            checkNotNull(csharpToolchain),
            csharpSource,
            csharpAssembly,
            producerAssembly,
            csharpDirectory.resolve(DotNetRuntimeArtifact.ASSEMBLY_FILE_NAME),
            csharpDirectory.resolve("Kotlin.Stdlib.dll"),
            target = "exe",
        )
        assertEquals(0, csharpCompile.exitCode, csharpCompile.output)
        csharpDirectory.resolve("KTypeCSharpConsumer.runtimeconfig.json").writeText(net10RuntimeConfig())
        runDotNet(
            checkNotNull(csharpToolchain).dotNetHost,
            csharpAssembly,
            csharpDirectory,
            "C# KType consumer failed",
        )
    }

    @Test
    fun testKClassIdentityAcrossLibraryBoundary() {
        requireOrAssumeToolchain(DotNetIlAssembler.findModernIlasm() != null, "Modern ilasm is not available")
        val csharpToolchain = DotNetIlAssembler.findModernCSharpCompiler()
        requireOrAssumeToolchain(
            csharpToolchain != null,
            "Modern Roslyn and the net10 reference pack are not available",
        )
        val producerDirectory = File(tmpdir, "kclass-producer")
        val producerSource = File(tmpdir, "KClassLibrary.kt").apply {
            writeText(
                """
                package kclassboundary

                import kotlin.reflect.KClass

                @Retention(AnnotationRetention.RUNTIME)
                @Target(AnnotationTarget.CLASS)
                public annotation class LibraryMarker(public val value: String = "library")

                @LibraryMarker
                public class LibraryToken

                public class LibraryBox<T>(public val value: T)

                public fun staticToken(): KClass<LibraryToken> = LibraryToken::class

                public fun staticBox(): KClass<LibraryBox<*>> = LibraryBox::class

                public fun runtimeToken(value: Any): KClass<out Any> = value::class
                """.trimIndent()
            )
        }
        compileInProcess(
            K2DotNetCompiler(),
            producerSource.path,
            K2DotNetCompilerArguments::dotNetProduceLibrary.cliArgument,
            K2DotNetCompilerArguments::dotNetTarget.cliArgument, "netstandard2.0",
            K2DotNetCompilerArguments::moduleName.cliArgument, "KClass.Library",
            K2DotNetCompilerArguments::destination.cliArgument, producerDirectory.path,
        )

        val consumerDirectory = File(tmpdir, "kclass-consumer").apply { mkdirs() }
        val foreignSource = consumerDirectory.resolve("ForeignAnnotations.cs").apply {
            writeText(
                """
                using System;

                namespace ForeignAnnotations
                {
                    [AttributeUsage(
                        AttributeTargets.Class | AttributeTargets.Interface,
                        AllowMultiple = true,
                        Inherited = true)]
                    public sealed class ForeignMarkerAttribute : Attribute
                    {
                        public ForeignMarkerAttribute(string value) { Value = value; }
                        public string Value { get; }
                    }

                    [ForeignMarker("direct")]
                    public interface ForeignAnnotated
                    {
                        void Touch();
                    }
                }
                """.trimIndent()
            )
        }
        val foreignAssembly = consumerDirectory.resolve("Foreign.Annotations.dll")
        val foreignCompile = runModernCSharpCompiler(
            checkNotNull(csharpToolchain),
            foreignSource,
            foreignAssembly,
        )
        assertEquals(0, foreignCompile.exitCode, foreignCompile.output)
        val consumerSource = consumerDirectory.resolve("consumer.kt").apply {
            writeText(
                """
                package consumer

                import ForeignAnnotations.ForeignAnnotated
                import kclassboundary.*

                fun main() {
                    val intBox: Any = LibraryBox(1)
                    val stringBox: Any = LibraryBox("value")
                    if (staticToken() != LibraryToken::class) throw Error("static token identity")
                    if (runtimeToken(LibraryToken()) != staticToken()) throw Error("dynamic token identity")
                    if (runtimeToken(intBox) != runtimeToken(stringBox)) throw Error("generic erasure")
                    if (runtimeToken(intBox) != staticBox()) throw Error("static generic identity")
                    if (!staticBox().isInstance(stringBox)) throw Error("generic instance")

                    val kotlinAnnotations = staticToken().annotations
                    if (kotlinAnnotations.size != 1) throw Error("KLIB annotation count")
                    val marker = kotlinAnnotations[0] as? LibraryMarker
                        ?: throw Error("KLIB annotation identity")
                    if (marker.value != "library") throw Error("KLIB annotation default")

                    val foreignAnnotations = ForeignAnnotated::class.annotations
                    if (foreignAnnotations.size != 1) throw Error("foreign annotation count")
                    if (foreignAnnotations[0]::class.simpleName != "ForeignMarkerAttribute") {
                        throw Error("foreign annotation identity")
                    }
                }
                """.trimIndent()
            )
        }
        val consumerAssembly = consumerDirectory.resolve("KClassConsumer.dll")
        compileInProcess(
            K2DotNetCompiler(),
            consumerSource.path,
            K2DotNetCompilerArguments::classpath.cliArgument,
            listOf(
                producerDirectory.resolve("KClass.Library.dll"),
                foreignAssembly,
                checkNotNull(csharpToolchain).referenceDirectory.resolve("System.Runtime.dll"),
            ).joinToString(File.pathSeparator) { it.path },
            K2DotNetCompilerArguments::dotNetTarget.cliArgument, "net10.0",
            K2DotNetCompilerArguments::moduleName.cliArgument, "KClassConsumer",
            K2DotNetCompilerArguments::destination.cliArgument, consumerAssembly.path,
        )

        val consumerIl = consumerDirectory.resolve("KClassConsumer.il").readText()
        assertTrue("[KClass.Library]'kclassboundary.KClassLibraryKt'::'staticToken'()" in consumerIl)
        assertTrue("[KClass.Library]'kclassboundary.KClassLibraryKt'::'runtimeToken'(object)" in consumerIl)
        val producerIl = producerDirectory.resolve("KClass.Library.il").readText()
        assertTrue("'<AnnotationFactory>'" in producerIl) { producerIl }
        assertTrue("'<GetKotlinAnnotations>'" in producerIl) { producerIl }
        runDotNet(
            modernDotNetHostOrSkip(),
            consumerAssembly,
            consumerDirectory,
            "KClass cross-module consumer failed",
        )

        val csharpSource = consumerDirectory.resolve("KClassConsumer.cs").apply {
            writeText(
                """
                using System;

                [Obsolete("foreign class")]
                public sealed class ForeignAnnotatedClass { }

                public static class KClassConsumer
                {
                    public static int Main()
                    {
                        Kotlin.KClass token = kclassboundary.KClassLibraryKt.staticToken();
                        if (token.simpleName != "LibraryToken") return 1;
                        if (!token.isInstance(new kclassboundary.LibraryToken())) return 2;
                        Kotlin.KClass foreign =
                            Kotlin.Runtime.Internal.KClassFactory.GetClass(new ForeignAnnotatedClass());
                        Kotlin.Collections.List annotations =
                            ((Kotlin.KAnnotatedElement)foreign).annotations;
                        if (annotations.Size != 1) return 3;
                        ObsoleteAttribute obsolete = annotations.Get(0) as ObsoleteAttribute;
                        if (obsolete == null || obsolete.Message != "foreign class") return 4;
                        return 0;
                    }
                }
                """.trimIndent()
            )
        }
        val csharpAssembly = consumerDirectory.resolve("KClassCSharpConsumer.dll")
        val csharpCompile = runModernCSharpCompiler(
            checkNotNull(csharpToolchain),
            csharpSource,
            csharpAssembly,
            producerDirectory.resolve("KClass.Library.dll"),
            consumerDirectory.resolve(DotNetRuntimeArtifact.ASSEMBLY_FILE_NAME),
            target = "exe",
        )
        assertEquals(0, csharpCompile.exitCode, csharpCompile.output)
        consumerDirectory.resolve("KClassCSharpConsumer.runtimeconfig.json").writeText(net10RuntimeConfig())
        runDotNet(
            checkNotNull(csharpToolchain).dotNetHost,
            csharpAssembly,
            consumerDirectory,
            "C# KClass consumer failed",
        )
    }

    @Test
    fun testKCallableAnnotationsAcrossLibraryAndClrBoundary() {
        requireOrAssumeToolchain(DotNetIlAssembler.findModernIlasm() != null, "Modern ilasm is not available")
        val csharpToolchain = DotNetIlAssembler.findModernCSharpCompiler()
        requireOrAssumeToolchain(
            csharpToolchain != null,
            "Modern Roslyn and the net10 reference pack are not available",
        )

        val producerDirectory = File(tmpdir, "kcallable-producer")
        val producerSource = File(tmpdir, "KCallableLibrary.kt").apply {
            writeText(
                """
                package kcallable.boundary

                import kotlin.reflect.KCallable
                import kotlin.reflect.KFunction0

                @Retention(AnnotationRetention.RUNTIME)
                @Target(AnnotationTarget.FUNCTION, AnnotationTarget.PROPERTY, AnnotationTarget.VALUE_PARAMETER)
                public annotation class LibraryCallableMarker(public val value: String = "library")

                @Retention(AnnotationRetention.BINARY)
                @Target(AnnotationTarget.FUNCTION, AnnotationTarget.PROPERTY)
                public annotation class BinaryCallableMarker

                @LibraryCallableMarker
                @BinaryCallableMarker
                public fun libraryFunction(@LibraryCallableMarker("parameter") value: Int): Int = value + 1

                public inline fun libraryInlineFunction(): Int = 42

                public fun libraryInlineFunctionReference(): KFunction0<Int> = ::libraryInlineFunction

                public open class LibraryOperatorBase {
                    public open operator fun plus(value: Int): Int = value
