                        if (classifier == null || classifier.qualifiedName != "kotlin.Int") return 2;
                        if (callable.typeParameters.Size != 0) return 3;
                        if (callable.parameters.Size != 1) return 4;
                        object result = callable.Call(new object[] { 41 });
                        if ((int)result != 42) return 5;
                        System.Reflection.MethodInfo callBy =
                            typeof(Kotlin.KCallable).GetMethod("CallBy", new[] { typeof(Kotlin.Collections.Map) });
                        if (callBy == null || callBy.ReturnType != typeof(object)) return 6;
                        try
                        {
                            callable.Call(new object[0]);
                            return 7;
                        }
                        catch (System.ArgumentException exception)
                        {
                            if (exception.Message != "Callable expects 1 arguments, but 0 were provided.") return 8;
                        }
                        return 0;
                    }
                }
                """.trimIndent()
            )
        }
        val csharpAssembly = consumerDirectory.resolve("KCallableCSharpConsumer.dll")
        val csharpCompile = runModernCSharpCompiler(
            checkNotNull(csharpToolchain),
            csharpSource,
            csharpAssembly,
            producerAssembly,
            consumerDirectory.resolve(DotNetRuntimeArtifact.ASSEMBLY_FILE_NAME),
            consumerDirectory.resolve("Kotlin.Stdlib.dll"),
            target = "exe",
        )
        assertEquals(0, csharpCompile.exitCode, csharpCompile.output)
        producerAssembly.copyTo(consumerDirectory.resolve(producerAssembly.name), overwrite = true)
        consumerDirectory.resolve("KCallableCSharpConsumer.runtimeconfig.json").writeText(net10RuntimeConfig())
        runDotNet(
            checkNotNull(csharpToolchain).dotNetHost,
            csharpAssembly,
            consumerDirectory,
            "C# KCallable return-type consumer failed",
        )
    }

    @Test
    fun testKClassIdentityDistinguishesSameNamedClassesAcrossAssemblies() {
        requireOrAssumeToolchain(DotNetIlAssembler.findModernIlasm() != null, "Modern ilasm is not available")
        val directory = File(tmpdir, "kclass-assembly-identity").apply { mkdirs() }
        fun assembleSameNamedClass(assemblyName: String) {
            val source = directory.resolve("$assemblyName.il").apply {
                writeText(
                    """
                    .assembly extern mscorlib {}
                    .assembly '$assemblyName' {}
                    .module '$assemblyName.dll'

                    .namespace duplicate
                    {
                      .class public auto ansi sealed beforefieldinit Same
                             extends [mscorlib]System.Object
                      {
                        .method public hidebysig specialname rtspecialname instance void .ctor() cil managed
                        {
                          .maxstack 1
                          ldarg.0
                          call instance void [mscorlib]System.Object::.ctor()
                          ret
                        }
                      }
                    }
                    """.trimIndent()
                )
            }
            assertTrue(
                DotNetIlAssembler.assembleLibrary(
                    source,
                    directory.resolve("$assemblyName.dll"),
                    DotNetTarget.NET10_0,
                    MessageCollector.NONE,
                )
            )
        }
        assembleSameNamedClass("KClass.First")
        assembleSameNamedClass("KClass.Second")
        assertTrue(
            DotNetIlAssembler.assembleRuntimeForTests(
                directory,
                DotNetTarget.NET10_0,
                MessageCollector.NONE,
            )?.isFile == true
        )

        val consumerIl = directory.resolve("KClassAssemblyIdentityConsumer.il").apply {
            writeText(
                """
                .assembly extern mscorlib {}
                .assembly extern Kotlin.Runtime {}
                .assembly extern KClass.First {}
                .assembly extern KClass.Second {}
                .assembly KClassAssemblyIdentityConsumer {}
                .module KClassAssemblyIdentityConsumer.dll

                .method public static void Main() cil managed
                {
                  .entrypoint
                  .maxstack 5
                  .locals init (
                    [0] class [Kotlin.Runtime]Kotlin.KClass first,
                    [1] class [Kotlin.Runtime]Kotlin.KClass second,
                    [2] class [Kotlin.Runtime]Kotlin.KClass dynamicAny,
                    [3] class [Kotlin.Runtime]Kotlin.KClass staticAny
                  )
                  newobj instance void [KClass.First]duplicate.Same::.ctor()
                  call class [Kotlin.Runtime]Kotlin.KClass
                      [Kotlin.Runtime]Kotlin.Runtime.Internal.KClassFactory::GetClass(object)
                  stloc.0
                  newobj instance void [KClass.Second]duplicate.Same::.ctor()
                  call class [Kotlin.Runtime]Kotlin.KClass
                      [Kotlin.Runtime]Kotlin.Runtime.Internal.KClassFactory::GetClass(object)
                  stloc.1
                  ldloc.0
                  ldloc.1
                  callvirt instance bool [mscorlib]System.Object::Equals(object)
                  brfalse.s Success
                  ldstr "same-named classes from distinct assemblies became one KClass"
                  newobj instance void [mscorlib]System.Exception::.ctor(string)
                  throw
                Success:
                  newobj instance void [mscorlib]System.Object::.ctor()
                  call class [Kotlin.Runtime]Kotlin.KClass
                      [Kotlin.Runtime]Kotlin.Runtime.Internal.KClassFactory::GetClass(object)
                  stloc.2
                  ldtoken [mscorlib]System.Object
                  call class [mscorlib]System.Type [mscorlib]System.Type::GetTypeFromHandle(
                      valuetype [mscorlib]System.RuntimeTypeHandle)
                  ldstr "Any"
                  ldstr "kotlin.Any"
                  ldc.i4.0
                  ldc.i4.0
                  call class [Kotlin.Runtime]Kotlin.KClass
                      [Kotlin.Runtime]Kotlin.Runtime.Internal.KClassFactory::Create(
                          class [mscorlib]System.Type, string, string, int32, int32)
                  stloc.3
                  ldloc.2
                  ldloc.3
                  callvirt instance bool [mscorlib]System.Object::Equals(object)
                  brtrue.s AnyIdentityReady
                  ldstr "dynamic System.Object did not retain kotlin.Any identity"
                  newobj instance void [mscorlib]System.Exception::.ctor(string)
                  throw
                AnyIdentityReady:
                  ldloc.2
                  newobj instance void [mscorlib]System.Object::.ctor()
                  callvirt instance bool [Kotlin.Runtime]Kotlin.KClass::isInstance(object)
                  brtrue.s Done
                  ldstr "kotlin.Any KClass rejected System.Object"
                  newobj instance void [mscorlib]System.Exception::.ctor(string)
                  throw
                Done:
                  ret
                }
                """.trimIndent()
            )
        }
        val consumerAssembly = directory.resolve("KClassAssemblyIdentityConsumer.dll")
        assertTrue(
            DotNetIlAssembler.assembleExecutable(
                consumerIl,
                consumerAssembly,
                DotNetTarget.NET10_0,
                MessageCollector.NONE,
            )
        )
        runDotNet(
            modernDotNetHostOrSkip(),
            consumerAssembly,
            directory,
            "KClass assembly-identity consumer failed",
        )
    }

    @Test
    fun testCompanionStaticHoldersBindAcrossModules() {
        requireOrAssumeToolchain(DotNetIlAssembler.findModernIlasm() != null, "Modern ilasm is not available")
        requireOrAssumeToolchain(
            DotNetIlAssembler.findFrameworkIlasm() != null,
            ".NET Framework ilasm is not available",
        )
        val producerDirectory = File(tmpdir, "companion-holder-producer")
        val producerSource = File(tmpdir, "holder-library.kt").apply {
            writeText(
                """
                package companionholder

                public class GenericOwner<T> private constructor(public val value: Int) {
                    public fun reveal(): Int = secret()

                    companion {
                        public const val marker: Int = 7
                        public val answer: Int get() = 42
                        private fun secret(): Int = 11
                        public fun create(value: Int = 40): GenericOwner<String> = GenericOwner(value)
                        public fun <R> echo(value: R): R = value
                    }
                }

                public interface GenericInterface<T> {
                    companion {
                        public const val marker: Int = 9
                        public val answer: Int get() = 43
                        public fun <R> echo(value: R): R = value
                    }
                }

                public class DirectOwner {
                    public fun instanceValue(): Int = 1

                    companion {
                        public fun answer(value: Int = 45): Int = value
                    }
                }

                public fun topLevelAnswer(value: Int = 46): Int = value
                """.trimIndent()
            )
        }
        compileInProcess(
            K2DotNetCompiler(),
            producerSource.path,
            "-Xcompanion-blocks",
            K2DotNetCompilerArguments::dotNetProduceLibrary.cliArgument,
            K2DotNetCompilerArguments::dotNetTarget.cliArgument, "netstandard2.0",
            K2DotNetCompilerArguments::moduleName.cliArgument, "Companion.Holder.Library",
            K2DotNetCompilerArguments::destination.cliArgument, producerDirectory.path,
        )

        val producerIl = producerDirectory.resolve("Companion.Holder.Library.il").readText()
        assertTrue("'companionholder.GenericOwner'/'<CompanionStatics>'" in producerIl) { producerIl }
        assertTrue("'companionholder.GenericInterface'/'<CompanionStatics>'" in producerIl) { producerIl }
        assertTrue("static !!0 'echo'<'R'>(!!0 'value')" in producerIl) { producerIl }
        assertTrue("'create\$default'" in producerIl) { producerIl }
        assertTrue("KotlinCompilerAbiAttribute" in producerIl) { producerIl }

        for (target in listOf("net48", "net10.0")) {
            val profileDirectory = File(tmpdir, "companion-holder-$target")
            compileInProcess(
                K2DotNetCompiler(),
                producerSource.path,
                "-Xcompanion-blocks",
                K2DotNetCompilerArguments::dotNetProduceLibrary.cliArgument,
                K2DotNetCompilerArguments::dotNetTarget.cliArgument, target,
                K2DotNetCompilerArguments::moduleName.cliArgument, "Companion.Holder.Library",
                K2DotNetCompilerArguments::destination.cliArgument, profileDirectory.path,
            )
            val profileIl = profileDirectory.resolve("Companion.Holder.Library.il").readText()
            assertTrue("'companionholder.GenericOwner'/'<CompanionStatics>'" in profileIl) { profileIl }
            assertTrue("'companionholder.GenericInterface'/'<CompanionStatics>'" in profileIl) { profileIl }
            assertTrue("static !!0 'echo'<'R'>(!!0 'value')" in profileIl) { profileIl }
        }

        val consumerDirectory = File(tmpdir, "companion-holder-consumer").apply { mkdirs() }
        val consumerSource = consumerDirectory.resolve("consumer.kt").apply {
            writeText(
                """
                package consumer

                import companionholder.GenericInterface
                import companionholder.GenericOwner
                import companionholder.DirectOwner
                import companionholder.topLevelAnswer

                fun main() {
                    val owner = GenericOwner.create()
                    if (owner.value != 40) throw Error("default")
                    if (owner.reveal() != 11) throw Error("private bridge")
                    if (GenericOwner.marker != 7) throw Error("class const")
                    if (GenericOwner.answer != 42) throw Error("class property")
                    if (GenericOwner.echo("OK") != "OK") throw Error("class generic method")
                    if (GenericInterface.marker != 9) throw Error("interface const")
                    if (GenericInterface.answer != 43) throw Error("interface property")
                    if (GenericInterface.echo(44) != 44) throw Error("interface generic method")
                    val directOwner = DirectOwner()
                    if (directOwner.instanceValue() != 1) throw Error("direct class record")
                    if (DirectOwner.answer() != 45) throw Error("direct class default")
                    if (topLevelAnswer() != 46) throw Error("top-level default")
                }
                """.trimIndent()
            )
        }
        val consumerAssembly = consumerDirectory.resolve("CompanionHolderConsumer.dll")
        compileInProcess(
            K2DotNetCompiler(),
            consumerSource.path,
            "-Xcompanion-blocks",
            K2DotNetCompilerArguments::classpath.cliArgument,
            producerDirectory.resolve("Companion.Holder.Library.dll").path,
            K2DotNetCompilerArguments::dotNetTarget.cliArgument, "net10.0",
            K2DotNetCompilerArguments::moduleName.cliArgument, "CompanionHolderConsumer",
            K2DotNetCompilerArguments::destination.cliArgument, consumerAssembly.path,
        )

        val consumerIl = consumerDirectory.resolve("CompanionHolderConsumer.il").readText()
        val classHolder =
            "[Companion.Holder.Library]'companionholder.GenericOwner'/'<CompanionStatics>'"
        val interfaceHolder =
            "[Companion.Holder.Library]'companionholder.GenericInterface'/'<CompanionStatics>'"
        assertTrue("$classHolder::'create\$default'(int32, int32)" in consumerIl) { consumerIl }
        assertTrue("$classHolder::'get_answer'()" in consumerIl) { consumerIl }
        assertTrue("$classHolder::'echo'<string>(!!0)" in consumerIl) { consumerIl }
        assertTrue("$interfaceHolder::'get_answer'()" in consumerIl) { consumerIl }
        assertTrue("$interfaceHolder::'echo'<int32>(!!0)" in consumerIl) { consumerIl }
        runDotNet(
            modernDotNetHostOrSkip(),
            consumerAssembly,
            consumerDirectory,
            "Companion-holder cross-module consumer failed",
        )
    }

    @Test
    fun testCompanionInitializationGraphBindsAcrossModules() {
        requireOrAssumeToolchain(DotNetIlAssembler.findModernIlasm() != null, "Modern ilasm is not available")
        requireOrAssumeToolchain(
            DotNetIlAssembler.findFrameworkIlasm() != null,
            ".NET Framework ilasm is not available",
        )
        val producerSource = File(tmpdir, "companion-initialization-library.kt").apply {
            writeText(
                """
                package companioninit

                private var initializationOrder: String = ""

                public fun recordInitialization(tag: String): String {
                    initializationOrder += tag
                    return tag
                }

                public fun currentInitializationOrder(): String = initializationOrder

                public open class Parent {
                    companion {
                        public val state: String = recordInitialization("P")
                    }
                }

                public interface SelectedDefault {
                    companion {
                        public val state: String = recordInitialization("I")
                    }

                    public fun selected(): String = "selected"
                }

                public interface AbstractOnly {
                    companion {
                        public val state: String = recordInitialization("A")
                    }

                    public fun abstractMember(): String
                }

                public open class ProducerChild : Parent(), AbstractOnly, SelectedDefault {
                    companion {
                        public val state: String = recordInitialization("C")
                    }

                    override fun abstractMember(): String = "abstract"
                }

                public object ProducerSingleton {
                    public val state: String = recordInitialization("O")
                }

                public class GenericProducer<T> {
                    companion object {
                        public val state: String = recordInitialization("G")
                    }
                }

                public open class GenericPrivateState<T> {
                    companion {
                        private val state: String = recordInitialization("H")
                    }
                }

                public class PortableMixed<T> {
                    companion {
                        public val first: String = "first"
                    }

                    companion object {
                        public val second: String = "second"
                    }

                    companion {
                        public val third: String = "third"
                    }
                }

                public interface PortableInterfaceMixed {
                    companion {
                        public val first: String = "first"
                    }

                    companion object {
                        public val second: String = "second"
                    }

                    companion {
                        public val third: String = "third"
                    }
                }
                """.trimIndent()
            )
        }

        fun compileProducer(target: String, directory: File) {
            compileInProcess(
                K2DotNetCompiler(),
                producerSource.path,
                "-Xcompanion-blocks",
                K2DotNetCompilerArguments::dotNetProduceLibrary.cliArgument,
                K2DotNetCompilerArguments::dotNetTarget.cliArgument, target,
                K2DotNetCompilerArguments::moduleName.cliArgument, "Companion.Initialization.Library",
                K2DotNetCompilerArguments::destination.cliArgument, directory.path,
            )
            val il = directory.resolve("Companion.Initialization.Library.il").readText()
            assertTrue("'<EnsureInitialized>'" in il) { il }
            assertTrue("KotlinCompilerAbiAttribute" in il) { il }
        }

        val producerDirectory = File(tmpdir, "companion-initialization-producer")
        compileProducer("netstandard2.0", producerDirectory)
        compileProducer("net48", File(tmpdir, "companion-initialization-net48"))
        compileProducer("net10.0", File(tmpdir, "companion-initialization-net10"))

        val consumerDirectory = File(tmpdir, "companion-initialization-consumer").apply { mkdirs() }
        val consumerSource = consumerDirectory.resolve("consumer.kt").apply {
            writeText(
                """
                package consumer

                import companioninit.AbstractOnly
                import companioninit.GenericProducer
                import companioninit.GenericPrivateState
                import companioninit.ProducerChild
                import companioninit.ProducerSingleton
                import companioninit.currentInitializationOrder
                import companioninit.recordInitialization

                class ConsumerChild : ProducerChild() {
                    companion {
                        val state: String = recordInitialization("D")
                    }
                }


                class GenericPrivateConsumer : GenericPrivateState<String>() {
                    companion {
                        val state: String = recordInitialization("J")
                    }
                }

                fun main() {
                    if (ConsumerChild.state != "D") throw Error("consumer state")
                    if (currentInitializationOrder() != "PICD") {
                        throw Error("cross-module order=" + currentInitializationOrder())
                    }
                    if (AbstractOnly.state != "A") throw Error("abstract-only state")
                    if (currentInitializationOrder() != "PICDA") {
                        throw Error("abstract-only order=" + currentInitializationOrder())
                    }
                    ConsumerChild()
                    if (currentInitializationOrder() != "PICDA") throw Error("reinitialized")

                    if (ProducerSingleton.state != "O") throw Error("ordinary object state")
                    if (GenericProducer.state != "G") throw Error("generic companion state")
                    GenericProducer<String>()
                    GenericProducer<Int>()
                    if (currentInitializationOrder() != "PICDAOG") {
                        throw Error("object binding order=" + currentInitializationOrder())
                    }
                    if (GenericPrivateConsumer.state != "J") throw Error("private holder state")
                    if (currentInitializationOrder() != "PICDAOGHJ") {
                        throw Error("private holder order=" + currentInitializationOrder())
                    }
                }
                """.trimIndent()
            )
        }
        val consumerAssembly = consumerDirectory.resolve("CompanionInitializationConsumer.dll")
        compileInProcess(
            K2DotNetCompiler(),
            consumerSource.path,
            "-Xcompanion-blocks",
            K2DotNetCompilerArguments::classpath.cliArgument,
            producerDirectory.resolve("Companion.Initialization.Library.dll").path,
            K2DotNetCompilerArguments::dotNetTarget.cliArgument, "net10.0",
            K2DotNetCompilerArguments::moduleName.cliArgument, "CompanionInitializationConsumer",
            K2DotNetCompilerArguments::destination.cliArgument, consumerAssembly.path,
        )

        val consumerIl = consumerDirectory.resolve("CompanionInitializationConsumer.il").readText()
        assertTrue(
            "call void [Companion.Initialization.Library]'companioninit.ProducerChild'::" +
                    "'<EnsureInitialized>'()" in consumerIl
        ) { consumerIl }
        assertTrue("ldsfld" in consumerIl && "'<CompanionStatics>'::'Companion'" in consumerIl) { consumerIl }
        assertTrue("'companioninit.ProducerSingleton'::'INSTANCE'" in consumerIl) { consumerIl }
        assertTrue(
            "call void [Companion.Initialization.Library]'companioninit.GenericPrivateState'/" +
                    "'<CompanionStatics>'::'<EnsureInitialized>'()" in consumerIl
        ) { consumerIl }
        runDotNet(
            modernDotNetHostOrSkip(),
            consumerAssembly,
            consumerDirectory,
            "Companion-initialization cross-module consumer failed",
        )
    }

    @Test
    fun testStaticInitializationFailuresPreserveKotlinSemanticsAcrossModules() {
        requireOrAssumeToolchain(DotNetIlAssembler.findModernIlasm() != null, "Modern ilasm is not available")
        requireOrAssumeToolchain(
            DotNetIlAssembler.findFrameworkIlasm() != null,
            ".NET Framework ilasm is not available",
        )
        val dotnetHost = modernDotNetHostOrSkip()
        val frameworkHost = DotNetIlAssembler.findFrameworkPowerShellHost()
        requireOrAssumeToolchain(frameworkHost != null, "Windows PowerShell CLR 4 host is not available")

        val producerDirectory = File(tmpdir, "static-initialization-failure-producer").apply { mkdirs() }
        val declarationsSource = producerDirectory.resolve("declarations.kt").apply {
            writeText(
                """
                package staticfailure

                public val classCause: IllegalStateException = IllegalStateException("class")
                public val genericClassCause: IllegalStateException = IllegalStateException("generic class")
                public val objectCause: IllegalStateException = IllegalStateException("object")
                public val fileCause: IllegalStateException = IllegalStateException("file")

                public class ProducerFailure {
                    public companion object {
                        public val never: Int = throw classCause
                    }
                }

                public open class ProducerGenericParentFailure {
                    public companion object {
                        public val never: Int = throw genericClassCause
                    }
                }

                public class ProducerGenericChildFailure<T> : ProducerGenericParentFailure()

                public object ProducerObjectFailure {
                    public val never: Int = throw objectCause
                }

                public class ProducerExactError(message: String) : Error(message)

                public val exactCause: ProducerExactError = ProducerExactError("exact")

                public object ProducerExactFailure {
                    public val never: Int = throw exactCause
                }
                """.trimIndent()
            )
        }
        val fileFailureSource = producerDirectory.resolve("failingFile.kt").apply {
            writeText(
                """
                package staticfailure

                public val failingFileValue: Int = throw fileCause
                public val unreachableFileValue: Int = 42
                """.trimIndent()
            )
        }
        compileInProcess(
            K2DotNetCompiler(),
            declarationsSource.path,
            fileFailureSource.path,
            K2DotNetCompilerArguments::dotNetProduceLibrary.cliArgument,
            K2DotNetCompilerArguments::dotNetTarget.cliArgument, "netstandard2.0",
            K2DotNetCompilerArguments::moduleName.cliArgument, "Static.Initialization.Failures",
            K2DotNetCompilerArguments::destination.cliArgument, producerDirectory.path,
        )

        val producerAssembly = producerDirectory.resolve("Static.Initialization.Failures.dll")
        val producerIl = producerDirectory.resolve("Static.Initialization.Failures.il").readText()
        assertTrue("StaticInitialization'::'Capture'" in producerIl) { producerIl }
        assertTrue("StaticInitialization'::'Observe'" in producerIl) { producerIl }
        assertTrue("StaticInitialization'::'Throw'" in producerIl) { producerIl }
        assertTrue("'<static-initialization-failure>'" in producerIl) { producerIl }
        assertTrue("'<StaticInitialization>'" in producerIl) { producerIl }
        val producerDeclarations = DotNetLibraryAbiCodec.decode(producerAssembly.readKlibManifest())
        val initializationOwners = producerDeclarations.values
            .filterIsInstance<DotNetPhysicalDeclaration.Class>()
            .filter { it.staticInitialization != null }
            .mapTo(linkedSetOf()) { it.ownerPath.last() }
        assertTrue("staticfailure.ProducerFailure" in initializationOwners) {
            initializationOwners.toString()
        }
        assertTrue("staticfailure.ProducerObjectFailure" in initializationOwners) {
            initializationOwners.toString()
        }
        assertTrue("staticfailure.ProducerExactFailure" in initializationOwners) {
            initializationOwners.toString()
        }
        val genericChildDeclaration = producerDeclarations.values
            .filterIsInstance<DotNetPhysicalDeclaration.Class>()
            .single { declaration ->
                declaration.staticInitialization?.ownerPath?.last() == "<StaticInitialization>"
            }
        assertEquals("staticfailure.ProducerGenericChildFailure", genericChildDeclaration.ownerPath.last())
        assertEquals(
            "<StaticInitialization>",
            genericChildDeclaration.staticInitialization?.ownerPath?.last(),
        )

        val consumerSource = File(tmpdir, "static-initialization-failure-consumer.kt").apply {
            writeText(
                """
                package consumer

                import staticfailure.ProducerExactError
                import staticfailure.ProducerExactFailure
                import staticfailure.ProducerFailure
                import staticfailure.ProducerGenericChildFailure
                import staticfailure.ProducerObjectFailure
                import staticfailure.classCause
                import staticfailure.exactCause
                import staticfailure.failingFileValue
                import staticfailure.fileCause
                import staticfailure.genericClassCause
                import staticfailure.objectCause
                import staticfailure.unreachableFileValue

                private fun failureMessage(failure: Throwable): String? = failure.message
                private fun failureCause(failure: Throwable): Throwable? = failure.cause

                fun main() {
                    @Suppress("INVISIBLE_REFERENCE")
                    try {
                        ProducerFailure()
                        throw Error("class first did not fail")
                    } catch (failure: ExceptionInInitializerError) {
                        if (failureCause(failure) !== classCause) throw Error("class cause identity")
                    }

                    @Suppress("INVISIBLE_REFERENCE")
                    try {
                        ProducerFailure()
                        throw Error("class later did not fail")
                    } catch (failure: NoClassDefFoundError) {
                        if (failureMessage(failure) !=
                            "Could not initialize class staticfailure.ProducerFailure"
                        ) {
                            throw Error("class later message=" + failureMessage(failure))
                        }
                    }

                    @Suppress("INVISIBLE_REFERENCE")
                    try {
                        ProducerGenericChildFailure<String>()
                        throw Error("generic class first did not fail")
                    } catch (failure: ExceptionInInitializerError) {
                        if (failureCause(failure) !== genericClassCause) {
                            throw Error("generic class cause identity")
                        }
                    }

                    @Suppress("INVISIBLE_REFERENCE")
                    try {
                        ProducerGenericChildFailure<Int>()
                        throw Error("generic class later did not fail")
                    } catch (failure: NoClassDefFoundError) {
                        if (failureMessage(failure) !=
                            "Could not initialize class staticfailure.ProducerGenericChildFailure"
                        ) {
                            throw Error("generic class later message=" + failureMessage(failure))
                        }
                    }

                    @Suppress("INVISIBLE_REFERENCE")
                    try {
                        ProducerObjectFailure.never
                        throw Error("object first did not fail")
                    } catch (failure: ExceptionInInitializerError) {
                        if (failureCause(failure) !== objectCause) throw Error("object cause identity")
                    }

                    @Suppress("INVISIBLE_REFERENCE")
                    try {
                        ProducerObjectFailure.never
                        throw Error("object later did not fail")
                    } catch (failure: NoClassDefFoundError) {
                        if (failureMessage(failure) !=
                            "Could not initialize class staticfailure.ProducerObjectFailure"
                        ) {
                            throw Error("object later message=" + failureMessage(failure))
                        }
                    }

                    try {
                        ProducerExactFailure.never
                        throw Error("exact Error first did not fail")
                    } catch (failure: ProducerExactError) {
                        if (failure !== exactCause) throw Error("exact Error identity")
                    }

                    @Suppress("INVISIBLE_REFERENCE")
                    try {
                        ProducerExactFailure.never
                        throw Error("exact Error later did not fail")
                    } catch (failure: NoClassDefFoundError) {
                        if (failureMessage(failure) !=
                            "Could not initialize class staticfailure.ProducerExactFailure"
                        ) {
                            throw Error("exact Error later message=" + failureMessage(failure))
                        }
                    }

                    @Suppress("INVISIBLE_REFERENCE")
                    try {
                        failingFileValue
                        throw Error("file first did not fail")
                    } catch (failure: ExceptionInInitializerError) {
                        if (failureCause(failure) !== fileCause) throw Error("file cause identity")
                    }

                    @Suppress("INVISIBLE_REFERENCE")
                    try {
                        unreachableFileValue
                        throw Error("file later did not fail")
                    } catch (failure: NoClassDefFoundError) {
                        if (failureMessage(failure) != "Could not initialize file") {
                            throw Error("file later message=" + failureMessage(failure))
                        }
                    }

                    println("OK")
                }
                """.trimIndent()
            )
        }

        for (target in listOf("net48", "net10.0")) {
            val consumerDirectory = File(tmpdir, "static-initialization-failure-$target").apply { mkdirs() }
            val consumerAssembly = consumerDirectory.resolve(
                if (target == "net48") "StaticInitializationFailureConsumer.exe"
                else "StaticInitializationFailureConsumer.dll"
            )
            compileInProcess(
                K2DotNetCompiler(),
