                fun main() {
                    if (throughA(10) { it + 1 } != 23) throw Error("selected inline dependency graph")
                    println("OK")
                }
                """.trimIndent()
            )
        }

        for (case in listOf(
            "intra-module" to "Prepared",
            "full" to "Full",
            "disabled" to "Main",
        )) {
            val mode = case.first
            val suffix = case.second
            val libraryBDirectory = File(tmpdir, "inline-graph-b-$suffix").apply { mkdirs() }
