    @Test
    fun testSuspendInlineFunctionsAndSafeContinuationRace() {
        requireOrAssumeToolchain(DotNetIlAssembler.findModernIlasm() != null, "Modern ilasm is not available")
        val modernCSharp = DotNetIlAssembler.findModernCSharpCompiler()
        requireOrAssumeToolchain(
            modernCSharp != null,
            "Modern Roslyn and the net10 reference pack are not available",
        )
        val source = File(tmpdir, "inline-suspend.kt").apply {
            writeText(
                """
                package inline.suspendshape

                import kotlin.coroutines.*

                suspend inline fun suspended(block: () -> Int): Int = block()

                private var pending: Continuation<Unit>? = null
                private var completed: Int = 0

                private object RaceCompletion : Continuation<Unit> {
                    override val context: CoroutineContext
                        get() = EmptyCoroutineContext

                    override fun resumeWith(result: Result<Unit>) {
                        result.getOrThrow()
                    }
                }

                public fun prepareRace() {
                    pending = null
                    completed = 0
                    val block: suspend () -> Unit = {
                        suspendCoroutine<Unit> { continuation ->
                            pending = continuation
                        }
                        completed += 1
                    }
                    block.startCoroutine(RaceCompletion)
                    if (pending == null) throw IllegalStateException("Continuation was not captured")
                }

                public fun resumeRace() {
                    pending!!.resume(Unit)
                }

                public fun completedCount(): Int = completed

                fun main() {
                    var result = 0
                    val block: suspend () -> Unit = {
                        result = suspended { 42 }
                    }
                    block.startCoroutine(RaceCompletion)
                    if (result != 42) throw IllegalStateException("Suspend inline result: ${'$'}result")
                    println("OK")
                }
                """.trimIndent()
            )
        }
        val outputDirectory = File(tmpdir, "inline-suspend-output").apply { mkdirs() }
        val output = outputDirectory.resolve("InlineSuspend.dll")
        val [diagnostics, exitCode] = AbstractCliTest.executeCompilerGrabOutput(
            K2DotNetCompiler(),
            listOf(
                source.path,
                K2DotNetCompilerArguments::dotNetTarget.cliArgument, "net10.0",
                K2DotNetCompilerArguments::moduleName.cliArgument, "InlineSuspend",
                K2DotNetCompilerArguments::destination.cliArgument, output.path,
            ),
        )

        assertEquals(ExitCode.OK, exitCode, diagnostics)
        assertFalse("requires coroutine lowering" in diagnostics) { diagnostics }
        val il = outputDirectory.resolve("InlineSuspend.il").readText()
        assertTrue("extends [Kotlin.Stdlib]'Kotlin.Coroutines.DotNetCoroutineImpl'" in il) { il }
        assertTrue("'resumeRace'" in il) {
            "The public continuation-resume entry point was evicted:\n$diagnostics\n\n$il"
        }
        runDotNet(modernDotNetHostOrSkip(), output, outputDirectory, "Suspend-inline executable failed")

        val raceSource = outputDirectory.resolve("race.cs").apply {
            writeText(
                """
                using System;
                using System.Linq;
                using System.Reflection;
                using System.Threading;

                public static class SafeContinuationRace
                {
                    private static MethodInfo Find(Assembly assembly, string name)
                    {
                        return assembly.GetTypes()
                            .SelectMany(type => type.GetMethods(
                                BindingFlags.Public | BindingFlags.Static | BindingFlags.DeclaredOnly))
                            .Single(method => method.Name == name && method.GetParameters().Length == 0);
                    }

                    public static int Main()
                    {
                        Assembly kotlin = Assembly.LoadFrom("InlineSuspend.dll");
                        MethodInfo prepare = Find(kotlin, "prepareRace");
                        MethodInfo resume = Find(kotlin, "resumeRace");
                        MethodInfo count = Find(kotlin, "completedCount");
                        prepare.Invoke(null, null);

                        var gate = new ManualResetEventSlim(false);
                        int successes = 0;
                        int duplicateFailures = 0;
                        Exception unexpected = null;
                        ThreadStart action = () =>
                        {
                            gate.Wait();
                            try
                            {
                                resume.Invoke(null, null);
                                Interlocked.Increment(ref successes);
                            }
                            catch (TargetInvocationException failure)
                                when (failure.InnerException is InvalidOperationException)
                            {
                                Interlocked.Increment(ref duplicateFailures);
                            }
                            catch (Exception failure)
                            {
                                Interlocked.CompareExchange(ref unexpected, failure, null);
                            }
                        };

                        var first = new Thread(action);
                        var second = new Thread(action);
                        first.Start();
                        second.Start();
                        gate.Set();
                        if (!first.Join(TimeSpan.FromSeconds(10)) ||
                            !second.Join(TimeSpan.FromSeconds(10))) return 1;
                        if (unexpected != null) throw unexpected;
                        if (successes != 1 || duplicateFailures != 1) return 2;
                        if ((int)count.Invoke(null, null) != 1) return 3;
                        return 0;
                    }
                }
                """.trimIndent()
            )
        }
        val raceRunner = outputDirectory.resolve("SafeContinuationRace.dll")
        val csharpResult = runModernCSharpCompiler(
            checkNotNull(modernCSharp),
            raceSource,
            raceRunner,
            target = "exe",
        )
        assertEquals(0, csharpResult.exitCode, csharpResult.output)
        outputDirectory.resolve("SafeContinuationRace.runtimeconfig.json").writeText(net10RuntimeConfig())
        runDotNet(
            modernCSharp.dotNetHost,
            raceRunner,
            outputDirectory,
            "Concurrent SafeContinuation C# probe failed",
        )
    }

    @Test
    fun testSuspendPhysicalAbiAcrossPortableLibrary() {
        requireOrAssumeToolchain(DotNetIlAssembler.findModernIlasm() != null, "Modern ilasm is not available")
        val frameworkHost = DotNetIlAssembler.findFrameworkPowerShellHost()
        requireOrAssumeToolchain(frameworkHost != null, "Windows PowerShell CLR 4 host is not available")

        val producerSource = File(tmpdir, "coroutine-abi-producer.kt").apply {
            writeText(
                """
                package coroutine.abi

                import kotlin.coroutines.Continuation
                import kotlin.coroutines.resume
                import kotlin.coroutines.suspendCoroutine

                private var pending: Continuation<Int>? = null

                private suspend fun park(): Int = suspendCoroutine { continuation ->
                    if (pending != null) throw IllegalStateException("A continuation is already pending")
                    pending = continuation
                }

                public fun resume(value: Int) {
                    val continuation = pending ?: throw IllegalStateException("No continuation is pending")
                    pending = null
                    continuation.resume(value)
                }

                public suspend fun top(seed: Int): String = (seed + park()).toString()

                public open class Worker {
                    public open suspend fun compute(seed: Int): String = (seed + park()).toString()
                }

                public class Derived : Worker() {
                    override suspend fun compute(seed: Int): String = super.compute(seed) + "!"
                }
                """.trimIndent()
            )
        }
        val producerDirectory = File(tmpdir, "coroutine-abi-producer").apply { mkdirs() }
        compileInProcess(
            K2DotNetCompiler(),
            producerSource.path,
            K2DotNetCompilerArguments::dotNetProduceLibrary.cliArgument,
            K2DotNetCompilerArguments::dotNetTarget.cliArgument, "netstandard2.0",
            K2DotNetCompilerArguments::moduleName.cliArgument, "Coroutine.Abi",
            K2DotNetCompilerArguments::destination.cliArgument, producerDirectory.path,
        )

        val producerAssembly = producerDirectory.resolve("Coroutine.Abi.dll")
        val metadata = DotNetClrMetadataReader.read(producerAssembly)
        val stdlibReference = metadata.assemblyReferences.single { reference ->
            reference.name == "Kotlin.Stdlib"
        }
        val continuationReference = metadata.typeReferences.single { reference ->
            reference.namespaceName == "Kotlin.Coroutines" &&
                    reference.metadataName == "Continuation" &&
                    reference.resolutionScope == stdlibReference.handle
        }
        val coroutineBaseReference = metadata.typeReferences.single { reference ->
            reference.namespaceName == "Kotlin.Coroutines" &&
                    reference.metadataName == "DotNetCoroutineImpl" &&
                    reference.resolutionScope == stdlibReference.handle
        }
        val continuationType = DotNetClrTypeSignature.Named(
            type = continuationReference.handle,
            isValueType = false,
        )
        val erasedResultType = DotNetClrTypeSignature.Primitive(DotNetClrPrimitiveType.OBJECT)
        val intType = DotNetClrTypeSignature.Primitive(DotNetClrPrimitiveType.INT32)

        fun assertSuspendEntry(
            owner: DotNetClrTypeDefinition,
            name: String,
            isStatic: Boolean,
        ) {
            val method = metadata.methodDefinitions.single { candidate ->
                candidate.declaringType == owner.handle && candidate.name == name
            }
            assertEquals(DotNetClrMethodVisibility.PUBLIC, method.visibility)
            assertEquals(isStatic, method.isStatic)
            if (!isStatic) {
                assertTrue(method.isVirtual) { "A suspend override must retain its CLR virtual slot: $method" }
            }
            assertEquals(erasedResultType, method.signature.returnType)
            assertEquals(listOf(intType, continuationType), method.signature.parameterTypes)
        }

        val topEntry = metadata.methodDefinitions.single { method ->
            method.name == "top" && method.isStatic
        }
        val facade = metadata.typeDefinitions.single { definition ->
            definition.handle == topEntry.declaringType
        }
        val worker = metadata.typeDefinitions.single { definition ->
            definition.namespaceName == "coroutine.abi" && definition.metadataName == "Worker"
        }
        val derived = metadata.typeDefinitions.single { definition ->
            definition.namespaceName == "coroutine.abi" && definition.metadataName == "Derived"
        }
        assertSuspendEntry(facade, "top", isStatic = true)
        assertSuspendEntry(worker, "compute", isStatic = false)
        assertSuspendEntry(derived, "compute", isStatic = false)

        val stateMachines = metadata.typeDefinitions.filter { definition ->
            definition.baseType == coroutineBaseReference.handle
        }
        assertTrue(stateMachines.size >= 2) {
            "Both non-tail suspend bodies must lower to private CLR state machines: ${metadata.typeDefinitions}"
        }
        for (stateMachine in stateMachines) {
            assertTrue(
                stateMachine.visibility == DotNetClrTypeVisibility.NOT_PUBLIC ||
                        stateMachine.visibility == DotNetClrTypeVisibility.NESTED_PRIVATE
            ) {
                "A generated coroutine state machine became externally visible: $stateMachine"
            }
            assertTrue(stateMachine.isSealed) { "A generated coroutine state machine must be sealed: $stateMachine" }
            val constructor = metadata.methodDefinitions.single { method ->
                method.declaringType == stateMachine.handle && method.name == ".ctor"
            }
            assertEquals(DotNetClrMethodVisibility.PUBLIC, constructor.visibility) {
                "A private state-machine TypeDef needs a callable public-in-private-type constructor"
            }
            assertEquals(DotNetClrTypeSignature.Void, constructor.signature.returnType)
            assertEquals(continuationType, constructor.signature.parameterTypes.last()) {
                "Private constructor layout may retain receivers and live parameters, but completion must remain last"
            }
        }

        val consumerSource = File(tmpdir, "coroutine-abi-consumer.kt").apply {
            writeText(
                """
                package coroutine.consumer

                import coroutine.abi.Derived
                import coroutine.abi.Worker
                import coroutine.abi.resume
                import coroutine.abi.top
                import kotlin.coroutines.Continuation
                import kotlin.coroutines.CoroutineContext
                import kotlin.coroutines.EmptyCoroutineContext
                import kotlin.coroutines.startCoroutine

                private class Completion : Continuation<String> {
                    override val context: CoroutineContext
                        get() = EmptyCoroutineContext

                    var completed: Boolean = false
                    var value: String? = null

                    override fun resumeWith(result: Result<String>) {
                        value = result.getOrThrow()
                        completed = true
                    }
                }

                private fun launch(block: suspend () -> String): Completion {
                    val completion = Completion()
                    block.startCoroutine(completion)
                    if (completion.completed) throw IllegalStateException("The producer did not suspend")
                    return completion
                }

                fun main() {
                    val topCompletion = launch { top(40) }
                    resume(2)
                    if (!topCompletion.completed || topCompletion.value != "42") {
                        throw IllegalStateException("Top-level result: ${'$'}{topCompletion.value}")
                    }

                    val worker: Worker = Derived()
                    val memberCompletion = launch { worker.compute(39) }
                    resume(3)
                    if (!memberCompletion.completed || memberCompletion.value != "42!") {
                        throw IllegalStateException("Virtual result: ${'$'}{memberCompletion.value}")
                    }
                    println("OK")
                }
                """.trimIndent()
            )
        }
        for (target in listOf("net48", "net10.0")) {
            val targetName = if (target == "net48") "Framework" else "Core"
            val consumerDirectory = File(tmpdir, "coroutine-abi-consumer-$targetName").apply { mkdirs() }
            val consumerAssembly = consumerDirectory.resolve(
                if (target == "net48") "CoroutineAbiConsumer.exe" else "CoroutineAbiConsumer.dll"
            )
            compileInProcess(
                K2DotNetCompiler(),
                consumerSource.path,
                K2DotNetCompilerArguments::classpath.cliArgument, producerAssembly.path,
                K2DotNetCompilerArguments::dotNetTarget.cliArgument, target,
                K2DotNetCompilerArguments::moduleName.cliArgument, "CoroutineAbi${targetName}Consumer",
                K2DotNetCompilerArguments::destination.cliArgument, consumerAssembly.path,
            )
            if (target == "net48") {
                runAssemblerPairing(
                    frameworkExecutionCommand(checkNotNull(frameworkHost), consumerAssembly),
                    consumerDirectory,
                    "Framework portable-coroutine consumer failed",
                )
            } else {
                runDotNet(
                    modernDotNetHostOrSkip(),
                    consumerAssembly,
                    consumerDirectory,
                    "CoreCLR portable-coroutine consumer failed",
                )
            }
        }
    }

    @Test
    fun testProducesPortableSelfDescribingUserLibrary() {
        requireOrAssumeToolchain(DotNetIlAssembler.findModernIlasm() != null, "Modern ilasm is not available")
        val frameworkHost = DotNetIlAssembler.findFrameworkPowerShellHost()
        requireOrAssumeToolchain(frameworkHost != null, "Windows PowerShell CLR 4 host is not available")
        val source = File(tmpdir, "library.kt").apply {
            writeText(
                """
                package sample

                public fun increment(value: Int): Int = value + 1

                public class Counter(public val value: Int) {
                    public fun plus(delta: Int): Int = value + delta
                }
                """.trimIndent()
            )
        }
        val outputDirectory = File(tmpdir, "sample-library").apply {
            mkdirs()
            resolve("Sample.Library.klib").writeText("obsolete sibling")
            resolve(".Sample.Library.klib.tmp").mkdirs()
        }
        compileInProcess(
            K2DotNetCompiler(),
            source.path,
            K2DotNetCompilerArguments::dotNetProduceLibrary.cliArgument,
            K2DotNetCompilerArguments::dotNetTarget.cliArgument, "netstandard2.0",
            K2DotNetCompilerArguments::moduleName.cliArgument, "Sample.Library",
            K2DotNetCompilerArguments::dotNetExports.cliArgument, "sample.increment=Increment",
            K2DotNetCompilerArguments::destination.cliArgument, outputDirectory.path,
        )

        val implementationLibrary = outputDirectory.resolve("Sample.Library.dll")
        assertTrue(implementationLibrary.isFile) { "Expected self-describing CLR library at $implementationLibrary" }
        assertFalse(outputDirectory.resolve("Sample.Library.klib").exists()) {
            "The library producer must remove an obsolete sibling KLIB"
        }
        assertFalse(outputDirectory.resolve(".Sample.Library.klib.tmp").exists()) {
            "The library producer must remove an obsolete temporary sibling KLIB"
        }
        val manifest = implementationLibrary.readKlibManifest()
        assertTrue(manifest.getProperty("unique_name") == "Sample.Library")
        assertTrue(manifest.getProperty("dotnet_assembly_name") == "Sample.Library")
        assertTrue(manifest.getProperty("dotnet_assembly_version") == "1.0.0.0")
        assertTrue(manifest.getProperty("dotnet_assembly_file") == "Sample.Library.dll")
        assertEquals("netstandard2.0", manifest.getProperty("dotnet_library_tfm"))
        assertEquals(DotNetLibraryAbiCodec.ABI_VERSION, manifest.getProperty("dotnet_abi_version"))
        assertEquals("", manifest.getProperty(DotNetLibraryAbiCodec.FRIEND_ASSEMBLIES_PROPERTY))
        assertEquals(
            DotNetKotlinMetadataResource.EMBEDDED_KLIB_FORMAT,
            manifest.getProperty(DotNetKotlinMetadataResource.CONTAINER_FORMAT_PROPERTY),
        )
        assertEquals(
            DotNetKotlinMetadataResource.SELF_IMPLEMENTATION_BINDING,
            manifest.getProperty(DotNetKotlinMetadataResource.IMPLEMENTATION_BINDING_PROPERTY),
        )
        assertTrue(
            manifest.getProperty(DotNetLibraryAbiCodec.LOGICAL_IDENTITY_SCHEME_PROPERTY) ==
                    DotNetLibraryAbiCodec.LOGICAL_IDENTITY_SCHEME
        )
        assertTrue(
            manifest.getProperty(DotNetLibraryAbiCodec.PHYSICAL_NAME_GRAMMAR_VERSION_PROPERTY) ==
                    DotNetLibraryAbiCodec.PHYSICAL_NAME_GRAMMAR_VERSION
        )
        assertTrue(
            manifest.getProperty(DotNetLibraryAbiCodec.RUNTIME_SURFACE_LEVEL_PROPERTY) ==
                    DotNetLibraryAbiCodec.CURRENT_RUNTIME_SURFACE_LEVEL.toString()
        )
        assertFalse(DotNetLibraryAbiCodec.IMPLEMENTATION_SHA256_PROPERTY in manifest.stringPropertyNames())
        assertTrue(manifest.stringPropertyNames().any { it.startsWith("dotnet_decl_") })

        val embeddedMetadata = outputDirectory.resolve("Sample.Library.embedded.klib").apply {
            writeBytes(
                readFrameworkManagedResource(
                    checkNotNull(frameworkHost),
                    implementationLibrary,
                    DotNetKotlinMetadataResource.MANAGED_RESOURCE_NAME,
                )
            )
        }
        val embeddedManifest = embeddedMetadata.readKlibManifest()
        assertEquals(manifest, embeddedManifest)
        val compilerPayload = implementationLibrary.readKlibPayloadEntries()
        val embeddedPayload = embeddedMetadata.readKlibPayloadEntries()
        assertEquals(compilerPayload.keys, embeddedPayload.keys)
        for (entryName in compilerPayload.keys) {
            assertArrayEquals(
                compilerPayload.getValue(entryName),
                embeddedPayload.getValue(entryName),
                "JVM and Framework resource readers differ at $entryName",
            )
        }
        val packedLibrary = loadPackedKlib(implementationLibrary.toPath(), implementationLibrary.readKlibCarrier())
        assertEquals(1, checkNotNull(packedLibrary.ir).irFileCount) {
            "A one-source user library must retain its IR without injected bootstrap-stdlib files"
        }

        val il = outputDirectory.resolve("Sample.Library.il").readText()
        assertTrue(".assembly extern netstandard" in il)
        assertTrue("System.Runtime.Versioning.TargetFrameworkAttribute" in il)
        assertTrue(".ver 1:0:0:0" in il)
        assertTrue(".module 'Sample.Library.dll'" in il)
        assertTrue("'Increment'(int32 'value')" in il)
        assertTrue(".entrypoint" !in il)
        assertTrue("[mscorlib]" !in il)
        assertTrue("'kotlin.internal.UsedFromCompilerGeneratedCode'" !in il) {
            "A resolution-only target-stdlib annotation leaked into a user library:\n$il"
        }
        assertTrue(
            ".mresource private ${DotNetKotlinMetadataResource.MANAGED_RESOURCE_NAME}" in il
        ) {
            il
        }

        val dotnetHost = modernDotNetHostOrSkip()
        val consumerIl = outputDirectory.resolve("LibraryConsumer.il").apply {
            writeText(
                """
                .assembly extern mscorlib {}
                .assembly extern Sample.Library
                {
                  .ver 1:0:0:0
                }
                .assembly LibraryConsumer {}
                .module LibraryConsumer.dll

                .method public static void Main() cil managed
                {
                  .entrypoint
                  .maxstack 2
                  ldc.i4.s 41
                  call int32 [Sample.Library]'sample.libraryKt'::'Increment'(int32)
                  ldc.i4.s 42
                  beq.s IL_success
                  ldstr "Portable Kotlin library returned an unexpected result."
                  newobj instance void [mscorlib]System.Exception::.ctor(string)
                  throw
                IL_success:
                  ret
                }
                """.trimIndent()
            )
        }
        val consumerAssembly = outputDirectory.resolve("LibraryConsumer.dll")
        assertTrue(
            DotNetIlAssembler.assembleExecutable(
                consumerIl,
                consumerAssembly,
                DotNetTarget.NET10_0,
                MessageCollector.NONE,
            )
        )
        runDotNet(dotnetHost, consumerAssembly, outputDirectory, "Portable library consumer failed")

        val kotlinConsumerDirectory = outputDirectory.resolve("kotlin-consumer").apply { mkdirs() }
        val kotlinConsumerSource = kotlinConsumerDirectory.resolve("consumer.kt").apply {
            writeText(
                """
                package consumer

                import sample.Counter
                import sample.increment

                fun main() {
                    val answer = increment(Counter(40).plus(1))
                    if (answer != 42) throw Error("Kotlin library returned ${'$'}answer")
                }
                """.trimIndent()
            )
        }
        val kotlinConsumerAssembly = kotlinConsumerDirectory.resolve("KotlinConsumer.dll")
        compileInProcess(
            K2DotNetCompiler(),
            kotlinConsumerSource.path,
            K2DotNetCompilerArguments::classpath.cliArgument, implementationLibrary.path,
            K2DotNetCompilerArguments::dotNetTarget.cliArgument, "net10.0",
            K2DotNetCompilerArguments::moduleName.cliArgument, "KotlinConsumer",
            K2DotNetCompilerArguments::destination.cliArgument, kotlinConsumerAssembly.path,
        )
        assertTrue(kotlinConsumerDirectory.resolve("Sample.Library.dll").isFile) {
            "The external CLR implementation must be packaged beside an executable consumer"
        }
        val kotlinConsumerIl = kotlinConsumerDirectory.resolve("KotlinConsumer.il").readText()
        assertTrue(
            """
            .assembly extern 'Sample.Library'
            {
              .ver 1:0:0:0
            }
            """.trimIndent() in kotlinConsumerIl
        ) { kotlinConsumerIl }
        assertTrue("[Sample.Library]" in kotlinConsumerIl)
        runDotNet(
            dotnetHost,
            kotlinConsumerAssembly,
            kotlinConsumerDirectory,
            "Kotlin cross-module library consumer failed",
        )

        val unrelatedConsumerDirectory = outputDirectory.resolve("unrelated-consumer").apply { mkdirs() }
        val unrelatedConsumerSource = unrelatedConsumerDirectory.resolve("consumer.kt").apply {
            writeText(
                """
                package unrelated

                fun main() {
                    if (40 + 2 != 42) throw Error("arithmetic")
                }
                """.trimIndent()
            )
        }
        val unrelatedConsumerAssembly = unrelatedConsumerDirectory.resolve("UnrelatedConsumer.dll")
        compileInProcess(
            K2DotNetCompiler(),
            unrelatedConsumerSource.path,
            K2DotNetCompilerArguments::classpath.cliArgument, implementationLibrary.path,
            K2DotNetCompilerArguments::dotNetTarget.cliArgument, "net10.0",
            K2DotNetCompilerArguments::moduleName.cliArgument, "UnrelatedConsumer",
            K2DotNetCompilerArguments::destination.cliArgument, unrelatedConsumerAssembly.path,
        )
        val unrelatedConsumerIl = unrelatedConsumerDirectory.resolve("UnrelatedConsumer.il").readText()
        assertTrue(".assembly extern 'Sample.Library'" !in unrelatedConsumerIl) { unrelatedConsumerIl }
        assertTrue("[Sample.Library]" !in unrelatedConsumerIl) { unrelatedConsumerIl }
        assertTrue(!unrelatedConsumerDirectory.resolve("Sample.Library.dll").exists()) {
            "An unused metadata classpath entry must not become a CLR runtime dependency"
        }
        runDotNet(
            dotnetHost,
            unrelatedConsumerAssembly,
            unrelatedConsumerDirectory,
            "Consumer with an unused Kotlin/.NET classpath library failed",
        )

        val dllOnlyDependencyDirectory = outputDirectory.resolve("dll-only-dependency").apply { mkdirs() }
        val dllOnlyLibrary = implementationLibrary.copyTo(
            dllOnlyDependencyDirectory.resolve(implementationLibrary.name),
        )
        assertFalse(dllOnlyDependencyDirectory.resolve("Sample.Library.klib").exists()) {
            "The DLL-only dependency fixture must not expose a sibling KLIB"
        }
        val dllOnlyConsumerDirectory = outputDirectory.resolve("dll-only-consumer").apply { mkdirs() }
        val dllOnlyConsumerAssembly = dllOnlyConsumerDirectory.resolve("DllOnlyConsumer.dll")
        compileInProcess(
            K2DotNetCompiler(),
            kotlinConsumerSource.path,
            K2DotNetCompilerArguments::classpath.cliArgument, dllOnlyLibrary.path,
            K2DotNetCompilerArguments::dotNetTarget.cliArgument, "net10.0",
            K2DotNetCompilerArguments::moduleName.cliArgument, "DllOnlyConsumer",
            K2DotNetCompilerArguments::destination.cliArgument, dllOnlyConsumerAssembly.path,
        )
        assertFalse(dllOnlyDependencyDirectory.resolve("Sample.Library.klib").exists()) {
            "DLL-first compilation must not materialize a published sibling KLIB"
        }
        val dllOnlyConsumerIl = dllOnlyConsumerDirectory.resolve("DllOnlyConsumer.il").readText()
        assertTrue(".assembly extern 'Sample.Library'" in dllOnlyConsumerIl) { dllOnlyConsumerIl }
        assertTrue("[Sample.Library]" in dllOnlyConsumerIl) { dllOnlyConsumerIl }
        runDotNet(
            dotnetHost,
            dllOnlyConsumerAssembly,
            dllOnlyConsumerDirectory,
            "DLL-only Kotlin cross-module library consumer failed",
        )

        val mismatchedIdentityIl = outputDirectory.resolve("MismatchedIdentity.il").apply {
            val mismatchedText = il.replaceFirst(
                ".assembly 'Sample.Library'",
                ".assembly 'Physical.Mismatch'",
            )
            assertTrue(il != mismatchedText) { "Expected to rewrite the physical Assembly declaration" }
            writeText(mismatchedText)
        }
        val mismatchedIdentityDll = outputDirectory.resolve("MismatchedIdentity.dll")
        assertTrue(
            DotNetIlAssembler.assembleLibrary(
                mismatchedIdentityIl,
                mismatchedIdentityDll,
                DotNetTarget.NETSTANDARD_2_0,
                MessageCollector.NONE,
                mapOf(
                    DotNetCSharpImplementationManifestCodec.MANAGED_RESOURCE_NAME to
                            readFrameworkManagedResource(
                                checkNotNull(frameworkHost),
                                implementationLibrary,
                                DotNetCSharpImplementationManifestCodec.MANAGED_RESOURCE_NAME,
                            ),
                    DotNetKotlinMetadataResource.MANAGED_RESOURCE_NAME to embeddedMetadata.readBytes(),
                ),
            )
        )
        val identityDiagnosticSource = outputDirectory.resolve("identity-diagnostic.kt").apply {
            writeText("package consumer\n\npublic fun answer(): Int = 42")
        }
        val [identityDiagnostics, identityExitCode] = AbstractCliTest.executeCompilerGrabOutput(
            K2DotNetCompiler(),
            listOf(
                identityDiagnosticSource.path,
                K2DotNetCompilerArguments::noStdlib.cliArgument,
                K2DotNetCompilerArguments::classpath.cliArgument, mismatchedIdentityDll.path,
                K2DotNetCompilerArguments::moduleName.cliArgument, "IdentityDiagnosticConsumer",
                K2DotNetCompilerArguments::destination.cliArgument,
                outputDirectory.resolve("IdentityDiagnosticConsumer.il").path,
            )
        )
        assertEquals(ExitCode.COMPILATION_ERROR, identityExitCode, identityDiagnostics)
        assertTrue(
            "declares CLR assembly 'Sample.Library, Version=1.0.0.0, Culture=neutral, PublicKeyToken=null'" in
                    identityDiagnostics &&
                    "containing PE declares 'Physical.Mismatch, Version=1.0.0.0, Culture=neutral, " +
                    "PublicKeyToken=null'" in identityDiagnostics
        ) {
            identityDiagnostics
        }
    }

    @Test
    fun testDllClasspathClassifiesForeignAndRejectsMalformedMetadata() {
        requireOrAssumeToolchain(DotNetIlAssembler.findModernIlasm() != null, "Modern ilasm is not available")
        val source = File(tmpdir, "dll-metadata-diagnostic.kt").apply {
            writeText("package consumer\n\npublic fun answer(): Int = 42")
        }
        val foreignIl = File(tmpdir, "Foreign.Library.il").apply {
            writeText(
                """
                .assembly Foreign.Library {}
                .module Foreign.Library.dll
                """.trimIndent()
            )
        }
        val foreignDll = File(tmpdir, "Foreign.Library.dll")
        assertTrue(
            DotNetIlAssembler.assembleLibrary(
                foreignIl,
                foreignDll,
                DotNetTarget.NETSTANDARD_2_0,
                MessageCollector.NONE,
            )
        )
        val foreignClassification = DotNetClrClasspathAssemblyReader.read(
            foreignDll,
            DotNetKotlinMetadataResource.MANAGED_RESOURCE_NAME,
        )
        assertTrue(foreignClassification is DotNetClrClasspathAssembly.WithoutCarrier) {
            "A resource-free managed assembly must be retained as foreign CLR metadata"
        }
        foreignClassification as DotNetClrClasspathAssembly.WithoutCarrier
        assertEquals(foreignDll.canonicalFile, foreignClassification.assemblyFile)
        assertEquals("Foreign.Library", foreignClassification.metadata.identity.name)
        assertEquals("0.0.0.0", foreignClassification.metadata.identity.version)
        assertEquals("neutral", foreignClassification.metadata.identity.culture)
        assertFalse(foreignClassification.metadata.identity.hasPublicKey)

        val alternateCarrierName = "Architecture.Probe"
        val alternateCarrierIl = File(tmpdir, "Alternate.Carrier.il").apply {
            writeText(
                """
                .assembly Alternate.Carrier {}
                .module Alternate.Carrier.dll
                .mresource private $alternateCarrierName
                {
                }
                """.trimIndent()
            )
        }
        val alternateCarrierDll = File(tmpdir, "Alternate.Carrier.dll")
        assertTrue(
            DotNetIlAssembler.assembleLibrary(
                alternateCarrierIl,
                alternateCarrierDll,
                DotNetTarget.NETSTANDARD_2_0,
                MessageCollector.NONE,
                mapOf(alternateCarrierName to byteArrayOf(1)),
            )
        )
        assertTrue(
            DotNetClrClasspathAssemblyReader.read(
                alternateCarrierDll,
                DotNetKotlinMetadataResource.MANAGED_RESOURCE_NAME,
            ) is DotNetClrClasspathAssembly.WithoutCarrier
        ) {
            "The objective CLR reader must not infer a Kotlin carrier from an unrelated resource"
        }
        assertTrue(
            DotNetClrClasspathAssemblyReader.read(
                alternateCarrierDll,
                alternateCarrierName,
            ) is DotNetClrClasspathAssembly.WithCarrier
        ) {
            "The CLR reader must classify only the carrier identity supplied by its caller"
        }

        val [foreignDiagnostics, foreignExitCode] = AbstractCliTest.executeCompilerGrabOutput(
            K2DotNetCompiler(),
            listOf(
                source.path,
                K2DotNetCompilerArguments::noStdlib.cliArgument,
                K2DotNetCompilerArguments::classpath.cliArgument, foreignDll.path,
                K2DotNetCompilerArguments::moduleName.cliArgument, "ForeignAssemblyConsumer",
                K2DotNetCompilerArguments::destination.cliArgument,
                File(tmpdir, "ForeignAssemblyConsumer.il").path,
            )
        )
        assertEquals(ExitCode.OK, foreignExitCode, foreignDiagnostics)
        assertFalse("Kotlin.Metadata" in foreignDiagnostics, foreignDiagnostics)

        val malformedDll = File(tmpdir, "Malformed.Library.dll").apply {
            writeBytes(byteArrayOf(0x4d, 0x5a))
        }
        val [malformedDiagnostics, malformedExitCode] = AbstractCliTest.executeCompilerGrabOutput(
            K2DotNetCompiler(),
            listOf(
                source.path,
                K2DotNetCompilerArguments::noStdlib.cliArgument,
                K2DotNetCompilerArguments::classpath.cliArgument, malformedDll.path,
                K2DotNetCompilerArguments::moduleName.cliArgument, "MalformedMetadataConsumer",
                K2DotNetCompilerArguments::destination.cliArgument,
                File(tmpdir, "MalformedMetadataConsumer.il").path,
            )
        )
        assertEquals(ExitCode.COMPILATION_ERROR, malformedExitCode, malformedDiagnostics)
        assertTrue("Malformed.Library.dll' is invalid: DOS header is outside the PE file" in malformedDiagnostics) {
            malformedDiagnostics
        }

        val malformedMetadataDll = produceLibraryWithTransformedMetadataCarrier(
            assemblyName = "Malformed.Embedded.Metadata",
            transform = { byteArrayOf(0x50, 0x4b, 0x03, 0x04) },
        )
        val malformedCarrierClassification = DotNetClrClasspathAssemblyReader.read(
            malformedMetadataDll,
            DotNetKotlinMetadataResource.MANAGED_RESOURCE_NAME,
        )
        assertTrue(malformedCarrierClassification is DotNetClrClasspathAssembly.WithCarrier) {
            "A present reserved resource must stay on the Kotlin-produced path even when its payload is malformed"
        }
        val malformedMetadataDiagnostics = compileAgainstRejectedDll(malformedMetadataDll)
        assertTrue(
            "has invalid private '${DotNetKotlinMetadataResource.MANAGED_RESOURCE_NAME}' Kotlin metadata" in
                    malformedMetadataDiagnostics
        ) {
            malformedMetadataDiagnostics
        }
        assertTrue("archive has no valid end-of-central-directory record" in malformedMetadataDiagnostics) {
            malformedMetadataDiagnostics
        }
    }

    @Test
    fun testRetainedForeignDeclarationCarrierRejectsDetachedRowsAndWrongOwners() {
        requireOrAssumeToolchain(DotNetIlAssembler.findModernIlasm() != null, "Modern ilasm is not available")
        val foreignIl = File(tmpdir, "Foreign.Carrier.il").apply {
            writeText(
                """
                .assembly Foreign.Carrier {}
                .module Foreign.Carrier.dll

                .class interface public abstract auto ansi Foreign.IContract
                       implements Foreign.IOther
                {
                  .method public hidebysig newslot abstract virtual instance int32 Echo(int32 'value') cil managed
                  {
                  }

                  .method public hidebysig specialname newslot abstract virtual instance int32 get_Value() cil managed
                  {
                  }

                  .method public hidebysig specialname newslot abstract virtual instance void set_Value(int32 'value') cil managed
                  {
                  }

                  .property instance int32 Value()
                  {
                    .get instance int32 Foreign.IContract::get_Value()
                    .set instance void Foreign.IContract::set_Value(int32)
                  }
                }

                .class interface public abstract auto ansi Foreign.IOther
                {
                  .method public hidebysig newslot abstract virtual instance int32 Other() cil managed
                  {
                  }
                }
                """.trimIndent()
            )
        }
        val foreignDll = File(tmpdir, "Foreign.Carrier.dll")
        assertTrue(
            DotNetIlAssembler.assembleLibrary(
                foreignIl,
                foreignDll,
                DotNetTarget.NETSTANDARD_2_0,
                MessageCollector.NONE,
            )
        )
        val assembly = DotNetClrClasspathAssemblyReader.read(
            foreignDll,
            DotNetKotlinMetadataResource.MANAGED_RESOURCE_NAME,
        ) as DotNetClrClasspathAssembly.WithoutCarrier
        val declaringType = assembly.metadata.typeDefinitions.single { type ->
            type.namespaceName == "Foreign" && type.metadataName == "IContract"
        }
        val wrongOwner = assembly.metadata.typeDefinitions.single { type ->
            type.namespaceName == "Foreign" && type.metadataName == "IOther"
        }
        val method = assembly.metadata.methodDefinitions.single { it.name == "Echo" }
        val getter = assembly.metadata.methodDefinitions.single { it.name == "get_Value" }
        val setter = assembly.metadata.methodDefinitions.single { it.name == "set_Value" }
        val property = assembly.metadata.propertyDefinitions.single { it.name == "Value" }
        val typeResolver = DotNetClrTypeResolver(
            DotNetClrAssemblyReferenceBinder { _, _ -> null }
        )
        val signatureResolver = DotNetClrSignatureResolver(typeResolver)
        fun resolvedSignature(method: DotNetClrMethodDefinition): DotNetClrResolvedMethodSignature =
            (signatureResolver.resolve(assembly.metadata, method.signature) as
                    DotNetClrResolvedMethodSignatureResolution.Resolved).signature
        val declaringHierarchy = (
                DotNetClrTypeHierarchyViewResolver(typeResolver).resolve(
                    DotNetClrResolvedTypeView(
                        DotNetClrResolvedTypeDefinition(assembly.metadata, declaringType),
                        emptyList(),
                    )
                ) as DotNetClrTypeHierarchyViewResolution.Resolved
                ).hierarchy
        val graph = DotNetClrImportedDeclarationGraph(
            listOf(assembly),
            listOf(declaringHierarchy),
        )
        val methodSignature = resolvedSignature(method)
        val getterSignature = resolvedSignature(getter)
        val setterSignature = resolvedSignature(setter)

        val methodSource = DotNetClrImportedMethodSource(
            assembly,
            declaringType,
            declaringHierarchy,
            graph,
            method,
            methodSignature,
        )
        assertEquals(DotNetClrImportedDeclarationCarrierVersion.V3, methodSource.carrierVersion)
        assertSame(assembly, methodSource.assembly)
        assertSame(declaringType, methodSource.declaringType)
        assertSame(method, methodSource.method)
        assertSame(graph, methodSource.graph)

        val propertySource = DotNetClrImportedPropertySource(
            assembly,
            declaringType,
            declaringHierarchy,
            graph,
            property,
            getter,
            setter,
            getterSignature,
            setterSignature,
        )
        assertEquals(DotNetClrImportedDeclarationCarrierVersion.V3, propertySource.carrierVersion)
        assertSame(property, propertySource.property)
        assertSame(getter, propertySource.getter)
        assertSame(setter, propertySource.setter)
        assertSame(graph, propertySource.graph)

        assertThrows(IllegalArgumentException::class.java) {
            DotNetClrImportedDeclarationGraph(
                listOf(assembly, assembly),
                listOf(declaringHierarchy),
            )
        }
        assertThrows(IllegalArgumentException::class.java) {
            DotNetClrImportedDeclarationGraph(
                listOf(assembly),
                listOf(declaringHierarchy, declaringHierarchy),
            )
        }
        val interfaceImplementation = declaringHierarchy.interfaces.single()
        assertThrows(IllegalArgumentException::class.java) {
            DotNetClrImportedDeclarationGraph(
                listOf(assembly),
                listOf(
                    declaringHierarchy.copy(
                        interfaces = listOf(
                            interfaceImplementation.copy(
                                row = interfaceImplementation.row.copy()
                            )
                        )
                    )
                ),
            )
        }
        assertThrows(IllegalArgumentException::class.java) {
            DotNetClrImportedDeclarationGraph(
                listOf(assembly),
                listOf(
                    declaringHierarchy.copy(
                        interfaces = listOf(
                            interfaceImplementation.copy(
                                row = interfaceImplementation.row.copy(
                                    implementingType = wrongOwner.handle,
                                )
                            )
                        )
                    )
                ),
            )
        }

        assertThrows(IllegalArgumentException::class.java) {
            DotNetClrImportedMethodSource(
                assembly,
                wrongOwner,
                declaringHierarchy,
                graph,
                method,
                methodSignature,
            )
        }
        assertThrows(IllegalArgumentException::class.java) {
            DotNetClrImportedMethodSource(
                assembly,
                declaringType.copy(),
                declaringHierarchy,
                graph,
                method,
                methodSignature,
            )
        }
        assertThrows(IllegalArgumentException::class.java) {
            DotNetClrImportedMethodSource(
                assembly,
                declaringType,
                declaringHierarchy,
                graph,
                method.copy(),
                methodSignature,
            )
        }
        assertThrows(IllegalArgumentException::class.java) {
            DotNetClrImportedPropertySource(
                assembly,
                declaringType,
                declaringHierarchy,
                graph,
                property.copy(),
                getter,
                setter,
                getterSignature,
                setterSignature,
            )
        }
        assertThrows(IllegalArgumentException::class.java) {
            DotNetClrImportedPropertySource(
                assembly,
                declaringType,
                declaringHierarchy,
                graph,
                property,
                getter.copy(),
                setter,
                getterSignature,
                setterSignature,
            )
        }
        assertThrows(IllegalArgumentException::class.java) {
            DotNetClrImportedPropertySource(
                assembly,
                declaringType,
                declaringHierarchy,
                graph,
                property,
                getter,
                setter.copy(),
                getterSignature,
                setterSignature,
            )
        }
    }

    @Test
    fun testForeignClrNullableMetadataEnhancesFirTypes() {
        val csharpToolchain = DotNetIlAssembler.findModernCSharpCompiler()
        requireOrAssumeToolchain(
            csharpToolchain != null,
            "Modern Roslyn and the net10 reference pack are not available",
        )
        val toolchain = checkNotNull(csharpToolchain)
        val systemRuntime = toolchain.referenceDirectory.resolve("System.Runtime.dll")
        assertTrue(systemRuntime.isFile) { "Missing net10 System.Runtime reference assembly" }

        val fixtureSource = File(tmpdir, "foreign-nullability.cs").apply {
            writeText(
                """
                #nullable enable
                namespace ForeignContracts
                {
                    public interface NullableApi
                    {
                        string? Maybe();
                        string Sure();
                        string Echo(string value);
                        string? EchoNullable(string? value);

                #nullable disable
                        string Legacy();
                        string LegacyEcho(string value);
                #nullable restore
                    }

                    public interface UnsupportedApi
                    {
                        string? Maybe();
                        string this[int index] { get; }
                    }
                }
                """.trimIndent()
            )
        }
        val fixtureAssembly = File(tmpdir, "Foreign.Nullable.dll")
        val fixtureResult = runModernCSharpCompiler(
            toolchain,
            fixtureSource,
            fixtureAssembly,
        )
        assertEquals(0, fixtureResult.exitCode, fixtureResult.output)
        assertTrue(fixtureAssembly.isFile)

        fun compileForeignConsumer(
            sourceName: String,
            sourceText: String,
            classpath: List<File> = listOf(fixtureAssembly, systemRuntime),
        ): Pair<String, ExitCode> {
            val source = File(tmpdir, sourceName).apply { writeText(sourceText) }
            return AbstractCliTest.executeCompilerGrabOutput(
                K2DotNetCompiler(),
                listOf(
                    source.path,
                    K2DotNetCompilerArguments::noStdlib.cliArgument,
                    K2DotNetCompilerArguments::classpath.cliArgument,
                    classpath.joinToString(File.pathSeparator, transform = File::getPath),
                    K2DotNetCompilerArguments::moduleName.cliArgument, "ForeignNullableConsumer",
                    K2DotNetCompilerArguments::destination.cliArgument,
                    File(tmpdir, "$sourceName.il").path,
                )
            )
        }

        val [nullableDiagnostics, nullableExitCode] = compileForeignConsumer(
            "foreign-nullability.kt",
            """
            package consumer

            import ForeignContracts.NullableApi

            public fun sure(api: NullableApi): String = api.Sure()
            public fun legacy(api: NullableApi): String = api.Legacy()
            public fun acceptsNullable(api: NullableApi, value: String?): String? =
                api.EchoNullable(value)
            public fun acceptsLegacy(api: NullableApi, value: String?): String =
                api.LegacyEcho(value)
            public fun rejected(api: NullableApi): String = api.Maybe()
            public fun rejectedParameter(api: NullableApi, value: String?): String =
                api.Echo(value)
            """.trimIndent(),
        )
        assertEquals(ExitCode.COMPILATION_ERROR, nullableExitCode, nullableDiagnostics)
        assertTrue("String?" in nullableDiagnostics) { nullableDiagnostics }
        assertTrue("api.Maybe()" in nullableDiagnostics) { nullableDiagnostics }
        assertTrue("api.Echo(value)" in nullableDiagnostics) { nullableDiagnostics }
        assertFalse("api.Sure()" in nullableDiagnostics) { nullableDiagnostics }
        assertFalse("api.Legacy()" in nullableDiagnostics) { nullableDiagnostics }
        assertFalse("api.EchoNullable(value)" in nullableDiagnostics) { nullableDiagnostics }
        assertFalse("api.LegacyEcho(value)" in nullableDiagnostics) { nullableDiagnostics }
        assertFalse("unresolved reference 'NullableApi'" in nullableDiagnostics) { nullableDiagnostics }
        assertFalse("unresolved reference 'Sure'" in nullableDiagnostics) { nullableDiagnostics }
        assertFalse("unresolved reference 'Legacy'" in nullableDiagnostics) { nullableDiagnostics }

        val [unsupportedDiagnostics, unsupportedExitCode] = compileForeignConsumer(
            "foreign-unsupported.kt",
            """
            package consumer

            import ForeignContracts.UnsupportedApi

            public fun rejected(api: UnsupportedApi): String = api.Maybe()
            """.trimIndent(),
        )
        assertEquals(ExitCode.COMPILATION_ERROR, unsupportedExitCode, unsupportedDiagnostics)
        assertTrue("unresolved reference 'UnsupportedApi'" in unsupportedDiagnostics) {
            unsupportedDiagnostics
        }

        val duplicateSource = File(tmpdir, "foreign-nullability-duplicate.cs").apply {
            writeText(
                """
                #nullable enable
                namespace ForeignContracts
                {
                    public interface NullableApi
                    {
                        string? Duplicate();
                    }
                }
                """.trimIndent()
            )
        }
