        assertTrue(frameworkCoreLibrary.isFile) {
            "Framework compiler has no adjacent mscorlib reference: $frameworkCoreLibrary"
        }
        val modernSystemRuntime =
            checkNotNull(modernCSharp).referenceDirectory.resolve("System.Runtime.dll")
        assertTrue(modernSystemRuntime.isFile) {
            "Modern reference pack has no System.Runtime reference: $modernSystemRuntime"
        }
        data class Profile(
            val target: String,
            val modernDiagnosticMethod: String,
            val modernDiagnosticCall: String,
            val compileFixture: (File, File) -> CSharpCompilerResult,
            val systemReference: File,
        )

        val profiles = listOf(
            Profile(
                target = "net48",
                modernDiagnosticMethod = "",
                modernDiagnosticCall = "",
                compileFixture = { source, output ->
                    runCSharpCompiler(checkNotNull(frameworkCSharp), source, output)
                },
                systemReference = frameworkCoreLibrary,
            ),
            Profile(
                target = "net10.0",
                modernDiagnosticMethod =
                    """
                    [Obsolete(
                        "diagnostic message",
                        DiagnosticId = "DOTNET123",
                        UrlFormat = "https://example.test/{0}")]
                    void Diagnostic();
                    """.trimIndent(),
                modernDiagnosticCall = "api.Diagnostic()",
                compileFixture = { source, output ->
                    runModernCSharpCompiler(checkNotNull(modernCSharp), source, output)
                },
                systemReference = modernSystemRuntime,
            ),
        )

        fun compileConsumer(
            sourceName: String,
            sourceText: String,
            classpath: List<File>,
            target: String,
        ): Pair<String, ExitCode> {
            val source = File(tmpdir, sourceName).apply { writeText(sourceText) }
            return AbstractCliTest.executeCompilerGrabOutput(
                K2DotNetCompiler(),
                listOf(
                    source.path,
                    K2DotNetCompilerArguments::noStdlib.cliArgument,
                    K2DotNetCompilerArguments::classpath.cliArgument,
                    classpath.joinToString(File.pathSeparator, transform = File::getPath),
                    K2DotNetCompilerArguments::dotNetTarget.cliArgument, target,
                    K2DotNetCompilerArguments::moduleName.cliArgument, "ForeignObsoleteConsumer",
                    K2DotNetCompilerArguments::destination.cliArgument,
                    File(tmpdir, "$sourceName.il").path,
                )
            )
        }

        for (profile in profiles) {
            val profileSuffix = profile.target.replace('.', '-')
            val supportsAccessorDeprecation = profile.target == "net10.0"
            val accessorSource =
                File(tmpdir, "foreign-obsolete-accessor-$profileSuffix.cs").apply {
                    writeText(
                        """
                        using System;

                        public interface AccessorObsoleteProbe
                        {
                            string Value
                            {
                                [Obsolete("accessor obsoletion probe")]
                                get;
                            }
                        }
                        """.trimIndent()
                    )
                }
            val accessorAssembly =
                File(tmpdir, "Foreign.Obsolete.Accessor.$profileSuffix.dll")
            val accessorCompilerResult = profile.compileFixture(
                accessorSource,
                accessorAssembly,
            )
            if (supportsAccessorDeprecation) {
                assertEquals(0, accessorCompilerResult.exitCode, accessorCompilerResult.output)
                val accessorMetadata = DotNetClrMetadataReader.read(accessorAssembly)
                val accessorType = accessorMetadata.typeDefinitions.single { type ->
                    type.namespaceName.isEmpty() &&
                            type.metadataName == "AccessorObsoleteProbe"
                }
                val accessorProperty =
                    accessorMetadata.propertyDefinitions.single { property ->
                        property.declaringType == accessorType.handle &&
                                property.name == "Value"
                    }
                val accessorGetter = accessorMetadata.methodSemantics.single { semantics ->
                    semantics.association == accessorProperty.handle &&
                            semantics.kind == DotNetClrMethodSemanticsKind.GETTER
                }.method
                assertEquals(
                    1,
                    accessorMetadata.customAttributes.count { attribute ->
                        if (attribute.parent != accessorGetter) return@count false
                        val constructor =
                            accessorMetadata.memberReferences.singleOrNull { member ->
                                member.handle == attribute.constructor
                            } ?: return@count false
                        accessorMetadata.typeReferences.any { type ->
                            type.handle == constructor.parent &&
                                    type.namespaceName == "System" &&
                                    type.metadataName == "ObsoleteAttribute"
                        }
                    },
                )
            } else {
                assertTrue(accessorCompilerResult.exitCode != 0) {
                    accessorCompilerResult.output
                }
                assertTrue("CS1667" in accessorCompilerResult.output) {
                    accessorCompilerResult.output
                }
            }

            val accessorDeclarations =
                if (supportsAccessorDeprecation) {
                    """
                    string AccessorSplit
                    {
                        [Obsolete("getter error message", true)]
                        get;

                        [Obsolete("setter warning message")]
                        set;
                    }

                    string SetterError
                    {
                        get;

                        [Obsolete("setter error message", true)]
                        set;
                    }
                    """.trimIndent()
                } else {
                    ""
                }
            val fixtureSource = File(tmpdir, "foreign-obsolete-$profileSuffix.cs").apply {
                writeText(
                    """
                    using System;

                    namespace ForeignObsoleteContracts
                    {
                        public interface DeprecatedApi
                        {
                            [Obsolete]
                            void NoMessage();

                            [Obsolete(null)]
                            void NullMessage();

                            [Obsolete("warning message")]
                            void Warning();

                            [Obsolete("error message", true)]
                            void Error();

                            ${profile.modernDiagnosticMethod}

                            void Current();
                        }

                        public interface OverrideApi
                        {
                            [Obsolete("base-only message")]
                            void BaseOnly();
                        }

                        [Obsolete("warning interface message")]
                        public interface WarningTypeApi
                        {
                            void Current();
                        }

                        [Obsolete("error interface message", true)]
                        public interface ErrorTypeApi
                        {
                            void Current();
                        }

                        public interface DeprecatedPropertyApi
                        {
                            [Obsolete("whole property warning message")]
                            string Whole { get; set; }

                            [Obsolete("whole property error message", true)]
                            string ErrorProperty { get; set; }

                            $accessorDeclarations

                            string Current { get; set; }
                        }
                    }
                    """.trimIndent()
                )
            }
            val fixtureAssembly = File(tmpdir, "Foreign.Obsolete.$profileSuffix.dll")
            val fixtureResult = profile.compileFixture(fixtureSource, fixtureAssembly)
            assertEquals(0, fixtureResult.exitCode, fixtureResult.output)

            val [warningDiagnostics, warningExitCode] = compileConsumer(
                "foreign-obsolete-warning-$profileSuffix.kt",
                """
                package consumer

                import ForeignObsoleteContracts.DeprecatedApi
                import ForeignObsoleteContracts.DeprecatedPropertyApi
                import ForeignObsoleteContracts.WarningTypeApi

                public fun use(
                    api: DeprecatedApi,
                    type: WarningTypeApi,
                    properties: DeprecatedPropertyApi,
                ) {
                    api.NoMessage()
                    api.NullMessage()
                    api.Warning()
                    ${profile.modernDiagnosticCall}
                    api.Current()
                    type.Current()
                    val current = properties.Current
                    properties.Current = current
                    properties.Whole = properties.Whole
                    ${if (supportsAccessorDeprecation) "properties.AccessorSplit = current\nproperties.SetterError" else ""}
                }
                """.trimIndent(),
                listOf(fixtureAssembly, profile.systemReference),
                profile.target,
            )
            assertEquals(ExitCode.OK, warningExitCode, warningDiagnostics)
            assertTrue("Deprecated in .NET" in warningDiagnostics) { warningDiagnostics }
            assertTrue("warning message" in warningDiagnostics) { warningDiagnostics }
            assertTrue("warning interface message" in warningDiagnostics) {
                warningDiagnostics
            }
            assertTrue("whole property warning message" in warningDiagnostics) {
                warningDiagnostics
            }
            assertFalse("whole property error message" in warningDiagnostics) {
                warningDiagnostics
            }
            if (supportsAccessorDeprecation) {
                assertTrue("setter warning message" in warningDiagnostics) {
                    warningDiagnostics
                }
                assertFalse("getter error message" in warningDiagnostics) {
                    warningDiagnostics
                }
                assertFalse("setter error message" in warningDiagnostics) {
                    warningDiagnostics
                }
            }
            if (profile.modernDiagnosticCall.isNotEmpty()) {
                assertTrue("diagnostic message" in warningDiagnostics) { warningDiagnostics }
            }
            assertFalse("api.Current()" in warningDiagnostics) { warningDiagnostics }
            assertFalse("unresolved reference 'DeprecatedApi'" in warningDiagnostics) {
                warningDiagnostics
            }

            val [errorDiagnostics, errorExitCode] = compileConsumer(
                "foreign-obsolete-error-$profileSuffix.kt",
                """
                package consumer

                import ForeignObsoleteContracts.DeprecatedApi
                import ForeignObsoleteContracts.DeprecatedPropertyApi
                import ForeignObsoleteContracts.ErrorTypeApi

                public fun rejected(
                    api: DeprecatedApi,
                    type: ErrorTypeApi,
                    properties: DeprecatedPropertyApi,
                ) {
                    api.Error()
                    type.Current()
                    val value = properties.ErrorProperty
                    properties.ErrorProperty = value
                    ${if (supportsAccessorDeprecation) "val accessorValue = properties.AccessorSplit\nproperties.SetterError = accessorValue" else ""}
                }
                """.trimIndent(),
                listOf(fixtureAssembly, profile.systemReference),
                profile.target,
            )
            assertEquals(ExitCode.COMPILATION_ERROR, errorExitCode, errorDiagnostics)
            assertTrue("error message" in errorDiagnostics) { errorDiagnostics }
            assertTrue("error interface message" in errorDiagnostics) { errorDiagnostics }
            assertTrue("whole property error message" in errorDiagnostics) {
                errorDiagnostics
            }
            assertFalse("whole property warning message" in errorDiagnostics) {
                errorDiagnostics
            }
            if (supportsAccessorDeprecation) {
                assertTrue("getter error message" in errorDiagnostics) { errorDiagnostics }
                assertTrue("setter error message" in errorDiagnostics) { errorDiagnostics }
                assertFalse("setter warning message" in errorDiagnostics) {
                    errorDiagnostics
                }
            }

            val [overrideDiagnostics, overrideExitCode] = compileConsumer(
                "foreign-obsolete-override-$profileSuffix.kt",
                """
                package consumer

                import ForeignObsoleteContracts.DeprecatedPropertyApi
                import ForeignObsoleteContracts.OverrideApi
                import ForeignObsoleteContracts.WarningTypeApi

                public class CurrentOverride : OverrideApi {
                    override fun BaseOnly() {}
                }

                @Suppress("DEPRECATION")
                public class CurrentImplementation : WarningTypeApi {
                    override fun Current() {}
                }

                @Suppress("DEPRECATION", "DEPRECATION_ERROR")
                public class CurrentPropertyImplementation : DeprecatedPropertyApi {
                    override var Whole: String = ""
                    override var ErrorProperty: String = ""
                    ${if (supportsAccessorDeprecation) "override var AccessorSplit: String = \"\"\noverride var SetterError: String = \"\"" else ""}
                    override var Current: String = ""
                }

                public fun accepted(
                    api: CurrentOverride,
                    implementation: CurrentImplementation,
                    properties: CurrentPropertyImplementation,
                ) {
                    api.BaseOnly()
                    implementation.Current()
                    properties.Whole = properties.Whole
                    properties.ErrorProperty = properties.ErrorProperty
                    ${if (supportsAccessorDeprecation) "properties.AccessorSplit = properties.AccessorSplit\nproperties.SetterError = properties.SetterError" else ""}
                    properties.Current = properties.Current
                }
                """.trimIndent(),
                listOf(fixtureAssembly, profile.systemReference),
                profile.target,
            )
            assertEquals(ExitCode.OK, overrideExitCode, overrideDiagnostics)
            assertFalse("base-only message" in overrideDiagnostics) {
                overrideDiagnostics
            }
            assertFalse("warning interface message" in overrideDiagnostics) {
                overrideDiagnostics
            }
            assertFalse("whole property warning message" in overrideDiagnostics) {
                overrideDiagnostics
            }
            assertFalse("whole property error message" in overrideDiagnostics) {
                overrideDiagnostics
            }
            assertFalse("getter error message" in overrideDiagnostics) {
                overrideDiagnostics
            }
            assertFalse("setter warning message" in overrideDiagnostics) {
                overrideDiagnostics
            }
            assertFalse("setter error message" in overrideDiagnostics) {
                overrideDiagnostics
            }
        }

        val hostileSource = File(tmpdir, "foreign-obsolete-lookalike.cs").apply {
            writeText(
                """
                using System;

                namespace System
                {
                    [AttributeUsage(
                        AttributeTargets.Method |
                        AttributeTargets.Interface |
                        AttributeTargets.Property)]
                    public sealed class ObsoleteAttribute : Attribute
                    {
                        public ObsoleteAttribute(string message) {}
                    }
                }

                namespace HostileObsoleteContracts
                {
                    public interface LookalikeApi
                    {
                        [System.Obsolete("look-alike must not deprecate")]
                        void Current();
                    }

                    [System.Obsolete("look-alike type must not deprecate")]
                    public interface LookalikeTypeApi
                    {
                        void Current();
                    }

                    public interface LookalikePropertyApi
                    {
                        [System.Obsolete("look-alike property must not deprecate")]
                        string CurrentProperty { get; }
                    }
                }
                """.trimIndent()
            )
        }
        val hostileAssembly = File(tmpdir, "Foreign.Obsolete.Lookalike.dll")
        val hostileResult = runModernCSharpCompiler(
            checkNotNull(modernCSharp),
            hostileSource,
            hostileAssembly,
            additionalArguments = listOf("/nowarn:0436"),
        )
        assertEquals(0, hostileResult.exitCode, hostileResult.output)
        val [hostileDiagnostics, hostileExitCode] = compileConsumer(
            "foreign-obsolete-lookalike.kt",
            """
            package consumer

            import HostileObsoleteContracts.LookalikeApi
            import HostileObsoleteContracts.LookalikePropertyApi
            import HostileObsoleteContracts.LookalikeTypeApi

            public fun accepted(
                api: LookalikeApi,
                type: LookalikeTypeApi,
                properties: LookalikePropertyApi,
            ) {
                api.Current()
                type.Current()
                properties.CurrentProperty
            }
            """.trimIndent(),
            listOf(hostileAssembly, modernSystemRuntime),
            "net10.0",
        )
        assertEquals(ExitCode.OK, hostileExitCode, hostileDiagnostics)
        assertFalse("look-alike must not deprecate" in hostileDiagnostics) {
            hostileDiagnostics
        }
        assertFalse("look-alike type must not deprecate" in hostileDiagnostics) {
            hostileDiagnostics
        }
        assertFalse("look-alike property must not deprecate" in hostileDiagnostics) {
            hostileDiagnostics
        }

        val malformedSource = File(tmpdir, "foreign-obsolete-malformed.cs").apply {
            writeText(
                """
                using System;

                namespace MalformedObsoleteContracts
                {
                    public interface MalformedApi
                    {
                        [Obsolete("malformed must not deprecate", true)]
                        void Malformed();

                        [Obsolete("malformed property must not deprecate", true)]
                        string MalformedProperty { get; }

                        [Obsolete("malformed accessor must not deprecate", true)]
                        string AccessorShaped { get; }

                        [Obsolete("duplicate property must not deprecate", true)]
                        string DuplicateProperty { get; }

                        [Obsolete("duplicate seed", true)]
                        void DuplicateSeed();
                    }

                    [Obsolete("malformed type must not deprecate", true)]
                    public interface MalformedTypeApi
                    {
                        void Current();
                    }
                }
                """.trimIndent()
            )
        }
        val pristineMalformedAssembly = File(tmpdir, "Foreign.Obsolete.Malformed.Primitive.dll")
        val malformedResult = runModernCSharpCompiler(
            checkNotNull(modernCSharp),
            malformedSource,
            pristineMalformedAssembly,
        )
        assertEquals(0, malformedResult.exitCode, malformedResult.output)
        val malformedMetadata = DotNetClrMetadataReader.read(pristineMalformedAssembly)
        val malformedApi = malformedMetadata.typeDefinitions.single { type ->
            type.namespaceName == "MalformedObsoleteContracts" &&
                    type.metadataName == "MalformedApi"
        }
        val malformedMethod = malformedMetadata.methodDefinitions.single { method ->
            method.declaringType == malformedApi.handle &&
                    method.name == "Malformed"
        }
        val malformedTypeApi = malformedMetadata.typeDefinitions.single { type ->
            type.namespaceName == "MalformedObsoleteContracts" &&
                    type.metadataName == "MalformedTypeApi"
        }
        val malformedProperty = malformedMetadata.propertyDefinitions.single { property ->
            property.declaringType == malformedApi.handle &&
                    property.name == "MalformedProperty"
        }
        val accessorShapedProperty =
            malformedMetadata.propertyDefinitions.single { property ->
                property.declaringType == malformedApi.handle &&
                        property.name == "AccessorShaped"
            }
        val accessorShapedGetter = malformedMetadata.methodSemantics.single { semantics ->
            semantics.association == accessorShapedProperty.handle &&
                    semantics.kind == DotNetClrMethodSemanticsKind.GETTER
        }.method
        val duplicateProperty =
            malformedMetadata.propertyDefinitions.single { property ->
                property.declaringType == malformedApi.handle &&
                        property.name == "DuplicateProperty"
            }
        val duplicateSeed = malformedMetadata.methodDefinitions.single { method ->
            method.declaringType == malformedApi.handle &&
                    method.name == "DuplicateSeed"
        }
        val malformedParents = setOf(
            malformedMethod.handle,
            malformedTypeApi.handle,
            malformedProperty.handle,
        )
        val malformedAttributes = malformedMetadata.customAttributes.filter { attribute ->
            if (attribute.parent !in malformedParents) return@filter false
            val constructor = malformedMetadata.memberReferences.singleOrNull { member ->
                member.handle == attribute.constructor
            } ?: return@filter false
            malformedMetadata.typeReferences.any { type ->
                type.handle == constructor.parent &&
                        type.namespaceName == "System" &&
                        type.metadataName == "ObsoleteAttribute"
            }
        }
        assertEquals(3, malformedAttributes.size)
        val accessorShapedAttribute = malformedMetadata.customAttributes.single { attribute ->
            if (attribute.parent != accessorShapedProperty.handle) return@single false
            val constructor = malformedMetadata.memberReferences.singleOrNull { member ->
                member.handle == attribute.constructor
            } ?: return@single false
            malformedMetadata.typeReferences.any { type ->
                type.handle == constructor.parent &&
                        type.namespaceName == "System" &&
                        type.metadataName == "ObsoleteAttribute"
            }
        }
        val duplicateSeedAttribute = malformedMetadata.customAttributes.single { attribute ->
            if (attribute.parent != duplicateSeed.handle) return@single false
            val constructor = malformedMetadata.memberReferences.singleOrNull { member ->
                member.handle == attribute.constructor
            } ?: return@single false
            malformedMetadata.typeReferences.any { type ->
                type.handle == constructor.parent &&
                        type.namespaceName == "System" &&
                        type.metadataName == "ObsoleteAttribute"
            }
        }
        val malformedImage = pristineMalformedAssembly.readBytes()
        val malformedTables = locateClrMetadataTables(malformedImage)
        for (malformedAttribute in malformedAttributes + accessorShapedAttribute) {
            val malformedValueIndex = readLittleEndianIndex(
                malformedImage,
                malformedTables.rowOffset(12, malformedAttribute.handle.row) +
                        malformedTables.hasCustomAttributeIndexSize +
                        malformedTables.customAttributeTypeIndexSize,
                malformedTables.blobIndexSize,
            )
            val malformedValueOffset =
                malformedTables.blobContentOffset(malformedImage, malformedValueIndex)
            assertEquals(1, malformedImage[malformedValueOffset].toInt() and 0xff)
            malformedImage[malformedValueOffset] = 0
        }
        // HasCustomAttribute uses five tag bits; MethodDef is tag 0 and Property is tag 9.
        writeLittleEndian(
            malformedImage,
            malformedTables.rowOffset(12, accessorShapedAttribute.handle.row),
            malformedTables.hasCustomAttributeIndexSize,
            accessorShapedGetter.row shl 5,
        )
        writeLittleEndian(
            malformedImage,
            malformedTables.rowOffset(12, duplicateSeedAttribute.handle.row),
            malformedTables.hasCustomAttributeIndexSize,
            (duplicateProperty.handle.row shl 5) or 9,
        )
        val malformedAssembly = File(tmpdir, "Foreign.Obsolete.Malformed.dll").apply {
            writeBytes(malformedImage)
        }
        val [malformedDiagnostics, malformedExitCode] = compileConsumer(
            "foreign-obsolete-malformed.kt",
            """
            package consumer

            import MalformedObsoleteContracts.MalformedApi
            import MalformedObsoleteContracts.MalformedTypeApi

            public fun accepted(api: MalformedApi, type: MalformedTypeApi) {
                api.Malformed()
                api.MalformedProperty
                api.AccessorShaped
                api.DuplicateProperty
                type.Current()
            }
            """.trimIndent(),
            listOf(malformedAssembly, modernSystemRuntime),
            "net10.0",
        )
        assertEquals(ExitCode.OK, malformedExitCode, malformedDiagnostics)
        assertFalse("malformed must not deprecate" in malformedDiagnostics) {
            malformedDiagnostics
        }
        assertFalse("malformed type must not deprecate" in malformedDiagnostics) {
            malformedDiagnostics
        }
        assertFalse("malformed property must not deprecate" in malformedDiagnostics) {
            malformedDiagnostics
        }
        assertFalse("malformed accessor must not deprecate" in malformedDiagnostics) {
            malformedDiagnostics
        }
        assertFalse("duplicate property must not deprecate" in malformedDiagnostics) {
            malformedDiagnostics
        }
    }

    @Test
    fun testForeignClrInterfaceCallsRetainPhysicalBindingAcrossRuntimeProfiles() {
        val modernCSharp = DotNetIlAssembler.findModernCSharpCompiler()
        requireOrAssumeToolchain(
            modernCSharp != null,
            "Modern Roslyn and the net10 reference pack are not available",
        )
        val frameworkCSharp = DotNetIlAssembler.findFrameworkCSharpCompiler()
        requireOrAssumeToolchain(
            frameworkCSharp != null,
            ".NET Framework C# compiler is not available",
        )
        val frameworkHost = DotNetIlAssembler.findFrameworkPowerShellHost()
        requireOrAssumeToolchain(
            frameworkHost != null,
            "Windows PowerShell CLR 4 host is not available",
        )
        val dotnetHost = modernDotNetHostOrSkip()
        val frameworkCoreLibrary = checkNotNull(frameworkCSharp).parentFile.resolve("mscorlib.dll")
        assertTrue(frameworkCoreLibrary.isFile) {
            "Framework compiler has no adjacent mscorlib reference: $frameworkCoreLibrary"
        }
        val modernSystemRuntime =
            checkNotNull(modernCSharp).referenceDirectory.resolve("System.Runtime.dll")
        assertTrue(modernSystemRuntime.isFile) {
            "Modern reference pack has no System.Runtime reference: $modernSystemRuntime"
        }

        data class Profile(
            val target: String,
            val applicationFileName: String,
            val fixturePreamble: String,
            val nullableDirective: String,
            val nullableStringType: String,
            val nullableObjectArrayType: String,
            val nullableStringArrayType: String,
            val nullableIntArrayType: String,
            val nullableGenericDeclaration: String,
            val nullableOwnerGenericDeclaration: String,
            val nullableOpenType: String,
            val rejectsNullableGenericOverrideInFrontend: Boolean,
            val compileFixture: (File, File) -> CSharpCompilerResult,
            val systemReference: File,
            val compileVerifier: (File, File, File) -> CSharpCompilerResult,
            val executionCommand: (File) -> List<String>,
        ) {
            val hasRoslynNullableMetadata: Boolean
                get() = nullableDirective.isNotEmpty()
        }

        val profiles = listOf(
            Profile(
                target = "net48",
                applicationFileName = "ForeignCallConsumer.exe",
                fixturePreamble =
                    """
                    namespace System.Diagnostics.CodeAnalysis
                    {
                        [System.AttributeUsage(System.AttributeTargets.Method)]
                        public sealed class DoesNotReturnAttribute : System.Attribute {}

                        [System.AttributeUsage(
                            System.AttributeTargets.Property |
                            System.AttributeTargets.Field |
                            System.AttributeTargets.Parameter)]
                        public sealed class AllowNullAttribute : System.Attribute {}

                        [System.AttributeUsage(
                            System.AttributeTargets.Property |
                            System.AttributeTargets.Field |
                            System.AttributeTargets.Parameter |
                            System.AttributeTargets.ReturnValue)]
                        public sealed class MaybeNullAttribute : System.Attribute {}
                    }
                    """.trimIndent(),
                nullableDirective = "",
                nullableStringType = "string",
                nullableObjectArrayType = "object[]",
                nullableStringArrayType = "string[]",
                nullableIntArrayType = "int[]",
                nullableGenericDeclaration =
                    "[return: MaybeNull] T Maybe<T>([AllowNull] T value);",
                nullableOwnerGenericDeclaration =
                    "[return: MaybeNull] T Maybe([AllowNull] T value);",
                nullableOpenType = "T",
                rejectsNullableGenericOverrideInFrontend = false,
                compileFixture = { source, output ->
                    runCSharpCompiler(checkNotNull(frameworkCSharp), source, output)
                },
                systemReference = frameworkCoreLibrary,
                compileVerifier = { source, output, fixture ->
                    runCSharpCompiler(
                        checkNotNull(frameworkCSharp),
                        source,
                        output,
                        fixture,
                        target = "exe",
                    )
                },
                executionCommand = { executable ->
                    frameworkExecutionCommand(checkNotNull(frameworkHost), executable)
                },
            ),
            Profile(
                target = "net10.0",
                applicationFileName = "ForeignCallConsumer.dll",
                fixturePreamble = "",
                nullableDirective = "#nullable enable",
                nullableStringType = "string?",
                nullableObjectArrayType = "object?[]",
                nullableStringArrayType = "string?[]?",
                nullableIntArrayType = "int[]?",
                nullableGenericDeclaration = "T? Maybe<T>(T? value);",
                nullableOwnerGenericDeclaration = "T? Maybe(T? value);",
                nullableOpenType = "T?",
                rejectsNullableGenericOverrideInFrontend = true,
                compileFixture = { source, output ->
                    runModernCSharpCompiler(checkNotNull(modernCSharp), source, output)
                },
                systemReference = modernSystemRuntime,
                compileVerifier = { source, output, fixture ->
                    runModernCSharpCompiler(
                        checkNotNull(modernCSharp),
                        source,
                        output,
                        fixture,
                        target = "exe",
                    )
                },
                executionCommand = { executable ->
                    listOf(dotnetHost.path, "exec", executable.path)
                },
            ),
        )

        for (profile in profiles) {
            val fixtureDirectory =
                File(tmpdir, "foreign-call-fixture-${profile.target.replace('.', '-')}").apply { mkdirs() }
            val fixtureSource = fixtureDirectory.resolve("ForeignCallContracts.cs").apply {
                writeText(
                    """
                    using System;
                    using System.Diagnostics.CodeAnalysis;
                    using System.Reflection;
                    [assembly: AssemblyVersion("3.4.5.6")]

                    ${profile.nullableDirective}

                    ${profile.fixturePreamble}

                    namespace ForeignCallContracts
                    {
                        public interface Api
                        {
                            int Compute(int value);
                            int Compute(string value);
                            string Echo(string value);
                            string Join(string prefix, params string[] values);
                            string Describe(params ${profile.nullableObjectArrayType} values);
                            void Touch();
                            int Count { get; }
                            string Name { get; set; }
                            ${profile.nullableStringType} Optional { get; set; }

                            [DoesNotReturn]
                            int ReturnsValue();

                            [DoesNotReturn]
                            void ReturnsVoid();
                        }

                        public sealed class ApiImpl : Api
                        {
                            private string name = "initial";
                            private ${profile.nullableStringType} optional;

                            public int Compute(int value) { return value + 1; }
                            public int Compute(string value) { return value.Length + 10; }
                            public string Echo(string value) { return value + "!"; }
                            public string Join(string prefix, params string[] values)
                            {
                                return prefix + ":" + values.Length + ":" +
