        )
        val csharpCompiler = DotNetIlAssembler.findFrameworkCSharpCompiler()
        requireOrAssumeToolchain(csharpCompiler != null, ".NET Framework C# compiler is not available")
        val dotnetHost = modernDotNetHostOrSkip()
        val libraryDirectory = File(tmpdir, "primitive-array-wrapper-library")
        val librarySource = File(tmpdir, "primitiveArrayLibrary.kt").apply {
            writeText(
                """
                package primitivearrays

                public fun measure(values: IntArray): Int = values[0] + values[1]

                public fun measure(values: Array<Int>): Int = values[0] + values[1] + 10

                public fun makeSpecialized(): IntArray = intArrayOf(1, 2)

                public fun makeGeneric(): Array<Int> = arrayOf(1, 2)

                public fun identity(values: IntArray): IntArray = values

                public fun identityBytes(values: ByteArray): ByteArray = values

                public fun identityShorts(values: ShortArray): ShortArray = values

                public fun identityFloats(values: FloatArray): FloatArray = values

                private var remembered: IntArray? = null

                public fun sameIdentity(first: IntArray, second: IntArray): Boolean = first === second

                public fun rememberIdentity(values: IntArray): Boolean {
                    remembered = values
                    return true
                }

                public fun isRememberedIdentity(values: IntArray): Boolean = remembered === values

                public fun makeAndRemember(): IntArray {
                    val values = intArrayOf(20, 22)
                    remembered = values
                    return values
                }
                """.trimIndent()
            )
        }
        compileInProcess(
            K2DotNetCompiler(),
            librarySource.path,
            K2DotNetCompilerArguments::dotNetProduceLibrary.cliArgument,
            K2DotNetCompilerArguments::dotNetTarget.cliArgument, "netstandard2.0",
            K2DotNetCompilerArguments::moduleName.cliArgument, "PrimitiveArray.Library",
            K2DotNetCompilerArguments::dotNetExports.cliArgument,
            "primitivearrays.identity(kotlin.IntArray)=RoundTripSpecialized",
            K2DotNetCompilerArguments::dotNetExports.cliArgument,
            "primitivearrays.identityBytes(kotlin.ByteArray)=RoundTripBytes",
            K2DotNetCompilerArguments::dotNetExports.cliArgument,
            "primitivearrays.identityShorts(kotlin.ShortArray)=RoundTripShorts",
            K2DotNetCompilerArguments::dotNetExports.cliArgument,
            "primitivearrays.identityFloats(kotlin.FloatArray)=RoundTripFloats",
            K2DotNetCompilerArguments::dotNetExports.cliArgument,
            "primitivearrays.makeSpecialized=MakeSpecialized",
            K2DotNetCompilerArguments::dotNetExports.cliArgument,
            "primitivearrays.sameIdentity(kotlin.IntArray,kotlin.IntArray)=SameSpecialized",
            K2DotNetCompilerArguments::dotNetExports.cliArgument,
            "primitivearrays.rememberIdentity(kotlin.IntArray)=RememberSpecialized",
            K2DotNetCompilerArguments::dotNetExports.cliArgument,
            "primitivearrays.isRememberedIdentity(kotlin.IntArray)=IsRememberedSpecialized",
            K2DotNetCompilerArguments::dotNetExports.cliArgument,
            "primitivearrays.makeAndRemember=MakeAndRemember",
            K2DotNetCompilerArguments::destination.cliArgument, libraryDirectory.path,
        )

        val metadataLibrary = libraryDirectory.resolve("PrimitiveArray.Library.dll")
        val libraryIl = libraryDirectory.resolve("PrimitiveArray.Library.il").readText()
        assertTrue(
            "'measure'(class [Kotlin.Runtime]'Kotlin.IntArray' 'values')" in libraryIl
        ) { libraryIl }
        assertTrue("'measure'(int32[] 'values')" in libraryIl) { libraryIl }
        assertTrue(
            "class [Kotlin.Runtime]'Kotlin.IntArray' 'makeSpecialized'()" in libraryIl
        ) { libraryIl }
        assertTrue("int32[] 'makeGeneric'()" in libraryIl) { libraryIl }
        assertTrue("int32[] 'RoundTripSpecialized'(int32[] 'values')" in libraryIl) { libraryIl }
        assertTrue("int8[] 'RoundTripBytes'(int8[] 'values')" in libraryIl) { libraryIl }
        assertTrue("int16[] 'RoundTripShorts'(int16[] 'values')" in libraryIl) { libraryIl }
        assertTrue("float32[] 'RoundTripFloats'(float32[] 'values')" in libraryIl) { libraryIl }
        assertTrue("int32[] 'MakeSpecialized'()" in libraryIl) { libraryIl }
        assertTrue("bool 'SameSpecialized'(int32[] 'first', int32[] 'second')" in libraryIl) { libraryIl }
        assertTrue("bool 'RememberSpecialized'(int32[] 'values')" in libraryIl) { libraryIl }
        assertTrue("bool 'IsRememberedSpecialized'(int32[] 'values')" in libraryIl) { libraryIl }
        assertTrue("int32[] 'MakeAndRemember'()" in libraryIl) { libraryIl }

        for (target in listOf("net48", "net10.0")) {
            val consumerDirectory = libraryDirectory.resolve("consumer-${target.replace('.', '-')}").apply { mkdirs() }
            val consumerSource = consumerDirectory.resolve("consumer.kt").apply {
                writeText(
                    """
                    package primitivearrayconsumer

                    import primitivearrays.*

                    fun main() {
                        val specialized = makeSpecialized()
                        val generic = makeGeneric()
                        if (measure(specialized) != 3) throw Error("specialized overload")
                        if (measure(generic) != 13) throw Error("generic primitive substitution overload")
                        val specializedIdentity: Any = specialized
                        val genericIdentity: Any = generic
                        if (specializedIdentity === genericIdentity) throw Error("array identities collapsed")
                        specialized[0] = 40
                        generic[0] = 41
                        if (measure(specialized) != 42 || measure(generic) != 53) {
                            throw Error("cross-module mutation")
                        }
                        val bytes = identityBytes(byteArrayOf((-2).toByte(), 3.toByte()))
                        val shorts = identityShorts(shortArrayOf((-200).toShort(), 300.toShort()))
                        val floats = identityFloats(floatArrayOf(-2.5f, 3.75f))
                        if (bytes[0] != (-2).toByte() || bytes[1] != 3.toByte()) {
                            throw Error("ByteArray cross-module round trip")
                        }
                        if (shorts[0] != (-200).toShort() || shorts[1] != 300.toShort()) {
                            throw Error("ShortArray cross-module round trip")
                        }
                        if (floats[0] != -2.5f || floats[1] != 3.75f) {
                            throw Error("FloatArray cross-module round trip")
                        }
                    }
                    """.trimIndent()
                )
            }
            val application = consumerDirectory.resolve(
                if (target == "net48") "PrimitiveArrayConsumer.exe" else "PrimitiveArrayConsumer.dll"
            )
            compileInProcess(
                K2DotNetCompiler(),
                consumerSource.path,
                K2DotNetCompilerArguments::classpath.cliArgument, metadataLibrary.path,
                K2DotNetCompilerArguments::dotNetTarget.cliArgument, target,
                K2DotNetCompilerArguments::moduleName.cliArgument, "PrimitiveArrayConsumer",
                K2DotNetCompilerArguments::destination.cliArgument, application.path,
            )
            if (target == "net10.0") {
                runDotNet(
                    dotnetHost,
                    application,
                    consumerDirectory,
                    "Primitive-array Kotlin consumer failed for $target",
                )
            } else {
                val process = ProcessBuilder(application.path)
                    .directory(consumerDirectory)
                    .redirectErrorStream(true)
                    .start()
                val output = process.inputStream.bufferedReader().use { it.readText() }
                assertEquals(0, process.waitFor(), "Primitive-array Kotlin consumer failed for $target:\n$output")
            }

            val verifierSource = consumerDirectory.resolve("PrimitiveArrayVerifier.cs").apply {
                writeText(
                    """
                    using System;
                    using System.Reflection;
                    using System.Threading;

                    public static class PrimitiveArrayVerifier
                    {
                        private static void Require(bool condition, string message)
                        {
                            if (!condition) throw new Exception(message);
                        }

                        private static bool HasAttribute(MemberInfo member, string fullName)
                        {
                            foreach (object attribute in member.GetCustomAttributes(false))
                            {
                                if (attribute.GetType().FullName == fullName) return true;
                            }
                            return false;
                        }

                        public static int Main()
                        {
                            Assembly library = Assembly.LoadFrom("PrimitiveArray.Library.dll");
                            Type facade = library.GetType("primitivearrays.primitiveArrayLibraryKt", true);
                            MethodInfo specializedMeasure = facade.GetMethod(
                                "measure", new Type[] { Type.GetType("Kotlin.IntArray, Kotlin.Runtime", true) });
                            MethodInfo genericMeasure = facade.GetMethod("measure", new Type[] { typeof(int[]) });
                            MethodInfo makeSpecialized = facade.GetMethod("makeSpecialized", Type.EmptyTypes);
                            MethodInfo makeGeneric = facade.GetMethod("makeGeneric", Type.EmptyTypes);
                            MethodInfo roundTripExport = facade.GetMethod(
                                "RoundTripSpecialized", new Type[] { typeof(int[]) });
                            MethodInfo byteRoundTripExport = facade.GetMethod(
                                "RoundTripBytes", new Type[] { typeof(sbyte[]) });
                            MethodInfo shortRoundTripExport = facade.GetMethod(
                                "RoundTripShorts", new Type[] { typeof(short[]) });
                            MethodInfo floatRoundTripExport = facade.GetMethod(
                                "RoundTripFloats", new Type[] { typeof(float[]) });
                            MethodInfo makeSpecializedExport = facade.GetMethod(
                                "MakeSpecialized", Type.EmptyTypes);
                            MethodInfo sameExport = facade.GetMethod(
                                "SameSpecialized", new Type[] { typeof(int[]), typeof(int[]) });
                            MethodInfo rememberExport = facade.GetMethod(
                                "RememberSpecialized", new Type[] { typeof(int[]) });
                            MethodInfo isRememberedExport = facade.GetMethod(
                                "IsRememberedSpecialized", new Type[] { typeof(int[]) });
                            MethodInfo makeAndRememberExport = facade.GetMethod(
                                "MakeAndRemember", Type.EmptyTypes);
                            Require(specializedMeasure != null, "specialized overload is not wrapper-shaped");
                            Require(genericMeasure != null, "Array<Int> overload is not int[]-shaped");
                            Require(makeSpecialized.ReturnType.FullName == "Kotlin.IntArray",
                                "specialized result leaked its vector storage");
                            Require(makeGeneric.ReturnType == typeof(int[]),
                                "generic substitution did not retain the natural CLR vector");
                            Require(roundTripExport != null && roundTripExport.ReturnType == typeof(int[]),
                                "explicit specialized-array export is not int[]-shaped");
                            Require(byteRoundTripExport != null && byteRoundTripExport.ReturnType == typeof(sbyte[]),
                                "ByteArray export is not signed int8[]-shaped");
                            Require(shortRoundTripExport != null && shortRoundTripExport.ReturnType == typeof(short[]),
                                "ShortArray export is not int16[]-shaped");
                            Require(floatRoundTripExport != null && floatRoundTripExport.ReturnType == typeof(float[]),
                                "FloatArray export is not float32[]-shaped");
                            Require(makeSpecializedExport != null &&
                                    makeSpecializedExport.ReturnType == typeof(int[]),
                                "explicit specialized-array result export is not int[]-shaped");
                            Require(sameExport != null && sameExport.ReturnType == typeof(bool),
                                "two-parameter identity export is not bool/int[]-shaped");
                            Require(rememberExport != null && isRememberedExport != null,
                                "cross-call identity exports are missing");
                            Require(makeAndRememberExport != null &&
                                    makeAndRememberExport.ReturnType == typeof(int[]),
                                "stored specialized-array result export is not int[]-shaped");

                            Type wrapperType = makeSpecialized.ReturnType;
                            Require(wrapperType.IsSealed, "primitive-array wrapper must be sealed");
                            FieldInfo storageField = wrapperType.GetField(
                                "_storage", BindingFlags.Instance | BindingFlags.NonPublic);
                            Require(storageField != null && storageField.IsPrivate && storageField.FieldType == typeof(int[]),
                                "wrapper storage layout is not private int[]");
                            Type byteWrapperType = Type.GetType("Kotlin.ByteArray, Kotlin.Runtime", true);
                            Type shortWrapperType = Type.GetType("Kotlin.ShortArray, Kotlin.Runtime", true);
                            Type floatWrapperType = Type.GetType("Kotlin.FloatArray, Kotlin.Runtime", true);
                            FieldInfo byteStorageField = byteWrapperType.GetField(
                                "_storage", BindingFlags.Instance | BindingFlags.NonPublic);
                            FieldInfo shortStorageField = shortWrapperType.GetField(
                                "_storage", BindingFlags.Instance | BindingFlags.NonPublic);
                            FieldInfo floatStorageField = floatWrapperType.GetField(
                                "_storage", BindingFlags.Instance | BindingFlags.NonPublic);
                            Require(byteStorageField != null && byteStorageField.FieldType == typeof(sbyte[]),
                                "ByteArray wrapper storage is not signed sbyte[]");
                            Require(shortStorageField != null && shortStorageField.FieldType == typeof(short[]),
                                "ShortArray wrapper storage is not short[]");
                            Require(floatStorageField != null && floatStorageField.FieldType == typeof(float[]),
                                "FloatArray wrapper storage is not float[]");
                            FieldInfo internTable = wrapperType.GetField(
                                "_internedByStorage", BindingFlags.Static | BindingFlags.NonPublic);
                            Require(internTable != null && internTable.IsPrivate && internTable.IsInitOnly &&
                                    internTable.FieldType.IsGenericType &&
                                    internTable.FieldType.GetGenericTypeDefinition().FullName ==
                                        "System.Runtime.CompilerServices.ConditionalWeakTable`2",
                                "interop identity association is not runtime-owned weak interning");
                            ConstructorInfo storageConstructor = wrapperType.GetConstructor(new Type[] { typeof(int[]) });
                            MethodInfo getStorage = wrapperType.GetMethod("GetStorage", BindingFlags.Public | BindingFlags.Instance);
                            MethodInfo wrapStorageOrNull = wrapperType.GetMethod(
                                "WrapStorageOrNull", BindingFlags.Public | BindingFlags.Static);
                            Require(storageConstructor != null && getStorage != null && wrapStorageOrNull != null,
                                "cross-assembly primitive-array compiler ABI is missing");
                            Require(HasAttribute(storageConstructor,
                                    "Kotlin.Runtime.Internal.KotlinCompilerAbiAttribute"),
                                "storage constructor is not marked compiler ABI");

                            object specialized = makeSpecialized.Invoke(null, null);
                            int[] generic = (int[]) makeGeneric.Invoke(null, null);
                            Require(!Object.ReferenceEquals(specialized, generic),
                                "specialized and generic array identities collapsed");
                            int[] liveStorage = (int[]) getStorage.Invoke(specialized, null);
                            liveStorage[0] = 40;
                            Require((int) specializedMeasure.Invoke(null, new object[] { specialized }) == 42,
                                "wrapper-to-storage mutation alias was lost");
                            generic[0] = 41;
                            Require((int) genericMeasure.Invoke(null, new object[] { generic }) == 53,
                                "natural generic vector mutation failed");

                            int[] exportedInput = new int[] { 20, 22 };
                            object exportedRoundTrip = roundTripExport.Invoke(
                                null, new object[] { exportedInput });
                            Require(Object.ReferenceEquals(exportedInput, exportedRoundTrip),
                                "explicit export copied or replaced primitive-array storage");
                            sbyte[] byteInput = new sbyte[] { -2, 3 };
                            short[] shortInput = new short[] { -200, 300 };
                            float[] floatInput = new float[] { -2.5f, 3.75f };
                            Require(Object.ReferenceEquals(byteInput, byteRoundTripExport.Invoke(
                                    null, new object[] { byteInput })),
                                "ByteArray export copied or replaced its signed storage");
                            Require(Object.ReferenceEquals(shortInput, shortRoundTripExport.Invoke(
                                    null, new object[] { shortInput })),
                                "ShortArray export copied or replaced its storage");
                            Require(Object.ReferenceEquals(floatInput, floatRoundTripExport.Invoke(
                                    null, new object[] { floatInput })),
                                "FloatArray export copied or replaced its storage");
                            Require((bool) sameExport.Invoke(
                                    null, new object[] { exportedInput, exportedInput }),
                                "one CLR vector did not project to one Kotlin wrapper within a call");
                            Require(!(bool) sameExport.Invoke(
                                    null, new object[] { exportedInput, new int[] { 20, 22 } }),
                                "distinct CLR vectors collapsed to one Kotlin wrapper");
                            Require((bool) rememberExport.Invoke(
                                    null, new object[] { exportedInput }),
                                "identity remember export failed");
                            Require((bool) isRememberedExport.Invoke(
                                    null, new object[] { exportedInput }),
                                "one CLR vector did not retain Kotlin wrapper identity across calls");
                            int[] exportedResult = (int[]) makeSpecializedExport.Invoke(null, null);
                            Require(exportedResult.Length == 2 && exportedResult[0] == 1 && exportedResult[1] == 2,
                                "explicit primitive-array result export lost contents");
                            int[] rememberedResult = (int[]) makeAndRememberExport.Invoke(null, null);
                            Require((bool) isRememberedExport.Invoke(
                                    null, new object[] { rememberedResult }),
                                "outbound Kotlin wrapper was not recovered when its vector returned inbound");

                            int[] inboundStorage = new int[] { 20, 22 };
                            object inboundWrapper = storageConstructor.Invoke(new object[] { inboundStorage });
                            Require(Object.ReferenceEquals(inboundStorage, getStorage.Invoke(inboundWrapper, null)),
                                "compiler ABI wrapper construction copied storage silently");
                            Require((int) specializedMeasure.Invoke(null, new object[] { inboundWrapper }) == 42,
                                "inbound wrapper did not alias its supplied vector");

                            int[] concurrentStorage = new int[] { 42 };
                            object[] concurrentWrappers = new object[8];
                            Exception[] concurrentErrors = new Exception[8];
                            Thread[] threads = new Thread[8];
                            for (int index = 0; index < threads.Length; index++)
                            {
                                int slot = index;
                                threads[index] = new Thread(delegate()
                                {
                                    try
                                    {
                                        concurrentWrappers[slot] = wrapStorageOrNull.Invoke(
                                            null, new object[] { concurrentStorage });
                                    }
                                    catch (Exception error)
                                    {
                                        concurrentErrors[slot] = error;
                                    }
                                });
                                threads[index].Start();
                            }
                            for (int index = 0; index < threads.Length; index++) threads[index].Join();
                            for (int index = 0; index < threads.Length; index++)
                            {
                                Require(concurrentErrors[index] == null,
                                    "concurrent vector adaptation failed");
                                Require(Object.ReferenceEquals(concurrentWrappers[0], concurrentWrappers[index]),
                                    "concurrent first conversion created multiple Kotlin wrappers");
                            }
                            return 0;
                        }
                    }
                    """.trimIndent()
                )
            }
            val verifier = consumerDirectory.resolve("PrimitiveArrayVerifier.exe")
            val compileResult = runCSharpCompiler(
                checkNotNull(csharpCompiler),
                verifierSource,
                verifier,
                target = "exe",
            )
            assertEquals(0, compileResult.exitCode, compileResult.output)
            val verifierProcess = if (target == "net10.0") {
                consumerDirectory.resolve("PrimitiveArrayConsumer.runtimeconfig.json")
                    .copyTo(consumerDirectory.resolve("PrimitiveArrayVerifier.runtimeconfig.json"), overwrite = true)
                ProcessBuilder(dotnetHost.path, "exec", verifier.path)
            } else {
                ProcessBuilder(verifier.path)
            }.directory(consumerDirectory).redirectErrorStream(true).start()
            val verifierOutput = verifierProcess.inputStream.bufferedReader().use { it.readText() }
            assertEquals(
                0,
                verifierProcess.waitFor(),
                "Primitive-array C# verifier failed for $target:\n$verifierOutput",
            )
        }
    }

    @Test
    fun testNullablePrimitiveGenericArraysAcrossPortableLibraryBoundary() {
        requireOrAssumeToolchain(
            DotNetIlAssembler.findFrameworkIlasm() != null,
            ".NET Framework ILAsm is not available",
        )
        requireOrAssumeToolchain(
            DotNetIlAssembler.findModernIlasm() != null,
            "Modern ILAsm is not available",
        )
        val frameworkHost = DotNetIlAssembler.findFrameworkPowerShellHost()
        requireOrAssumeToolchain(frameworkHost != null, "Windows PowerShell CLR 4 host is not available")
        val csharpCompiler = DotNetIlAssembler.findFrameworkCSharpCompiler()
        requireOrAssumeToolchain(csharpCompiler != null, ".NET Framework C# compiler is not available")
        val frameworkNetStandardFacade = findFrameworkNetStandardFacade()
        requireOrAssumeToolchain(
            frameworkNetStandardFacade != null,
            ".NET Framework netstandard facade is not available",
        )
        val dotnetHost = modernDotNetHostOrSkip()
        val libraryDirectory = File(tmpdir, "nullable-primitive-array-library")
        val librarySource = File(tmpdir, "nullablePrimitiveArrayLibrary.kt").apply {
            writeText(
                """
                package nullableprimitivearrays

                public fun identityBooleans(values: Array<Boolean?>): Array<Boolean?> = values
                public fun identityBytes(values: Array<Byte?>): Array<Byte?> = values
                public fun identityShorts(values: Array<Short?>): Array<Short?> = values
                public fun identityInts(values: Array<Int?>): Array<Int?> = values
                public fun identityLongs(values: Array<Long?>): Array<Long?> = values
                public fun identityFloats(values: Array<Float?>): Array<Float?> = values
                public fun identityDoubles(values: Array<Double?>): Array<Double?> = values
                public fun identityChars(values: Array<Char?>): Array<Char?> = values

                public fun <T> genericIdentity(values: Array<T>): Array<T> = values
                """.trimIndent()
            )
        }
        compileInProcess(
            K2DotNetCompiler(),
            librarySource.path,
            K2DotNetCompilerArguments::dotNetProduceLibrary.cliArgument,
            K2DotNetCompilerArguments::dotNetTarget.cliArgument, "netstandard2.0",
            K2DotNetCompilerArguments::moduleName.cliArgument, "NullablePrimitiveArray.Library",
            K2DotNetCompilerArguments::destination.cliArgument, libraryDirectory.path,
        )

        val metadataLibrary = libraryDirectory.resolve("NullablePrimitiveArray.Library.dll")
        val libraryIl = libraryDirectory.resolve("NullablePrimitiveArray.Library.il").readText()
        for (methodAndElementToken in listOf(
            "identityBooleans" to "bool",
            "identityBytes" to "int8",
            "identityShorts" to "int16",
            "identityInts" to "int32",
            "identityLongs" to "int64",
            "identityFloats" to "float32",
            "identityDoubles" to "float64",
            "identityChars" to "char",
        )) {
            val methodName = methodAndElementToken.first
            val elementToken = methodAndElementToken.second
            assertTrue("System.Nullable`1<$elementToken>[] '$methodName'(" in libraryIl) { libraryIl }
        }
        assertTrue("!!0[] 'genericIdentity'<'T'>(!!0[] 'values')" in libraryIl) { libraryIl }

        val frameworkDirectSource = libraryDirectory.resolve("FrameworkDirectNullableArrayConsumer.cs").apply {
            writeText(
                """
                using System;
                using System.Reflection;

                public static class FrameworkDirectNullableArrayConsumer
                {
                    private static bool HasExactSignature(Type facade, string name, Type arrayType)
                    {
                        MethodInfo method = facade.GetMethod(name, new Type[] { arrayType });
                        return method != null && method.ReturnType == arrayType;
                    }

                    public static int Main()
                    {
                        Type facade = typeof(nullableprimitivearrays.nullablePrimitiveArrayLibraryKt);
                        if (!HasExactSignature(facade, "identityBooleans", typeof(bool?[]))) return 11;
                        if (!HasExactSignature(facade, "identityBytes", typeof(sbyte?[]))) return 12;
                        if (!HasExactSignature(facade, "identityShorts", typeof(short?[]))) return 13;
                        if (!HasExactSignature(facade, "identityInts", typeof(int?[]))) return 14;
                        if (!HasExactSignature(facade, "identityLongs", typeof(long?[]))) return 15;
                        if (!HasExactSignature(facade, "identityFloats", typeof(float?[]))) return 16;
                        if (!HasExactSignature(facade, "identityDoubles", typeof(double?[]))) return 17;
                        if (!HasExactSignature(facade, "identityChars", typeof(char?[]))) return 18;
                        bool?[] booleans = new bool?[] { true, null };
                        sbyte?[] bytes = new sbyte?[] { -2, null };
                        short?[] shorts = new short?[] { -200, null };
                        int?[] ints = new int?[] { 40, null, 2 };
                        long?[] longs = new long?[] { 42L, null };
                        float?[] floats = new float?[] { 1.25f, null };
                        double?[] doubles = new double?[] { 2.5, null };
                        char?[] chars = new char?[] { 'K', null };
                        if (!Object.ReferenceEquals(booleans,
                            nullableprimitivearrays.nullablePrimitiveArrayLibraryKt.identityBooleans(booleans))) return 1;
                        if (!Object.ReferenceEquals(bytes,
                            nullableprimitivearrays.nullablePrimitiveArrayLibraryKt.identityBytes(bytes))) return 2;
                        if (!Object.ReferenceEquals(shorts,
                            nullableprimitivearrays.nullablePrimitiveArrayLibraryKt.identityShorts(shorts))) return 3;
                        if (!Object.ReferenceEquals(ints,
                            nullableprimitivearrays.nullablePrimitiveArrayLibraryKt.identityInts(ints))) return 4;
                        if (!Object.ReferenceEquals(longs,
                            nullableprimitivearrays.nullablePrimitiveArrayLibraryKt.identityLongs(longs))) return 5;
                        if (!Object.ReferenceEquals(floats,
                            nullableprimitivearrays.nullablePrimitiveArrayLibraryKt.identityFloats(floats))) return 6;
                        if (!Object.ReferenceEquals(doubles,
                            nullableprimitivearrays.nullablePrimitiveArrayLibraryKt.identityDoubles(doubles))) return 7;
                        if (!Object.ReferenceEquals(chars,
                            nullableprimitivearrays.nullablePrimitiveArrayLibraryKt.identityChars(chars))) return 8;
                        return 0;
                    }
                }
                """.trimIndent()
            )
        }
        val frameworkDirectConsumer = libraryDirectory.resolve("FrameworkDirectNullableArrayConsumer.exe")
        val frameworkDirectCompile = runCSharpCompiler(
            checkNotNull(csharpCompiler),
            frameworkDirectSource,
            frameworkDirectConsumer,
            metadataLibrary,
            checkNotNull(frameworkNetStandardFacade),
            target = "exe",
        )
        assertEquals(0, frameworkDirectCompile.exitCode, frameworkDirectCompile.output)
        val frameworkDirectProcess = ProcessBuilder(
            frameworkExecutionCommand(checkNotNull(frameworkHost), frameworkDirectConsumer)
        )
            .directory(libraryDirectory)
            .redirectErrorStream(true)
            .start()
        val frameworkDirectOutput = frameworkDirectProcess.inputStream.bufferedReader().use { it.readText() }
        assertEquals(
            0,
            frameworkDirectProcess.waitFor(),
            "Roslyn direct nullable-array consumer failed on net48:\n$frameworkDirectOutput",
        )
        for (target in listOf("net48", "net10.0")) {
            val consumerDirectory = libraryDirectory.resolve("consumer-${target.replace('.', '-')}").apply { mkdirs() }
            val consumerSource = consumerDirectory.resolve("consumer.kt").apply {
                writeText(
                    """
                    package nullableprimitivearrayconsumer

                    import nullableprimitivearrays.*

                    fun main() {
                        val booleans = arrayOf<Boolean?>(true, null)
                        val bytes = arrayOf<Byte?>((-2).toByte(), null)
                        val shorts = arrayOf<Short?>((-200).toShort(), null)
                        val ints = arrayOf<Int?>(40, null, 2)
                        val longs = arrayOf<Long?>(42L, null)
                        val floats = arrayOf<Float?>(1.25f, null)
                        val doubles = arrayOf<Double?>(2.5, null)
                        val chars = arrayOf<Char?>('K', null)
                        if (identityBooleans(booleans) !== booleans || identityBytes(bytes) !== bytes ||
                            identityShorts(shorts) !== shorts || identityInts(ints) !== ints ||
                            identityLongs(longs) !== longs || identityFloats(floats) !== floats ||
                            identityDoubles(doubles) !== doubles || identityChars(chars) !== chars
                        ) throw Error("closed nullable primitive array identity")
                        if (genericIdentity(ints) !== ints || genericIdentity(chars) !== chars) {
                            throw Error("generic nullable primitive array identity")
                        }
                        if (ints[0] != 40 || ints[1] != null || ints[2] != 2) {
                            throw Error("closed nullable primitive array contents")
                        }
                    }
                    """.trimIndent()
                )
            }
            val application = consumerDirectory.resolve(
                if (target == "net48") "NullablePrimitiveArrayConsumer.exe" else "NullablePrimitiveArrayConsumer.dll"
            )
            compileInProcess(
                K2DotNetCompiler(),
                consumerSource.path,
                K2DotNetCompilerArguments::classpath.cliArgument, metadataLibrary.path,
                K2DotNetCompilerArguments::dotNetTarget.cliArgument, target,
                K2DotNetCompilerArguments::moduleName.cliArgument, "NullablePrimitiveArrayConsumer",
                K2DotNetCompilerArguments::destination.cliArgument, application.path,
            )
            if (target == "net10.0") {
                runDotNet(
                    dotnetHost,
                    application,
                    consumerDirectory,
                    "Nullable primitive-array Kotlin consumer failed for $target",
                )
            } else {
                val process = ProcessBuilder(
                    frameworkExecutionCommand(checkNotNull(frameworkHost), application)
                )
                    .directory(consumerDirectory)
                    .redirectErrorStream(true)
                    .start()
                val output = process.inputStream.bufferedReader().use { it.readText() }
                assertEquals(
                    0,
                    process.waitFor(),
                    "Nullable primitive-array Kotlin consumer failed for $target:\n$output",
                )
            }
            if (target == "net10.0") {
                val modernCSharpConsumer = consumerDirectory.resolve(frameworkDirectConsumer.name)
                frameworkDirectConsumer.copyTo(modernCSharpConsumer, overwrite = true)
                consumerDirectory.resolve("NullablePrimitiveArrayConsumer.runtimeconfig.json")
                    .copyTo(
                        consumerDirectory.resolve("FrameworkDirectNullableArrayConsumer.runtimeconfig.json"),
                        overwrite = true,
                    )
                runDotNet(
                    dotnetHost,
                    modernCSharpConsumer,
                    consumerDirectory,
                    "Roslyn nullable-array consumer failed on $target",
                )
            }
        }
    }

    @Test
    fun testExactCommonContractsProjectOnlyToSupportedExplicitExports() {
        requireOrAssumeToolchain(
            DotNetIlAssembler.findFrameworkIlasm() != null,
            ".NET Framework ILAsm is not available",
        )
        requireOrAssumeToolchain(
            DotNetIlAssembler.findModernIlasm() != null,
            "Modern ILAsm is not available",
        )
        val csharpToolchain = DotNetIlAssembler.findModernCSharpCompiler()
        requireOrAssumeToolchain(
            csharpToolchain != null,
            "Modern Roslyn and the net10 reference pack are not available",
        )
        val modernCSharp = checkNotNull(csharpToolchain)
        val sourceText = """
            package contractexports

            import kotlin.contracts.ExperimentalContracts
            import kotlin.contracts.ExperimentalExtendedContracts
            import kotlin.contracts.contract

            public typealias TextAlias = String?
            public typealias NullableIntAlias = Int?

            @OptIn(ExperimentalContracts::class)
            public fun requireText(value: String?) {
                contract { returns() implies (value != null) }
                if (value == null) throw IllegalArgumentException("value")
            }

            @OptIn(ExperimentalContracts::class)
            public fun isText(value: String?): Boolean {
                contract { returns(true) implies (value != null) }
                return value != null
            }

            @OptIn(ExperimentalContracts::class)
            public fun isNull(value: String?): Boolean {
                contract { returns(false) implies (value != null) }
                return value == null
            }

            @OptIn(ExperimentalContracts::class, ExperimentalExtendedContracts::class)
            public fun copyText(value: String?): String? {
                contract { (value != null) implies returnsNotNull() }
                return value
            }

            @OptIn(ExperimentalContracts::class, ExperimentalExtendedContracts::class)
            public fun copyDefaulted(value: String? = "fallback"): String? {
                contract { (value != null) implies returnsNotNull() }
                return value
            }

            @OptIn(ExperimentalContracts::class)
            public fun isKnown(value: String?): Boolean {
                contract {
                    returns(true) implies (value != null)
                    returns(false) implies (value != null)
                }
                if (value == null) throw IllegalArgumentException("value")
                return true
            }

            @OptIn(ExperimentalContracts::class)
            public fun requireTrue(value: Boolean) {
                contract { returns() implies value }
                if (!value) throw IllegalArgumentException("value")
            }

            public fun fail(): Nothing = throw IllegalStateException("fail")

            @OptIn(ExperimentalContracts::class)
            public fun defaulted(value: String? = "fallback"): String {
                contract { returns() implies (value != null) }
                return value ?: throw IllegalArgumentException("value")
            }

            @OptIn(ExperimentalContracts::class)
            public fun requireBoth(first: String?, second: String?) {
                contract { returns() implies (first != null && second != null) }
                if (first == null || second == null) throw IllegalArgumentException("values")
            }

            @OptIn(ExperimentalContracts::class)
            public fun requireAlias(value: TextAlias) {
                contract { returns() implies (value != null) }
                if (value == null) throw IllegalArgumentException("value")
            }

            @OptIn(ExperimentalContracts::class)
            public fun requireNullableIntAlias(value: NullableIntAlias) {
                contract { returns() implies (value != null) }
                if (value == null) throw IllegalArgumentException("value")
            }
        """.trimIndent()
        val exportArguments = arrayOf(
            K2DotNetCompilerArguments::dotNetExports.cliArgument, "contractexports.requireText=RequireText",
            K2DotNetCompilerArguments::dotNetExports.cliArgument, "contractexports.isText=IsText",
            K2DotNetCompilerArguments::dotNetExports.cliArgument, "contractexports.isNull=IsNull",
            K2DotNetCompilerArguments::dotNetExports.cliArgument, "contractexports.copyText=CopyText",
            K2DotNetCompilerArguments::dotNetExports.cliArgument, "contractexports.copyDefaulted=CopyDefaulted",
            K2DotNetCompilerArguments::dotNetExports.cliArgument, "contractexports.isKnown=IsKnown",
            K2DotNetCompilerArguments::dotNetExports.cliArgument, "contractexports.requireTrue=RequireTrue",
            K2DotNetCompilerArguments::dotNetExports.cliArgument, "contractexports.fail=Fail",
            K2DotNetCompilerArguments::dotNetExports.cliArgument, "contractexports.defaulted=Defaulted",
            K2DotNetCompilerArguments::dotNetExports.cliArgument, "contractexports.requireBoth=RequireBoth",
            K2DotNetCompilerArguments::dotNetExports.cliArgument, "contractexports.requireAlias=RequireAlias",
            K2DotNetCompilerArguments::dotNetExports.cliArgument,
            "contractexports.requireNullableIntAlias=RequireNullableIntAlias",
        )

        fun compileProducer(target: String, useLightTree: Boolean = true): File {
            val parserName = if (useLightTree) "lt" else "psi"
            val directory = File(
                tmpdir,
                "contract-export-${target.replace('.', '-')}-$parserName",
            ).apply { mkdirs() }
            val source = directory.resolve("contracts.kt").apply { writeText(sourceText) }
            val moduleName = "Contract.Exports.${target.replace('.', '_')}.$parserName"
            compileInProcess(
                K2DotNetCompiler(),
                source.path,
                K2DotNetCompilerArguments::dotNetProduceLibrary.cliArgument,
                K2DotNetCompilerArguments::dotNetTarget.cliArgument, target,
                K2DotNetCompilerArguments::moduleName.cliArgument, moduleName,
                "-Xuse-fir-lt=$useLightTree",
                "-XXLanguage:+ConditionImpliesReturnsContracts",
                *exportArguments,
                K2DotNetCompilerArguments::destination.cliArgument, directory.path,
            )
            return directory.resolve("$moduleName.dll")
                .also { library -> assertTrue(library.isFile) }
        }

        val frameworkLibrary = compileProducer("net48")
        val portableLibrary = compileProducer("netstandard2.0")
        val modernLibrary = compileProducer("net10.0")
        val psiModernLibrary = compileProducer("net10.0", useLightTree = false)
        for (library in listOf(frameworkLibrary, portableLibrary)) {
            val il = library.resolveSibling("${library.nameWithoutExtension}.il").readText()
            assertFalse("System.Diagnostics.CodeAnalysis" in il) { il }
        }

        val modernDirectory = checkNotNull(modernLibrary.parentFile)
        val modernIl = modernLibrary.resolveSibling("${modernLibrary.nameWithoutExtension}.il").readText()
        for (attributeName in listOf(
            "NotNullAttribute",
            "NotNullWhenAttribute",
            "NotNullIfNotNullAttribute",
            "DoesNotReturnIfAttribute",
            "DoesNotReturnAttribute",
        )) {
            assertTrue("System.Diagnostics.CodeAnalysis.$attributeName" in modernIl) {
                "Missing $attributeName from explicit net10 export:\n$modernIl"
            }
        }
        val psiModernIl = psiModernLibrary.resolveSibling("${psiModernLibrary.nameWithoutExtension}.il").readText()
        for (attributeName in listOf(
            "NotNullAttribute",
            "NotNullWhenAttribute",
            "NotNullIfNotNullAttribute",
            "DoesNotReturnIfAttribute",
            "DoesNotReturnAttribute",
        )) {
            assertTrue("System.Diagnostics.CodeAnalysis.$attributeName" in psiModernIl) {
                "PSI and LightTree contract projection differ for $attributeName:\n$psiModernIl"
            }
        }
        assertTrue(".assembly extern System.Runtime" in modernIl) { modernIl }

        val strippedDirectory = modernDirectory.resolve("stripped").apply { mkdirs() }
        val strippedIl = strippedDirectory.resolve("${modernLibrary.nameWithoutExtension}.il").apply {
            writeText(
                modernIl.lineSequence()
                    .filterNot { line -> "System.Diagnostics.CodeAnalysis" in line }
                    .joinToString("\n")
            )
        }
        val strippedLibrary = strippedDirectory.resolve(modernLibrary.name)
        val strippedResources = buildMap {
            put(DotNetKotlinMetadataResource.MANAGED_RESOURCE_NAME, modernLibrary.readKlibCarrier())
            DotNetManagedResourceReader.read(
                modernLibrary,
                DotNetCSharpImplementationManifestCodec.MANAGED_RESOURCE_NAME,
            )?.let { resource ->
                put(DotNetCSharpImplementationManifestCodec.MANAGED_RESOURCE_NAME, resource.content)
            }
        }
        assertTrue(
            DotNetIlAssembler.assembleLibrary(
                strippedIl,
                strippedLibrary,
                DotNetTarget.NET10_0,
                MessageCollector.NONE,
                strippedResources,
            )
        ) { "Could not reassemble the library after stripping derived CodeAnalysis attributes" }

        val kotlinConsumerDirectory = modernDirectory.resolve("kotlin-consumer").apply { mkdirs() }
        val kotlinConsumerSource = kotlinConsumerDirectory.resolve("consumer.kt").apply {
            writeText(
                """
                package contractconsumer

                import contractexports.requireText

                fun main() {
                    val value: String? = "OK"
                    requireText(value)
                    if (value.length != 2) throw Error("KLIB contract was not retained")
                }
                """.trimIndent()
            )
        }
        val kotlinConsumer = kotlinConsumerDirectory.resolve("ContractKotlinConsumer.dll")
        compileInProcess(
            K2DotNetCompiler(),
            kotlinConsumerSource.path,
            K2DotNetCompilerArguments::classpath.cliArgument, strippedLibrary.path,
            K2DotNetCompilerArguments::dotNetTarget.cliArgument, "net10.0",
            K2DotNetCompilerArguments::moduleName.cliArgument, "ContractKotlinConsumer",
            K2DotNetCompilerArguments::destination.cliArgument, kotlinConsumer.path,
        )
        runDotNet(
            modernCSharp.dotNetHost,
            kotlinConsumer,
            kotlinConsumerDirectory,
            "KLIB contract consumer failed",
        )

        val runtimeBootstrap = modernDirectory.resolve("runtime-bootstrap.kt").apply {
            writeText("fun main() {}")
        }
        compileInProcess(
            K2DotNetCompiler(),
            runtimeBootstrap.path,
            K2DotNetCompilerArguments::dotNetTarget.cliArgument, "net10.0",
            K2DotNetCompilerArguments::moduleName.cliArgument, "ContractRuntimeBootstrap",
            K2DotNetCompilerArguments::destination.cliArgument,
            modernDirectory.resolve("ContractRuntimeBootstrap.dll").path,
        )
        val runtimeAssembly = modernDirectory.resolve("Kotlin.Runtime.dll")
        val stdlibAssembly = modernDirectory.resolve("Kotlin.Stdlib.dll")
        assertTrue(runtimeAssembly.isFile)
        assertTrue(stdlibAssembly.isFile)

        val csharpSource = modernDirectory.resolve("consumer.cs").apply {
            writeText(
                """
                #nullable enable

                using System;
                using System.Collections.Generic;
                using System.Linq;
                using System.Reflection;
                using Facade = contractexports.contractsKt;

                public static class Program
                {
                    private const string CodeAnalysisNamespace = "System.Diagnostics.CodeAnalysis";

                    private static CustomAttributeData Attribute(
                        IEnumerable<CustomAttributeData> attributes,
                        string name)
                    {
                        return attributes.Single(attribute =>
                            attribute.AttributeType.FullName == CodeAnalysisNamespace + "." + name);
                    }

                    private static bool HasCodeAnalysisAttribute(IEnumerable<CustomAttributeData> attributes)
                    {
                        return attributes.Any(attribute =>
                            attribute.AttributeType.Namespace == CodeAnalysisNamespace);
                    }

                    private static MethodInfo Method(string name, int parameterCount)
                    {
                        return typeof(Facade).GetMethods(BindingFlags.Public | BindingFlags.Static)
                            .Single(method => method.Name == name &&
                                method.GetParameters().Length == parameterCount);
                    }

                    private static int AfterRequire(string? value)
                    {
                        Facade.RequireText(value);
                        return value.Length;
                    }

                    private static int AfterTrue(string? value)
                    {
                        return Facade.IsText(value) ? value.Length : 0;
                    }

                    private static int AfterFalse(string? value)
                    {
                        return !Facade.IsNull(value) ? value.Length : 0;
                    }

                    private static int AfterCopy(string? value)
                    {
                        if (value == null) return 0;
                        string? result = Facade.CopyText(value);
                        return result.Length;
                    }

                    private static int AfterGuard(string? value)
                    {
                        Facade.RequireTrue(value != null);
                        return value.Length;
                    }

                    private static int AfterKnown(string? value)
                    {
                        Facade.IsKnown(value);
                        return value.Length;
                    }

                    private static int AfterFail(string? value)
                    {
                        if (value == null) Facade.Fail();
                        return value.Length;
                    }

                    public static int Main()
                    {
                        MethodInfo requireText = Method("RequireText", 1);
                        Attribute(requireText.GetParameters()[0].GetCustomAttributesData(), "NotNullAttribute");

                        CustomAttributeData whenTrue = Attribute(
                            Method("IsText", 1).GetParameters()[0].GetCustomAttributesData(),
                            "NotNullWhenAttribute");
                        if (!(bool)whenTrue.ConstructorArguments.Single().Value!) return 1;

                        CustomAttributeData whenFalse = Attribute(
                            Method("IsNull", 1).GetParameters()[0].GetCustomAttributesData(),
                            "NotNullWhenAttribute");
                        if ((bool)whenFalse.ConstructorArguments.Single().Value!) return 2;

                        CustomAttributeData ifNotNull = Attribute(
                            Method("CopyText", 1).ReturnParameter.GetCustomAttributesData(),
                            "NotNullIfNotNullAttribute");
                        if ((string)ifNotNull.ConstructorArguments.Single().Value! != "value") return 3;
                        Attribute(
                            Method("CopyDefaulted", 1).ReturnParameter.GetCustomAttributesData(),
                            "NotNullIfNotNullAttribute");
                        if (HasCodeAnalysisAttribute(Method("CopyDefaulted", 0).GetCustomAttributesData()) ||
                            HasCodeAnalysisAttribute(
                                Method("CopyDefaulted", 0).ReturnParameter.GetCustomAttributesData()))
                            return 4;
                        MethodInfo isKnown = Method("IsKnown", 1);
                        Attribute(isKnown.GetParameters()[0].GetCustomAttributesData(), "NotNullAttribute");
                        if (isKnown.GetParameters()[0].GetCustomAttributesData().Any(attribute =>
                                attribute.AttributeType.FullName ==
                                    CodeAnalysisNamespace + ".NotNullWhenAttribute"))
                            return 5;

                        CustomAttributeData doesNotReturnIf = Attribute(
                            Method("RequireTrue", 1).GetParameters()[0].GetCustomAttributesData(),
                            "DoesNotReturnIfAttribute");
                        if ((bool)doesNotReturnIf.ConstructorArguments.Single().Value!) return 6;

                        Attribute(Method("Fail", 0).GetCustomAttributesData(), "DoesNotReturnAttribute");
                        Attribute(
                            Method("Defaulted", 1).GetParameters()[0].GetCustomAttributesData(),
                            "NotNullAttribute");
                        if (HasCodeAnalysisAttribute(Method("Defaulted", 0).GetCustomAttributesData()) ||
                            HasCodeAnalysisAttribute(Method("Defaulted", 0).ReturnParameter.GetCustomAttributesData()))
                            return 7;
                        if (HasCodeAnalysisAttribute(Method("RequireBoth", 2).GetCustomAttributesData()) ||
                            Method("RequireBoth", 2).GetParameters().Any(parameter =>
                                HasCodeAnalysisAttribute(parameter.GetCustomAttributesData())))
                            return 8;
                        Attribute(
                            Method("RequireAlias", 1).GetParameters()[0].GetCustomAttributesData(),
                            "NotNullAttribute");
                        if (HasCodeAnalysisAttribute(
                                Method("RequireNullableIntAlias", 1).GetParameters()[0].GetCustomAttributesData()))
                            return 9;

                        MethodInfo implementation = Method("requireText", 1);
                        if (HasCodeAnalysisAttribute(implementation.GetCustomAttributesData()) ||
                            HasCodeAnalysisAttribute(implementation.GetParameters()[0].GetCustomAttributesData()))
                            return 10;

                        if (AfterRequire("one") != 3 || AfterTrue("two") != 3 ||
                            AfterFalse("three") != 5 || AfterCopy("four") != 4 ||
                            AfterGuard("five") != 4 || AfterKnown("known") != 5 ||
                            AfterFail("six") != 3)
                            return 11;
                        return 0;
                    }
                }
                """.trimIndent()
            )
        }
        val csharpConsumer = modernDirectory.resolve("ContractCSharpConsumer.dll")
        val csharpCompile = runModernCSharpCompiler(
            modernCSharp,
            csharpSource,
            csharpConsumer,
            modernLibrary,
            runtimeAssembly,
            stdlibAssembly,
            target = "exe",
            additionalArguments = listOf("/nullable:enable", "/warnaserror+"),
        )
        assertEquals(0, csharpCompile.exitCode, csharpCompile.output)
        modernDirectory.resolve("ContractCSharpConsumer.runtimeconfig.json").writeText(net10RuntimeConfig())
        runDotNet(
            modernCSharp.dotNetHost,
            csharpConsumer,
            modernDirectory,
            "Roslyn exact-contract export consumer failed",
        )
    }

    @Test
    fun testAnnotationsAcrossPortableLibraryAndCSharpBoundaries() {
        requireOrAssumeToolchain(
            DotNetIlAssembler.findFrameworkIlasm() != null,
            ".NET Framework ILAsm is not available",
        )
        requireOrAssumeToolchain(
            DotNetIlAssembler.findModernIlasm() != null,
            "Modern ILAsm is not available",
        )
        val frameworkHost = DotNetIlAssembler.findFrameworkPowerShellHost()
        requireOrAssumeToolchain(frameworkHost != null, "Windows PowerShell CLR 4 host is not available")
        val csharpCompiler = DotNetIlAssembler.findFrameworkCSharpCompiler()
        requireOrAssumeToolchain(csharpCompiler != null, ".NET Framework C# compiler is not available")
        val frameworkNetStandardFacade = findFrameworkNetStandardFacade()
        requireOrAssumeToolchain(
            frameworkNetStandardFacade != null,
            ".NET Framework netstandard facade is not available",
        )
        val dotnetHost = modernDotNetHostOrSkip()

        val libraryDirectory = File(tmpdir, "marker-annotation-library").apply { mkdirs() }
        val librarySource = libraryDirectory.resolve("markerAnnotationLibrary.kt").apply {
            writeText(
                """
                package markerabi

                @Target(
                    AnnotationTarget.CLASS,
                    AnnotationTarget.CONSTRUCTOR,
                    AnnotationTarget.FUNCTION,
                    AnnotationTarget.PROPERTY,
                    AnnotationTarget.FIELD,
                    AnnotationTarget.VALUE_PARAMETER,
                    AnnotationTarget.PROPERTY_GETTER,
                    AnnotationTarget.PROPERTY_SETTER,
                )
                @Retention(AnnotationRetention.RUNTIME)
                @Repeatable
                public annotation class RuntimeMarker

                @Retention(AnnotationRetention.BINARY)
                public annotation class BinaryMarker

                @Retention(AnnotationRetention.SOURCE)
                public annotation class SourceMarker

                @Retention(AnnotationRetention.RUNTIME)
                public annotation class RuntimeValues(
                    val number: Int,
                    val text: String,
                    val names: Array<String> = ["default"],
                )

                @Retention(AnnotationRetention.RUNTIME)
                public annotation class KotlinOnlyValues(val klass: kotlin.reflect.KClass<*>)

                @RuntimeMarker
                @RuntimeValues(7, "kotlin")
                @KotlinOnlyValues(String::class)
                @BinaryMarker
                @SourceMarker
                public class KotlinApplied @RuntimeMarker constructor(public var value: Int) {
                    @RuntimeMarker
                    public fun update(@RuntimeMarker next: Int) {
                        value = next
                    }
                }
                """.trimIndent()
            )
        }
        compileInProcess(
            K2DotNetCompiler(),
            librarySource.path,
            K2DotNetCompilerArguments::dotNetProduceLibrary.cliArgument,
            K2DotNetCompilerArguments::dotNetTarget.cliArgument, "netstandard2.0",
            K2DotNetCompilerArguments::moduleName.cliArgument, "Marker.Annotation.Library",
            K2DotNetCompilerArguments::destination.cliArgument, libraryDirectory.path,
        )

        val metadataLibrary = libraryDirectory.resolve("Marker.Annotation.Library.dll")
        assertTrue(metadataLibrary.isFile)
        val libraryIl = libraryDirectory.resolve("Marker.Annotation.Library.il").readText()
        assertTrue(
            ".class public auto ansi sealed beforefieldinit 'markerabi.RuntimeMarker'" in libraryIl &&
                    "extends [netstandard]System.Attribute" in libraryIl
        ) { libraryIl }
        assertTrue(
            ".custom instance void [netstandard]System.AttributeUsageAttribute::.ctor(" +
                    "valuetype [netstandard]System.AttributeTargets)" in libraryIl
        ) { libraryIl }
        assertTrue(".custom instance void 'markerabi.RuntimeMarker'::.ctor()" in libraryIl) { libraryIl }
        assertTrue(
            ".custom instance void 'markerabi.RuntimeValues'::.ctor(int32, string, string[]) = " in libraryIl
        ) { libraryIl }
        assertFalse(".custom instance void 'markerabi.KotlinOnlyValues'::.ctor(" in libraryIl) { libraryIl }
        assertFalse(".custom instance void 'markerabi.BinaryMarker'::.ctor()" in libraryIl) { libraryIl }
        assertFalse(".custom instance void 'markerabi.SourceMarker'::.ctor()" in libraryIl) { libraryIl }

        val csharpSource = libraryDirectory.resolve("MarkerAnnotationConsumer.cs").apply {
            writeText(
                """
                using System;
                using System.Reflection;

                [markerabi.RuntimeMarker, markerabi.RuntimeMarker]
                [markerabi.RuntimeValues(9, "csharp", new string[] { "x", "y" })]
                public sealed class CSharpApplied
                {
                    [markerabi.RuntimeMarker]
                    public int Value;

                    [markerabi.RuntimeMarker]
                    public void Update([markerabi.RuntimeMarker] int next)
                    {
                        Value = next;
                    }
                }

                public static class MarkerAnnotationConsumer
                {
                    private static int Count(MemberInfo member)
                    {
                        return member.GetCustomAttributes(typeof(markerabi.RuntimeMarker), false).Length;
                    }

                    private static markerabi.RuntimeValues Values(Type type)
                    {
                        return (markerabi.RuntimeValues) Attribute.GetCustomAttribute(
                            type, typeof(markerabi.RuntimeValues));
                    }

                    public static int Main()
                    {
                        Type marker = typeof(markerabi.RuntimeMarker);
                        if (marker.BaseType != typeof(Attribute)) return 1;
                        AttributeUsageAttribute usage = (AttributeUsageAttribute)
                            Attribute.GetCustomAttribute(marker, typeof(AttributeUsageAttribute));
                        if (usage == null || !usage.AllowMultiple || usage.Inherited) return 2;
                        if ((usage.ValidOn & AttributeTargets.Class) == 0 ||
                            (usage.ValidOn & AttributeTargets.Method) == 0 ||
                            (usage.ValidOn & AttributeTargets.Field) == 0 ||
                            (usage.ValidOn & AttributeTargets.Parameter) == 0) return 3;
                        if (Count(typeof(markerabi.KotlinApplied)) != 1) return 4;
                        if (Count(typeof(CSharpApplied)) != 2) return 5;
                        if (Count(typeof(CSharpApplied).GetField("Value")) != 1) return 6;
                        MethodInfo update = typeof(CSharpApplied).GetMethod("Update");
                        if (Count(update) != 1) return 7;
                        if (update.GetParameters()[0].GetCustomAttributes(
                                typeof(markerabi.RuntimeMarker), false).Length != 1) return 8;
                        markerabi.RuntimeValues kotlinValues = Values(typeof(markerabi.KotlinApplied));
                        if (kotlinValues == null || kotlinValues.number != 7 ||
                            kotlinValues.text != "kotlin" || kotlinValues.names.Length != 1 ||
                            kotlinValues.names[0] != "default") return 9;
                        markerabi.RuntimeValues csharpValues = Values(typeof(CSharpApplied));
                        if (csharpValues == null || csharpValues.number != 9 ||
                            csharpValues.text != "csharp" || csharpValues.names.Length != 2 ||
                            csharpValues.names[0] != "x" || csharpValues.names[1] != "y") return 10;
                        if (Attribute.GetCustomAttribute(
                                typeof(markerabi.KotlinApplied),
                                typeof(markerabi.KotlinOnlyValues)) != null) return 11;
                        return 0;
                    }
                }
                """.trimIndent()
            )
        }
        val csharpConsumer = libraryDirectory.resolve("MarkerAnnotationConsumer.exe")
        val csharpCompile = runCSharpCompiler(
            checkNotNull(csharpCompiler),
            csharpSource,
            csharpConsumer,
            metadataLibrary,
            checkNotNull(frameworkNetStandardFacade),
            target = "exe",
        )
        assertEquals(0, csharpCompile.exitCode, csharpCompile.output)

        for (target in listOf("net48", "net10.0")) {
            val consumerDirectory = libraryDirectory.resolve("consumer-${target.replace('.', '-')}").apply { mkdirs() }
            val consumerSource = consumerDirectory.resolve("consumer.kt").apply {
                writeText(
                    """
                    package markerconsumer

                    import markerabi.KotlinOnlyValues
                    import markerabi.RuntimeMarker
                    import markerabi.RuntimeValues

                    @RuntimeMarker
                    @RuntimeValues(11, "downstream", ["d"])
                    @KotlinOnlyValues(String::class)
                    class DownstreamApplied

                    fun main() {
                        val first: Annotation = RuntimeMarker()
                        val second = RuntimeMarker()
                        if (first !is RuntimeMarker || first != second || first.hashCode() != 0 ||
                            first.toString() != "@markerabi.RuntimeMarker()"
                        ) {
                            throw Error("external marker value semantics")
                        }
                        val defaultValues = RuntimeValues(1, "external")
                        val explicitValues = RuntimeValues(1, "external", arrayOf("default"))
                        if (defaultValues != explicitValues ||
                            defaultValues.hashCode() != explicitValues.hashCode()
                        ) {
                            throw Error("external valued annotation semantics")
                        }
                        val kotlinOnly = KotlinOnlyValues(String::class)
                        if (kotlinOnly.klass != String::class) {
                            throw Error("KLIB-only annotation construction")
                        }
                    }
                    """.trimIndent()
                )
            }
            val application = consumerDirectory.resolve(
                if (target == "net48") "MarkerKotlinConsumer.exe" else "MarkerKotlinConsumer.dll"
            )
            compileInProcess(
                K2DotNetCompiler(),
                consumerSource.path,
                K2DotNetCompilerArguments::classpath.cliArgument, metadataLibrary.path,
                K2DotNetCompilerArguments::dotNetTarget.cliArgument, target,
                K2DotNetCompilerArguments::moduleName.cliArgument, "MarkerKotlinConsumer",
                K2DotNetCompilerArguments::destination.cliArgument, application.path,
            )
            val consumerIl = consumerDirectory.resolve("MarkerKotlinConsumer.il").readText()
            assertTrue(
                ".custom instance void [Marker.Annotation.Library]'markerabi.RuntimeMarker'::.ctor()" in consumerIl
            ) { consumerIl }
            assertTrue(
                ".custom instance void [Marker.Annotation.Library]'markerabi.RuntimeValues'::.ctor(" in consumerIl
            ) { consumerIl }
            assertFalse(
                ".custom instance void [Marker.Annotation.Library]'markerabi.KotlinOnlyValues'::.ctor(" in consumerIl
            ) { consumerIl }
            if (target == "net10.0") {
                runDotNet(dotnetHost, application, consumerDirectory, "Kotlin marker consumer failed for $target")
            } else {
                val kotlinProcess = ProcessBuilder(frameworkExecutionCommand(checkNotNull(frameworkHost), application))
                    .directory(consumerDirectory)
                    .redirectErrorStream(true)
                    .start()
                val kotlinOutput = kotlinProcess.inputStream.bufferedReader().use { it.readText() }
                assertEquals(0, kotlinProcess.waitFor(), "Kotlin marker consumer failed for $target:\n$kotlinOutput")

                consumerDirectory.resolve("Kotlin.Runtime.dll")
                    .copyTo(libraryDirectory.resolve("Kotlin.Runtime.dll"), overwrite = true)
                val csharpProcess = ProcessBuilder(
                    frameworkExecutionCommand(checkNotNull(frameworkHost), csharpConsumer)
                )
                    .directory(libraryDirectory)
                    .redirectErrorStream(true)
                    .start()
                val csharpOutput = csharpProcess.inputStream.bufferedReader().use { it.readText() }
                assertEquals(0, csharpProcess.waitFor(), "C# marker consumer failed on net48:\n$csharpOutput")
            }
            if (target == "net10.0") {
                val modernCSharpConsumer = consumerDirectory.resolve(csharpConsumer.name)
                csharpConsumer.copyTo(modernCSharpConsumer, overwrite = true)
                consumerDirectory.resolve("MarkerKotlinConsumer.runtimeconfig.json")
                    .copyTo(
                        consumerDirectory.resolve("MarkerAnnotationConsumer.runtimeconfig.json"),
                        overwrite = true,
                    )
                runDotNet(dotnetHost, modernCSharpConsumer, consumerDirectory, "C# marker consumer failed on $target")
            }
        }
    }

    @Test
    fun testValueClassPublishesOneNominalOwnerAndCompilerAbi() {
        requireOrAssumeToolchain(
            DotNetIlAssembler.findModernIlasm() != null,
            "Modern ILAsm is not available",
        )
        val libraryDirectory = File(tmpdir, "value-class-abi-library").apply { mkdirs() }
        val librarySource = libraryDirectory.resolve("valueClassLibrary.kt").apply {
            writeText(
                """
                package valueclassabi

                public value class Token(public val value: String)
                public value class GenericToken<T : Any>(public val value: T)

                public fun makeToken(value: String): Token = Token(value)
                public fun eraseToken(token: Token): Any = token
                public fun readToken(value: Any): String = (value as Token).value
                public fun makeGenericToken(value: String): GenericToken<String> = GenericToken(value)
                """.trimIndent()
            )
        }
        compileInProcess(
            K2DotNetCompiler(),
            librarySource.path,
            K2DotNetCompilerArguments::dotNetProduceLibrary.cliArgument,
            K2DotNetCompilerArguments::dotNetTarget.cliArgument, "netstandard2.0",
            K2DotNetCompilerArguments::moduleName.cliArgument, "ValueClass.Abi.Library",
            K2DotNetCompilerArguments::destination.cliArgument, libraryDirectory.path,
        )

        val assembly = libraryDirectory.resolve("ValueClass.Abi.Library.dll")
        val libraryIl = libraryDirectory.resolve("ValueClass.Abi.Library.il").readText()
        val tokenOwnerPattern = Regex("""(?m)^\s*\.class[^\r\n]*'valueclassabi\.Token'\s*$""")
        assertEquals(1, tokenOwnerPattern.findAll(libraryIl).count(), libraryIl)
        assertFalse("valueclassabi.Token`" in libraryIl) { libraryIl }
        val genericTokenOwnerPattern = Regex("""(?m)^\s*\.class[^\r\n]*'valueclassabi\.GenericToken'\s*$""")
        assertEquals(1, genericTokenOwnerPattern.findAll(libraryIl).count(), libraryIl)
        assertFalse("valueclassabi.GenericToken`" in libraryIl) { libraryIl }

        val declarations = DotNetLibraryAbiCodec.decode(assembly.readKlibManifest())
        fun assertCompilerAbi(className: String) {
            val tokenDeclaration = declarations.values
                .filterIsInstance<DotNetPhysicalDeclaration.Class>()
                .single { declaration -> declaration.ownerPath.last() == className }
            val valueClassAbi = checkNotNull(tokenDeclaration.valueClassAbi) {
                "The nominal value-class owner '$className' has no producer-published compiler ABI"
            }
            val helperNames = setOf(
                valueClassAbi.primaryConstructorMethodName,
                valueClassAbi.boxMethodName,
                valueClassAbi.unboxMethodName,
            )
            assertEquals(3, helperNames.size)
            helperNames.forEach { methodName ->
                assertTrue("'$methodName'" in libraryIl) {
                    "Value-class compiler helper '$methodName' is absent from the producer IL:\n$libraryIl"
                }
            }
            val logicalTokenMethods = declarations.values
                .filterIsInstance<DotNetPhysicalDeclaration.Function>()
                .filter { declaration -> declaration.ownerPath.last() == className }
            assertTrue(logicalTokenMethods.none { declaration -> declaration.methodName in helperNames }) {
                "Compiler-only value-class helpers escaped into the logical function index: $logicalTokenMethods"
            }
        }
        assertCompilerAbi("valueclassabi.Token")
        assertCompilerAbi("valueclassabi.GenericToken")
    }

    @Test
    fun testGenericClassErasedIdentityAcrossPortableLibraryBoundary() {
        requireOrAssumeToolchain(
            DotNetIlAssembler.findFrameworkIlasm() != null,
            ".NET Framework ILAsm is not available",
        )
        requireOrAssumeToolchain(
            DotNetIlAssembler.findModernIlasm() != null,
            "Modern ILAsm is not available",
        )
        val frameworkHost = DotNetIlAssembler.findFrameworkPowerShellHost()
        requireOrAssumeToolchain(frameworkHost != null, "Windows PowerShell CLR 4 host is not available")
        val csharpCompiler = DotNetIlAssembler.findFrameworkCSharpCompiler()
        requireOrAssumeToolchain(csharpCompiler != null, ".NET Framework C# compiler is not available")
        val frameworkNetStandardFacade = findFrameworkNetStandardFacade()
        requireOrAssumeToolchain(
            frameworkNetStandardFacade != null,
            ".NET Framework netstandard facade is not available",
        )
        val dotnetHost = modernDotNetHostOrSkip()
        val libraryDirectory = File(tmpdir, "generic-class-erased-library").apply { mkdirs() }
        val librarySource = libraryDirectory.resolve("genericClassLibrary.kt").apply {
            writeText(
                """
                package genericclassabi

                public open class Box<T>(private var value: T) {
                    public open fun read(): T = value

                    public open fun write(next: T) {
                        value = next
                    }
                }

                public fun makeBox(value: String): Box<String> = Box(value)
                public fun isBox(value: Any?): Boolean = value is Box<*>
                public fun checkedBox(value: Any?): Box<*> = value as Box<*>
                public fun safeBox(value: Any?): Box<*>? = value as? Box<*>
                public fun readStar(value: Box<*>): Any? = value.read()
                public fun readString(value: Box<String>): String = value.read()
                public fun writeString(value: Box<String>, next: String) = value.write(next)
                public fun choose(value: Box<Int>): String = "int:${'$'}{value.read()}"
                public fun choose(value: Box<String>): String = "string:${'$'}{value.read()}"

                public class OverloadOwner {
                    public fun choose(value: Box<Int>): String = "int:${'$'}{value.read()}"
                    public fun choose(value: Box<String>): String = "string:${'$'}{value.read()}"
                }

                public class Holder {
                    public class Nested<T>(private val value: T) {
                        public fun read(): T = value
                    }
                }

                public fun makeNested(): Holder.Nested<String> = Holder.Nested("nested")
                public fun isNested(value: Any?): Boolean = value is Holder.Nested<*>
                """.trimIndent()
            )
        }
        compileInProcess(
            K2DotNetCompiler(),
            librarySource.path,
            K2DotNetCompilerArguments::dotNetProduceLibrary.cliArgument,
            K2DotNetCompilerArguments::dotNetTarget.cliArgument, "netstandard2.0",
            K2DotNetCompilerArguments::moduleName.cliArgument, "GenericClass.Library",
            K2DotNetCompilerArguments::destination.cliArgument, libraryDirectory.path,
        )

        val metadataLibrary = libraryDirectory.resolve("GenericClass.Library.dll")
        val libraryIl = libraryDirectory.resolve("GenericClass.Library.il").readText()
        val repeatedLibraryDirectory = File(tmpdir, "generic-class-erased-library-repeat").apply { mkdirs() }
        val repeatedLibrarySource = repeatedLibraryDirectory.resolve(librarySource.name).apply {
            writeText(librarySource.readText())
        }
        compileInProcess(
            K2DotNetCompiler(),
            repeatedLibrarySource.path,
            K2DotNetCompilerArguments::dotNetProduceLibrary.cliArgument,
            K2DotNetCompilerArguments::dotNetTarget.cliArgument, "netstandard2.0",
            K2DotNetCompilerArguments::moduleName.cliArgument, "GenericClass.Library",
            K2DotNetCompilerArguments::destination.cliArgument, repeatedLibraryDirectory.path,
        )
        assertEquals(
            libraryIl,
            repeatedLibraryDirectory.resolve("GenericClass.Library.il").readText(),
            "The erased generic-class ABI must be reproducible across independent IR symbols",
        )
        assertTrue(".class public auto ansi beforefieldinit 'genericclassabi.Box'" in libraryIl) { libraryIl }
        assertTrue(".field private object 'value'" in libraryIl) { libraryIl }
        assertTrue("instance void .ctor(object 'value')" in libraryIl) { libraryIl }
        assertTrue("instance object 'read'()" in libraryIl) { libraryIl }
        assertTrue("instance void 'write'(object 'next')" in libraryIl) { libraryIl }
        assertFalse("genericclassabi.Box`1" in libraryIl) { libraryIl }
        assertFalse("GenericClassCanonicalBridge" in libraryIl) { libraryIl }

        val declarations = DotNetLibraryAbiCodec.decode(metadataLibrary.readKlibManifest())
        val boxClass = declarations.values.filterIsInstance<DotNetPhysicalDeclaration.Class>()
            .single { declaration -> declaration.ownerPath.last() == "genericclassabi.Box" }
        val boxFunctions = declarations.values
            .filterIsInstance<DotNetPhysicalDeclaration.Function>()
            .filter { declaration -> declaration.ownerPath.last() == "genericclassabi.Box" }
        assertEquals(setOf("read", "write"), boxFunctions.map { function -> function.methodName }.toSet())
        val facadeFunctions = declarations.values
            .filterIsInstance<DotNetPhysicalDeclaration.Function>()
            .filter { declaration -> declaration.ownerPath.last() == "genericclassabi.genericClassLibraryKt" }
        val readStarFunction = facadeFunctions.single { function ->
            function.methodName.startsWith("readStar__KotlinErased__")
        }
        val readStringFunction = facadeFunctions.single { function ->
            function.methodName.startsWith("readString__KotlinErased__")
        }
        val writeStringFunction = facadeFunctions.single { function ->
            function.methodName.startsWith("writeString__KotlinErased__")
        }
        val erasedOverloads = declarations.values
            .filterIsInstance<DotNetPhysicalDeclaration.Function>()
            .filter { declaration -> declaration.methodName.startsWith("choose__KotlinErased__") }
        assertEquals(4, erasedOverloads.size)
        assertEquals(4, erasedOverloads.map { declaration ->
            declaration.ownerPath to declaration.methodName
        }.toSet().size)

        val csharpSource = libraryDirectory.resolve("GenericClassConsumer.cs").apply {
            writeText(
                """
                using System;

                public sealed class CSharpBox : genericclassabi.Box
                {
                    public CSharpBox(string value) : base(value) {}

                    public override object read()
                    {
                        return (string)base.read() + "!";
                    }

                    public override void write(object value)
                    {
                        base.write((string)value + "?");
                    }
                }

                public static class GenericClassConsumer
                {
                    public static int Main()
                    {
                        CSharpBox typed = new CSharpBox("csharp");
                        if (!genericclassabi.genericClassLibraryKt.isBox(typed)) return 1;
                        if (genericclassabi.genericClassLibraryKt.${readStarFunction.methodName}(typed).ToString() != "csharp!") return 2;
                        genericclassabi.genericClassLibraryKt.${writeStringFunction.methodName}(typed, "changed");
                        if (genericclassabi.genericClassLibraryKt.${readStringFunction.methodName}(typed) != "changed?!") return 3;
                        if (!Object.ReferenceEquals(typed,
                            genericclassabi.genericClassLibraryKt.checkedBox(typed))) return 4;
                        return 0;
                    }
                }
                """.trimIndent()
            )
        }
        val csharpConsumer = libraryDirectory.resolve("GenericClassConsumer.exe")
        val csharpCompile = runCSharpCompiler(
            checkNotNull(csharpCompiler),
            csharpSource,
            csharpConsumer,
            metadataLibrary,
            checkNotNull(frameworkNetStandardFacade),
            target = "exe",
        )
        assertEquals(0, csharpCompile.exitCode, csharpCompile.output)
        val accidentalTypedSource = libraryDirectory.resolve("AccidentalTypedGenericConsumer.cs").apply {
            writeText(
                """
                public sealed class AccidentalTypedGenericConsumer
                {
                    private genericclassabi.Box<string> value;
                }
                """.trimIndent()
            )
        }
        val accidentalTypedCompile = runCSharpCompiler(
            checkNotNull(csharpCompiler),
            accidentalTypedSource,
            libraryDirectory.resolve("AccidentalTypedGenericConsumer.dll"),
            metadataLibrary,
            checkNotNull(frameworkNetStandardFacade),
            target = "library",
        )
        assertNotEquals(0, accidentalTypedCompile.exitCode) {
            "Kotlin-owned generic classes must not silently publish a CLR C<T> ABI"
        }

        for (target in listOf("net48", "net10.0")) {
            val consumerDirectory = libraryDirectory.resolve("consumer-${target.replace('.', '-')}").apply { mkdirs() }
            val consumerSource = consumerDirectory.resolve("consumer.kt").apply {
                writeText(
                    """
                    package genericclassconsumer

                    import genericclassabi.*

                    class LocalBox(value: String) : Box<String>(value) {
                        override fun read(): String = super.read() + "!"

                        override fun write(next: String) {
                            super.write(next + "?")
                        }
                    }

                    class LocalCarrier<T>(private val value: T) {
                        fun wrap(): Box<T> = Box(value)

                        fun read(box: Box<T>): T = box.read()
                    }

                    fun main() {
                        val library = makeBox("library")
                        if (!isBox(library) || library !is Box<*> || readStar(library) != "library") {
                            throw Error("library erased identity")
                        }
                        if (checkedBox(library) !== library || safeBox(library) !== library) {
                            throw Error("library cast identity")
                        }
                        val local = LocalBox("local")
                        val localAny: Any = local
                        if (localAny !is Box<*> || checkedBox(localAny) !== local) {
                            throw Error("external generic base ancestry")
                        }
                        writeString(local, "changed")
                        if (readString(local) != "changed?!") throw Error("external erased super dispatch")
                        val carrier = LocalCarrier("nested")
                        val nested = carrier.wrap()
                        if (carrier.read(nested) != "nested" || nested !is Box<*>) {
                            throw Error("external generic class in erased member signature")
                        }
                        if (choose(Box(35)) != "int:35" || choose(Box("thirty-six")) != "string:thirty-six") {
                            throw Error("external erased top-level overload")
                        }
                        val overloadOwner = OverloadOwner()
                        if (overloadOwner.choose(Box(37)) != "int:37" ||
                            overloadOwner.choose(Box("thirty-eight")) != "string:thirty-eight"
                        ) {
                            throw Error("external erased member overload")
                        }
                        val holderNested = makeNested()
                        val nestedAny: Any = holderNested
                        if (!isNested(nestedAny) || nestedAny !is Holder.Nested<*>) {
                            throw Error("external nested generic erased identity")
                        }
                        val nestedProjected = nestedAny as Holder.Nested<*>
                        if (nestedProjected !== holderNested || nestedProjected.read() != "nested") {
                            throw Error("external nested generic cast identity and members")
                        }
                        if (safeBox("wrong") != null || isBox("wrong")) throw Error("unrelated admission")
                        @Suppress("UNCHECKED_CAST")
                        val wrong = library as Any as Box<Int>
                        try {
                            val value: Int = wrong.read()
                            value + 1
                            throw Error("logical type barrier")
                        } catch (_: ClassCastException) {
                        }
                        wrong.write(40)
                        try {
                            readString(library)
                            throw Error("unchecked mutation must fail only at the later incompatible use")
                        } catch (_: ClassCastException) {
                        }
                    }
                    """.trimIndent()
                )
            }
            val application = consumerDirectory.resolve(
                if (target == "net48") "GenericClassKotlinConsumer.exe" else "GenericClassKotlinConsumer.dll"
            )
            compileInProcess(
                K2DotNetCompiler(),
                consumerSource.path,
                K2DotNetCompilerArguments::classpath.cliArgument, metadataLibrary.path,
                K2DotNetCompilerArguments::dotNetTarget.cliArgument, target,
                K2DotNetCompilerArguments::moduleName.cliArgument, "GenericClassKotlinConsumer",
                K2DotNetCompilerArguments::destination.cliArgument, application.path,
            )
            if (target == "net10.0") {
                runDotNet(dotnetHost, application, consumerDirectory, "Generic-class Kotlin consumer failed for $target")
            } else {
                val process = ProcessBuilder(frameworkExecutionCommand(checkNotNull(frameworkHost), application))
                    .directory(consumerDirectory)
                    .redirectErrorStream(true)
                    .start()
                val output = process.inputStream.bufferedReader().use { it.readText() }
                assertEquals(0, process.waitFor(), "Generic-class Kotlin consumer failed for $target:\n$output")
                consumerDirectory.resolve("Kotlin.Runtime.dll")
                    .copyTo(libraryDirectory.resolve("Kotlin.Runtime.dll"), overwrite = true)
                val csharpProcess = ProcessBuilder(frameworkExecutionCommand(checkNotNull(frameworkHost), csharpConsumer))
                    .directory(libraryDirectory)
                    .redirectErrorStream(true)
                    .start()
                val csharpOutput = csharpProcess.inputStream.bufferedReader().use { it.readText() }
                assertEquals(0, csharpProcess.waitFor(), "Generic-class C# consumer failed on net48:\n$csharpOutput")
            }
            if (target == "net10.0") {
                val modernCSharpConsumer = consumerDirectory.resolve(csharpConsumer.name)
                csharpConsumer.copyTo(modernCSharpConsumer, overwrite = true)
                consumerDirectory.resolve("GenericClassKotlinConsumer.runtimeconfig.json")
                    .copyTo(
                        consumerDirectory.resolve("GenericClassConsumer.runtimeconfig.json"),
                        overwrite = true,
                    )
                runDotNet(dotnetHost, modernCSharpConsumer, consumerDirectory, "Generic-class C# consumer failed on net10")
            }
        }
    }

    @Test
    fun testOrdinaryEnumsAcrossPortableLibraryBoundary() {
        requireOrAssumeToolchain(
            DotNetIlAssembler.findFrameworkIlasm() != null,
            ".NET Framework ILAsm is not available",
        )
        requireOrAssumeToolchain(
            DotNetIlAssembler.findModernIlasm() != null,
            "Modern ILAsm is not available",
        )
        val frameworkHost = DotNetIlAssembler.findFrameworkPowerShellHost()
        requireOrAssumeToolchain(frameworkHost != null, "Windows PowerShell CLR 4 host is not available")
        val csharpCompiler = DotNetIlAssembler.findFrameworkCSharpCompiler()
        requireOrAssumeToolchain(csharpCompiler != null, ".NET Framework C# compiler is not available")
        val frameworkNetStandardFacade = findFrameworkNetStandardFacade()
        requireOrAssumeToolchain(
            frameworkNetStandardFacade != null,
            ".NET Framework netstandard facade is not available",
        )
        val dotnetHost = modernDotNetHostOrSkip()
        val libraryDirectory = File(tmpdir, "ordinary-enum-library").apply { mkdirs() }
        val librarySource = libraryDirectory.resolve("ordinaryEnumLibrary.kt").apply {
            writeText(
                """
                package enumabi

                public annotation class EntryMarker

                public enum class State(public val code: Int) {
                    @EntryMarker
                    READY(1) {
                        override fun label(): String = "ready"
                    },
                    BUSY(2) {
                        override fun label(): String = "busy"
                    },
                    DONE(3) {
                        override fun label(): String = "done"
                    };

                    public abstract fun label(): String
                }

                public enum class OtherState { ONLY }

                public fun selected(): State = State.READY
                public fun selectedName(): String = State.READY.name
                public fun byName(name: String): State = State.valueOf(name)
                public fun allStates(): Array<State> = State.values()
                """.trimIndent()
            )
        }
        compileInProcess(
            K2DotNetCompiler(),
            librarySource.path,
            K2DotNetCompilerArguments::dotNetProduceLibrary.cliArgument,
            K2DotNetCompilerArguments::dotNetTarget.cliArgument, "netstandard2.0",
            K2DotNetCompilerArguments::moduleName.cliArgument, "Ordinary.Enum.Library",
            K2DotNetCompilerArguments::destination.cliArgument, libraryDirectory.path,
        )

        val library = libraryDirectory.resolve("Ordinary.Enum.Library.dll")
        val libraryIl = libraryDirectory.resolve("Ordinary.Enum.Library.il").readText()
        assertTrue(
            Regex(
                """\.class public[^\n]*'enumabi\.State'\s+extends \[Kotlin\.Runtime]'Kotlin\.Enum'"""
            ).containsMatchIn(libraryIl)
        ) { libraryIl }
        assertTrue(Regex("""\.class public abstract[^\n]*'enumabi\.State'""").containsMatchIn(libraryIl)) {
            libraryIl
        }
        assertTrue(
            "call void [Kotlin.Runtime]'Kotlin.Enum'/'<CompanionStatics>'::'<EnsureInitialized>'()" in libraryIl
        ) {
            "A Runtime-owned nested initialization helper must use an ECMA-335 nested TypeRef:\n$libraryIl"
        }
        assertFalse("[Kotlin.Runtime]'Kotlin.Enum/<CompanionStatics>'" in libraryIl) {
            "A slash inside one quoted TypeRef names a flat type that does not exist:\n$libraryIl"
        }
        for (entryName in listOf("READY", "BUSY", "DONE")) {
            assertTrue(".field public static initonly class 'enumabi.State' '$entryName'" in libraryIl) { libraryIl }
        }
        assertTrue(".custom instance void 'enumabi.EntryMarker'::.ctor()" in libraryIl) { libraryIl }
        assertFalse("System.Enum" in libraryIl) { libraryIl }
        assertFalse("value__" in libraryIl) { libraryIl }
        assertFalse(" static literal " in libraryIl) { libraryIl }

        val physicalDeclarations = DotNetLibraryAbiCodec.decode(library.readKlibManifest()).values
        val entryDeclarations = physicalDeclarations.filterIsInstance<DotNetPhysicalDeclaration.EnumEntry>()
        val stateEntries = entryDeclarations.filter { it.ownerPath.last() == "enumabi.State" }
        assertEquals(setOf("READY", "BUSY", "DONE"), stateEntries.map { it.fieldName }.toSet())
        assertEquals(
            setOf("ONLY"),
            entryDeclarations.filter { it.ownerPath.last() == "enumabi.OtherState" }.map { it.fieldName }.toSet(),
        )

        val csharpSource = libraryDirectory.resolve("OrdinaryEnumConsumer.cs").apply {
            writeText(
                """
                using System;
                using System.Reflection;

                public static class OrdinaryEnumConsumer
                {
                    public static int Main()
                    {
                        enumabi.State ready = enumabi.State.READY;
                        if (ready.name != "READY" || ready.ordinal != 0) return 1;
                        if (ready.code != 1 || ready.label() != "ready") return 2;
                        if (!Object.ReferenceEquals(ready, enumabi.State.valueOf("READY"))) return 3;
                        enumabi.State[] first = enumabi.State.values();
                        enumabi.State[] second = enumabi.State.values();
                        if (Object.ReferenceEquals(first, second) || first.Length != 3) return 4;
                        if (!Object.ReferenceEquals(first[2], enumabi.State.DONE)) return 5;
                        if (typeof(enumabi.State).IsEnum) return 6;
                        FieldInfo readyField = typeof(enumabi.State).GetField("READY");
                        if (readyField == null || !readyField.IsInitOnly || readyField.IsLiteral) return 7;
                        if (readyField.GetCustomAttributes(typeof(enumabi.EntryMarker), false).Length != 1) return 8;
                        if (typeof(enumabi.State).BaseType.FullName != "Kotlin.Enum") return 9;
                        if (typeof(enumabi.State).BaseType.Assembly.GetName().Name != "Kotlin.Runtime") return 10;
                        if (((IComparable)ready).CompareTo(enumabi.State.BUSY) >= 0) return 11;
                        try
                        {
                            ((IComparable)ready).CompareTo(enumabi.OtherState.ONLY);
                            return 12;
                        }
                        catch (InvalidCastException)
                        {
                        }
                        return 0;
                    }
                }
                """.trimIndent()
            )
        }
        val csharpConsumer = libraryDirectory.resolve("OrdinaryEnumConsumer.exe")

        for (target in listOf("net48", "net10.0")) {
            val consumerDirectory = libraryDirectory.resolve("consumer-${target.replace('.', '-')}").apply { mkdirs() }
            val consumerSource = consumerDirectory.resolve("consumer.kt").apply {
                writeText(
                    """
                    package enumconsumer

                    import enumabi.*

                    private fun describe(state: State): String = when (state) {
                        State.READY -> "ready"
                        State.BUSY -> "busy"
                        State.DONE -> "done"
                    }

                    fun main() {
                        val selected = selected()
                        if (selected !== State.READY || selectedName() != "READY") {
                            throw Error("external entry binding")
                        }
                        if (byName("BUSY") !== State.BUSY || describe(State.DONE) != "done") {
                            throw Error("external synthetic members")
                        }
                        if (State.READY.label() != "ready" || State.BUSY.code != 2) {
                            throw Error("external entry subclass dispatch")
                        }
                        val first = allStates()
                        val second = State.values()
                        if (first === second || first.size != 3 || first[1] !== State.BUSY) {
                            throw Error("external values")
                        }
                        val entries = State.entries
                        if (entries !== State.entries || entries.size != 3 || entries[2] !== State.DONE) {
                            throw Error("external entries")
                        }
                        val widened: Enum<*> = State.BUSY
                        if (widened.name != "BUSY" || widened.ordinal != 1) {
                            throw Error("external widened enum")
                        }
                        if (State.READY.compareTo(State.BUSY) >= 0 || State.DONE.compareTo(State.BUSY) <= 0) {
                            throw Error("external enum ordering")
                        }
                        @Suppress("UNCHECKED_CAST")
                        val wrongComparable = State.READY as Comparable<OtherState>
                        try {
                            wrongComparable.compareTo(OtherState.ONLY)
                            throw Error("cross-enum comparison succeeded")
                        } catch (_: ClassCastException) {
                        }
                    }
                    """.trimIndent()
                )
            }
            val application = consumerDirectory.resolve(
                if (target == "net48") "OrdinaryEnumKotlinConsumer.exe" else "OrdinaryEnumKotlinConsumer.dll"
            )
            compileInProcess(
                K2DotNetCompiler(),
                consumerSource.path,
                K2DotNetCompilerArguments::classpath.cliArgument, library.path,
                K2DotNetCompilerArguments::dotNetTarget.cliArgument, target,
                K2DotNetCompilerArguments::moduleName.cliArgument, "OrdinaryEnumKotlinConsumer",
                K2DotNetCompilerArguments::destination.cliArgument, application.path,
            )
            val consumerIl = consumerDirectory.resolve("OrdinaryEnumKotlinConsumer.il").readText()
            assertTrue(
                "callvirt instance string [Ordinary.Enum.Library]'enumabi.State'::'label'()" in consumerIl
            ) { consumerIl }
            if (target == "net10.0") {
                runDotNet(dotnetHost, application, consumerDirectory, "Kotlin enum consumer failed for $target")
            } else {
                val process = ProcessBuilder(frameworkExecutionCommand(checkNotNull(frameworkHost), application))
                    .directory(consumerDirectory)
                    .redirectErrorStream(true)
                    .start()
                val output = process.inputStream.bufferedReader().use { it.readText() }
                assertEquals(0, process.waitFor(), "Kotlin enum consumer failed for $target:\n$output")
                val csharpCompile = runCSharpCompiler(
                    checkNotNull(csharpCompiler),
                    csharpSource,
                    csharpConsumer,
                    library,
                    consumerDirectory.resolve("Kotlin.Stdlib.dll"),
                    consumerDirectory.resolve("Kotlin.Runtime.dll"),
                    checkNotNull(frameworkNetStandardFacade),
                    target = "exe",
                )
                assertEquals(0, csharpCompile.exitCode, csharpCompile.output)
                consumerDirectory.resolve("Kotlin.Stdlib.dll")
                    .copyTo(libraryDirectory.resolve("Kotlin.Stdlib.dll"), overwrite = true)
                consumerDirectory.resolve("Kotlin.Runtime.dll")
                    .copyTo(libraryDirectory.resolve("Kotlin.Runtime.dll"), overwrite = true)
                val csharpProcess = ProcessBuilder(
                    frameworkExecutionCommand(checkNotNull(frameworkHost), csharpConsumer)
                )
                    .directory(libraryDirectory)
                    .redirectErrorStream(true)
                    .start()
                val csharpOutput = csharpProcess.inputStream.bufferedReader().use { it.readText() }
                assertEquals(0, csharpProcess.waitFor(), "C# enum consumer failed on net48:\n$csharpOutput")
            }
            if (target == "net10.0") {
                val modernCSharpConsumer = consumerDirectory.resolve(csharpConsumer.name)
                csharpConsumer.copyTo(modernCSharpConsumer, overwrite = true)
                consumerDirectory.resolve("OrdinaryEnumKotlinConsumer.runtimeconfig.json")
                    .copyTo(
                        consumerDirectory.resolve("OrdinaryEnumConsumer.runtimeconfig.json"),
                        overwrite = true,
                    )
                runDotNet(
                    dotnetHost,
                    modernCSharpConsumer,
                    consumerDirectory,
                    "C# enum consumer failed on net10",
                )
            }
        }
    }

    @Test
    fun testComparableAcrossPortableLibraryBoundary() {
        requireOrAssumeToolchain(
            DotNetIlAssembler.findFrameworkIlasm() != null,
            ".NET Framework ILAsm is not available",
        )
        requireOrAssumeToolchain(
            DotNetIlAssembler.findModernIlasm() != null,
            "Modern ILAsm is not available",
        )
        val frameworkHost = DotNetIlAssembler.findFrameworkPowerShellHost()
        requireOrAssumeToolchain(frameworkHost != null, "Windows PowerShell CLR 4 host is not available")
        val frameworkCSharp = DotNetIlAssembler.findFrameworkCSharpCompiler()
        requireOrAssumeToolchain(frameworkCSharp != null, ".NET Framework C# compiler is not available")
        val frameworkNetStandardFacade = findFrameworkNetStandardFacade()
        requireOrAssumeToolchain(
            frameworkNetStandardFacade != null,
            ".NET Framework netstandard facade is not available",
        )
        val dotnetHost = modernDotNetHostOrSkip()
        val libraryDirectory = File(tmpdir, "comparable-library").apply { mkdirs() }
        val librarySource = libraryDirectory.resolve("comparableLibrary.kt").apply {
            writeText(
                """
                package comparableabi

                public class Rank(private val value: Int) : Comparable<Rank> {
                    override fun compareTo(other: Rank): Int = value - other.value
                }

                public fun compareRanks(left: Comparable<Rank>, right: Rank): Int = left.compareTo(right)
                public fun <T : Comparable<T>> compareGeneric(left: T, right: T): Int = left.compareTo(right)
                public fun compareAnything(left: Comparable<Any>, right: Any): Int = left.compareTo(right)
                public fun isComparable(value: Any): Boolean = value is Comparable<*>
                public fun compareStrings(left: String, right: String): Int = left.compareTo(right)
                public fun compareDoubles(left: Double, right: Double): Int = left.compareTo(right)
                """.trimIndent()
            )
        }
        compileInProcess(
            K2DotNetCompiler(),
            librarySource.path,
            K2DotNetCompilerArguments::dotNetProduceLibrary.cliArgument,
            K2DotNetCompilerArguments::dotNetTarget.cliArgument, "netstandard2.0",
            K2DotNetCompilerArguments::moduleName.cliArgument, "Comparable.Library",
            K2DotNetCompilerArguments::destination.cliArgument, libraryDirectory.path,
        )

        val library = libraryDirectory.resolve("Comparable.Library.dll")
        val libraryIl = libraryDirectory.resolve("Comparable.Library.il").readText()
        assertTrue(
            "implements [netstandard]'System.IComparable', " +
                    "class [netstandard]'System.IComparable`1'<class 'comparableabi.Rank'>" in libraryIl
        ) { libraryIl }
        assertTrue(
            ".override method instance int32 [netstandard]'System.IComparable'::'CompareTo'(object)" in libraryIl
        ) { libraryIl }
        assertTrue(
            ".override method instance int32 class [netstandard]'System.IComparable`1'" in libraryIl
        ) { libraryIl }
        assertTrue(
            "'compareGeneric'<(class [netstandard]'System.IComparable') 'T'>" in libraryIl
        ) { libraryIl }
        assertTrue("'ComparableCompareTo'(object, object)" in libraryIl) { libraryIl }

        val csharpSource = libraryDirectory.resolve("ComparableConsumer.cs").apply {
            writeText(
                """
                using System;
                using System.Collections.Generic;

                public static class ComparableConsumer
                {
                    private sealed class LegacyComparable : IComparable
                    {
                        private readonly int value;

                        internal LegacyComparable(int value)
                        {
                            this.value = value;
                        }

                        public int CompareTo(object other)
                        {
                            return value - ((LegacyComparable)other).value;
                        }
                    }

                    private sealed class TypedOnly : IComparable<TypedOnly>
                    {
                        private readonly int value;

                        internal TypedOnly(int value)
                        {
                            this.value = value;
                        }

                        public int CompareTo(TypedOnly other)
                        {
                            return value - other.value;
                        }
                    }

                    public static int Main()
                    {
                        var low = new comparableabi.Rank(2);
                        var high = new comparableabi.Rank(5);
                        IComparable erased = low;
                        IComparable<comparableabi.Rank> typed = low;
                        if (erased.CompareTo(high) >= 0) return 1;
                        if (typed.CompareTo(high) >= 0) return 2;
                        if (comparableabi.comparableLibraryKt.compareRanks(low, high) >= 0) return 3;
                        if (comparableabi.comparableLibraryKt.compareStrings("ä", "z") <= 0) return 4;
                        if (comparableabi.comparableLibraryKt.compareDoubles(
                                Double.NaN, Double.PositiveInfinity) <= 0) return 5;
                        if (comparableabi.comparableLibraryKt.compareAnything(
                                new LegacyComparable(2), new LegacyComparable(5)) >= 0) return 6;
                        if (comparableabi.comparableLibraryKt.compareGeneric(
                                new LegacyComparable(2), new LegacyComparable(5)) >= 0) return 7;
                        if (!comparableabi.comparableLibraryKt.isComparable(new LegacyComparable(1))) return 8;
                        if (comparableabi.comparableLibraryKt.isComparable(new TypedOnly(1))) return 9;
                        return 0;
                    }
                }
                """.trimIndent()
            )
        }
        val csharpConsumer = libraryDirectory.resolve("ComparableConsumer.exe")
        val csharpCompile = runCSharpCompiler(
            checkNotNull(frameworkCSharp),
            csharpSource,
            csharpConsumer,
            library,
            checkNotNull(frameworkNetStandardFacade),
            target = "exe",
        )
        assertEquals(0, csharpCompile.exitCode, csharpCompile.output)

        for (target in listOf("net48", "net10.0")) {
            val consumerDirectory = libraryDirectory.resolve("consumer-${target.replace('.', '-')}").apply { mkdirs() }
            val consumerSource = consumerDirectory.resolve("consumer.kt").apply {
                writeText(
                    """
                    package comparableconsumer

                    import comparableabi.*

                    private class LocalRank(private val value: Int) : Comparable<LocalRank> {
                        override fun compareTo(other: LocalRank): Int = value - other.value
                    }

                    fun main() {
                        val low = Rank(2)
                        val high = Rank(5)
                        if (compareRanks(low, high) >= 0) throw Error("portable canonical comparison")
                        if (compareGeneric(low, high) >= 0) throw Error("portable recursive bound")
                        if (compareGeneric(LocalRank(7), LocalRank(3)) <= 0) {
                            throw Error("consumer implementation")
                        }
                        if (compareGeneric(3, 2) <= 0) throw Error("primitive substitution")
                        if (compareStrings("ä", "z") <= 0) throw Error("ordinal String order")
                        if (compareDoubles(Double.NaN, Double.POSITIVE_INFINITY) <= 0) {
                            throw Error("Kotlin Double order")
                        }
                        val erased: Any = low
                        if (erased !is Comparable<*>) throw Error("separate classifier")
                        @Suppress("UNCHECKED_CAST")
                        val wrong = "wrong" as Comparable<Int>
                        try {
                            wrong.compareTo(1)
                            throw Error("delayed argument barrier")
                        } catch (_: ClassCastException) {
                        }
                    }
                    """.trimIndent()
                )
            }
            val application = consumerDirectory.resolve(
                if (target == "net48") "ComparableKotlinConsumer.exe" else "ComparableKotlinConsumer.dll"
            )
            compileInProcess(
                K2DotNetCompiler(),
                consumerSource.path,
                K2DotNetCompilerArguments::classpath.cliArgument, library.path,
                K2DotNetCompilerArguments::dotNetTarget.cliArgument, target,
                K2DotNetCompilerArguments::moduleName.cliArgument, "ComparableKotlinConsumer",
                K2DotNetCompilerArguments::destination.cliArgument, application.path,
            )
            if (target == "net48") {
                val process = ProcessBuilder(frameworkExecutionCommand(checkNotNull(frameworkHost), application))
                    .directory(consumerDirectory)
                    .redirectErrorStream(true)
                    .start()
                val output = process.inputStream.bufferedReader().use { it.readText() }
                assertEquals(0, process.waitFor(), "Comparable Kotlin consumer failed for $target:\n$output")
            } else {
                runDotNet(dotnetHost, application, consumerDirectory, "Comparable Kotlin consumer failed for $target")
            }

            consumerDirectory.resolve("Kotlin.Runtime.dll")
                .copyTo(libraryDirectory.resolve("Kotlin.Runtime.dll"), overwrite = true)
            if (target == "net48") {
                val process = ProcessBuilder(frameworkExecutionCommand(checkNotNull(frameworkHost), csharpConsumer))
                    .directory(libraryDirectory)
                    .redirectErrorStream(true)
                    .start()
                val output = process.inputStream.bufferedReader().use { it.readText() }
                assertEquals(0, process.waitFor(), "Comparable C# consumer failed for $target:\n$output")
            } else {
                libraryDirectory.resolve("ComparableConsumer.runtimeconfig.json").writeText(net10RuntimeConfig())
                runDotNet(dotnetHost, csharpConsumer, libraryDirectory, "Comparable C# consumer failed for $target")
            }
        }
    }

    @Test
    fun testStarProjectedArraysAcrossPortableLibraryBoundary() {
        requireOrAssumeToolchain(
            DotNetIlAssembler.findFrameworkIlasm() != null,
            ".NET Framework ILAsm is not available",
        )
        requireOrAssumeToolchain(
            DotNetIlAssembler.findModernIlasm() != null,
            "Modern ILAsm is not available",
        )
        val frameworkHost = DotNetIlAssembler.findFrameworkPowerShellHost()
        requireOrAssumeToolchain(frameworkHost != null, "Windows PowerShell CLR 4 host is not available")
        val csharpCompiler = DotNetIlAssembler.findFrameworkCSharpCompiler()
        requireOrAssumeToolchain(csharpCompiler != null, ".NET Framework C# compiler is not available")
        val frameworkNetStandardFacade = findFrameworkNetStandardFacade()
        requireOrAssumeToolchain(
            frameworkNetStandardFacade != null,
            ".NET Framework netstandard facade is not available",
        )
        val dotnetHost = modernDotNetHostOrSkip()
        val libraryDirectory = File(tmpdir, "star-projected-array-library")
        val librarySource = File(tmpdir, "starProjectedArrayLibrary.kt").apply {
            writeText(
                """
                package starprojectedarrays

                public fun eraseStrings(values: Array<String>): Array<*> = values
                public fun eraseInts(values: Array<Int>): Array<*> = values
                public fun eraseNullableInts(values: Array<Int?>): Array<*> = values
                public fun identityStar(values: Array<*>): Array<*> = values
                public fun starSize(values: Array<*>): Int = values.size
                public fun starFirst(values: Array<*>): Any? = values[0]
                public fun isGenericArray(value: Any?): Boolean = value is Array<*>
                public fun checkedStar(value: Any?): Array<*> = value as Array<*>
                public fun safeStar(value: Any?): Array<*>? = value as? Array<*>

                @Suppress("UNCHECKED_CAST")
                public fun incrementFirstInt(values: Array<*>): Int {
                    val exact = values as Array<Int>
                    exact[0] = exact[0] + 1
                    return exact[0]
                }
                """.trimIndent()
            )
        }
        compileInProcess(
            K2DotNetCompiler(),
            librarySource.path,
            K2DotNetCompilerArguments::dotNetProduceLibrary.cliArgument,
            K2DotNetCompilerArguments::dotNetTarget.cliArgument, "netstandard2.0",
            K2DotNetCompilerArguments::moduleName.cliArgument, "StarProjectedArray.Library",
            K2DotNetCompilerArguments::destination.cliArgument, libraryDirectory.path,
        )

        val metadataLibrary = libraryDirectory.resolve("StarProjectedArray.Library.dll")
        val libraryIl = libraryDirectory.resolve("StarProjectedArray.Library.il").readText()
        val systemArray = "class [netstandard]System.Array"
        assertTrue("$systemArray 'eraseStrings'(string[] 'values')" in libraryIl) { libraryIl }
        assertTrue("$systemArray 'eraseInts'(int32[] 'values')" in libraryIl) { libraryIl }
        assertTrue("$systemArray 'eraseNullableInts'(" in libraryIl) { libraryIl }
        assertTrue("$systemArray 'identityStar'($systemArray 'values')" in libraryIl) { libraryIl }
        assertTrue("int32 'starSize'($systemArray 'values')" in libraryIl) { libraryIl }
        assertTrue("object 'starFirst'($systemArray 'values')" in libraryIl) { libraryIl }

        val csharpSource = libraryDirectory.resolve("StarProjectedArrayConsumer.cs").apply {
            writeText(
                """
                using System;
                using System.Reflection;

                public static class StarProjectedArrayConsumer
                {
                    private static bool HasArraySignature(Type facade, string name, Type parameter, Type result)
                    {
                        MethodInfo method = facade.GetMethod(name, new Type[] { parameter });
                        return method != null && method.ReturnType == result;
                    }

                    public static int Main()
                    {
                        Type facade = typeof(starprojectedarrays.starProjectedArrayLibraryKt);
                        if (!HasArraySignature(facade, "eraseStrings", typeof(string[]), typeof(Array))) return 1;
                        if (!HasArraySignature(facade, "eraseInts", typeof(int[]), typeof(Array))) return 2;
                        if (!HasArraySignature(facade, "eraseNullableInts", typeof(int?[]), typeof(Array))) return 3;
                        if (!HasArraySignature(facade, "identityStar", typeof(Array), typeof(Array))) return 4;
                        if (!HasArraySignature(facade, "checkedStar", typeof(object), typeof(Array))) return 5;
                        if (!HasArraySignature(facade, "safeStar", typeof(object), typeof(Array))) return 6;

                        string[] strings = new string[] { "a", "b" };
                        int[] ints = new int[] { 40, 2 };
                        int?[] nullableInts = new int?[] { 1, null, 3 };
                        if (!Object.ReferenceEquals(strings,
                            starprojectedarrays.starProjectedArrayLibraryKt.eraseStrings(strings))) return 7;
                        if (!Object.ReferenceEquals(ints,
                            starprojectedarrays.starProjectedArrayLibraryKt.eraseInts(ints))) return 8;
                        if (!Object.ReferenceEquals(nullableInts,
                            starprojectedarrays.starProjectedArrayLibraryKt.eraseNullableInts(nullableInts))) return 9;
                        if (!Object.ReferenceEquals(ints,
                            starprojectedarrays.starProjectedArrayLibraryKt.identityStar(ints))) return 10;
                        if (starprojectedarrays.starProjectedArrayLibraryKt.starSize(ints) != 2) return 11;
                        if (!Object.Equals(starprojectedarrays.starProjectedArrayLibraryKt.starFirst(ints), 40)) return 12;

                        if (!starprojectedarrays.starProjectedArrayLibraryKt.isGenericArray(strings) ||
                            !starprojectedarrays.starProjectedArrayLibraryKt.isGenericArray(ints) ||
                            !starprojectedarrays.starProjectedArrayLibraryKt.isGenericArray(nullableInts)) return 13;
                        if (!Object.ReferenceEquals(ints,
                            starprojectedarrays.starProjectedArrayLibraryKt.checkedStar(ints))) return 14;
                        if (!Object.ReferenceEquals(strings,
                            starprojectedarrays.starProjectedArrayLibraryKt.safeStar(strings))) return 15;
                        if (starprojectedarrays.starProjectedArrayLibraryKt.incrementFirstInt(ints) != 41 || ints[0] != 41) {
                            return 16;
                        }

                        Array rectangular = new int[1, 2];
                        Array nonZeroBased = Array.CreateInstance(typeof(int), new int[] { 2 }, new int[] { 1 });
                        if (starprojectedarrays.starProjectedArrayLibraryKt.isGenericArray(rectangular) ||
                            starprojectedarrays.starProjectedArrayLibraryKt.isGenericArray(nonZeroBased)) return 17;
                        if (starprojectedarrays.starProjectedArrayLibraryKt.safeStar(rectangular) != null ||
                            starprojectedarrays.starProjectedArrayLibraryKt.safeStar(nonZeroBased) != null) return 18;

                        bool rectangularRejected = false;
                        try
                        {
                            starprojectedarrays.starProjectedArrayLibraryKt.checkedStar(rectangular);
                        }
                        catch (InvalidCastException)
                        {
                            rectangularRejected = true;
                        }
                        if (!rectangularRejected) return 19;

                        bool nonZeroRejected = false;
                        try
                        {
                            starprojectedarrays.starProjectedArrayLibraryKt.checkedStar(nonZeroBased);
                        }
                        catch (InvalidCastException)
                        {
                            nonZeroRejected = true;
                        }
                        if (!nonZeroRejected) return 20;
                        return 0;
                    }
                }
                """.trimIndent()
            )
        }
        val csharpConsumer = libraryDirectory.resolve("StarProjectedArrayConsumer.exe")
        val csharpCompile = runCSharpCompiler(
            checkNotNull(csharpCompiler),
            csharpSource,
            csharpConsumer,
            metadataLibrary,
            checkNotNull(frameworkNetStandardFacade),
            target = "exe",
        )
        assertEquals(0, csharpCompile.exitCode, csharpCompile.output)

        for (target in listOf("net48", "net10.0")) {
            val consumerDirectory = libraryDirectory.resolve("consumer-${target.replace('.', '-')}").apply { mkdirs() }
            val consumerSource = consumerDirectory.resolve("consumer.kt").apply {
                writeText(
                    """
                    package starprojectedarrayconsumer

                    import starprojectedarrays.*

                    fun main() {
                        val strings = arrayOf("a", "b")
                        val ints = arrayOf(40, 2)
                        val nullableInts = arrayOf<Int?>(1, null, 3)
                        val stringStar = eraseStrings(strings)
                        val intStar = eraseInts(ints)
                        val nullableStar = eraseNullableInts(nullableInts)
                        if (stringStar !== strings || intStar !== ints || nullableStar !== nullableInts) {
                            throw Error("star identity")
                        }
                        if (identityStar(intStar) !== ints || starSize(nullableStar) != 3 ||
                            starFirst(stringStar) != "a" || starFirst(nullableStar) != 1
                        ) throw Error("star operations")
                        if (!isGenericArray(strings) || !isGenericArray(ints) ||
                            !isGenericArray(nullableInts) || isGenericArray(intArrayOf(1))
                        ) throw Error("star classifier")
                        if (checkedStar(ints) !== ints || safeStar(strings) !== strings ||
                            safeStar(intArrayOf(1)) != null
                        ) throw Error("star casts")
                        if (incrementFirstInt(intStar) != 41 || ints[0] != 41) {
                            throw Error("exact mutation alias")
                        }
                    }
                    """.trimIndent()
                )
            }
            val application = consumerDirectory.resolve(
                if (target == "net48") "StarProjectedArrayKotlinConsumer.exe" else "StarProjectedArrayKotlinConsumer.dll"
            )
            compileInProcess(
                K2DotNetCompiler(),
                consumerSource.path,
                K2DotNetCompilerArguments::classpath.cliArgument, metadataLibrary.path,
                K2DotNetCompilerArguments::dotNetTarget.cliArgument, target,
                K2DotNetCompilerArguments::moduleName.cliArgument, "StarProjectedArrayKotlinConsumer",
                K2DotNetCompilerArguments::destination.cliArgument, application.path,
            )
            if (target == "net10.0") {
                runDotNet(
                    dotnetHost,
                    application,
                    consumerDirectory,
                    "Star-array Kotlin consumer failed for $target",
                )
            } else {
                val process = ProcessBuilder(frameworkExecutionCommand(checkNotNull(frameworkHost), application))
                    .directory(consumerDirectory)
                    .redirectErrorStream(true)
                    .start()
                val output = process.inputStream.bufferedReader().use { it.readText() }
                assertEquals(
                    0,
                    process.waitFor(),
                    "Star-array Kotlin consumer failed for $target:\n$output",
                )
                val runtimeAssembly = consumerDirectory.resolve("Kotlin.Runtime.dll")
                assertTrue(runtimeAssembly.isFile)
                runtimeAssembly.copyTo(libraryDirectory.resolve(runtimeAssembly.name), overwrite = true)
                val frameworkCSharpProcess = ProcessBuilder(
                    frameworkExecutionCommand(checkNotNull(frameworkHost), csharpConsumer)
                )
                    .directory(libraryDirectory)
                    .redirectErrorStream(true)
                    .start()
                val frameworkCSharpOutput = frameworkCSharpProcess.inputStream.bufferedReader().use { it.readText() }
                assertEquals(
                    0,
                    frameworkCSharpProcess.waitFor(),
                    "Roslyn star-array consumer failed on net48:\n$frameworkCSharpOutput",
                )
            }
            if (target == "net10.0") {
                val modernCSharpConsumer = consumerDirectory.resolve(csharpConsumer.name)
                csharpConsumer.copyTo(modernCSharpConsumer, overwrite = true)
                consumerDirectory.resolve("StarProjectedArrayKotlinConsumer.runtimeconfig.json")
                    .copyTo(
                        consumerDirectory.resolve("StarProjectedArrayConsumer.runtimeconfig.json"),
                        overwrite = true,
                    )
                runDotNet(
                    dotnetHost,
                    modernCSharpConsumer,
                    consumerDirectory,
                    "Roslyn star-array consumer failed on $target",
                )
            }
        }
    }

    @Test
    fun testCharSequenceCarrierAcrossPortableLibraryBoundary() {
        requireOrAssumeToolchain(
            DotNetIlAssembler.findFrameworkIlasm() != null,
            ".NET Framework ILAsm is not available",
        )
        requireOrAssumeToolchain(
            DotNetIlAssembler.findModernIlasm() != null,
            "Modern ILAsm is not available",
        )
        val modernCSharp = DotNetIlAssembler.findModernCSharpCompiler()
        requireOrAssumeToolchain(
            modernCSharp != null,
            "Modern Roslyn and the net10 reference pack are not available",
        )
        val dotnetHost = modernDotNetHostOrSkip()
        val libraryDirectory = File(tmpdir, "char-sequence-library").apply { mkdirs() }
        val librarySource = libraryDirectory.resolve("charSequenceLibrary.kt").apply {
            writeText(
                """
                package charsequenceabi

                public class LibrarySequence(private val text: String) : CharSequence {
                    override val length: Int get() = text.length
                    override fun get(index: Int): Char = text[index]
                    override fun subSequence(startIndex: Int, endIndex: Int): CharSequence =
                        text.subSequence(startIndex, endIndex)
                }

                public fun lengthOf(value: CharSequence): Int = value.length

                public fun firstOf(value: CharSequence): Char = value[0]

                public fun slice(value: CharSequence, startIndex: Int, endIndex: Int): CharSequence =
                    value.subSequence(startIndex, endIndex)

                public fun isSequence(value: Any?): Boolean = value is CharSequence

                public fun safeSequence(value: Any): CharSequence? = value as? CharSequence

                public fun checkedSequence(value: Any): CharSequence = value as CharSequence

                public fun <T : CharSequence> genericLength(value: T): Int = value.length

                public fun <T : CharSequence> genericIdentity(value: T): T = value
                """.trimIndent()
            )
        }
        compileInProcess(
            K2DotNetCompiler(),
            librarySource.path,
            K2DotNetCompilerArguments::dotNetProduceLibrary.cliArgument,
            K2DotNetCompilerArguments::dotNetTarget.cliArgument, "netstandard2.0",
            K2DotNetCompilerArguments::moduleName.cliArgument, "CharSequence.Library",
            K2DotNetCompilerArguments::destination.cliArgument, libraryDirectory.path,
        )

        val metadataLibrary = libraryDirectory.resolve("CharSequence.Library.dll")
        val libraryIl = libraryDirectory.resolve("CharSequence.Library.il").readText()
        assertTrue("implements [Kotlin.Runtime]'Kotlin.CharSequence'" in libraryIl) { libraryIl }
        assertTrue("static int32 'lengthOf'(object 'value')" in libraryIl) { libraryIl }
        assertTrue("static object 'slice'(object 'value', int32 'startIndex', int32 'endIndex')" in libraryIl) {
            libraryIl
        }
        assertTrue("static int32 'genericLength'<'T'>(!!0 'value')" in libraryIl) { libraryIl }
        assertTrue("static !!0 'genericIdentity'<'T'>(!!0 'value')" in libraryIl) { libraryIl }
        assertTrue("box !!0" in libraryIl) { libraryIl }
        assertTrue("::'CharSequenceLength'(object)" in libraryIl) { libraryIl }
        assertTrue("<(class [Kotlin.Runtime]'Kotlin.CharSequence')" !in libraryIl) { libraryIl }

        for (target in listOf("net48", "net10.0")) {
            val consumerDirectory = libraryDirectory.resolve("consumer-${target.replace('.', '-')}").apply { mkdirs() }
            val consumerSource = consumerDirectory.resolve("consumer.kt").apply {
                writeText(
                    """
                    package charsequenceconsumer

                    import charsequenceabi.*

                    fun main() {
                        val string = "abcd"
                        val implementation = LibrarySequence("wxyz")
                        if (lengthOf(string) != 4 || firstOf(string) != 'a') throw Error("string carrier")
                        if (lengthOf(implementation) != 4 || firstOf(implementation) != 'w') {
                            throw Error("implementation carrier")
                        }
                        if (slice(string, 1, 3) != "bc") throw Error("string slice")
                        if (slice(implementation, 1, 3) != "xy") throw Error("implementation slice")
                        if (!isSequence(string) || !isSequence(implementation) || isSequence(42)) {
                            throw Error("classifier")
                        }
                        if (safeSequence(string) !== string ||
                            safeSequence(implementation) !== implementation ||
                            safeSequence(42) != null
                        ) {
                            throw Error("safe cast")
                        }
                        if (checkedSequence(string) !== string ||
                            checkedSequence(implementation) !== implementation
                        ) {
                            throw Error("checked cast identity")
                        }
                        try {
                            checkedSequence(42)
                            throw Error("invalid checked cast succeeded")
                        } catch (_: ClassCastException) {
                        }
                        if (genericLength(string) != 4 || genericLength(implementation) != 4) {
                            throw Error("generic operation")
                        }
                        if (genericIdentity(string) !== string ||
                            genericIdentity(implementation) !== implementation
                        ) {
                            throw Error("generic identity")
                        }
                    }
                    """.trimIndent()
                )
            }
            val application = consumerDirectory.resolve(
                if (target == "net48") "CharSequenceConsumer.exe" else "CharSequenceConsumer.dll"
            )
            compileInProcess(
                K2DotNetCompiler(),
                consumerSource.path,
                K2DotNetCompilerArguments::classpath.cliArgument, metadataLibrary.path,
                K2DotNetCompilerArguments::dotNetTarget.cliArgument, target,
                K2DotNetCompilerArguments::moduleName.cliArgument, "CharSequenceConsumer",
                K2DotNetCompilerArguments::destination.cliArgument, application.path,
            )
            if (target == "net10.0") {
                runDotNet(
                    dotnetHost,
                    application,
                    consumerDirectory,
                    "CharSequence Kotlin consumer failed for $target",
                )
            } else {
                val process = ProcessBuilder(application.path)
                    .directory(consumerDirectory)
                    .redirectErrorStream(true)
                    .start()
                val output = process.inputStream.bufferedReader().use { it.readText() }
                assertEquals(0, process.waitFor(), "CharSequence Kotlin consumer failed for $target:\n$output")
            }

            if (target == "net10.0") {
                val csharpSource = consumerDirectory.resolve("consumer.cs").apply {
                    writeText(
                        """
                        using System;

                        public sealed class ForeignSequence : Kotlin.CharSequence
                        {
                            private readonly string value;

                            public ForeignSequence(string value) { this.value = value; }

                            public int length { get { return value.Length; } }

                            public char get(int index) { return value[index]; }

                            public object subSequence(int startIndex, int endIndex)
                            {
                                return value.Substring(startIndex, endIndex - startIndex);
                            }
                        }

                        public static class Program
                        {
                            public static int Main()
                            {
                                var foreign = new ForeignSequence("foreign");
                                if (charsequenceabi.charSequenceLibraryKt.lengthOf("string") != 6) return 1;
                                if (charsequenceabi.charSequenceLibraryKt.lengthOf(foreign) != 7) return 2;
                                if (charsequenceabi.charSequenceLibraryKt.firstOf(foreign) != 'f') return 3;
                                if ((string) charsequenceabi.charSequenceLibraryKt.slice(foreign, 1, 4) != "ore") return 4;
                                if (!charsequenceabi.charSequenceLibraryKt.isSequence("string") ||
                                    !charsequenceabi.charSequenceLibraryKt.isSequence(foreign) ||
                                    charsequenceabi.charSequenceLibraryKt.isSequence(42)) return 5;
                                if (!Object.ReferenceEquals(
                                    charsequenceabi.charSequenceLibraryKt.safeSequence(foreign), foreign)) return 6;
                                if (charsequenceabi.charSequenceLibraryKt.safeSequence(42) != null) return 7;
                                if (charsequenceabi.charSequenceLibraryKt.genericLength<string>("generic") != 7 ||
                                    charsequenceabi.charSequenceLibraryKt.genericLength<ForeignSequence>(foreign) != 7) {
                                    return 8;
                                }
                                if (!Object.ReferenceEquals(
                                    charsequenceabi.charSequenceLibraryKt.genericIdentity<ForeignSequence>(foreign),
                                    foreign)) return 9;
                                try
                                {
                                    charsequenceabi.charSequenceLibraryKt.checkedSequence(42);
                                    return 10;
                                }
                                catch (InvalidCastException)
                                {
                                }
                                return 0;
                            }
                        }
                        """.trimIndent()
                    )
                }
                val csharpApplication = consumerDirectory.resolve("CharSequenceCSharpConsumer.dll")
                val csharpCompile = runModernCSharpCompiler(
                    checkNotNull(modernCSharp),
                    csharpSource,
                    csharpApplication,
                    metadataLibrary,
                    consumerDirectory.resolve("Kotlin.Runtime.dll"),
                    target = "exe",
                )
                assertEquals(0, csharpCompile.exitCode, csharpCompile.output)
                consumerDirectory.resolve("CharSequenceConsumer.runtimeconfig.json").copyTo(
                    consumerDirectory.resolve("CharSequenceCSharpConsumer.runtimeconfig.json"),
                    overwrite = true,
                )
                runDotNet(
                    dotnetHost,
                    csharpApplication,
                    consumerDirectory,
                    "CharSequence C# consumer failed",
                )
            }
        }
    }

    @Test
    fun testOpenNullableTypeParametersAcrossPortableLibraryBoundary() {
        requireOrAssumeToolchain(
            DotNetIlAssembler.findFrameworkIlasm() != null,
            ".NET Framework ILAsm is not available",
        )
        requireOrAssumeToolchain(
            DotNetIlAssembler.findModernIlasm() != null,
            "Modern ILAsm is not available",
        )
        val dotnetHost = modernDotNetHostOrSkip()
        val modernCSharp = DotNetIlAssembler.findModernCSharpCompiler()
        requireOrAssumeToolchain(
            modernCSharp != null,
            "Modern Roslyn and the net10 reference pack are not available",
        )
        val libraryDirectory = File(tmpdir, "open-nullable-library")
        val librarySource = File(tmpdir, "openNullableLibrary.kt").apply {
            writeText(
                """
                package nullableabi

                public class NullableHolder<T>(public var value: T?)

                public interface NullableSource<T> {
                    public fun nullableValue(): T?
                }

                public class StoredNullableSource<T>(private val stored: T?) : NullableSource<T> {
                    override fun nullableValue(): T? = stored
                }

                public fun <T> echoNullable(value: T?): T? = value

                public fun <T> requireNullable(value: T?): T = value!!

                public fun <T> readNullable(source: NullableSource<T>): T? = source.nullableValue()

                public fun <T : String> echoStringBoundNullable(value: T?): T? = value

                public fun <T : String> requireStringBoundNullable(value: T?): T = value!!
                """.trimIndent()
            )
        }
        compileInProcess(
            K2DotNetCompiler(),
            librarySource.path,
            K2DotNetCompilerArguments::dotNetProduceLibrary.cliArgument,
            K2DotNetCompilerArguments::dotNetTarget.cliArgument, "netstandard2.0",
            K2DotNetCompilerArguments::moduleName.cliArgument, "OpenNullable.Library",
            K2DotNetCompilerArguments::destination.cliArgument, libraryDirectory.path,
        )

        val metadataLibrary = libraryDirectory.resolve("OpenNullable.Library.dll")
        val libraryIl = libraryDirectory.resolve("OpenNullable.Library.il").readText()
        assertTrue(".field private object 'value'" in libraryIl) { libraryIl }
        assertTrue("static object 'echoNullable'<'T'>(object 'value')" in libraryIl) { libraryIl }
        assertTrue("static !!0 'requireNullable'<'T'>(object 'value')" in libraryIl) { libraryIl }
        assertTrue("static object 'echoStringBoundNullable'<'T'>(object 'value')" in libraryIl) { libraryIl }
        assertTrue("static string 'requireStringBoundNullable'<'T'>(object 'value')" in libraryIl) { libraryIl }
        assertTrue("unbox.any !!0" in libraryIl) { libraryIl }
        assertTrue("castclass string" in libraryIl) { libraryIl }
        assertTrue(".class interface public abstract auto ansi 'nullableabi.NullableSource'" in libraryIl) { libraryIl }
        assertFalse("nullableabi.NullableSource`1" in libraryIl) { libraryIl }
        assertTrue("instance object 'nullableValue'()" in libraryIl) { libraryIl }
        val storedNullableSourceIl = libraryIl
            .substringAfter(".class public auto ansi sealed beforefieldinit 'nullableabi.StoredNullableSource'")
            .substringBefore("\n.class ")
        assertTrue(
            ".override method instance object 'nullableabi.NullableSource'::" +
                    "'nullableValue__KotlinErased__" in storedNullableSourceIl
        ) { storedNullableSourceIl }
        assertFalse("'nullableabi.NullableSource`1'<object>" in storedNullableSourceIl) {
            storedNullableSourceIl
        }

        for (target in listOf("net48", "net10.0")) {
            val consumerDirectory = libraryDirectory.resolve("consumer-${target.replace('.', '-')}").apply { mkdirs() }
            val consumerSource = consumerDirectory.resolve("consumer.kt").apply {
                writeText(
                    """
                    package nullableconsumer

                    import nullableabi.*

                    fun main() {
                        val numbers = NullableHolder<Int>(null)
                        if (numbers.value != null) throw Error("primitive null field")
                        numbers.value = 41
                        if (numbers.value != 41) throw Error("primitive field recovery")
                        if (echoNullable<Int>(null) != null) throw Error("primitive null call")
                        if (echoNullable(42) != 42) throw Error("primitive call recovery")
                        if (requireNullable(43) != 43) throw Error("primitive non-null recovery")
                        val numberSource: NullableSource<Int> = StoredNullableSource(44)
                        if (numberSource.nullableValue() != 44) throw Error("primitive interface recovery")
                        if (readNullable(numberSource) != 44) throw Error("primitive generic interface call")

                        val strings = NullableHolder<String>(null)
                        strings.value = "reference"
                        if (strings.value != "reference") throw Error("reference field recovery")
                        if (echoNullable<String>(null) != null) throw Error("reference null call")
                        if (requireNullable("ok") != "ok") throw Error("reference non-null recovery")
                        val stringSource: NullableSource<String> = StoredNullableSource(null)
                        if (stringSource.nullableValue() != null) throw Error("reference interface recovery")
                        if (readNullable(stringSource) != null) throw Error("reference generic interface call")

                        if (echoStringBoundNullable<String>(null) != null) {
                            throw Error("string-bound null call")
                        }
                        if (echoStringBoundNullable("bounded-call") != "bounded-call") {
                            throw Error("string-bound call recovery")
                        }
                        if (requireStringBoundNullable("bounded-required") != "bounded-required") {
                            throw Error("string-bound non-null recovery")
                        }
                    }
                    """.trimIndent()
                )
            }
            val application = consumerDirectory.resolve(
                if (target == "net48") "OpenNullableConsumer.exe" else "OpenNullableConsumer.dll"
            )
            compileInProcess(
                K2DotNetCompiler(),
                consumerSource.path,
                K2DotNetCompilerArguments::classpath.cliArgument, metadataLibrary.path,
                K2DotNetCompilerArguments::dotNetTarget.cliArgument, target,
                K2DotNetCompilerArguments::moduleName.cliArgument, "OpenNullableConsumer",
                K2DotNetCompilerArguments::destination.cliArgument, application.path,
            )
            if (target == "net10.0") {
                runDotNet(
                    dotnetHost,
                    application,
                    consumerDirectory,
                    "Open-nullable Kotlin consumer failed for $target",
                )
            } else {
                val process = ProcessBuilder(application.path)
                    .directory(consumerDirectory)
                    .redirectErrorStream(true)
                    .start()
                val output = process.inputStream.bufferedReader().use { it.readText() }
                assertEquals(0, process.waitFor(), "Open-nullable Kotlin consumer failed for $target:\n$output")
            }

            if (target == "net10.0") {
                val csharpSource = consumerDirectory.resolve("consumer.cs").apply {
                    writeText(
                        """
                        public static class Program
                        {
                            public static int Main()
                            {
                                var holder = new nullableabi.NullableHolder(41);
                                if ((int) holder.value != 41) return 1;
                                holder.value = null;
                                if (holder.value != null) return 2;

                                var stored = new nullableabi.StoredNullableSource(42);
                                nullableabi.NullableSource source = stored;
                                if ((int) stored.nullableValue() != 42) return 3;
                                if ((int) nullableabi.openNullableLibraryKt.readNullable<int>(source) != 42) return 4;

                                var empty = new nullableabi.StoredNullableSource(null);
                                if (empty.nullableValue() != null) return 5;
                                if (nullableabi.openNullableLibraryKt.echoNullable<string>(null) != null) return 6;
                                if (nullableabi.openNullableLibraryKt.requireNullable<int>(43) != 43) return 7;

                                if (nullableabi.openNullableLibraryKt.echoStringBoundNullable<string>(null) != null)
                                    return 8;
                                if ((string) nullableabi.openNullableLibraryKt
                                    .echoStringBoundNullable<string>("bounded-call") != "bounded-call") return 9;
                                if (nullableabi.openNullableLibraryKt
                                    .requireStringBoundNullable<string>("bounded-required") != "bounded-required")
                                    return 10;
                                return 0;
                            }
                        }
                        """.trimIndent()
                    )
                }
                val csharpApplication = consumerDirectory.resolve("OpenNullableCSharpConsumer.dll")
                val csharpCompile = runModernCSharpCompiler(
                    checkNotNull(modernCSharp),
                    csharpSource,
                    csharpApplication,
                    libraryDirectory.resolve("OpenNullable.Library.dll"),
                    consumerDirectory.resolve("Kotlin.Runtime.dll"),
                    target = "exe",
                )
                assertEquals(0, csharpCompile.exitCode, csharpCompile.output)
                consumerDirectory.resolve("OpenNullableConsumer.runtimeconfig.json").copyTo(
                    consumerDirectory.resolve("OpenNullableCSharpConsumer.runtimeconfig.json"),
                    overwrite = true,
                )
                runDotNet(
                    dotnetHost,
                    csharpApplication,
                    consumerDirectory,
                    "Open-nullable C# consumer failed for $target",
                )
            }
        }
    }

    @Test
    fun testCovariantReturnsAcrossPortableLibraryBoundary() {
        requireOrAssumeToolchain(
            DotNetIlAssembler.findFrameworkIlasm() != null,
            ".NET Framework ILAsm is not available",
        )
        requireOrAssumeToolchain(
            DotNetIlAssembler.findModernIlasm() != null,
            "Modern ILAsm is not available",
        )
        val frameworkCSharp = DotNetIlAssembler.findFrameworkCSharpCompiler()
        requireOrAssumeToolchain(frameworkCSharp != null, ".NET Framework C# compiler is not available")
        val frameworkNetStandardFacade = findFrameworkNetStandardFacade()
        requireOrAssumeToolchain(
            frameworkNetStandardFacade != null,
            ".NET Framework netstandard 2.0 facade is not available",
        )
        val modernCSharp = DotNetIlAssembler.findModernCSharpCompiler()
        requireOrAssumeToolchain(
            modernCSharp != null,
            "Modern Roslyn and the net10 reference pack are not available",
        )
        val dotnetHost = modernDotNetHostOrSkip()
        val libraryDirectory = File(tmpdir, "covariant-return-library")
        val librarySource = File(tmpdir, "covariantReturnLibrary.kt").apply {
            writeText(
                """
                package covarianceabi

                public open class Animal(public val tag: String)

                public open class Cat(tag: String) : Animal(tag)

                public open class Source {
                    public open fun make(): Animal = Animal("source-method")
                    public open val item: Animal get() = Animal("source-property")
                    public open fun <T> generic(value: T): Animal = Animal("source-generic")
                }

                public interface Maker {
                    public fun make(): Animal
                }

                public interface HasItem {
                    public val item: Animal
                }

                public interface DefaultMaker {
                    public fun defaultMake(): Animal = Animal("portable-default")
                }

                public interface ValueSource<out T> {
                    public fun value(): T
                }

                public class CatValueSource : ValueSource<Cat> {
                    override fun value(): Cat = Cat("variant-value")
                }

                public open class VariantReturnBase {
                    public open fun variant(): ValueSource<Animal> = CatValueSource()
                }

                public open class Factory {
                    public open fun make(): Cat = Cat("factory-method")
                }

                public open class ItemFactory {
                    public open val item: Cat get() = Cat("factory-property")
                }

                public abstract class AbstractCatSource : Source() {
                    public abstract override fun make(): Cat
                }
                """.trimIndent()
            )
        }
        compileInProcess(
            K2DotNetCompiler(),
            librarySource.path,
            K2DotNetCompilerArguments::dotNetProduceLibrary.cliArgument,
            K2DotNetCompilerArguments::dotNetTarget.cliArgument, "netstandard2.0",
            K2DotNetCompilerArguments::moduleName.cliArgument, "Covariance.Library",
            K2DotNetCompilerArguments::destination.cliArgument, libraryDirectory.path,
        )

        val metadataLibrary = libraryDirectory.resolve("Covariance.Library.dll")
        for (target in listOf("net48", "net10.0")) {
            val consumerDirectory = libraryDirectory.resolve("consumer-${target.replace('.', '-')}").apply { mkdirs() }
            val consumerSource = consumerDirectory.resolve("consumer.kt").apply {
                writeText(
                    """
                    package covarianceconsumer

                    import covarianceabi.*

                    public class Derived : Source() {
                        override fun make(): Cat = Cat("derived-method")
                        override val item: Cat get() = Cat("derived-property")
                        override fun <T> generic(value: T): Cat = Cat("derived-generic")
                    }

                    public class Combo : Factory(), Maker

                    public class ItemCombo : ItemFactory(), HasItem

                    public class VariantReturnDerived : VariantReturnBase() {
                        override fun variant(): ValueSource<Cat> = CatValueSource()
                    }

                    public interface RefinedDefaultMaker : DefaultMaker {
                        override fun defaultMake(): Cat = Cat("refined-default")
                    }

                    public class DefaultMakerImplementation : RefinedDefaultMaker

                    public class ConcreteAbstractSource : AbstractCatSource() {
                        override fun make(): Cat = Cat("abstract-method")
                    }

                    public open class Middle : Source() {
                        override fun make(): Cat = Cat("middle-method")
                    }

                    public class Siamese(tag: String) : Cat(tag)

                    public class Leaf : Middle() {
                        override fun make(): Siamese = Siamese("leaf-method")
                    }

                    fun main() {
                        val exact = Derived()
                        val exactMethod: Cat = exact.make()
                        val exactProperty: Cat = exact.item
                        val exactGeneric: Cat = exact.generic(42)
                        if (exactMethod.tag != "derived-method") throw Error("exact method")
                        if (exactProperty.tag != "derived-property") throw Error("exact property")
                        if (exactGeneric.tag != "derived-generic") throw Error("exact generic")

                        val base: Source = exact
                        if (base.make().tag != "derived-method") throw Error("base method")
                        if (base.item.tag != "derived-property") throw Error("base property")
                        if (base.generic("value").tag != "derived-generic") throw Error("base generic")

                        val maker: Maker = Combo()
                        if (maker.make().tag != "factory-method") throw Error("inherited interface method")
                        val hasItem: HasItem = ItemCombo()
                        if (hasItem.item.tag != "factory-property") throw Error("inherited interface property")

                        val variant: VariantReturnBase = VariantReturnDerived()
                        if (variant.variant().value().tag != "variant-value") {
                            throw Error("canonical variant return")
                        }

                        val defaultMaker: DefaultMaker = DefaultMakerImplementation()
                        if (defaultMaker.defaultMake().tag != "refined-default") {
                            throw Error("covariant interface default")
                        }

                        val abstractBase: Source = ConcreteAbstractSource()
                        if (abstractBase.make().tag != "abstract-method") throw Error("abstract refinement")

                        val leaf = Leaf()
                        val leafAsRoot: Source = leaf
                        val leafAsMiddle: Middle = leaf
                        if (leafAsRoot.make().tag != "leaf-method") throw Error("root leaf dispatch")
                        if (leafAsMiddle.make().tag != "leaf-method") throw Error("middle leaf dispatch")
                    }
                    """.trimIndent()
                )
            }
            val application = consumerDirectory.resolve(
                if (target == "net48") "Covariance.Consumer.exe" else "Covariance.Consumer.dll"
            )
            compileInProcess(
                K2DotNetCompiler(),
                consumerSource.path,
                K2DotNetCompilerArguments::classpath.cliArgument, metadataLibrary.path,
                K2DotNetCompilerArguments::dotNetTarget.cliArgument, target,
                K2DotNetCompilerArguments::moduleName.cliArgument, "Covariance.Consumer",
                K2DotNetCompilerArguments::destination.cliArgument, application.path,
            )

            val consumerIl = consumerDirectory.resolve("Covariance.Consumer.il").readText()
            val bridgeBodies = Regex(
                "(?s)\\.method private[^\\n]*'<CovariantReturnBridge-[^']+'[^\\n]*\\n  \\{(.*?)\\n  \\}"
            ).findAll(consumerIl).map { match -> match.groupValues[1] }.toList()
            assertEquals(8, bridgeBodies.size, consumerIl)
            bridgeBodies.forEach { body ->
                assertTrue(".override method" in body) { body }
                assertTrue("callvirt instance" in body) { body }
                assertTrue("newobj" !in body) { "Covariant-return bridge copied a constructor body:\n$body" }
            }
            assertTrue("class [Covariance.Library]'covarianceabi.Animal'" in consumerIl) { consumerIl }
            assertTrue("class [Covariance.Library]'covarianceabi.Cat'" in consumerIl) { consumerIl }
            assertTrue("[Covariance.Library]'covarianceabi.Source'::'make'()" in consumerIl) { consumerIl }
            assertTrue("[Covariance.Library]'covarianceabi.Maker'::'make'()" in consumerIl) { consumerIl }
            assertTrue("<CovariantReturnBridge-covarianceabi.VariantReturnBase-variant-" !in consumerIl) {
                "A canonical split-interface return acquired an unnecessary ordinary bridge:\n$consumerIl"
            }

            if (target == "net10.0") {
                runDotNet(
                    dotnetHost,
                    application,
                    consumerDirectory,
                    "Covariant-return Kotlin consumer failed for $target",
                )
            } else {
                val process = ProcessBuilder(application.path)
                    .directory(consumerDirectory)
                    .redirectErrorStream(true)
                    .start()
                val output = process.inputStream.bufferedReader().use { it.readText() }
                assertEquals(0, process.waitFor(), "Covariant-return Kotlin consumer failed for $target:\n$output")
            }

            val csharpSource = consumerDirectory.resolve("consumer.cs").apply {
                val foreignDefaultClass = if (target == "net10.0") {
                    """
                    public sealed class ForeignDefaultMaker : covarianceconsumer.RefinedDefaultMaker
                    {
                    }
                    """.trimIndent()
                } else {
                    ""
                }
                val foreignDefaultCall = if (target == "net10.0") {
                    """
                    covarianceabi.DefaultMaker foreignDefault = new ForeignDefaultMaker();
                    Require(foreignDefault.defaultMake().tag == "refined-default", "foreign DIM");
                    """.trimIndent()
                } else {
                    ""
                }
                writeText(
                    """
                    using System;
                    using System.Linq;
                    using System.Reflection;

                    $foreignDefaultClass

                    public static class Program
                    {
                        private static void Require(bool condition, string message)
                        {
                            if (!condition) throw new Exception(message);
                        }

                        public static int Main()
                        {
                            var exact = new covarianceconsumer.Derived();
                            covarianceabi.Cat exactMethod = exact.make();
                            covarianceabi.Cat exactProperty = exact.item;
                            covarianceabi.Cat exactGeneric = exact.generic<int>(42);
                            Require(exactMethod.tag == "derived-method", "exact method");
                            Require(exactProperty.tag == "derived-property", "exact property");
                            Require(exactGeneric.tag == "derived-generic", "exact generic");

                            covarianceabi.Source baseView = exact;
                            Require(baseView.make().tag == "derived-method", "base method");
                            Require(baseView.item.tag == "derived-property", "base property");
                            Require(baseView.generic<string>("value").tag == "derived-generic", "base generic");

                            covarianceabi.Maker maker = new covarianceconsumer.Combo();
                            Require(maker.make().tag == "factory-method", "interface method");
                            covarianceabi.HasItem hasItem = new covarianceconsumer.ItemCombo();
                            Require(hasItem.item.tag == "factory-property", "interface property");
                            covarianceabi.DefaultMaker defaultMaker =
                                new covarianceconsumer.DefaultMakerImplementation();
                            Require(defaultMaker.defaultMake().tag == "refined-default", "Kotlin default");
                            $foreignDefaultCall

                            covarianceabi.Source abstractView = new covarianceconsumer.ConcreteAbstractSource();
                            Require(abstractView.make().tag == "abstract-method", "abstract refinement");

                            var leaf = new covarianceconsumer.Leaf();
                            covarianceabi.Source rootView = leaf;
                            covarianceconsumer.Middle middleView = leaf;
                            Require(rootView.make().tag == "leaf-method", "root leaf dispatch");
                            Require(middleView.make().tag == "leaf-method", "middle leaf dispatch");

                            MethodInfo[] declared = typeof(covarianceconsumer.Derived).GetMethods(
                                BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic |
                                BindingFlags.DeclaredOnly);
                            MethodInfo precise = declared.Single(method =>
                                method.Name == "make" && method.IsPublic &&
                                method.ReturnType == typeof(covarianceabi.Cat));
                            Require(precise != null, "precise public C# method missing");
                            MethodInfo[] bridges = declared.Where(method =>
                                method.Name.StartsWith("<CovariantReturnBridge-", StringComparison.Ordinal)).ToArray();
                            Require(bridges.Length >= 3, "compiler bridges missing");
                            Require(bridges.All(method => method.IsPrivate), "compiler bridge leaked as public API");
                            return 0;
                        }
                    }
                    """.trimIndent()
                )
            }
            val csharpApplication = consumerDirectory.resolve(
                if (target == "net48") "Covariance.CSharpConsumer.exe" else "Covariance.CSharpConsumer.dll"
            )
            val csharpCompile = if (target == "net48") {
                runCSharpCompiler(
                    checkNotNull(frameworkCSharp),
                    csharpSource,
                    csharpApplication,
                    application,
                    libraryDirectory.resolve("Covariance.Library.dll"),
                    consumerDirectory.resolve("Kotlin.Runtime.dll"),
                    checkNotNull(frameworkNetStandardFacade),
                    target = "exe",
                )
            } else {
                runModernCSharpCompiler(
                    checkNotNull(modernCSharp),
                    csharpSource,
                    csharpApplication,
                    application,
                    libraryDirectory.resolve("Covariance.Library.dll"),
                    consumerDirectory.resolve("Kotlin.Runtime.dll"),
                    target = "exe",
                )
            }
            assertEquals(0, csharpCompile.exitCode, csharpCompile.output)
            if (target == "net10.0") {
                consumerDirectory.resolve("Covariance.Consumer.runtimeconfig.json").copyTo(
                    consumerDirectory.resolve("Covariance.CSharpConsumer.runtimeconfig.json"),
                    overwrite = true,
                )
                runDotNet(
                    dotnetHost,
                    csharpApplication,
                    consumerDirectory,
                    "Covariant-return C# consumer failed for $target",
                )
            } else {
                val process = ProcessBuilder(csharpApplication.path)
                    .directory(consumerDirectory)
                    .redirectErrorStream(true)
                    .start()
                val output = process.inputStream.bufferedReader().use { it.readText() }
                assertEquals(0, process.waitFor(), "Covariant-return C# consumer failed for $target:\n$output")
            }
        }

        val refinedDirectory = libraryDirectory.resolve("refined-net10-library").apply { mkdirs() }
        val refinedSource = refinedDirectory.resolve("refined.kt").apply {
            writeText(
                """
                package covariancerefined

                import covarianceabi.*

                public interface RefinedDefaultMaker : DefaultMaker {
                    override fun defaultMake(): Cat = Cat("external-refined-default")
                }
                """.trimIndent()
            )
        }
        compileInProcess(
            K2DotNetCompiler(),
            refinedSource.path,
            K2DotNetCompilerArguments::dotNetProduceLibrary.cliArgument,
            K2DotNetCompilerArguments::classpath.cliArgument, metadataLibrary.path,
            K2DotNetCompilerArguments::dotNetTarget.cliArgument, "net10.0",
            K2DotNetCompilerArguments::moduleName.cliArgument, "Covariance.Refined",
            K2DotNetCompilerArguments::destination.cliArgument, refinedDirectory.path,
        )
        val refinedMetadata = refinedDirectory.resolve("Covariance.Refined.dll")
        val refinedBridgeRecords = DotNetLibraryAbiCodec.decode(refinedMetadata.readKlibManifest()).values
            .filterIsInstance<DotNetPhysicalDeclaration.CovariantReturnBridge>()
        assertEquals(1, refinedBridgeRecords.size, refinedBridgeRecords.joinToString("\n"))
        assertEquals(
            listOf("covariancerefined.RefinedDefaultMaker"),
            refinedBridgeRecords.single().ownerPath,
        )

        val downstreamDirectory = refinedDirectory.resolve("downstream").apply { mkdirs() }
        val downstreamSource = downstreamDirectory.resolve("downstream.kt").apply {
            writeText(
                """
                package covariancedownstream

                import covarianceabi.DefaultMaker
                import covariancerefined.RefinedDefaultMaker

                public class KotlinDefaultMaker : RefinedDefaultMaker

                fun main() {
                    val value: DefaultMaker = KotlinDefaultMaker()
                    if (value.defaultMake().tag != "external-refined-default") {
                        throw Error("external covariant DIM")
                    }
                }
                """.trimIndent()
            )
        }
        val downstreamApplication = downstreamDirectory.resolve("Covariance.Downstream.dll")
        val downstreamClasspath = listOf(refinedMetadata, metadataLibrary)
            .joinToString(File.pathSeparator) { it.path }
        compileInProcess(
            K2DotNetCompiler(),
            downstreamSource.path,
            K2DotNetCompilerArguments::classpath.cliArgument, downstreamClasspath,
            K2DotNetCompilerArguments::dotNetTarget.cliArgument, "net10.0",
            K2DotNetCompilerArguments::moduleName.cliArgument, "Covariance.Downstream",
            K2DotNetCompilerArguments::destination.cliArgument, downstreamApplication.path,
        )
        val downstreamIl = downstreamDirectory.resolve("Covariance.Downstream.il").readText()
        val downstreamClass = Regex(
            "(?s)\\.class public[^\\n]*'covariancedownstream.KotlinDefaultMaker'.*?^}",
            setOf(RegexOption.MULTILINE),
        ).find(downstreamIl)?.value ?: error("KotlinDefaultMaker class missing:\n$downstreamIl")
        assertTrue("<CovariantReturnBridge-" !in downstreamClass) {
            "A producer-recorded interface MethodImpl must suppress a downstream class bridge:\n$downstreamClass"
        }
        runDotNet(
            dotnetHost,
            downstreamApplication,
            downstreamDirectory,
            "Downstream Kotlin consumer of an external covariant DIM failed",
        )

        val downstreamCSharpSource = downstreamDirectory.resolve("downstream.cs").apply {
            writeText(
                """
                using System;

                public sealed class ForeignDefaultMaker : covariancerefined.RefinedDefaultMaker
                {
                }

                public static class Program
                {
                    public static int Main()
                    {
                        covarianceabi.DefaultMaker value = new ForeignDefaultMaker();
                        if (value.defaultMake().tag != "external-refined-default")
                            throw new Exception("external foreign covariant DIM");
                        return 0;
                    }
                }
                """.trimIndent()
            )
        }
        val downstreamCSharpApplication = downstreamDirectory.resolve("Covariance.Downstream.CSharp.dll")
        val downstreamCSharpCompile = runModernCSharpCompiler(
            checkNotNull(modernCSharp),
            downstreamCSharpSource,
            downstreamCSharpApplication,
            refinedDirectory.resolve("Covariance.Refined.dll"),
            libraryDirectory.resolve("Covariance.Library.dll"),
            downstreamDirectory.resolve("Kotlin.Runtime.dll"),
            target = "exe",
        )
        assertEquals(0, downstreamCSharpCompile.exitCode, downstreamCSharpCompile.output)
        downstreamDirectory.resolve("Covariance.Downstream.runtimeconfig.json").copyTo(
            downstreamDirectory.resolve("Covariance.Downstream.CSharp.runtimeconfig.json"),
            overwrite = true,
        )
        runDotNet(
            dotnetHost,
            downstreamCSharpApplication,
            downstreamDirectory,
            "Downstream C# consumer of an external covariant DIM failed",
        )
    }

    @Test
    fun testKotlinExceptionInheritanceAcrossPortableLibraryBoundary() {
        requireOrAssumeToolchain(
            DotNetIlAssembler.findFrameworkIlasm() != null,
            ".NET Framework ILAsm is not available",
        )
        requireOrAssumeToolchain(
            DotNetIlAssembler.findModernIlasm() != null,
            "Modern ILAsm is not available",
        )
        val dotnetHost = modernDotNetHostOrSkip()
        val libraryDirectory = File(tmpdir, "portable-exception-library")
        val librarySource = File(tmpdir, "portable-exception-library.kt").apply {
            writeText(
                """
                package crossfailure

                public open class LibraryRuntimeFailure(message: String) : RuntimeException(message)

                public class LibraryRuntimeChild(message: String) : LibraryRuntimeFailure(message)

                public class LibraryFatalFailure(message: String) : Error(message)

                public fun libraryRuntimeFailure(): Throwable = LibraryRuntimeChild("library-runtime")

                public fun libraryFatalFailure(): Throwable = LibraryFatalFailure("library-fatal")

                public fun classifySupplied(value: Throwable): Int = try {
                    throw value
                } catch (failure: LibraryRuntimeFailure) {
                    2
                } catch (failure: RuntimeException) {
                    3
                } catch (failure: Exception) {
                    1
                } catch (failure: Error) {
                    4
                } catch (failure: Throwable) {
                    0
                }
                """.trimIndent()
            )
        }
        compileInProcess(
            K2DotNetCompiler(),
            librarySource.path,
            K2DotNetCompilerArguments::dotNetProduceLibrary.cliArgument,
            K2DotNetCompilerArguments::dotNetTarget.cliArgument, "netstandard2.0",
            K2DotNetCompilerArguments::moduleName.cliArgument, "Exception.Library",
            K2DotNetCompilerArguments::destination.cliArgument, libraryDirectory.path,
        )

        val metadataLibrary = libraryDirectory.resolve("Exception.Library.dll")
        val libraryIl = libraryDirectory.resolve("Exception.Library.il").readText()
        assertTrue(
            Regex(
                "'crossfailure\\.LibraryRuntimeFailure'\\s+extends " +
                        "\\[Kotlin\\.Runtime]'Kotlin\\.RuntimeException'"
            ).containsMatchIn(libraryIl)
        ) { libraryIl }
        assertTrue(
            Regex(
                "'crossfailure\\.LibraryRuntimeChild'\\s+extends " +
                        "'crossfailure\\.LibraryRuntimeFailure'"
            ).containsMatchIn(libraryIl)
        ) { libraryIl }
        assertTrue(
            Regex(
                "'crossfailure\\.LibraryFatalFailure'\\s+extends \\[Kotlin\\.Runtime]'Kotlin\\.Error'"
            ).containsMatchIn(libraryIl)
        ) { libraryIl }

        for (target in listOf("net48", "net10.0")) {
            val consumerDirectory = libraryDirectory.resolve("consumer-${target.replace('.', '-')}").apply { mkdirs() }
            val consumerSource = consumerDirectory.resolve("consumer.kt").apply {
                writeText(
                    """
                    package exceptionconsumer

                    import crossfailure.*

                    private class ConsumerRuntimeChild(message: String) : LibraryRuntimeFailure(message)

                    private fun caughtAsLibraryType(value: Throwable): Boolean = try {
                        throw value
                    } catch (failure: LibraryRuntimeFailure) {
                        failure === value
                    } catch (failure: Throwable) {
                        false
                    }

                    private fun caughtAsRuntime(value: Throwable): Boolean = try {
                        throw value
                    } catch (failure: RuntimeException) {
                        failure === value
                    } catch (failure: Throwable) {
                        false
                    }

                    fun main() {
                        val libraryRuntime = libraryRuntimeFailure()
                        if (libraryRuntime !is LibraryRuntimeChild ||
                            libraryRuntime !is LibraryRuntimeFailure ||
                            libraryRuntime !is RuntimeException ||
                            libraryRuntime !is Exception ||
                            libraryRuntime is Error
                        ) {
                            throw Error("portable library runtime classification")
                        }
                        if (!caughtAsLibraryType(libraryRuntime) || !caughtAsRuntime(libraryRuntime)) {
                            throw Error("portable library runtime catch/identity")
                        }

                        val consumerRuntime: Throwable = ConsumerRuntimeChild("consumer-runtime")
                        if (consumerRuntime !is LibraryRuntimeFailure ||
                            consumerRuntime !is RuntimeException ||
                            !caughtAsLibraryType(consumerRuntime) ||
                            !caughtAsRuntime(consumerRuntime) ||
                            classifySupplied(consumerRuntime) != 2
                        ) {
                            throw Error("consumer subclass of portable exception")
                        }

                        if (classifySupplied(IllegalStateException("mapped-runtime")) != 3) {
                            throw Error("portable library mapped-runtime classification")
                        }
                        if (classifySupplied(Exception("plain")) != 1) {
                            throw Error("portable library plain-exception classification")
                        }
                        if (classifySupplied(Error("application-fatal")) != 4) {
                            throw Error("portable library application-error classification")
                        }

                        val libraryFatal = libraryFatalFailure()
                        if (libraryFatal !is LibraryFatalFailure ||
                            libraryFatal !is Error ||
                            libraryFatal is Exception ||
                            caughtAsRuntime(libraryFatal)
                        ) {
                            throw Error("portable library error classification")
                        }
                    }
                    """.trimIndent()
                )
            }
            val application = consumerDirectory.resolve(
                if (target == "net48") "ExceptionConsumer.exe" else "ExceptionConsumer.dll"
            )
            compileInProcess(
                K2DotNetCompiler(),
                consumerSource.path,
                K2DotNetCompilerArguments::classpath.cliArgument, metadataLibrary.path,
                K2DotNetCompilerArguments::dotNetTarget.cliArgument, target,
                K2DotNetCompilerArguments::moduleName.cliArgument, "ExceptionConsumer",
                K2DotNetCompilerArguments::destination.cliArgument, application.path,
            )
            assertTrue(consumerDirectory.resolve("Exception.Library.dll").isFile) {
                "The portable exception implementation must be packaged beside its $target consumer"
            }
            val consumerIl = consumerDirectory.resolve("ExceptionConsumer.il").readText()
            assertTrue("[Exception.Library]'crossfailure.LibraryRuntimeFailure'" in consumerIl) { consumerIl }
            assertTrue("filter" in consumerIl) { consumerIl }

            if (target == "net10.0") {
                runDotNet(
                    dotnetHost,
                    application,
                    consumerDirectory,
                    "Portable exception consumer failed for $target",
                )
            } else {
                val process = ProcessBuilder(application.path)
                    .directory(consumerDirectory)
                    .redirectErrorStream(true)
                    .start()
                val output = process.inputStream.bufferedReader().use { it.readText() }
                assertEquals(0, process.waitFor(), "Portable exception consumer failed for $target:\n$output")
            }
        }
    }

    @Test
    fun testExceptionOverloadAbi() {
        requireOrAssumeToolchain(
            DotNetIlAssembler.findFrameworkIlasm() != null,
            ".NET Framework ILAsm is not available",
        )
        requireOrAssumeToolchain(
            DotNetIlAssembler.findModernIlasm() != null,
            "Modern ILAsm is not available",
        )
        val dotnetHost = modernDotNetHostOrSkip()
        val libraryDirectory = File(tmpdir, "portable-exception-overload-library")
        val librarySource = File(tmpdir, "portable-exception-overload-library.kt").apply {
            writeText(
                """
                package exceptionoverload

                public fun classify(value: Throwable): Int = 1
                public fun classify(value: Exception): Int = 2
                public fun classify(value: RuntimeException): Int = 3
                public fun classify(value: Error): Int = 4

                public open class BaseClassifier {
                    public open fun classify(value: Throwable): Int = 11
                    public open fun classify(value: Exception): Int = 12
                    public open fun classify(value: RuntimeException): Int = 13
                    public open fun classify(value: Error): Int = 14
                }

                private class DerivedClassifier : BaseClassifier() {
                    override fun classify(value: Throwable): Int = 21
                    override fun classify(value: Exception): Int = 22
                    override fun classify(value: RuntimeException): Int = 23
                    override fun classify(value: Error): Int = 24
                }

                public interface Classifier {
                    public fun classify(value: Throwable): Int
                    public fun classify(value: Exception): Int
                    public fun classify(value: RuntimeException): Int
                    public fun classify(value: Error): Int
                }

                private class InterfaceClassifier : Classifier {
                    override fun classify(value: Throwable): Int = 31
                    override fun classify(value: Exception): Int = 32
                    override fun classify(value: RuntimeException): Int = 33
                    override fun classify(value: Error): Int = 34
                }

                public interface GenericClassifier<T> {
                    public fun classify(value: Throwable): Int
                    public fun classify(value: Exception): Int
                }

                private class GenericClassifierImpl : GenericClassifier<String> {
                    override fun classify(value: Throwable): Int = 51
                    override fun classify(value: Exception): Int = 52
                }

                public open class GenericBaseClassifier<T> {
                    public open fun select(value: T): Int = 61
                }

                private class ThrowableBaseClassifier : GenericBaseClassifier<Throwable>() {
                    override fun select(value: Throwable): Int = 62
                }

                public interface ThrowableSelector {
                    public fun select(value: Throwable): Int
                }

                private class CombinedClassifier : GenericBaseClassifier<Throwable>(), ThrowableSelector {
                    override fun select(value: Throwable): Int = 71
                }

                public class ExceptionBox<T>(public val value: T)

                public fun nested(value: ExceptionBox<Throwable>): Int = 41
                public fun nested(value: ExceptionBox<Exception>): Int = 42

                public fun derivedClassifier(): BaseClassifier = DerivedClassifier()
                public fun interfaceClassifier(): Classifier = InterfaceClassifier()
                public fun genericClassifier(): GenericClassifier<String> = GenericClassifierImpl()
                public fun genericBaseClassifier(): GenericBaseClassifier<Throwable> = ThrowableBaseClassifier()
                public fun combinedBaseClassifier(): GenericBaseClassifier<Throwable> = CombinedClassifier()
                public fun combinedInterfaceClassifier(): ThrowableSelector = CombinedClassifier()
                """.trimIndent()
            )
        }
        compileInProcess(
            K2DotNetCompiler(),
            librarySource.path,
            K2DotNetCompilerArguments::dotNetProduceLibrary.cliArgument,
            K2DotNetCompilerArguments::dotNetTarget.cliArgument, "netstandard2.0",
            K2DotNetCompilerArguments::moduleName.cliArgument, "Exception.Overloads",
            K2DotNetCompilerArguments::destination.cliArgument, libraryDirectory.path,
        )

        val metadataLibrary = libraryDirectory.resolve("Exception.Overloads.dll")
        val libraryIl = libraryDirectory.resolve("Exception.Overloads.il").readText()
        assertEquals(
            22,
            Regex("\\.method [^\\n]*'classify__KotlinException__[0-9a-f]{32}'")
                .findAll(libraryIl)
                .count(),
            libraryIl,
        )
        assertEquals(
            2,
            Regex("\\.method [^\\n]*'classify__KotlinErased__[0-9a-f]{32}'")
                .findAll(libraryIl)
                .count(),
            libraryIl,
        )
        assertEquals(
            2,
            Regex("\\.method [^\\n]*'nested__KotlinException__[0-9a-f]{32}'").findAll(libraryIl).count(),
            libraryIl,
        )
        assertTrue("'classify'(class [netstandard]System.Exception" !in libraryIl) { libraryIl }

        for (target in listOf("net48", "net10.0")) {
            val consumerDirectory = libraryDirectory.resolve("consumer-${target.replace('.', '-')}").apply { mkdirs() }
            val consumerSource = consumerDirectory.resolve("consumer.kt").apply {
                writeText(
                    """
                    package exceptionoverloadconsumer

                    import exceptionoverload.*

                    fun main() {
                        val throwable: Throwable = Exception("throwable")
                        val exception: Exception = Exception("exception")
                        val runtime: RuntimeException = RuntimeException("runtime")
                        val error: Error = Error("error")

                        if (classify(throwable) != 1 || classify(exception) != 2 ||
                            classify(runtime) != 3 || classify(error) != 4
                        ) {
                            throw Error("top-level classified exception overload")
                        }

                        val member: BaseClassifier = derivedClassifier()
                        if (member.classify(throwable) != 21 || member.classify(exception) != 22 ||
                            member.classify(runtime) != 23 || member.classify(error) != 24
                        ) {
                            throw Error("virtual classified exception overload")
                        }

                        val interfaceValue: Classifier = interfaceClassifier()
                        if (interfaceValue.classify(throwable) != 31 || interfaceValue.classify(exception) != 32 ||
                            interfaceValue.classify(runtime) != 33 || interfaceValue.classify(error) != 34
                        ) {
                            throw Error("interface classified exception overload")
                        }

                        val genericValue: GenericClassifier<String> = genericClassifier()
                        if (genericValue.classify(throwable) != 51 || genericValue.classify(exception) != 52) {
                            throw Error("generic-interface classified exception overload")
                        }

                        val genericBase: GenericBaseClassifier<Throwable> = genericBaseClassifier()
                        if (genericBase.select(throwable) != 62) {
                            throw Error("generic-base classified exception override")
                        }

                        if (combinedBaseClassifier().select(throwable) != 71 ||
                            combinedInterfaceClassifier().select(throwable) != 71
                        ) {
                            throw Error("multi-slot classified exception override")
                        }

                        if (nested(ExceptionBox<Throwable>(throwable)) != 41 ||
                            nested(ExceptionBox<Exception>(exception)) != 42
                        ) {
                            throw Error("nested classified exception overload")
                        }
                    }
                    """.trimIndent()
                )
            }
            val application = consumerDirectory.resolve(
                if (target == "net48") "ExceptionOverloadConsumer.exe" else "ExceptionOverloadConsumer.dll"
            )
            compileInProcess(
                K2DotNetCompiler(),
                consumerSource.path,
                K2DotNetCompilerArguments::classpath.cliArgument, metadataLibrary.path,
                K2DotNetCompilerArguments::dotNetTarget.cliArgument, target,
                K2DotNetCompilerArguments::moduleName.cliArgument, "ExceptionOverloadConsumer",
                K2DotNetCompilerArguments::destination.cliArgument, application.path,
            )
            assertTrue(consumerDirectory.resolve("Exception.Overloads.dll").isFile) {
                "The portable overload implementation must be packaged beside its $target consumer"
            }

            if (target == "net10.0") {
                runDotNet(
                    dotnetHost,
                    application,
                    consumerDirectory,
                    "Portable exception-overload consumer failed for $target",
                )
            } else {
                val process = ProcessBuilder(application.path)
                    .directory(consumerDirectory)
                    .redirectErrorStream(true)
                    .start()
                val output = process.inputStream.bufferedReader().use { it.readText() }
                assertEquals(0, process.waitFor(), "Portable exception-overload consumer failed for $target:\n$output")
            }
        }
    }

    @Test
    fun testExceptionSignaturePositions() {
        requireOrAssumeToolchain(
            DotNetIlAssembler.findFrameworkIlasm() != null,
            ".NET Framework ILAsm is not available",
        )
        requireOrAssumeToolchain(
            DotNetIlAssembler.findModernIlasm() != null,
