        val libraryIl = libraryDirectory.resolve("Exception.ArrayCallable.il").readText()
        assertEquals(
            2,
            Regex("\\.method [^\\n]*'arrayKind__KotlinException__[0-9a-f]{32}'")
                .findAll(libraryIl)
                .count(),
            libraryIl,
