        sourceFiles += File("libraries/stdlib/src/kotlin/reflect/KCallable.kt").absoluteFile
        sourceFiles += File("libraries/stdlib/src/kotlin/reflect/KFunction.kt").absoluteFile
        sourceFiles += File("libraries/stdlib/src/kotlin/reflect/KProperty.kt").absoluteFile
        sourceFiles += File("libraries/stdlib/src/kotlin/reflect/KClasses.kt").absoluteFile
        sourceFiles += File("libraries/stdlib/src/kotlin/reflect/KClassifier.kt").absoluteFile
        sourceFiles += File("libraries/stdlib/src/kotlin/reflect/KType.kt").absoluteFile
        sourceFiles += File("libraries/stdlib/src/kotlin/reflect/KTypeParameter.kt").absoluteFile
        sourceFiles += File("libraries/stdlib/src/kotlin/reflect/KTypeProjection.kt").absoluteFile
        sourceFiles += File("libraries/stdlib/src/kotlin/reflect/KVariance.kt").absoluteFile
        sourceFiles += File("libraries/stdlib/jvm/src/kotlin/reflect/KVisibility.kt").absoluteFile
        sourceFiles += File("libraries/stdlib/jvm/src/kotlin/reflect/KDeclarationContainer.kt").absoluteFile
        sourceFiles += File("libraries/stdlib/src/kotlin/reflect/typeOf.kt").absoluteFile
        sourceFiles += File("libraries/stdlib/common-non-jvm/src/kotlin/Exceptions.kt").absoluteFile
        sourceFiles += File("libraries/stdlib/common-non-jvm/src/kotlin/internal/SharedVariableBox.kt").absoluteFile
        sourceFiles += File("libraries/stdlib/common-non-jvm/src/kotlin/internal/SyntheticConstructorMarker.kt").absoluteFile
        sourceFiles += File("libraries/stdlib/common-non-jvm/src/kotlin/internal/ThrowHelpers.kt").absoluteFile
        sourceFiles += File("libraries/stdlib/common-non-jvm/src/kotlin/reflect/KTypeParameterBase.kt").absoluteFile
        sourceFiles.sortBy(File::invariantSeparatorsPath)
        assertEquals(DOTNET_STDLIB_SOURCES.keys.sorted(), sourceFiles.map(File::getName).sorted())
        for (sourceFile in sourceFiles) {
            assertEquals(
                sourceFile.readText(),
                DOTNET_STDLIB_SOURCES.getValue(sourceFile.name),
                "Packaged fallback source differs from ${sourceFile.path}",
            )
        }
        return sourceFiles
    }

    private fun dotNetReflectionSourceFiles(): List<File> {
        val sourceDirectory = File("libraries/reflect/dotnet/src").absoluteFile
        assertTrue(sourceDirectory.isDirectory) {
            "Missing ordinary Kotlin/.NET reflection source directory: $sourceDirectory"
        }
        val sourceFiles = sourceDirectory.walkTopDown()
            .filter(File::isFile)
            .filter { file -> file.extension == "kt" }
            .sortedBy(File::invariantSeparatorsPath)
            .toList()
        assertEquals(DOTNET_REFLECTION_SOURCES.keys.sorted(), sourceFiles.map(File::getName).sorted())
        for (sourceFile in sourceFiles) {
            assertEquals(
                sourceFile.readText(),
                DOTNET_REFLECTION_SOURCES.getValue(sourceFile.name),
                "Packaged reflection source differs from ${sourceFile.path}",
            )
        }
        return sourceFiles
    }

    private fun assertKlibPayloadEquals(expected: File, actual: File, message: String) {
        assertEquals(expected.readKlibManifest(), actual.readKlibManifest(), "$message: manifest")
        val expectedEntries = expected.readKlibPayloadEntries()
        val actualEntries = actual.readKlibPayloadEntries()
        assertEquals(expectedEntries.keys, actualEntries.keys, "$message: entry names")
        for (entryName in expectedEntries.keys.sorted()) {
            assertArrayEquals(
                expectedEntries.getValue(entryName),
                actualEntries.getValue(entryName),
                "$message: $entryName",
            )
        }
        assertArrayEquals(
            expected.readKlibCarrier(),
            actual.readKlibCarrier(),
            "$message: packed KLIB",
        )
    }

    private fun consumeSelfDescribingStdlib(stdlibDirectory: File, target: String) {
        val metadataLibrary = stdlibDirectory.resolve("Kotlin.Stdlib.dll")
        val coreLibraryReference = if (target == "netstandard2.0") "[netstandard]" else "[mscorlib]"
        val consumerSource = stdlibDirectory.resolve("consumer.kt").apply {
            writeText(
                """
                package consumer

                public fun <T> firstAndLast(values: Iterable<T>): T {
                    values.first()
                    return values.last()
                }

                public fun <T> firstAndLastList(values: List<T>): T {
                    values.first()
                    return values.last()
                }

                public fun <T> optionalEnds(values: Iterable<T>): T? {
                    values.firstOrNull()
                    return values.lastOrNull()
                }

                public fun <T> optionalListEnds(values: List<T>): T? {
                    values.firstOrNull()
                    return values.lastOrNull()
                }

                public fun <T> firstMatching(
                    values: Iterable<T>,
                    predicate: (T) -> Boolean,
                ): T = values.first(predicate)

                public fun <T> firstMatchingOrNull(
                    values: Iterable<T>,
                    predicate: (T) -> Boolean,
                ): T? = values.firstOrNull(predicate)

                public fun <T> lastMatching(
                    values: Iterable<T>,
                    predicate: (T) -> Boolean,
                ): T = values.last(predicate)

                public fun <T> lastMatchingOrNull(
                    values: Iterable<T>,
                    predicate: (T) -> Boolean,
                ): T? = values.lastOrNull(predicate)

                public fun <T> lastListMatching(
                    values: List<T>,
                    predicate: (T) -> Boolean,
                ): T = values.last(predicate)

                public fun <T> lastListMatchingOrNull(
                    values: List<T>,
                    predicate: (T) -> Boolean,
                ): T? = values.lastOrNull(predicate)

                public fun <T> singleMatching(
                    values: Iterable<T>,
                    predicate: (T) -> Boolean,
                ): T = values.single(predicate)

                public fun <T> singleMatchingOrNull(
                    values: Iterable<T>,
                    predicate: (T) -> Boolean,
                ): T? = values.singleOrNull(predicate)

                public fun <T> optionalAt(values: Iterable<T>, index: Int): T? =
                    values.elementAtOrNull(index)

                public fun <T> optionalListGet(values: List<T>, index: Int): T? =
                    values.getOrNull(index)

                public fun <T> optionalListAt(values: List<T>, index: Int): T? =
                    values.elementAtOrNull(index)

                public fun <T> elementCount(values: Iterable<T>): Int = values.count()

                public fun <T> inlineOnlyCollectionCount(values: Collection<T>): Int = values.count()

                public fun <T> inlineOnlyIterableIdentity(values: Iterable<T>): Iterable<T> =
                    values.asIterable()

                public fun <T> inlineOnlyListElements(values: List<T>, index: Int): T? {
                    values.component1()
                    values.component2()
                    values.component3()
                    values.component4()
                    values.component5()
                    values.elementAt(index)
                    return values.elementAtOrNull(index)
                }

                public fun <T> inlineOnlyFind(
                    values: Iterable<T>,
                    predicate: (T) -> Boolean,
                ): T? = values.find(predicate)

                public fun <T> inlineOnlyFindLast(
                    values: Iterable<T>,
                    predicate: (T) -> Boolean,
                ): T? = values.findLast(predicate)

                public fun <T> inlineOnlyListFindLast(
                    values: List<T>,
                    predicate: (T) -> Boolean,
                ): T? = values.findLast(predicate)

                public fun <T, R : Any> inlineOnlyFirstNotNullOf(
                    values: Iterable<T>,
                    transform: (T) -> R?,
                ): R = values.firstNotNullOf(transform)

                public fun <T, R : Any> inlineOnlyFirstNotNullOfOrNull(
                    values: Iterable<T>,
                    transform: (T) -> R?,
                ): R? = values.firstNotNullOfOrNull(transform)

                public fun <T, R> foldLeft(
                    values: Iterable<T>,
                    initial: R,
                    operation: (R, T) -> R,
                ): R = values.fold(initial, operation)

                public fun <T, R> foldLeftIndexed(
                    values: Iterable<T>,
                    initial: R,
                    operation: (Int, R, T) -> R,
                ): R = values.foldIndexed(initial, operation)

                public fun <T, R> foldListRight(
                    values: List<T>,
                    initial: R,
                    operation: (T, R) -> R,
                ): R = values.foldRight(initial, operation)

                public fun <T, R> foldListRightIndexed(
                    values: List<T>,
                    initial: R,
                    operation: (Int, T, R) -> R,
                ): R = values.foldRightIndexed(initial, operation)

                public fun <T> iterateAll(
                    values: Iterable<T>,
                    action: (T) -> Unit,
                ): Unit = values.forEach(action)

                public fun <T> iterateAllIndexed(
                    values: Iterable<T>,
                    action: (Int, T) -> Unit,
                ): Unit = values.forEachIndexed(action)

                public fun <T, C : Iterable<T>> observeEach(
                    values: C,
                    action: (T) -> Unit,
                ): C = values.onEach(action)

                public fun <T, C : Iterable<T>> observeEachIndexed(
                    values: C,
                    action: (Int, T) -> Unit,
                ): C = values.onEachIndexed(action)

                public fun <S, T : S> reduceLeft(
                    values: Iterable<T>,
                    operation: (S, T) -> S,
                ): S = values.reduce(operation)

                public fun <S, T : S> reduceLeftIndexed(
                    values: Iterable<T>,
                    operation: (Int, S, T) -> S,
                ): S = values.reduceIndexed(operation)

                public fun <S, T : S> reduceLeftOrNull(
                    values: Iterable<T>,
                    operation: (S, T) -> S,
                ): S? = values.reduceOrNull(operation)

                public fun <S, T : S> reduceLeftIndexedOrNull(
                    values: Iterable<T>,
                    operation: (Int, S, T) -> S,
                ): S? = values.reduceIndexedOrNull(operation)

                public fun <S, T : S> reduceListRight(
                    values: List<T>,
                    operation: (T, S) -> S,
                ): S = values.reduceRight(operation)

                public fun <S, T : S> reduceListRightIndexed(
                    values: List<T>,
                    operation: (Int, T, S) -> S,
                ): S = values.reduceRightIndexed(operation)

                public fun <S, T : S> reduceListRightOrNull(
                    values: List<T>,
                    operation: (T, S) -> S,
                ): S? = values.reduceRightOrNull(operation)

                public fun <S, T : S> reduceListRightIndexedOrNull(
                    values: List<T>,
                    operation: (Int, T, S) -> S,
                ): S? = values.reduceRightIndexedOrNull(operation)

                public fun sumBytes(values: Iterable<Byte>): Int = values.sum()

                public fun sumShorts(values: Iterable<Short>): Int = values.sum()

                public fun sumInts(values: Iterable<Int>): Int = values.sum()

                public fun sumLongs(values: Iterable<Long>): Long = values.sum()

                public fun sumFloats(values: Iterable<Float>): Float = values.sum()

                public fun sumDoubles(values: Iterable<Double>): Double = values.sum()

                public fun averageBytes(values: Iterable<Byte>): Double = values.average()

                public fun averageShorts(values: Iterable<Short>): Double = values.average()

                public fun averageInts(values: Iterable<Int>): Double = values.average()

                public fun averageLongs(values: Iterable<Long>): Double = values.average()

                public fun averageFloats(values: Iterable<Float>): Double = values.average()

                public fun averageDoubles(values: Iterable<Double>): Double = values.average()

