                public fun <T> sumOfSelectedLongs(values: Iterable<T>, selector: (T) -> Long): Long =
                    values.sumOf(selector)

                public fun <T> sumOfSelectedDoubles(values: Iterable<T>, selector: (T) -> Double): Double =
                    values.sumOf(selector)

                @Suppress("DEPRECATION")
                public fun sumSelectedNonLocal(values: Iterable<Int>): Int {
                    values.sumBy { value ->
                        if (value == 2) return 23
                        value
                    }
                    return -1
                }

                public fun <T : Any> requireIterableValues(values: Iterable<T?>): Iterable<T> =
                    values.requireNoNulls()

                public fun <T : Any> requireListValues(values: List<T?>): List<T> =
                    values.requireNoNulls()

                public fun <T> containsElement(values: Iterable<T>, element: T): Boolean =
                    values.contains(element)

                public fun <T> allMatching(
                    values: Iterable<T>,
                    predicate: (T) -> Boolean,
                ): Boolean = values.all(predicate)

                public fun <T> anyMatching(
                    values: Iterable<T>,
                    predicate: (T) -> Boolean,
                ): Boolean = values.any(predicate)

