        val invalidBoundOutput = File(tmpdir, "invalid-stdlib-bound-$target.il")
        val [invalidBoundDiagnostics, invalidBoundExitCode] = AbstractCliTest.executeCompilerGrabOutput(
            K2DotNetCompiler(),
            listOf(
                invalidBoundSource.path,
