                    try {
                        TODO()
                    } catch (failure: NotImplementedError) {
                        noReason = failure.message == "An operation is not implemented." && failure.cause == null
                    }
                    var withReason = false
                    try {
                        TODO("reason")
                    } catch (failure: NotImplementedError) {
                        withReason = failure.message == "An operation is not implemented: reason"
                    }
                    return noReason && withReason
                }

                public fun installedBuilders(): Boolean {
                    val firstAssigned: String
                    val first = buildString {
                        firstAssigned = "first"
                        append('O')
                        append('K')
                    }
                    val secondAssigned: String
                    val second = buildString(2) {
                        secondAssigned = "second"
                        append("OK")
                    }
                    var rejectedNegativeCapacity = false
                    try {
                        buildString(-1) { append("unreachable") }
                    } catch (_: IllegalArgumentException) {
                        rejectedNegativeCapacity = true
                    }
                    return firstAssigned == "first" &&
                        secondAssigned == "second" &&
                        first == "OK" &&
                        second == "OK" &&
                        rejectedNegativeCapacity
                }

                fun main() {
                    val values = Array<String>(2) { index -> if (index == 0) "O" else "K" }
                    val kClassOk = installedKClassFloor()
                    val owner = RuntimeException("owner")
                    val suppressed = IllegalStateException("suppressed")
                    owner.addSuppressed(suppressed)
                    val snapshot = owner.suppressedExceptions
                    val view = values.asList()
                    values[0] = "changed"
                    val mutable = mutableListOf<Int?>(1, null, 3)
                    val mutableRoundTrip = installedMutableRoundTrip(mutable, 4)
                    val mutableView = mutable.subList(0, 2)
                    mutableView[0] = 2
                    val staleMutableIterator = mutable.iterator()
                    mutable.add(5)
                    var mutableFailFast = false
                    try {
                        staleMutableIterator.next()
                    } catch (_: ConcurrentModificationException) {
                        mutableFailFast = true
                    }
                    var escapedBuilder: MutableList<Int>? = null
                    val builtList = buildList {
                        escapedBuilder = this
                        add(6)
                        add(7)
                    }
                    var builderSealed = false
                    try {
                        escapedBuilder!!.add(8)
                    } catch (_: UnsupportedOperationException) {
                        builderSealed = true
                    }
