    private fun runCSharpCompiler(
        compiler: File,
        source: File,
        output: File,
        vararg references: File,
        target: String = "library",
    ): CSharpCompilerResult {
        output.delete()
        val arguments = buildList {
            add(compiler.path)
            add("/nologo")
            add("/target:$target")
            add("/out:${output.path}")
            references.forEach { add("/reference:${it.path}") }
            add(source.path)
        }
        val process = ProcessBuilder(arguments)
            .directory(tmpdir)
            .redirectErrorStream(true)
            .start()
        val compilerOutput = process.inputStream.bufferedReader().use { it.readText() }
        return CSharpCompilerResult(process.waitFor(), compilerOutput)
    }

    private fun runModernCSharpCompiler(
        toolchain: DotNetModernCSharpToolchain,
        source: File,
        output: File,
        vararg references: File,
        target: String = "library",
        analyzers: List<File> = emptyList(),
        generatedFilesDirectory: File? = null,
        resources: List<Pair<File, String>> = emptyList(),
        additionalArguments: List<String> = emptyList(),
    ): CSharpCompilerResult {
        output.delete()
        val frameworkReferences = toolchain.referenceDirectory.listFiles { file ->
            file.isFile && file.extension.equals("dll", ignoreCase = true)
        }?.sortedBy(File::getName)
            ?: error("Modern C# reference directory is unreadable: ${toolchain.referenceDirectory}")
        val arguments = buildList {
            add(toolchain.dotNetHost.path)
            add(toolchain.compiler.path)
            add("/nologo")
            add("/noconfig")
            add("/nostdlib+")
            add("/deterministic+")
            add("/langversion:latest")
            add("/target:$target")
            add("/out:${output.path}")
            frameworkReferences.forEach { add("/reference:${it.path}") }
            references.forEach { reference ->
                assertTrue(reference.isFile) { "Missing C# reference: $reference" }
                add("/reference:${reference.path}")
            }
            analyzers.forEach { analyzer ->
                assertTrue(analyzer.isFile) { "Missing C# analyzer: $analyzer" }
                add("/analyzer:${analyzer.path}")
            }
            resources.forEach { resourceEntry ->
                val resource = resourceEntry.first
                val logicalName = resourceEntry.second
                assertTrue(resource.isFile) { "Missing C# resource: $resource" }
                require('/' !in logicalName && '\\' !in logicalName && ':' !in logicalName) {
                    "Unsafe C# resource logical name: $logicalName"
                }
                add("/resource:${resource.path},$logicalName,public")
            }
            generatedFilesDirectory?.let { directory ->
                directory.mkdirs()
                add("/generatedfilesout:${directory.path}")
            }
            addAll(additionalArguments)
            add(source.path)
        }
        val process = ProcessBuilder(arguments)
            .directory(tmpdir)
            .redirectErrorStream(true)
            .start()
        val compilerOutput = process.inputStream.bufferedReader().use { it.readText() }
        return CSharpCompilerResult(process.waitFor(), compilerOutput)
    }

    private fun buildCSharpAuthoringTooling(
        toolchain: DotNetModernCSharpToolchain,
    ): File {
        val project = File(
            "compiler/ir/backend.dotnet/csharp-authoring/" +
                    "Kotlin.DotNet.CSharpAuthoring/Kotlin.DotNet.CSharpAuthoring.csproj"
        ).absoluteFile
        assertTrue(project.isFile) { "Missing Kotlin C# authoring project: $project" }
        val process = ProcessBuilder(
            toolchain.dotNetHost.path,
            "build",
            project.path,
            "--configuration", "Release",
            "-p:RestoreLockedMode=true",
            "--nologo",
        )
            .directory(File(".").absoluteFile)
            .redirectErrorStream(true)
            .start()
        val output = process.inputStream.bufferedReader().use { it.readText() }
        assertEquals(0, process.waitFor(), "Could not build Kotlin C# authoring tooling:\n$output")
        return project.parentFile
            .resolve("bin/Release/netstandard2.0/Kotlin.DotNet.CSharpAuthoring.dll")
            .also { assembly ->
                assertTrue(assembly.isFile) {
                    "Kotlin C# authoring build produced no analyzer assembly:\n$output"
                }
            }
    }

    private fun compileInProcess(compiler: CLICompiler<*>, vararg args: String): String {
        val [output, exitCode] = AbstractCliTest.executeCompilerGrabOutput(compiler, args.toList())
        if (exitCode != ExitCode.OK) error("Failed to compile: ${args.joinToString(" ")}\nOutput:\n$output")
        return output
    }

    private fun modernDotNetHostOrSkip(): File {
        val host = DotNetIlAssembler.findModernDotNetHost()
        requireOrAssumeToolchain(host != null, "Modern dotnet host is not available")
        return checkNotNull(host)
    }

    private fun findFrameworkNetStandardFacade(): File? {
        val windowsDirectory = System.getenv("WINDIR")?.let(::File)
        val programFilesX86 = System.getenv("ProgramFiles(x86)")?.let(::File)
        val candidates = listOfNotNull(
            programFilesX86?.resolve(
                "Reference Assemblies/Microsoft/Framework/.NETFramework/v4.8/Facades/netstandard.dll"
            ),
            windowsDirectory?.resolve(
                "Microsoft.NET/assembly/GAC_MSIL/netstandard/" +
                        "v4.0_2.0.0.0__cc7b13ffcd2ddd51/netstandard.dll"
            ),
        )
        return candidates.firstOrNull { candidate -> candidate.isFile }
    }

    private fun frameworkExecutionCommand(host: File, assembly: File): List<String> {
        val escapedAssemblyPath = assembly.absolutePath.replace("'", "''")
        val command = """
            ${'$'}ErrorActionPreference = 'Stop'
            try {
                ${'$'}assembly = [Reflection.Assembly]::LoadFrom('$escapedAssemblyPath')
                ${'$'}entryPoint = ${'$'}assembly.EntryPoint
                if (${'$'}null -eq ${'$'}entryPoint) { throw 'Assembly has no managed entry point.' }
                if (${'$'}entryPoint.GetParameters().Count -eq 0) {
                    [void] ${'$'}entryPoint.Invoke(${'$'}null, ${'$'}null)
                } else {
                    [void] ${'$'}entryPoint.Invoke(${'$'}null, [object[]] @(,[string[]] @()))
                }
            } catch {
                [Console]::Error.WriteLine(${'$'}_.Exception.ToString())
                exit 1
            }
        """.trimIndent()
        return listOf(host.path, "-NoLogo", "-NoProfile", "-NonInteractive", "-Command", command)
    }

    private fun readFrameworkManagedResource(
        host: File,
        assembly: File,
        resourceName: String,
    ): ByteArray {
        val escapedAssemblyPath = assembly.absolutePath.replace("'", "''")
        val escapedResourceName = resourceName.replace("'", "''")
        val command = """
            ${'$'}ErrorActionPreference = 'Stop'
            try {
                ${'$'}assembly = [Reflection.Assembly]::ReflectionOnlyLoadFrom('$escapedAssemblyPath')
                ${'$'}stream = ${'$'}assembly.GetManifestResourceStream('$escapedResourceName')
                if (${'$'}null -eq ${'$'}stream) { throw 'Assembly has no requested managed resource.' }
                try {
                    ${'$'}buffer = New-Object IO.MemoryStream
                    ${'$'}stream.CopyTo(${'$'}buffer)
                    [Console]::Out.Write([Convert]::ToBase64String(${'$'}buffer.ToArray()))
                } finally {
                    ${'$'}stream.Dispose()
                }
            } catch {
                [Console]::Error.WriteLine(${'$'}_.Exception.ToString())
                exit 1
            }
        """.trimIndent()
        val process = ProcessBuilder(
            host.path,
            "-NoLogo",
            "-NoProfile",
            "-NonInteractive",
            "-Command",
            command,
        )
            .directory(assembly.parentFile ?: File("."))
            .redirectErrorStream(true)
            .start()
        val output = process.inputStream.bufferedReader().use { it.readText() }
        assertEquals(
            0,
            process.waitFor(),
            "Could not read managed resource '$resourceName' from $assembly:\n$output",
        )
        return Base64.getDecoder().decode(output.trim())
    }

    private fun readCSharpImplementationManifestEnvelope(
        assembly: File,
    ): DotNetCSharpImplementationManifest {
        val image = assembly.readBytes()
        val envelopeOffset = findCSharpImplementationManifestEnvelope(image)
        val payloadSize = readLittleEndianInt(image, envelopeOffset + 12)
        val envelopeSize = 48 + payloadSize
        require(payloadSize >= 0 && envelopeOffset + envelopeSize <= image.size)
        return DotNetCSharpImplementationManifestCodec.decodeManagedResource(
            image.copyOfRange(envelopeOffset, envelopeOffset + envelopeSize),
        )
    }

    private fun findCSharpImplementationManifestEnvelope(image: ByteArray): Int {
        val magic = "KDNCSM01".toByteArray(Charsets.US_ASCII)
        val offsets = image.indices.filter { offset ->
            offset + magic.size <= image.size &&
                    magic.indices.all { index -> image[offset + index] == magic[index] }
        }
        assertEquals(1, offsets.size, "Expected one C# implementation manifest envelope")
        return offsets.single()
    }

    private fun readLittleEndianInt(bytes: ByteArray, offset: Int): Int =
        bytes[offset].toInt() and 0xff or
                ((bytes[offset + 1].toInt() and 0xff) shl 8) or
                ((bytes[offset + 2].toInt() and 0xff) shl 16) or
                ((bytes[offset + 3].toInt() and 0xff) shl 24)

    private fun readLittleEndianIndex(
        bytes: ByteArray,
        offset: Int,
        width: Int,
    ): Int {
        require(width == 2 || width == 4)
        var value = 0
        repeat(width) { byteIndex ->
            value = value or ((bytes[offset + byteIndex].toInt() and 0xff) shl (byteIndex * 8))
        }
        return value
    }

    private class ClrMetadataTablesLayout(
        private val tablesOffset: Int,
        private val blobHeapOffset: Int,
        private val validMask: Long,
        private val rowCounts: IntArray,
        val stringIndexSize: Int,
        val blobIndexSize: Int,
        private val guidIndexSize: Int,
    ) {
        private val tableDataOffset =
            tablesOffset + 24 + rowCounts.indices.count { table -> hasTable(table) } * 4

        fun tableIndexSize(table: Int): Int =
            if (rowCounts[table] < 0x1_0000) 2 else 4

        val hasConstantIndexSize: Int
            get() = codedIndexSize(2, 4, 8, 23)

        val hasFieldMarshalIndexSize: Int
            get() = codedIndexSize(1, 4, 8)

        val hasCustomAttributeIndexSize: Int
            get() = codedIndexSize(
                5,
                6, 4, 1, 2, 8, 9, 10, 0, 14, 23, 20,
                17, 26, 27, 32, 35, 38, 39, 40, 42, 44, 43,
            )

        val customAttributeTypeIndexSize: Int
            get() = codedIndexSize(3, 6, 10)

        val memberRefParentIndexSize: Int
            get() = codedIndexSize(3, 2, 1, 26, 6, 27)

        fun blobEntryOffset(index: Int): Int {
            require(index > 0)
            return blobHeapOffset + index
        }

        fun blobContentOffset(image: ByteArray, index: Int): Int {
            require(index > 0)
            val offset = blobHeapOffset + index
            val first = image[offset].toInt() and 0xff
            val headerSize = when {
                first and 0x80 == 0 -> 1
                first and 0xc0 == 0x80 -> 2
                first and 0xe0 == 0xc0 -> 4
                else -> error("Invalid test metadata blob length")
            }
            return offset + headerSize
        }

        fun rowOffset(table: Int, row: Int): Int {
            require(hasTable(table))
            require(row in 1..rowCounts[table])
            var offset = tableDataOffset
            for (precedingTable in 0 until table) {
                if (hasTable(precedingTable)) {
                    offset += rowCounts[precedingTable] * rowSize(precedingTable)
                }
            }
            return offset + (row - 1) * rowSize(table)
        }

        private fun hasTable(table: Int): Boolean =
            validMask ushr table and 1L != 0L

        private fun codedIndexSize(tagBits: Int, vararg tables: Int): Int {
            val maximumRows = tables.maxOf { table -> rowCounts[table] }
            return if (maximumRows < (1 shl (16 - tagBits))) 2 else 4
        }

        private fun rowSize(table: Int): Int = when (table) {
            0 -> 2 + stringIndexSize + guidIndexSize * 3
            1 -> codedIndexSize(2, 0, 26, 35, 1) + stringIndexSize * 2
            2 -> 4 + stringIndexSize * 2 + codedIndexSize(2, 2, 1, 27) +
                    tableIndexSize(4) + tableIndexSize(6)
            3 -> tableIndexSize(4)
            4 -> 2 + stringIndexSize + blobIndexSize
            5 -> tableIndexSize(6)
            6 -> 8 + stringIndexSize + blobIndexSize + tableIndexSize(8)
            7 -> tableIndexSize(8)
            8 -> 4 + stringIndexSize
            9 -> tableIndexSize(2) + codedIndexSize(2, 2, 1, 27)
            10 -> codedIndexSize(3, 2, 1, 26, 6, 27) + stringIndexSize + blobIndexSize
            11 -> 2 + hasConstantIndexSize + blobIndexSize
            12 -> hasCustomAttributeIndexSize + customAttributeTypeIndexSize + blobIndexSize
            13 -> codedIndexSize(1, 4, 8) + blobIndexSize
            14 -> 2 + codedIndexSize(2, 2, 6, 32) + blobIndexSize
            15 -> 6 + tableIndexSize(2)
            16 -> 4 + tableIndexSize(4)
            17 -> blobIndexSize
            18 -> tableIndexSize(2) + tableIndexSize(20)
            19 -> tableIndexSize(20)
            20 -> 2 + stringIndexSize + codedIndexSize(2, 2, 1, 27)
            21 -> tableIndexSize(2) + tableIndexSize(23)
            22 -> tableIndexSize(23)
            23 -> 2 + stringIndexSize + blobIndexSize
            else -> error("Test metadata locator does not require table $table")
        }
    }

    private fun locateClrMetadataTables(image: ByteArray): ClrMetadataTablesLayout {
        fun u2(offset: Int): Int =
            image[offset].toInt() and 0xff or
                    ((image[offset + 1].toInt() and 0xff) shl 8)

        fun u4(offset: Int): Long =
            readLittleEndianInt(image, offset).toLong() and 0xffff_ffffL

        fun u8(offset: Int): Long =
            u4(offset) or (u4(offset + 4) shl 32)

        fun align4(value: Int): Int = (value + 3) and 3.inv()

        val peOffset = u4(0x3c).toInt()
        require(readLittleEndianInt(image, peOffset) == 0x0000_4550)
        val sectionCount = u2(peOffset + 6)
        val optionalHeaderSize = u2(peOffset + 20)
        val optionalHeaderOffset = peOffset + 24
        val dataDirectoriesOffset = when (u2(optionalHeaderOffset)) {
            0x10b -> optionalHeaderOffset + 96
            0x20b -> optionalHeaderOffset + 112
            else -> error("Unsupported PE optional-header kind")
        }
        val sectionHeadersOffset = optionalHeaderOffset + optionalHeaderSize

        fun rvaToFileOffset(rva: Long): Int {
            repeat(sectionCount) { sectionIndex ->
                val sectionOffset = sectionHeadersOffset + sectionIndex * 40
                val virtualSize = u4(sectionOffset + 8)
                val virtualAddress = u4(sectionOffset + 12)
                val rawSize = u4(sectionOffset + 16)
                val rawOffset = u4(sectionOffset + 20)
                val sectionSize = maxOf(virtualSize, rawSize)
                if (rva >= virtualAddress && rva - virtualAddress < sectionSize) {
                    return (rawOffset + rva - virtualAddress).toInt()
                }
            }
            error("RVA 0x${rva.toString(16)} is outside the PE sections")
        }

        val cliRva = u4(dataDirectoriesOffset + 14 * 8)
        val cliOffset = rvaToFileOffset(cliRva)
        val metadataOffset = rvaToFileOffset(u4(cliOffset + 8))
        require(u4(metadataOffset) == 0x424a_5342L)
        val versionLength = u4(metadataOffset + 12).toInt()
        var streamHeaderOffset = metadataOffset + align4(16 + versionLength)
        streamHeaderOffset += 2
        val streamCount = u2(streamHeaderOffset)
        streamHeaderOffset += 2
        var tablesOffset: Int? = null
        var blobHeapOffset: Int? = null
        repeat(streamCount) {
            val streamOffset = u4(streamHeaderOffset).toInt()
            var nameEnd = streamHeaderOffset + 8
            while (image[nameEnd].toInt() != 0) nameEnd++
            val name = image.copyOfRange(streamHeaderOffset + 8, nameEnd)
                .toString(Charsets.US_ASCII)
            if (name == "#~" || name == "#-") {
                tablesOffset = metadataOffset + streamOffset
            }
            if (name == "#Blob") {
                blobHeapOffset = metadataOffset + streamOffset
            }
            streamHeaderOffset += align4(8 + nameEnd - (streamHeaderOffset + 8) + 1)
        }
        val resolvedTablesOffset = checkNotNull(tablesOffset)
        val heapSizes = image[resolvedTablesOffset + 6].toInt() and 0xff
        val validMask = u8(resolvedTablesOffset + 8)
        val rowCounts = IntArray(64)
        var rowCountOffset = resolvedTablesOffset + 24
        for (table in rowCounts.indices) {
            if (validMask ushr table and 1L == 0L) continue
            rowCounts[table] = u4(rowCountOffset).toInt()
            rowCountOffset += 4
        }
        return ClrMetadataTablesLayout(
            tablesOffset = resolvedTablesOffset,
            blobHeapOffset = checkNotNull(blobHeapOffset),
            validMask = validMask,
            rowCounts = rowCounts,
            stringIndexSize = if (heapSizes and 0x1 != 0) 4 else 2,
            blobIndexSize = if (heapSizes and 0x4 != 0) 4 else 2,
            guidIndexSize = if (heapSizes and 0x2 != 0) 4 else 2,
        )
    }

    private fun writeLittleEndian(
        bytes: ByteArray,
        offset: Int,
        width: Int,
        value: Int,
    ) {
        require(width == 2 || width == 4)
        require(width == 4 || value ushr 16 == 0)
        repeat(width) { index ->
            bytes[offset + index] = (value ushr (index * 8)).toByte()
        }
    }

    private fun corruptCSharpManifestLogicalDeclaration(
        assembly: File,
        output: File,
    ) {
        val image = assembly.readBytes()
        val envelopeOffset = findCSharpImplementationManifestEnvelope(image)
        val payloadSize = readLittleEndianInt(image, envelopeOffset + 12)
        val payloadOffset = envelopeOffset + 48
        require(payloadSize >= 0 && payloadOffset + payloadSize <= image.size)
        val payload = image.copyOfRange(payloadOffset, payloadOffset + payloadSize)
        val encodedPayload = payload.toString(Charsets.UTF_8)
        val interfaceRecord = encodedPayload.lineSequence()
            .first { record -> record.startsWith("I\t") }
        val encodedLogicalKey = interfaceRecord.split('\t')[1]
        val logicalKey = Base64.getUrlDecoder()
            .decode(encodedLogicalKey)
            .toString(Charsets.UTF_8)
        val replacementLastCharacter = if (logicalKey.last() == 'X') 'Y' else 'X'
        val replacementLogicalKey = logicalKey.dropLast(1) + replacementLastCharacter
        val replacementField = Base64.getUrlEncoder()
            .withoutPadding()
            .encodeToString(replacementLogicalKey.toByteArray(Charsets.UTF_8))
        assertEquals(encodedLogicalKey.length, replacementField.length)
        val corruptedPayloadText = encodedPayload.replaceFirst(
            "I\t$encodedLogicalKey\t",
            "I\t$replacementField\t",
        )
        val corruptedPayload = corruptedPayloadText.toByteArray(Charsets.UTF_8)
        assertEquals(payload.size, corruptedPayload.size)
        corruptedPayload.copyInto(image, payloadOffset)
        MessageDigest.getInstance("SHA-256")
            .digest(corruptedPayload)
            .copyInto(image, envelopeOffset + 16)
        output.parentFile?.mkdirs()
        output.writeBytes(image)
    }

    private fun produceLibraryWithRewrittenMetadata(
        assemblyName: String,
        propertyOverrides: Map<String, String>,
    ): File = produceLibraryWithTransformedMetadataCarrier(assemblyName) { carrier ->
        carrier.rewriteKlibManifest(propertyOverrides)
    }

    private fun produceLibraryWithTransformedMetadataCarrier(
        assemblyName: String,
        transform: (ByteArray) -> ByteArray,
    ): File {
        val directory = File(tmpdir, assemblyName).apply { mkdirs() }
        val source = directory.resolve("library.kt").apply {
            writeText("package fixture\n\npublic fun published(): Int = 1")
        }
        compileInProcess(
            K2DotNetCompiler(),
            source.path,
            K2DotNetCompilerArguments::dotNetProduceLibrary.cliArgument,
            K2DotNetCompilerArguments::dotNetTarget.cliArgument, "netstandard2.0",
            K2DotNetCompilerArguments::moduleName.cliArgument, assemblyName,
            K2DotNetCompilerArguments::destination.cliArgument, directory.path,
        )
        val original = directory.resolve("$assemblyName.dll")
        val rewrittenMetadata = transform(original.readKlibCarrier())
        val csharpManifest = checkNotNull(
            DotNetManagedResourceReader.read(
                original,
                DotNetCSharpImplementationManifestCodec.MANAGED_RESOURCE_NAME,
            )
        ).content
        val rewritten = directory.resolve("$assemblyName-rewritten.dll")
        assertTrue(
            DotNetIlAssembler.assembleLibrary(
                directory.resolve("$assemblyName.il"),
                rewritten,
                DotNetTarget.NETSTANDARD_2_0,
                MessageCollector.NONE,
                mapOf(
                    DotNetCSharpImplementationManifestCodec.MANAGED_RESOURCE_NAME to csharpManifest,
                    DotNetKotlinMetadataResource.MANAGED_RESOURCE_NAME to rewrittenMetadata,
                ),
            )
        )
        return rewritten
    }

    private fun ByteArray.rewriteKlibManifest(
        propertyOverrides: Map<String, String>,
    ): ByteArray {
        val outputBytes = ByteArrayOutputStream()
        var foundManifest = false
        ZipInputStream(ByteArrayInputStream(this)).use { input ->
            ZipOutputStream(outputBytes).use { output ->
                while (true) {
                    val inputEntry = input.nextEntry ?: break
                    val payload = input.readBytes()
                    val outputPayload = if (inputEntry.name == "default/manifest") {
                        foundManifest = true
                        val properties = Properties().apply {
                            load(ByteArrayInputStream(payload))
                            for (entry in propertyOverrides) {
                                setProperty(entry.key, entry.value)
                            }
                        }
                        ByteArrayOutputStream().use { manifestBytes ->
                            properties.store(manifestBytes, null)
                            manifestBytes.toByteArray()
                        }
                    } else {
                        payload
                    }
                    output.putNextEntry(ZipEntry(inputEntry.name))
                    output.write(outputPayload)
                    output.closeEntry()
                }
            }
        }
        assertTrue(foundManifest) { "Embedded KLIB has no default/manifest" }
        return outputBytes.toByteArray()
    }

    private fun compileAgainstRejectedDll(library: File): String {
        val source = File(tmpdir, "rejected-${library.nameWithoutExtension}.kt").apply {
            writeText("package consumer\n\npublic fun answer(): Int = 42")
        }
        val [diagnostics, exitCode] = AbstractCliTest.executeCompilerGrabOutput(
            K2DotNetCompiler(),
            listOf(
                source.path,
                K2DotNetCompilerArguments::noStdlib.cliArgument,
                K2DotNetCompilerArguments::classpath.cliArgument, library.path,
                K2DotNetCompilerArguments::moduleName.cliArgument, "RejectedConsumer",
                K2DotNetCompilerArguments::destination.cliArgument,
                File(tmpdir, "rejected-${library.nameWithoutExtension}.il").path,
            )
        )
        assertEquals(ExitCode.COMPILATION_ERROR, exitCode, diagnostics)
        return diagnostics
    }

    private fun requireOrAssumeToolchain(condition: Boolean, message: String) {
        if (dotNetToolchainIsRequired()) {
            assertTrue(condition) { "$message (KOTLIN_DOTNET_REQUIRE_TOOLCHAIN is enabled)" }
        } else {
            assumeTrue(condition, message)
        }
    }

    private fun dotNetToolchainIsRequired(): Boolean =
        System.getenv("KOTLIN_DOTNET_REQUIRE_TOOLCHAIN")?.let { value ->
            value == "1" || value.equals("true", ignoreCase = true)
        } == true

    private fun File.readKlibManifest(): Properties {
        ZipInputStream(ByteArrayInputStream(readKlibCarrier())).use { archive ->
            while (true) {
                val entry = archive.nextEntry ?: error("KLIB in '$path' has no default/manifest")
                if (entry.name == "default/manifest") {
                    return Properties().apply { load(archive) }
                }
            }
        }
    }

    private fun File.readKlibPayloadEntries(): Map<String, ByteArray> = buildMap {
        ZipInputStream(ByteArrayInputStream(readKlibCarrier())).use { archive ->
            while (true) {
                val entry = archive.nextEntry ?: break
                if (!entry.isDirectory && entry.name != "default/manifest") {
                    put(entry.name, archive.readBytes())
                }
            }
        }
    }

    private fun File.readKlibCarrier(): ByteArray {
        if (!extension.equals("dll", ignoreCase = true)) return readBytes()
        val resource = checkNotNull(
            DotNetManagedResourceReader.read(this, DotNetKotlinMetadataResource.MANAGED_RESOURCE_NAME)
        ) { "Assembly '$path' has no ${DotNetKotlinMetadataResource.MANAGED_RESOURCE_NAME} resource" }
        assertTrue(resource.isPrivate) {
            "Assembly '$path' exposes ${DotNetKotlinMetadataResource.MANAGED_RESOURCE_NAME} publicly"
        }
        return resource.content
    }

    private fun runDotNet(
        dotnetHost: File,
        assembly: File,
        workingDirectory: File,
        failureMessage: String,
    ) {
        val process = ProcessBuilder(dotnetHost.path, "exec", assembly.path)
            .directory(workingDirectory)
            .redirectErrorStream(true)
            .start()
        val output = process.inputStream.bufferedReader().use { it.readText() }
        assertTrue(process.waitFor() == 0) { "$failureMessage:\n$output" }
    }

    private fun runAssemblerPairing(command: List<String>, workingDirectory: File, description: String) {
        val process = ProcessBuilder(command)
            .directory(workingDirectory)
            .redirectErrorStream(true)
            .start()
        val output = process.inputStream.bufferedReader().use { it.readText() }
        assertEquals(0, process.waitFor(), "$description failed:\n$output")
        assertEquals("OK", output.trim(), "$description produced unexpected output")
    }

    private fun ByteArray.uniqueSequenceOffset(sequence: ByteArray): Int {
        val matches = (0..size - sequence.size).filter { offset ->
            sequence.indices.all { index -> this[offset + index] == sequence[index] }
        }
        assertEquals(1, matches.size, "Expected one physical metadata blob match")
        return matches.single()
    }
}
